export default spacetimedb;

export type WorldReducerContext = Parameters<Parameters<typeof spacetimedb.init>[1]>[0];
type WorldConnectionId = NonNullable<WorldReducerContext['connectionId']>;
type WorldNpcRow = NonNullable<ReturnType<WorldReducerContext['db']['world_npc']['id']['find']>>;
type PlayerPositionRow = NonNullable<ReturnType<WorldReducerContext['db']['player_position']['identity']['find']>>;
type WorldResourceRow = NonNullable<ReturnType<WorldReducerContext['db']['world_resource']['id']['find']>>;
type WorldChestRow = NonNullable<ReturnType<WorldReducerContext['db']['world_chest']['id']['find']>>;
type WorldChestSlotRow = NonNullable<ReturnType<WorldReducerContext['db']['world_chest_slot']['id']['find']>>;
export type WorldPlaceableRow = NonNullable<ReturnType<WorldReducerContext['db']['world_placeable']['id']['find']>>;
type WorldItemRow = NonNullable<ReturnType<WorldReducerContext['db']['world_item']['id']['find']>>;
type WorldProjectileRow = NonNullable<ReturnType<WorldReducerContext['db']['world_projectile']['id']['find']>>;
type WorldCombatTargetRow = NonNullable<ReturnType<WorldReducerContext['db']['world_combat_target']['id']['find']>>;
type WorldSoilRow = NonNullable<ReturnType<WorldReducerContext['db']['world_soil']['id']['find']>>;
type EnemyAttackRow = NonNullable<ReturnType<WorldReducerContext['db']['enemy_attack']['npcId']['find']>>;
type InventorySlotRow = NonNullable<ReturnType<WorldReducerContext['db']['inventory_slot']['id']['find']>>;
type WorldClockRow = NonNullable<ReturnType<WorldReducerContext['db']['world_clock']['id']['find']>>;
type ConnectionPresenceRow = NonNullable<ReturnType<WorldReducerContext['db']['connection_presence_v2']['connectionId']['find']>>;
type HomesteadRow = NonNullable<ReturnType<WorldReducerContext['db']['homestead']['spaceId']['find']>>;
type RogueRunRow = NonNullable<ReturnType<WorldReducerContext['db']['rogue_run']['id']['find']>>;
type RogueEnemyProfileRow = NonNullable<ReturnType<WorldReducerContext['db']['rogue_enemy_profile']['npcId']['find']>>;
type WorldAdminAuditRow = NonNullable<ReturnType<WorldReducerContext['db']['world_admin_audit']['id']['find']>>;
type AdminProcedureTx = Pick<WorldReducerContext, 'db' | 'sender'>;

type LegacyWorldAdminAuditInsert = Pick<
  WorldAdminAuditRow,
  'id' | 'actor' | 'action' | 'value' | 'occurredAt'
>;

/** Keeps every pre-Studio audit write source-compatible while additive columns
 * provide indexed, typed audit data for new administration mutations. */
function insertLegacyAdminAudit(
  ctx: Pick<WorldReducerContext, 'db'>,
  row: LegacyWorldAdminAuditInsert,
): void {
  ctx.db.world_admin_audit.insert({
    ...row,
    occurredAtMicros: row.occurredAt.microsSinceUnixEpoch,
    targetKey: '',
    payload: '',
  });
}

function adminAuditStorageRow(row: WorldAdminAuditRow): AdminAuditStorageRow {
  return {
    id: row.id.toString(),
    actorIdentity: row.actor.toHexString(),
    action: row.action,
    value: row.value,
    occurredAtMicros: (row.occurredAtMicros || row.occurredAt.microsSinceUnixEpoch).toString(),
    targetKey: row.targetKey,
    payload: row.payload,
  };
}

function adminPlayerMutationCommitId(actor: Identity, clientMutationId: string): string {
  return `${actor.toHexString()}:${clientMutationId}`;
}

function insertAdminPlayerMutationAudit(
  ctx: WorldReducerContext,
  input: {
    readonly target: Identity;
    readonly operation: AdminPlayerMutation['operation'] | 'undo';
    readonly clientMutationId: string;
    readonly committedVersion: string;
    readonly value: string;
    readonly payload: AdminAuditPayloadV1;
    readonly sourceAuditId?: bigint;
  },
): WorldAdminAuditRow {
  const id = adminPlayerMutationCommitId(ctx.sender, input.clientMutationId);
  if (ctx.db.admin_player_mutation_commit.id.find(id) !== null) {
    throw new SenderError('admin_invalid_mutation_id');
  }
  const targetKey = `player:${input.target.toHexString()}`;
  const audit = ctx.db.world_admin_audit.insert({
    id: 0n,
    actor: ctx.sender,
    action: input.operation,
    value: input.value,
    occurredAt: ctx.timestamp,
    occurredAtMicros: ctx.timestamp.microsSinceUnixEpoch,
    targetKey,
    payload: serializeAdminAuditPayload(input.payload),
  });
  ctx.db.admin_player_mutation_commit.insert({
    id,
    actor: ctx.sender,
    clientMutationId: input.clientMutationId,
    auditId: audit.id,
    targetIdentity: input.target,
    operation: input.operation,
    committedVersion: input.committedVersion,
    sourceAuditId: input.sourceAuditId,
  });
  return audit;
}

function validatedAdminMutationReason(reason: string, clientMutationId: string) {
  const parsed = parseAdminReason(reason);
  if (!parsed.ok) throw new SenderError(parsed.error);
  if (!ADMIN_MUTATION_ID_PATTERN.test(clientMutationId)) throw new SenderError('admin_invalid_mutation_id');
  return parsed.value;
}

function insertCapabilityAdminAudit(
  ctx: WorldReducerContext,
  input: {
    readonly identity: Identity;
    readonly capability: 'content_editor' | 'support';
    readonly granted: boolean;
    readonly reason: string;
    readonly clientMutationId: string;
  },
): void {
  const typedReason = validatedAdminMutationReason(input.reason, input.clientMutationId);
  const operation = `${input.granted ? 'grant' : 'revoke'}_${input.capability}` as const;
  const inverseOperation = `${input.granted ? 'revoke' : 'grant'}_${input.capability}` as const;
  const identity = input.identity.toHexString();
  ctx.db.world_admin_audit.insert({
    id: 0n,
    actor: ctx.sender,
    action: operation,
    value: identity,
    occurredAt: ctx.timestamp,
    occurredAtMicros: ctx.timestamp.microsSinceUnixEpoch,
    targetKey: `player:${identity}`,
    payload: JSON.stringify({
      schemaVersion: 1,
      clientMutationId: input.clientMutationId,
      target: { kind: 'player', identity },
      reason: typedReason,
      changes: [{
        path: `/grants/${input.capability}`,
        before: { present: true, value: !input.granted },
        after: { present: true, value: input.granted },
      }],
      inverse: { operation: inverseOperation, args: { identity } },
    }),
  });
}

function requireAdminProcedure(tx: AdminProcedureTx, scope: StudioScope = 'observe'): void {
  if (!scopesFor(tx).includes(scope)) throw new SenderError(`studio_scope_required:${scope}`);
  const grant = tx.db.studio_scope_grant.id.find(`${tx.sender.toHexString()}:${scope}`);
  if (grant !== null && grant.revokedAt === undefined) return;
  const membershipRow = tx.db.membership.identity.find(tx.sender);
  try {
    requireOwnerOrAdminRead(membershipRow === null ? null : {
      role: membershipRow.role,
      blocked: membershipRow.blocked,
      revoked: membershipRow.revokedAt !== undefined,
    });
  } catch {
    throw new SenderError('admin_role_forbidden');
  }
}

function requirePlayerAdminResultRead(tx: AdminProcedureTx): void {
  const override = tx.db.studio_scope_grant.id.find(`${tx.sender.toHexString()}:operate.players`);
  if (override !== null) {
    if (override.revokedAt === undefined && scopesFor(tx).includes('operate.players')) return;
    throw new SenderError('studio_scope_required:operate.players');
  }
  const role = resolveAdminEffectiveRole(
    tx.db.membership.identity.find(tx.sender),
    tx.db.content_editor_grant.identity.find(tx.sender),
    tx.db.support_grant.identity.find(tx.sender),
  );
  if (role === null || !adminRoleCanRead(role, 'player_private')) {
    throw new SenderError('admin_role_forbidden');
  }
}

function parseAdminIdentity(value: string): Identity {
  try { return Identity.fromString(value); }
  catch { throw new SenderError('admin_target_not_found'); }
}

function adminProcedureJson<T>(response: AdminProcedureExecution<T>): string {
  const counter = Object.entries(response.rowsScanned).find(([, value]) => value > 0);
  if (counter !== undefined) console.info(`${counter[0]}=${counter[1]}`);
  return stringifyAdminProcedureResult(response.result);
}

function adminPlayerSummary(tx: AdminProcedureTx, identity: Identity): AdminPlayerSummary | null {
  const profile = tx.db.player_public.identity.find(identity);
  if (profile === null) return null;
  const member = tx.db.membership.identity.find(identity);
  const position = tx.db.player_position.identity.find(identity);
  const contentGrant = tx.db.content_editor_grant.identity.find(identity);
  const supportGrant = tx.db.support_grant.identity.find(identity);
  return {
    identity: identity.toHexString(), displayName: profile.displayName,
    role: member?.role === 'owner' || member?.role === 'admin' || member?.role === 'moderator'
      ? member.role : 'friend',
    grants: [
      ...(contentGrant !== null && contentGrant.revokedAt === undefined ? ['content_editor' as const] : []),
      ...(supportGrant !== null && supportGrant.revokedAt === undefined ? ['support' as const] : []),
    ], online: profile.online,
    spaceId: position === null ? null : String(position.spaceId),
    tileX: position === null ? null : Math.floor(position.x / TILE_SIZE_FIXED),
    tileY: position === null ? null : Math.floor(position.y / TILE_SIZE_FIXED),
    lastSeenMicros: profile.lastActiveAtMicros.toString(),
  };
}

function adminInventoryArea(slot: number): { readonly area: AdminInventoryArea; readonly index: number } {
  if (slot < BACKPACK_SLOT_OFFSET) return { area: 'hotbar', index: slot };
  if (slot < EQUIPMENT_SLOT_OFFSET) return { area: 'backpack', index: slot - BACKPACK_SLOT_OFFSET };
  if (slot < CRAFTING_SLOT_OFFSET) return { area: 'equipment', index: slot - EQUIPMENT_SLOT_OFFSET };
  return { area: 'crafting', index: slot - CRAFTING_SLOT_OFFSET };
}

function adminResolvedStack(ctx: Pick<WorldReducerContext, 'db'>, row: { readonly itemKind: string; readonly quantity: number; readonly durability: number }): AdminResolvedStack {
  const definition = runtimeItemDefinition(contentRegistry(ctx), row.itemKind);
  return {
    itemKind: row.itemKind, quantity: row.quantity, durability: row.durability,
    displayName: definition?.displayName ?? row.itemKind,
    maxStack: definition?.maxStack ?? 1,
    tags: definition?.tags ?? [],
  };
}
type IndexedLookupContext = Readonly<{
  db: Readonly<{
    homestead: Readonly<{
      spaceId: Pick<WorldReducerContext['db']['homestead']['spaceId'], 'find'>;
      by_owner: Pick<WorldReducerContext['db']['homestead']['by_owner'], 'filter'>;
      by_residence_space: Pick<WorldReducerContext['db']['homestead']['by_residence_space'], 'filter'>;
    }>;
    player_trade_session: Readonly<{
      by_requester: Pick<WorldReducerContext['db']['player_trade_session']['by_requester'], 'filter'>;
      by_recipient: Pick<WorldReducerContext['db']['player_trade_session']['by_recipient'], 'filter'>;
    }>;
  }>;
}>;

function cancelFishingCastFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n,
): boolean {
  if (ctx.db.fishing_cast.identity.find(identity) === null) return false;
  ctx.db.fishing_cast.identity.delete(identity);
  const position = ctx.db.player_position.identity.find(identity);
  if (position !== null && (position.actionKind === 'fish_cast'
    || position.actionKind === 'fishing_wait')) {
    ctx.db.player_position.identity.update({
      ...position,
      actionKind: 'none',
      actionStartedTick: authorityTick,
    });
  }
  return true;
}

function combatTargetPositionAtTile(tileX: number, tileY: number): { readonly x: number; readonly y: number } {
  return {
    x: tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
    y: (tileY + 1) * TILE_SIZE_FIXED,
  };
}

function combatTargetTile(target: Pick<WorldCombatTargetRow, 'x' | 'y'>): { readonly tileX: number; readonly tileY: number } {
  return {
    tileX: Math.floor(target.x / TILE_SIZE_FIXED),
    tileY: Math.floor(target.y / TILE_SIZE_FIXED) - 1,
  };
}

function combatTargetProjectileBounds(target: Pick<WorldCombatTargetRow, 'x' | 'y'>) {
  return {
    left: target.x - 14 * FIXED_UNITS_PER_PIXEL,
    right: target.x + 14 * FIXED_UNITS_PER_PIXEL,
    top: target.y - 29 * FIXED_UNITS_PER_PIXEL,
    bottom: target.y,
  };
}

function combatTargetObjectReference(
  target: Pick<WorldCombatTargetRow, 'kind' | 'definitionId'>,
): { readonly kind: string; readonly definitionId?: string } {
  return target.definitionId === ''
    ? { kind: target.kind }
    : { kind: target.kind, definitionId: target.definitionId };
}

function activeCombatTargetDefinition(ctx: Pick<WorldReducerContext, 'db'>, target: Pick<WorldCombatTargetRow, 'kind' | 'definitionId'>) {
  return runtimeObjectDefinition(contentRegistry(ctx), combatTargetObjectReference(target));
}

function activeCombatTargetHealth(ctx: Pick<WorldReducerContext, 'db'>, target: Pick<WorldCombatTargetRow, 'kind' | 'definitionId'>) {
  const damageable = runtimeObjectDamageable(contentRegistry(ctx), combatTargetObjectReference(target));
  return damageable?.model === 'health' ? damageable : null;
}

/** Retains each arrow's exact impact offset when a struck target is carried.
 * Initial impact coordinates are never replaced with a synthetic target anchor. */
function moveEmbeddedArrowsWithTarget(
  ctx: WorldReducerContext,
  target: Pick<WorldCombatTargetRow, 'id' | 'x' | 'y' | 'spaceId'>,
  nextX: number,
  nextY: number,
  nextSpaceId: number,
): void {
  const deltaX = nextX - target.x;
  const deltaY = nextY - target.y;
  if (deltaX === 0 && deltaY === 0 && nextSpaceId === target.spaceId) return;
  for (const projectile of ctx.db.world_projectile.by_chunk.filter(target.spaceId)) {
    if (projectile.state !== 'hit' || projectile.hitKind !== 'combat_target'
      || projectile.hitId !== target.id.toString()) continue;
    const x = projectile.x + deltaX;
    const y = projectile.y + deltaY;
    ctx.db.world_projectile.id.update({
      ...projectile,
      x,
      y,
      chunkX: chunkAt(x),
      chunkY: chunkAt(y),
      spaceId: nextSpaceId,
    });
  }
}

function ensureArcheryTargets(ctx: WorldReducerContext): void {
  const registry = contentRegistry(ctx);
  const fieldPlans = runtimeFixedCombatTargetPlans(registry);
  if (fieldPlans === null) throw new SenderError('archery_target_content_invalid');
  const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
  const plans:Array<{spawn:{id:bigint;tileX:number;tileY:number;spaceId:number;kind:string};
    definition:NonNullable<ReturnType<typeof runtimeObjectDefinition>>;
    damageable:Extract<NonNullable<ReturnType<typeof runtimeObjectDamageable>>,{model:'health'}>;
    fixedLobby:boolean}> = fieldPlans.map(({id,tileX,tileY,spaceId,kind,definition,damageable}) => ({
      spawn:{id,tileX,tileY,spaceId,kind},definition,damageable,fixedLobby:false,
    }));
  const lobby=activeHearthLobbyDefinition(registry);
  if(lobby!==null){
    const definition=runtimeObjectDefinition(registry,{kind:lobby.practiceTarget.kind,
      definitionId:lobby.practiceTarget.definitionId});
    const damageable=runtimeObjectDamageable(registry,{kind:lobby.practiceTarget.kind,
      definitionId:lobby.practiceTarget.definitionId});
    if(definition!==null&&damageable?.model==='health')plans.push({spawn:{...lobby.practiceTarget,
      spaceId:lobby.spaceId},definition,damageable,fixedLobby:true});
  }
  if (new Set(plans.map(({spawn}) => spawn.id)).size !== plans.length)
    throw new SenderError('archery_target_content_invalid');
  // Preflight every fixed lobby conflict before inserting any missing field row.
  for (const {spawn,definition,fixedLobby} of plans) {
    const existing = ctx.db.world_combat_target.id.find(spawn.id);
    if (existing === null) continue;
    const existingDefinition = activeCombatTargetDefinition(ctx, existing);
    // Explicit missing/retired identity is inert but durable. Never rewrite
    // or reject a reconnect merely to coerce it back to bootstrap content.
    if (existingDefinition === null) continue;
    const position = combatTargetPositionAtTile(spawn.tileX, spawn.tileY);
    if (fixedLobby && (existing.spaceId !== spawn.spaceId
      || existingDefinition.id !== definition.id
      || existing.carriedBy !== undefined
      || existing.x !== position.x || existing.y !== position.y))
      throw new SenderError('hearth_lobby_target_conflict');
  }
  for (const {spawn,definition,damageable} of plans) {
    if (ctx.db.world_combat_target.id.find(spawn.id) !== null) continue;
    const position = combatTargetPositionAtTile(spawn.tileX, spawn.tileY);
    ctx.db.world_combat_target.insert({
      id: spawn.id,
      kind: spawn.kind,
      ...position,
      chunkX: chunkAt(position.x),
      chunkY: chunkAt(position.y),
      carriedBy: undefined,
      healthCenti: damageable.maximumHealthCenti,
      maxHealthCenti: damageable.maximumHealthCenti,
      regenTick: authorityTick,
      lastDamagedTick: 0n,
      lastHitCritical: false,
      spaceId: spawn.spaceId,
      definitionId: definition.id,
    });
  }
}

function regenerateCombatTarget(
  ctx: WorldReducerContext,
  target: WorldCombatTargetRow,
  authorityTick: bigint,
): WorldCombatTargetRow {
  const damageable = activeCombatTargetHealth(ctx, target);
  const regeneration = damageable?.regeneration;
  if (damageable === null || regeneration === undefined
    || target.healthCenti >= target.maxHealthCenti || authorityTick <= target.regenTick) return target;
  const elapsedTicks = authorityTick - target.regenTick;
  const intervals = elapsedTicks / BigInt(regeneration.everyTicks);
  if (intervals === 0n) return target;
  const healthCenti = Math.min(
    target.maxHealthCenti,
    target.healthCenti + Number(intervals * BigInt(regeneration.amountCenti)),
  );
  const next = {
    ...target,
    healthCenti,
    regenTick: target.regenTick + intervals * BigInt(regeneration.everyTicks),
  };
  ctx.db.world_combat_target.id.update(next);
  return next;
}

/** Lazily normalizes chests created under an older capacity. Stacks are first
 * compacted entirely in memory; persistence is changed only after everything
 * is proven to fit, so shrinking a chest can never silently discard contents. */
function ensureChestStorageRows(ctx: WorldReducerContext, chestId: bigint): WorldChestSlotRow[] {
  const rows = [...ctx.db.world_chest_slot.by_chest.filter(chestId)];
  const legacyRows = rows.filter((row) => row.slot >= CHEST_STORAGE_CAPACITY);
  if (legacyRows.length > 0) {
    let compacted: ContainerSnapshot = {
      id: 'chest',
      capacity: CHEST_STORAGE_CAPACITY,
      slots: Array.from({ length: CHEST_STORAGE_CAPACITY }, () => null),
    };
    for (const row of rows
      .filter((candidate) => candidate.itemKind !== 'empty' && candidate.quantity > 0)
      .sort((left, right) => left.slot - right.slot)) {
      const stack = storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
      if (stack === null) continue;
      const inserted = insertItemStackPartial(compacted, stack, activeItemContainerContent(ctx));
      if (!inserted.ok || inserted.remainderQuantity > 0) throw new SenderError('legacy_chest_over_capacity');
      compacted = inserted.container;
    }

    const bySlot = new Map(rows.map((row) => [row.slot, row]));
    const normalizedRows: WorldChestSlotRow[] = [];
    for (let slot = 0; slot < CHEST_STORAGE_CAPACITY; slot += 1) {
      const next = compacted.slots[slot];
      const existing = bySlot.get(slot);
      const values = {
        itemKind: next?.itemKind ?? 'empty',
        quantity: next?.quantity ?? 0,
        durability: storedDurability(ctx, next?.itemKind ?? 'empty', next?.durability),
        lit: storedLit(next?.itemKind ?? 'empty', next?.lit),
      };
      normalizedRows.push(existing === undefined
        ? ctx.db.world_chest_slot.insert({ id: `${chestId}:${slot}`, chestId, slot, ...values })
        : ctx.db.world_chest_slot.id.update({ ...existing, ...values }));
    }
    for (const row of legacyRows) ctx.db.world_chest_slot.id.delete(row.id);
    return normalizedRows;
  }

  const occupiedIndexes = new Set(rows.map((row) => row.slot));
  for (let slot = 0; slot < CHEST_STORAGE_CAPACITY; slot += 1) {
    if (occupiedIndexes.has(slot)) continue;
    rows.push(ctx.db.world_chest_slot.insert({
      id: `${chestId}:${slot}`,
      chestId,
      slot,
      itemKind: 'empty',
      quantity: 0,
      durability: 0,
      lit: true,
    }));
  }
  return rows;
}

function migrateSessionChatNotices(ctx: WorldReducerContext): void {
  const migration = ctx.db.chat_migration.id.find(0);
  if ((migration?.sessionNoticesVersion ?? 0) >= 1) return;
  for (const message of ctx.db.chat_message.iter()) {
    if (isLegacyPersistentLifecycleMessage(message.kind)) ctx.db.chat_message.id.delete(message.id);
  }
  const next = { id: 0, sessionNoticesVersion: 1 };
  if (migration === null) ctx.db.chat_migration.insert(next);
  else ctx.db.chat_migration.id.update(next);
}

function deleteSessionChatNoticesForConnection(
  ctx: WorldReducerContext,
  connectionId: WorldConnectionId,
): void {
  for (const notice of ctx.db.session_chat_notice.by_recipient_connection.filter(connectionId)) {
    ctx.db.session_chat_notice.id.delete(notice.id);
  }
}

function insertSessionChatNotice(
  ctx: WorldReducerContext,
  recipientIdentity: WorldReducerContext['sender'],
  recipientConnectionId: WorldConnectionId,
  kind: string,
  body: string,
): void {
  ctx.db.session_chat_notice.insert({
    id: 0n,
    recipientIdentity,
    recipientConnectionId,
    kind,
    body,
    issuedAt: ctx.timestamp,
  });
  const notices = [...ctx.db.session_chat_notice.by_recipient_connection.filter(recipientConnectionId)]
    .sort((left, right) => left.id < right.id ? -1 : left.id > right.id ? 1 : 0);
  for (const expired of notices.slice(0, Math.max(0, notices.length - SESSION_CHAT_NOTICE_LIMIT))) {
    ctx.db.session_chat_notice.id.delete(expired.id);
  }
}

function broadcastSessionChatNotice(
  ctx: WorldReducerContext,
  kind: 'entry' | 'disconnect',
  body: string,
): void {
  for (const presence of ctx.db.connection_presence_v2.iter()) {
    if (presenceLeaseExpired(
      presence.lastSeenAt.microsSinceUnixEpoch,
      ctx.timestamp.microsSinceUnixEpoch,
    )) continue;
    if (ctx.db.connection_notice.connectionId.find(presence.connectionId) === null) continue;
    insertSessionChatNotice(ctx, presence.identity, presence.connectionId, kind, body);
  }
}

function installDebugPortals(ctx: WorldReducerContext): void {
  if (ctx.db.space_portal.id.find(DEBUG_PORTAL_TOPSIDE_ID) === null) {
    ctx.db.space_portal.insert({
      id: DEBUG_PORTAL_TOPSIDE_ID,
      kind: 'debug_door',
      fromSpace: TOPSIDE_SPACE_ID,
      fromTileX: DEBUG_PORTAL_TOPSIDE_TILE.x,
      fromTileY: DEBUG_PORTAL_TOPSIDE_TILE.y,
      toSpace: DEBUG_SPACE_ID,
      toTileX: DEBUG_PORTAL_INTERIOR_TILE.x,
      toTileY: DEBUG_PORTAL_INTERIOR_TILE.y,
    });
  }
  if (ctx.db.space_portal.id.find(DEBUG_PORTAL_INTERIOR_ID) === null) {
    ctx.db.space_portal.insert({
      id: DEBUG_PORTAL_INTERIOR_ID,
      kind: 'debug_door',
      fromSpace: DEBUG_SPACE_ID,
      fromTileX: DEBUG_PORTAL_INTERIOR_TILE.x,
      fromTileY: DEBUG_PORTAL_INTERIOR_TILE.y,
      toSpace: TOPSIDE_SPACE_ID,
      toTileX: DEBUG_PORTAL_TOPSIDE_TILE.x,
      toTileY: DEBUG_PORTAL_TOPSIDE_TILE.y,
    });
  }
}

function installMarlowTent(ctx: WorldReducerContext): void {
  for (const portal of runtimeSpacePortalPlans(contentRegistry(ctx))) {
    const row = {
      id: portal.runtimeId,
      kind: portal.portalKind,
      fromSpace: portal.fromSpaceId,
      fromTileX: portal.fromTileX,
      fromTileY: portal.fromTileY,
      toSpace: portal.toSpaceId,
      toTileX: portal.toTileX,
      toTileY: portal.toTileY,
    };
    const existing = ctx.db.space_portal.id.find(row.id);
    if (existing === null) ctx.db.space_portal.insert(row);
    else ctx.db.space_portal.id.update(row);
  }
  for (const surface of authoredSurfacePlans(
    contentRegistry(ctx).spaces.values(), SURVIVAL_CHUNK_TILES,
  )) {
    if (ctx.db.world_surface.id.find(surface.id) === null) ctx.db.world_surface.insert(surface);
    else ctx.db.world_surface.id.update(surface);
  }
}

function teleportPlayer(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  spaceId: number,
  nextX: number,
  nextY: number,
): void {
  ctx.db.player_seat.identity.delete(position.identity);
  const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? position.authorityTick;
  const defense = ctx.db.player_combat_state.identity.find(position.identity);
  if (defense !== null) {
    advancePlayerStats(ctx, position.identity, authorityTick);
    combatRecovery(ctx, position.identity, authorityTick, defense.readyTick);
  }
  const nextPosition = {
    ...position,
    x: nextX,
    y: nextY,
    spaceId,
    chunkX: chunkAt(nextX),
    chunkY: chunkAt(nextY),
    moving: false,
    authorityTick,
    actionKind: 'none',
    actionStartedTick: authorityTick,
  };
  if (position.spaceId !== spaceId) {
    const handlers = currentWorldBehaviourHandlers(ctx);
    const registrySnapshot = behaviourRegistrySnapshot(ctx);
    const source = activeSpaceDefinition(ctx, position.spaceId, instanceForSpace(ctx, position.spaceId));
    const destination = activeSpaceDefinition(ctx, spaceId, instanceForSpace(ctx, spaceId));
    raisePlayerSystemLifecycleEvent(ctx, position.identity, position, {
      type: 'leaveSpace',
      actor: { entityType: 'player', id: position.identity.toHexString() },
      space: { id: position.spaceId.toString(), ...(source === null || source === undefined
        ? {} : { kind: source.generator }) },
    }, undefined, handlers, registrySnapshot);
    raisePlayerSystemLifecycleEvent(ctx, position.identity, nextPosition, {
      type: 'enterSpace',
      actor: { entityType: 'player', id: position.identity.toHexString() },
      space: { id: spaceId.toString(), ...(destination === null || destination === undefined
        ? {} : { kind: destination.generator }) },
    }, undefined, handlers, registrySnapshot);
  }
  cancelFishingCastFor(ctx, position.identity, authorityTick);
  ctx.db.player_jump_state.identity.delete(position.identity);
  ctx.db.player_position.identity.update(nextPosition);
  const input = ctx.db.player_input.identity.find(position.identity);
  if (input !== null) {
    ctx.db.player_input.identity.update({
      ...input,
      direction: 'idle',
      sprinting: false,
      settleDirection: 'idle',
      settleSteps: 0,
      settledSequence: input.sequence,
      pendingSequence: 0n,
      appliedSteps: 0n,
      updatedAtMicros: ctx.timestamp.microsSinceUnixEpoch,
    });
  }
  for (const chest of ctx.db.world_chest.by_carrier.filter(position.identity)) {
    const tileX = Math.floor(nextX / TILE_SIZE_FIXED);
    const tileY = Math.floor(nextY / TILE_SIZE_FIXED);
    const moved = {
      ...chest,
      tileX,
      tileY,
      chunkX: chunkAt(nextX),
      chunkY: chunkAt(nextY),
      spaceId,
    };
    ctx.db.world_chest.id.update(moved);
    syncLegacyChestGenericMirror(ctx, moved);
  }
  for (const target of ctx.db.world_combat_target.by_carrier.filter(position.identity)) {
    moveEmbeddedArrowsWithTarget(ctx, target, nextX, nextY, spaceId);
    ctx.db.world_combat_target.id.update({
      ...target,
      x: nextX,
      y: nextY,
      chunkX: chunkAt(nextX),
      chunkY: chunkAt(nextY),
      spaceId,
    });
  }
  for (const placeable of ctx.db.world_placeable.by_carrier.filter(position.identity)) {
    const tileX = Math.floor(nextX / TILE_SIZE_FIXED);
    const tileY = Math.floor(nextY / TILE_SIZE_FIXED);
    ctx.db.world_placeable.id.update({
      ...placeable,
      tileX,
      tileY,
      chunkX: chunkAt(nextX),
      chunkY: chunkAt(nextY),
      spaceId,
    });
  }
  const mount = mountedNpcFor(ctx, position.identity);
  if (mount !== null) {
    updateWorldNpc(ctx, {
      ...mount,
      x: nextX,
      y: nextY,
      homeX: nextX,
      homeY: nextY,
      chunkX: chunkAt(nextX),
      chunkY: chunkAt(nextY),
      spaceId,
      moving: false,
      wanderDirection: 'idle',
      authorityTick,
    });
    const wildlife = ctx.db.world_wildlife_profile.npcId.find(mount.id);
    if (wildlife !== null) ctx.db.world_wildlife_profile.npcId.update({
      ...wildlife,
      chunkX: chunkAt(nextX),
      chunkY: chunkAt(nextY),
      spaceId,
    });
  }
  ctx.db.active_chest.identity.delete(position.identity);
  clearActivePlaceable(ctx, position.identity);
  ctx.db.active_dialogue.identity.delete(position.identity);
  refreshPlayerQuestLocations(ctx, nextPosition, authorityTick);
}

/** Lobby travel preserves the ordinary portal transaction, but requires a
 * clear physical approach and exact landing before changing space or custody. */
function prepareHearthLobbyPortal(ctx:WorldReducerContext,position:PlayerPositionRow,
  portal:{fromSpace:number;fromTileX:number;fromTileY:number;toSpace:number;toTileX:number;toTileY:number}):void{
  if(position.spaceId!==portal.fromSpace)throw new SenderError('portal_out_of_range');
  if(rogueRunForIdentity(ctx,position.identity)!==null)throw new SenderError('descent_already_active');
  if(handsOccupiedFor(ctx,position.identity))throw new SenderError('hands_occupied');
  if(mountedNpcFor(ctx,position.identity)!==null)throw new SenderError('mounted_action_forbidden');
  const source=collisionForSpace(ctx,portal.fromSpace),destination=collisionForSpace(ctx,portal.toSpace);
  const landing={x:(portal.toTileX+.5)*TILE_SIZE_FIXED,y:(portal.toTileY+.5)*TILE_SIZE_FIXED};
  if(!hearthLobbyPortalApproachClear(position,portal,source))
    throw new SenderError('portal_out_of_range');
  if(positionCollides(landing,destination))throw new SenderError('portal_landing_blocked');
  const tick=ctx.db.world_clock.id.find(0)?.authorityTick??position.authorityTick;
  if(advancePlayerStats(ctx,position.identity,tick).healthCenti<=0)throw new SenderError('player_not_ready');
  if(runtimeHearthLobbyDefinition(contentRegistry(ctx),portal.toSpace)!==null)ensureArcheryTargets(ctx);
  clearBowCharge(ctx,position.identity);
  updateEquippedForIdentity(ctx,position.identity);
}

function usePortalRow(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  portal: NonNullable<ReturnType<WorldReducerContext['db']['space_portal']['id']['find']>>,
  requireRange: boolean,
): void {
  const sourceHomestead = homesteadForSpace(ctx, portal.fromSpace);
  const destinationHomestead = homesteadForSpace(ctx, portal.toSpace);
  const source = activeSpaceDefinition(ctx, portal.fromSpace, sourceHomestead);
  const destination = activeSpaceDefinition(ctx, portal.toSpace, destinationHomestead);
  if (source === undefined || destination === undefined) throw new SenderError('portal_destination_unavailable');
  const registry=contentRegistry(ctx);
  const sourceLobby=runtimeHearthLobbyDefinition(registry,source.spaceId);
  const destinationLobby=runtimeHearthLobbyDefinition(registry,destination.spaceId);
  if((source.generator==='delve_lobby'&&sourceLobby===null)
    ||(destination.generator==='delve_lobby'&&destinationLobby===null)){
    throw new SenderError('portal_destination_unavailable');
  }
  const lobbyPortal=sourceLobby!==null||destinationLobby!==null;
  if(lobbyPortal)prepareHearthLobbyPortal(ctx,position,portal);
  const mount = mountedNpcFor(ctx, position.identity);
  const mounted = mount !== null;
  if (runtimeNpcMount(contentRegistry(ctx), mount)?.adapter === 'boat') throw new SenderError('boat_cannot_use_portal');
  const allowMounted = mounted
    && (source.generator === 'island' || source.generator === 'homestead')
    && (destination.generator === 'island' || destination.generator === 'homestead');
  if (requireRange && !lobbyPortal) {
    const result = portalUseResult(position, portal, mounted, allowMounted);
    if (result !== 'ok') throw new SenderError(result);
  } else if (mounted && !allowMounted) {
    throw new SenderError('no_horses_underground');
  }
  if (destinationHomestead !== null && portal.toSpace === destinationHomestead.spaceId
    && homesteadRoleFor(ctx, destinationHomestead, position.identity) === null
    && !destinationHomestead.gateOpen) {
    throw new SenderError('homestead_private');
  }
  if (destinationHomestead !== null && portal.toSpace === destinationHomestead.spaceId) {
    const exitPortal = ctx.db.space_portal.id.find(destinationHomestead.spaceId * 2 + 1);
    if (exitPortal !== null && (exitPortal.fromTileX !== HOMESTEAD_EXIT_TILE.tileX
      || exitPortal.fromTileY !== HOMESTEAD_EXIT_TILE.tileY)) {
      ctx.db.space_portal.id.update({
        ...exitPortal,
        fromTileX: HOMESTEAD_EXIT_TILE.tileX,
        fromTileY: HOMESTEAD_EXIT_TILE.tileY,
      });
    }
  }
  teleportPlayer(
    ctx,
    position,
    portal.toSpace,
    portal.toTileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
    portal.toTileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
  );
  if (portal.toSpace === MARLOW_TENT_SPACE_ID) {
    const flag = 'marlow_tent_bigger_inside';
    const flagId = JSON.stringify([position.identity.toHexString(), flag]);
    if (ctx.db.player_quest_flag.id.find(flagId) === null) {
      const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? position.authorityTick;
      ctx.db.player_quest_flag.insert({ id: flagId, identity: position.identity, flag });
      const thought = {
        identity: position.identity,
        body: 'Hey, it\'s bigger on the inside.',
        tone: 'thought',
        issuedTick: authorityTick,
        expiresTick: authorityTick + BigInt(AUTHORITY_HZ * 6),
      };
      if (ctx.db.player_thought.identity.find(position.identity) === null) ctx.db.player_thought.insert(thought);
      else ctx.db.player_thought.identity.update(thought);
    }
  }
}

interface PrefetchedSpaceCollisionRows {
  readonly resources: readonly WorldResourceRow[];
  readonly chests: readonly WorldChestRow[];
  readonly combatTargets: readonly WorldCombatTargetRow[];
  readonly chunkScope?: ReadonlySet<string>;
}

function collisionForSpace(
  ctx: WorldReducerContext,
  spaceId: number,
  excludedHomesteadSpaceId?: number,
  prefetchedRows?: PrefetchedSpaceCollisionRows,
  prefetchedLiveMapRuntime?: LiveIslandCollisionRuntime | null,
  excludeFurniture = false,
  residenceExpansionRank?: number,
  excludeArchitecture = false,
) {
  const unifiedChestReads = chestMigrationReadsUsePlaceables(ctx);
  const liveMapRuntime = prefetchedLiveMapRuntime === undefined
    ? spaceId === TOPSIDE_SPACE_ID ? liveIslandCollisionRuntime(ctx) : null
    : prefetchedLiveMapRuntime;
  const resources = prefetchedRows?.resources
    ?? [...ctx.db.world_resource.by_chunk.filter(spaceId)];
  const chests = prefetchedRows?.chests
    ?? [...ctx.db.world_chest.by_chunk.filter(spaceId)];
  const combatTargets = prefetchedRows?.combatTargets
    ?? [...ctx.db.world_combat_target.by_chunk.filter(spaceId)];
  const placeableRows = [...ctx.db.world_placeable.by_chunk.filter(spaceId)]
    .filter((row) => row.carriedBy === undefined
      && (!genericChest(ctx, row) || unifiedChestReads
        || ctx.db.chest_migration_mapping.placeableId.find(row.id) === null));
  const placeables = placeableRows
    .filter((row) => hearthFurnitureShapeForPlaceable(contentRegistry(ctx), row) === null)
    .flatMap((row) => {
      const collision = authoredPlaceableDefinition(ctx, row)?.components.collision;
      const footprint = collision?.footprint ?? [[15]];
      const height = footprint.length;
      const width = footprint[0]?.length ?? 1;
      const tiles = homesteadBuildFootprintTiles({ footprint: { width, height } }, row.tileX, row.tileY);
      return tiles.flatMap((tile, index) => (footprint[Math.floor(index / width)]?.[index % width] ?? 0) === 0
        ? [] : [{
          ...tile,
          blocksMovement: runtimePlaceableBlocksMovement(contentRegistry(ctx), row),
        }]);
    });
  const persistedInstance = instanceForSpace(ctx, spaceId);
  const instance = excludeArchitecture && persistedInstance != null
    ? {...persistedInstance, residenceArchitectureJson: EMPTY_HEARTH_ARCHITECTURE_JSON} : persistedInstance;
  const collision = liveMapCollisionForSpace(ctx, spaceId, 'ground', createAuthoritySpaceCollisionMap(
    contentRegistry(ctx),
    spaceId,
    resources.filter((resource) => (
      !liveMapRuntimeGeneratedResourceSuppressed(liveMapRuntime, resource.id)
    )),
    chests.filter((chest) => (
      !unifiedChestReads || ctx.db.chest_migration_mapping.chestId.find(chest.id) === null
    )),
    'ground',
    placeables,
    residenceExpansionRank === undefined || instance == null ? instance : {...instance, residenceExpansionRank},
    [...ctx.db.cellar_excavation.by_space.filter(spaceId)],
  ), liveMapRuntime);
  // Topside collision includes every homestead tent. Instanced homestead
  // exteriors have a unique space id, so their equivalent lookup is indexed.
  const indexedHome = spaceId === TOPSIDE_SPACE_ID
    ? null
    : ctx.db.homestead.spaceId.find(spaceId);
  const homes = spaceId === TOPSIDE_SPACE_ID
    ? [...ctx.db.homestead.iter()].filter((home) => home.spaceId !== excludedHomesteadSpaceId)
    : indexedHome === null ? [] : [indexedHome];
  const obstacles = [...(collision.obstacles ?? [])];
  for (const row of excludeFurniture ? [] : placeableRows) {
    const shape = hearthFurnitureShapeForPlaceable(contentRegistry(ctx), row);
    if (shape === null) continue;
    const obstacle = hearthFurnitureObstacle({ id: row.id.toString(), shape, tileX: row.tileX, tileY: row.tileY });
    if (obstacle !== null) obstacles.push(obstacle);
  }
  for (const target of combatTargets) {
    if (target.carriedBy !== undefined || activeCombatTargetHealth(ctx, target) === null) continue;
    const tile = combatTargetTile(target);
    obstacles.push({
      left: tile.tileX * TILE_SIZE_FIXED,
      top: tile.tileY * TILE_SIZE_FIXED,
      right: (tile.tileX + 1) * TILE_SIZE_FIXED - 1,
      bottom: (tile.tileY + 1) * TILE_SIZE_FIXED - 1,
    });
  }
  for (const surface of ctx.db.world_surface.by_chunk.filter(spaceId)) {
    const obstacle = runtimeSpaceSurfaceObstacle(contentRegistry(ctx), surface);
    if (obstacle !== null) obstacles.push(obstacle);
  }
  const spaceDefinition = activeSpaceDefinition(ctx, spaceId, instanceForSpace(ctx, spaceId));
  for (const tile of interiorFurnitureBlockingTiles(spaceDefinition?.generator ?? 'debug_flat')) {
    obstacles.push({
      left: tile.tileX * TILE_SIZE_FIXED,
      top: tile.tileY * TILE_SIZE_FIXED,
      right: (tile.tileX + 1) * TILE_SIZE_FIXED - 1,
      bottom: (tile.tileY + 1) * TILE_SIZE_FIXED - 1,
    });
  }
  for (const home of homes) {
    const interior = spaceId !== TOPSIDE_SPACE_ID;
    const footprint = homesteadTentFootprint(
      interior ? HOMESTEAD_TENT_TILE.tileX : home.overworldTileX,
      interior ? HOMESTEAD_TENT_TILE.tileY : home.overworldTileY,
      interior,
    );
    obstacles.push({
      left: footprint.minX * TILE_SIZE_FIXED, top: footprint.minY * TILE_SIZE_FIXED,
      right: (footprint.maxX + 1) * TILE_SIZE_FIXED - 1,
      bottom: (footprint.maxY + 1) * TILE_SIZE_FIXED - 1,
    });
  }
  if (spaceId !== TOPSIDE_SPACE_ID && homes.length > 0) {
    const definition = activeSpaceDefinition(ctx, spaceId, homes[0]);
    for (const tile of homesteadBoundaryTiles(definition?.sizeTiles)) {
      if (tile.kind === 'gate' && homes[0]?.gateOpen) continue;
      obstacles.push({
        left: tile.tileX * TILE_SIZE_FIXED, top: tile.tileY * TILE_SIZE_FIXED,
        right: (tile.tileX + 1) * TILE_SIZE_FIXED - 1,
        bottom: (tile.tileY + 1) * TILE_SIZE_FIXED - 1,
      });
    }
  }
  const scoped = collisionWithinChunkScope({ ...collision, obstacles }, prefetchedRows?.chunkScope);
  return runtimeActorCollision(contentRegistry(ctx), scoped, { kind: 'placement', medium: 'ground' }, ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n);
}

function waterCollisionForSpace(
  ctx: WorldReducerContext,
  spaceId: number,
  prefetchedLiveMapRuntime?: LiveIslandCollisionRuntime | null,
  chunkScope?: ReadonlySet<string>,
  groundGeometry?: CollisionMap,
) {
  const scoped = collisionWithinChunkScope(
    liveMapCollisionForSpace(ctx, spaceId, 'water', createAuthoritySpaceCollisionMap(
      contentRegistry(ctx), spaceId, [], [], 'water', [], instanceForSpace(ctx, spaceId),
    ), prefetchedLiveMapRuntime),
    chunkScope,
  );
  const registry = contentRegistry(ctx);
  const geometry = runtimeTraversalPolicy(registry) === null ? scoped
    : traversalSolidGeometry(groundGeometry ?? collisionForSpace(ctx, spaceId), scoped);
  return runtimeActorCollision(registry, scoped, { kind: 'placement', medium: 'water' }, ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n, geometry);
}

function nextBoatNpcId(ctx: WorldReducerContext): bigint {
  for (let id = BOAT_FIRST_NPC_ID; id <= BOAT_LAST_NPC_ID; id += 1n) {
    if (ctx.db.world_npc.id.find(id) === null) return id;
  }
  throw new SenderError('too_many_boats');
}

function requireBoatPlacementTile(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  tileX: number,
  tileY: number,
): void {
  const water = waterCollisionForSpace(ctx, position.spaceId);
  const placement = tilePlacementResult(
    position.x,
    position.y,
    tileX,
    tileY,
    water,
    tileOverlapsAnyOtherPlayer(ctx, position.identity, position.spaceId, tileX, tileY),
  );
  if (placement === 'invalid_tile') throw new SenderError('invalid_boat_tile');
  if (placement === 'out_of_range') throw new SenderError('boat_out_of_range');
  if (placement === 'tile_blocked') throw new SenderError('boat_requires_water');
  const center = {
    x: tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
    y: tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
  };
  if (positionCollides(center, water)) throw new SenderError('boat_requires_water');
  for (const npc of ctx.db.world_npc.by_chunk.filter(position.spaceId)) {
    if (runtimeNpcMount(contentRegistry(ctx), npc)?.adapter === 'boat' && Math.floor(npc.x / TILE_SIZE_FIXED) === tileX
      && Math.floor(npc.y / TILE_SIZE_FIXED) === tileY) throw new SenderError('boat_tile_occupied');
  }
}

function sinkBoat(
  ctx: WorldReducerContext,
  boat: WorldNpcRow,
  authorityTick: bigint,
  ground: CollisionMap,
): void {
  if (boat.rider !== undefined) {
    const rider = ctx.db.player_position.identity.find(boat.rider);
    if (rider !== null) {
      const landing = findBoatDismountPosition(
        { x: boat.x, y: boat.y },
        boatFacingForDirection(parseDirection(boat.facing) ?? 'right'),
        runtimeActorCollision(contentRegistry(ctx), ground, { kind: 'player',
          effects: [...ctx.db.player_effect.by_identity.filter(rider.identity)] }, authorityTick,
          traversalSolidGeometry(ground, waterCollisionForSpace(ctx, rider.spaceId))),
      ) ?? { x: boat.homeX, y: boat.homeY };
      ctx.db.player_position.identity.update({
        ...rider,
        x: landing.x,
        y: landing.y,
        chunkX: chunkAt(landing.x),
        chunkY: chunkAt(landing.y),
        moving: false,
        actionKind: 'none',
        actionStartedTick: authorityTick,
        authorityTick,
      });
    }
  }
  ctx.db.world_npc.id.delete(boat.id);
}

function homesteadForOwner(ctx: IndexedLookupContext, owner: WorldReducerContext['sender']) {
  return firstIndexRow(ctx.db.homestead.by_owner.filter(owner));
}

function homesteadForSpace(ctx: IndexedLookupContext, spaceId: number) {
  const exterior = ctx.db.homestead.spaceId.find(spaceId);
  if (exterior !== null) return exterior;
  const residence = firstIndexRow(ctx.db.homestead.by_residence_space.filter(spaceId));
  if (residence !== null || spaceId === 0) return residence;
  return firstIndexRow(ctx.db.homestead.by_residence_space.filter(spaceId - 1));
}

function rogueRunForSpace(ctx: WorldReducerContext, spaceId: number): RogueRunRow | null {
  return firstIndexRow(ctx.db.rogue_run.by_space.filter(spaceId));
}

function instanceForSpace(ctx: WorldReducerContext, spaceId: number) {
  return rogueRunForSpace(ctx, spaceId) ?? homesteadForSpace(ctx, spaceId);
}

function rogueRunForIdentity(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): RogueRunRow | null {
  const member = ctx.db.rogue_run_member.identity.find(identity);
  return member === null ? null : ctx.db.rogue_run.id.find(member.runId);
}

function requireInventoryProtocol(ctx: WorldReducerContext): void {
  const acknowledgement = ctx.connectionId === null ? null
    : ctx.db.inventory_protocol.connectionId.find(ctx.connectionId);
  if (acknowledgement === null || !acknowledgement.identity.isEqual(ctx.sender)
    || acknowledgement.version !== CURRENT_INVENTORY_PROTOCOL_VERSION) {
    throw new SenderError('inventory_client_update_required');
  }
}

export const acknowledgeInventoryProtocol = spacetimedb.reducer(
  { version: t.u16() },
  (ctx, { version }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    if (version !== CURRENT_INVENTORY_PROTOCOL_VERSION || ctx.connectionId === null) {
      throw new SenderError('inventory_client_update_required');
    }
    const row = { connectionId: ctx.connectionId, identity: ctx.sender, version };
    const existing = ctx.db.inventory_protocol.connectionId.find(ctx.connectionId);
    if (existing === null) ctx.db.inventory_protocol.insert(row);
    else ctx.db.inventory_protocol.connectionId.update(row);
  },
);

function requirePersistentInventoryAvailable(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): void {
  requireInventoryProtocol(ctx);
  if (rogueRunForIdentity(ctx, identity) !== null) throw new SenderError('descent_inventory_locked');
}

function isRogueRoomKind(value: string): value is RogueRoomKind {
  return value === 'combat' || value === 'elite' || value === 'shop'
    || value === 'recovery' || value === 'treasure' || value === 'boss';
}

function nextRogueSpaceId(ctx: WorldReducerContext): number {
  const staticIds = new Set(contentRegistry(ctx).compiled.spaces.map(space => space.spaceId));
  for (let spaceId = FIRST_ROGUE_SPACE_ID; spaceId <= LAST_ROGUE_SPACE_ID; spaceId += 1) {
    if (staticIds.has(spaceId)) continue;
    if (rogueRunForSpace(ctx, spaceId) === null && homesteadForSpace(ctx, spaceId) === null) return spaceId;
  }
  throw new SenderError('descent_capacity_reached');
}

function clearRogueRoomRows(ctx: WorldReducerContext, run: RogueRunRow): void {
  for (const exit of [...ctx.db.rogue_room_exit.by_run.filter(run.id)]) {
    ctx.db.rogue_room_exit.id.delete(exit.id);
  }
  for (const offer of [...ctx.db.rogue_reward_offer.by_run.filter(run.id)]) {
    ctx.db.rogue_reward_offer.id.delete(offer.id);
  }
  for (const profile of [...ctx.db.rogue_enemy_profile.by_run.filter(run.id)]) {
    ctx.db.world_npc.id.delete(profile.npcId);
    ctx.db.enemy_attack.npcId.delete(profile.npcId);
    ctx.db.rogue_enemy_profile.npcId.delete(profile.npcId);
  }
  for (const projectile of [...ctx.db.world_projectile.by_chunk.filter(run.spaceId)]) {
    ctx.db.projectile_charge.projectileId.delete(projectile.id);
    ctx.db.world_projectile.id.delete(projectile.id);
  }
}

function insertRogueExits(ctx: WorldReducerContext, run: RogueRunRow): void {
  for (const exit of generateRogueRoomExits(run.seed, run.roomNumber)) {
    ctx.db.rogue_room_exit.insert({
      id: `${run.id}:${run.roomNumber}:${exit.slot}`,
      runId: run.id,
      slot: exit.slot,
      direction: exit.direction,
      destinationKind: exit.destinationKind,
      label: exit.label,
      tileX: exit.tileX,
      tileY: exit.tileY,
    });
  }
}

function insertRogueOffers(ctx: WorldReducerContext, run: RogueRunRow): void {
  const kind = isRogueRoomKind(run.roomKind) ? run.roomKind : 'combat';
  for (const offer of generateRogueUpgradeOffers(run.seed, run.roomNumber, kind,contentRegistry(ctx))) {
    ctx.db.rogue_reward_offer.insert({
      id: `${run.id}:${run.roomNumber}:${offer.slot}`,
      runId: run.id,
      slot: offer.slot,
      upgradeId: offer.upgradeId,
      rarity: offer.rarity,
      magnitudePermille: offer.magnitudePermille,
      cost: offer.cost,
    });
  }
}

function rogueNpcId(run: RogueRunRow, wave: number, slot: number): bigint {
  return ROGUE_NPC_ID_BASE + run.id * 10_000n
    + BigInt(run.roomNumber) * 500n + BigInt(wave) * 20n + BigInt(slot);
}

function spawnRogueWave(
  ctx: WorldReducerContext,
  run: RogueRunRow,
  wave: number,
  authorityTick: bigint,
): void {
  const kind = isRogueRoomKind(run.roomKind) ? run.roomKind : 'combat';
  const layout = generateRogueRoomLayout(run.seed, run.roomNumber, kind);
  const enemies = generateRogueWave(run.seed, run.roomNumber, kind, wave, contentRegistry(ctx));
  enemies.forEach((enemy, index) => {
    const spawn = layout.enemySpawns[index % layout.enemySpawns.length] ?? { tileX: 16, tileY: 10 };
    const x = spawn.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
    const y = spawn.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
    const npcId = rogueNpcId(run, wave, index);
    ctx.db.world_npc.insert({
      id: npcId,
      kind: enemy.kind,
      displayName: enemy.displayName,
      x, y, homeX: x, homeY: y,
      chunkX: chunkAt(x), chunkY: chunkAt(y), facing: 'down', moving: false,
      rider: undefined, wanderDirection: 'alert', nextDecisionTick: authorityTick,
      authorityTick, health: enemy.health, spaceId: run.spaceId,
      lastHitCritical: false, panicUntilTick: undefined, panicSource: undefined,
      panicSourceX: 0, panicSourceY: 0,
    });
    ctx.db.rogue_enemy_profile.insert({
      npcId, runId: run.id, archetype: enemy.archetype, maxHealth: enemy.health,
      damage: enemy.damage, speedPermille: enemy.speedPermille, wave,
      rewardCurrency: kind === 'boss' ? 12 : kind === 'elite' ? 6 : 2,
      nextAttackTick: authorityTick + ROGUE_ENEMY_ATTACK_INTERVAL_TICKS,
      chunkX: chunkAt(x), chunkY: chunkAt(y), spaceId: run.spaceId,
    });
  });
}

function beginRogueReward(
  ctx: WorldReducerContext,
  run: RogueRunRow,
  authorityTick: bigint,
): RogueRunRow {
  for (const offer of [...ctx.db.rogue_reward_offer.by_run.filter(run.id)]) {
    ctx.db.rogue_reward_offer.id.delete(offer.id);
  }
  const next = { ...run, phase: 'reward', updatedTick: authorityTick };
  ctx.db.rogue_run.id.update(next);
  insertRogueOffers(ctx, next);
  return next;
}

function initializeRogueRoom(
  ctx: WorldReducerContext,
  run: RogueRunRow,
  requestedKind: RogueRoomKind,
  authorityTick: bigint,
): RogueRunRow {
  clearRogueRoomRows(ctx, run);
  const roomKind = rogueRoomKindFor(run.roomNumber, requestedKind);
  const theme = rogueThemeForRoom(run.roomNumber);
  const maximumWaves = rogueWaveCount(run.roomNumber, roomKind);
  let next: RogueRunRow = {
    ...run, roomKind, theme, phase: maximumWaves > 0 ? 'combat' : 'reward',
    wave: 0, maximumWaves, updatedTick: authorityTick,
  };
  ctx.db.rogue_run.id.update(next);
  if (maximumWaves > 0) {
    spawnRogueWave(ctx, next, 0, authorityTick);
  } else if (roomKind === 'recovery') {
    for (const member of ctx.db.rogue_run_member.by_run.filter(run.id)) {
      const stats = ctx.db.player_stats.identity.find(member.identity);
      if (stats === null) continue;
      const resolved = resolvedStatsForRow(ctx, stats, member.identity, authorityTick);
      ctx.db.player_stats.identity.update({
        ...stats,
        healthCenti: Math.min(
          resolved.maxHealthCenti,
          stats.healthCenti + Math.ceil(resolved.maxHealthCenti * 35 / 100),
        ),
        regenTick: authorityTick,
      });
    }
    next = { ...next, phase: 'doors' };
    ctx.db.rogue_run.id.update(next);
    insertRogueExits(ctx, next);
  } else {
    insertRogueOffers(ctx, next);
  }
  return next;
}

/** Receipt is independent of active content, so retirement never traps a player in a run. */
function syncDelveCompletionKeepsake(
  ctx: WorldReducerContext, identity: WorldReducerContext['sender'], authorityTick: bigint,
): void {
  const identityHex = identity.toHexString();
  const receipt = ctx.db.player_quest_flag.id.find(`${identityHex}:${DELVE_COMPLETION_FLAG}`);
  const total = delveCompletionTotal(receipt?.flag);
  if (total === 0n) return;
  const registry = contentRegistry(ctx);
  const statistic = runtimeStatisticDefinition(registry, DELVE_COMPLETION_STATISTIC);
  if (statistic !== null && statistic.reserved !== true && statistic.aggregation === 'counter'
    && statistic.subject === 'none') {
    const previous = ctx.db.player_statistic.id.find(playerStatisticRowId(identityHex, DELVE_COMPLETION_STATISTIC, ''))?.value ?? 0n;
    if (total > previous) recordPlayerStatistic(ctx, identity, DELVE_COMPLETION_STATISTIC, total - previous, authorityTick);
  }
  const recipe = delveCompletionRecipe(registry);
  if (recipe === null) return;
  const recipeId = recipe.id.slice('recipe:'.length);
  const id = `${identityHex}:${recipeId}`;
  if (ctx.db.player_known_recipe.id.find(id) !== null) return;
  ctx.db.player_known_recipe.insert({ id, identity, recipeId, learnedAtTick: authorityTick,
    sourceKind: 'delve_completion' });
  const learnedStatistic = runtimeStatisticDefinition(registry, 'recipes_learned');
  if (learnedStatistic !== null && learnedStatistic.reserved !== true
    && learnedStatistic.aggregation === 'counter' && learnedStatistic.subject === 'none') {
    recordPlayerStatistic(ctx, identity, 'recipes_learned', 1n, authorityTick);
  }
}

function recordDelveCompletion(
  ctx: WorldReducerContext, identity: WorldReducerContext['sender'], authorityTick: bigint,
): void {
  const id = `${identity.toHexString()}:${DELVE_COMPLETION_FLAG}`;
  const previous = ctx.db.player_quest_flag.id.find(id);
  const total = delveCompletionTotal(previous?.flag);
  const next = total < (1n << 64n) - 1n ? total + 1n : total;
  const row = { id, identity, flag: `${DELVE_COMPLETION_FLAG}:${next}` };
  if (previous === null) ctx.db.player_quest_flag.insert(row);
  else ctx.db.player_quest_flag.id.update(row);
  syncDelveCompletionKeepsake(ctx, identity, authorityTick);
}

function finishRogueRun(ctx: WorldReducerContext, run: RogueRunRow): void {
  // The stored run, not a stale caller snapshot, controls reward and cleanup.
  const stored = ctx.db.rogue_run.id.find(run.id);
  if (stored === null) return;
  run = stored;
  const victorious = run.phase === 'complete' && run.roomNumber === ROGUE_RUN_ROOM_COUNT - 1
    && run.roomKind === 'boss';
  const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? run.updatedTick;
  clearRogueRoomRows(ctx, run);
  for (const upgrade of [...ctx.db.rogue_run_upgrade.by_run.filter(run.id)]) {
    ctx.db.rogue_run_upgrade.id.delete(upgrade.id);
  }
  for (const member of [...ctx.db.rogue_run_member.by_run.filter(run.id)]) {
    if (victorious) recordDelveCompletion(ctx, member.identity, authorityTick);
    const position = ctx.db.player_position.identity.find(member.identity);
    if (position !== null) teleportPlayer(
      ctx, position, member.returnSpaceId, member.returnX, member.returnY,
    );
    const restoredPosition = ctx.db.player_position.identity.find(member.identity);
    if (restoredPosition !== null && restoredPosition.facing !== member.returnFacing) {
      ctx.db.player_position.identity.update({ ...restoredPosition, facing: member.returnFacing });
    }
    const stats = ctx.db.player_stats.identity.find(member.identity);
    if (stats !== null) ctx.db.player_stats.identity.update({
      ...stats,
      healthCenti: member.savedHealthCenti,
      manaCenti: member.savedManaCenti,
      vigourCenti: member.savedVigourCenti,
      healthRemainder: member.savedHealthRemainder,
      manaRemainder: member.savedManaRemainder,
      vigourRemainder: member.savedVigourRemainder,
      regenTick: authorityTick,
    });
    const survival = ctx.db.player_survival.identity.find(member.identity);
    if (survival !== null) ctx.db.player_survival.identity.update({
      ...survival, hungerCenti: member.savedHungerCenti, hungerUpdatedTick: authorityTick,
    });
    ctx.db.bow_charge.identity.delete(member.identity);
    ctx.db.rogue_run_member.identity.delete(member.identity);
  }
  ctx.db.rogue_run.id.delete(run.id);
}

function completeRogueEnemyDefeat(
  ctx: WorldReducerContext,
  run: RogueRunRow,
  authorityTick: bigint,
): void {
  const liveEnemies = [...ctx.db.rogue_enemy_profile.by_run.filter(run.id)].some((profile) => (
    ctx.db.world_npc.id.find(profile.npcId)?.health !== 0
  ));
  if (liveEnemies) return;
  const nextWave = run.wave + 1;
  if (nextWave < run.maximumWaves) {
    const next = { ...run, wave: nextWave, updatedTick: authorityTick };
    ctx.db.rogue_run.id.update(next);
    spawnRogueWave(ctx, next, nextWave, authorityTick);
    return;
  }
  beginRogueReward(ctx, run, authorityTick);
}

function homesteadMemberId(spaceId: number, identityHex: string): string {
  return `${spaceId}:${identityHex}`;
}

function homesteadRoleFor(
  ctx: WorldReducerContext,
  home: HomesteadRow,
  identity: WorldReducerContext['sender'],
): HomesteadEffectiveRole | null {
  if (home.owner.isEqual(identity)) return 'owner';
  const member = ctx.db.homestead_guest.id.find(homesteadMemberId(home.spaceId, identity.toHexString()));
  return member !== null && isHomesteadMemberRole(member.role) ? member.role : null;
}

function homesteadUpgradeId(spaceId: number, upgradeKind: string): string {
  return `${spaceId}:${upgradeKind}`;
}

function homesteadUpgradeRank(
  ctx: WorldReducerContext,
  spaceId: number,
  mechanic: HomesteadUpgradeMechanic,
): number {
  const definition = runtimeUpgradeDefinitionForMechanic(contentRegistry(ctx), mechanic);
  if (definition === null) return 0;
  const upgradeKind = definition.mechanic[1];
  const rank = ctx.db.homestead_upgrade.id.find(homesteadUpgradeId(homesteadForSpace(ctx, spaceId)?.spaceId ?? spaceId, upgradeKind))?.rank;
  return rank !== undefined && rank <= definition.maximumRank ? rank : 0;
}

/** `tender` names whose farming skills shape the crop. Interactive paths use
 * the caller; unattended sweeps name the crop's own owner, since no player is
 * present to attribute the growth to. */
function cropDefinitionForHomestead(
  ctx: WorldReducerContext,
  spaceId: number,
  cropKind: string,
  tender?: WorldReducerContext['sender'],
) {
  const definition = runtimeCropDefinition(contentRegistry(ctx), cropKind);
  if (definition === null) return null;
  const rank = homesteadUpgradeRank(ctx, spaceId, 'soil');
  return farmingCropDefinition(rank === 0 ? definition : {
    ...definition,
    growthTicks: richSoilGrowthTicks(definition.growthTicks, rank),
  }, farmingSkillEffects(contentRegistry(ctx), playerSkillRanks(ctx,
    homesteadForSpace(ctx, spaceId)?.owner ?? tender ?? ctx.sender)));
}

function cropAutomaticallyWatered(
  ctx: WorldReducerContext,
  spaceId: number,
  tileX: number,
  tileY: number,
): boolean {
  const registry = contentRegistry(ctx);
  return [...ctx.db.world_placeable.by_chunk.filter(spaceId)].some((placeable) => (
    placeable.carriedBy === undefined
    && runtimeObjectIrrigatesTile(registry, placeable, tileX, tileY)
  ));
}

/** Rain is the world's own watering can. While a shower runs, every crop in an
 * open-air space — the island and every homestead — is topped up on the weather
 * sweep, so a farm left in the rain keeps growing. Growth is settled against
 * the lapsed window first, exactly as a player's watering can does, so the
 * fresh stamp never discards progress the previous window had earned. */
function waterCropsInTheRain(
  ctx: WorldReducerContext,
  authorityTick: bigint,
  counters: TickUpdateCounters,
): void {
  const registry = contentRegistry(ctx);
  const sweepTicks = BigInt(TREE_REGROWTH_SWEEP_TICKS);
  const calendarOffset = cropCalendarOffset(ctx);
  const rainReaches = new Map<number, boolean>();
  const greenhouses = new Map<number, boolean>();
  const irrigators = new Map<number, readonly WorldPlaceableRow[]>();
  for (const crop of ctx.db.world_crop.iter()) {
    recordTickRowScan(counters, 'soilRowsScanned');
    const soil = ctx.db.world_soil.id.find(crop.id);
    if (soil === null) continue;
    let reached = rainReaches.get(soil.spaceId);
    if (reached === undefined) {
      const space = activeSpaceDefinition(ctx, soil.spaceId, instanceForSpace(ctx, soil.spaceId));
      reached = space !== undefined
        && spaceReceivesRain(space, effectiveSpaceAdminBoolean(ctx, soil.spaceId, 'weather'));
      rainReaches.set(soil.spaceId, reached);
    }
    if (!reached) continue;
    const definition = cropDefinitionForHomestead(ctx, soil.spaceId, crop.cropKind, crop.owner);
    if (definition === null) continue;
    if (!rainWateringDue(soil, authorityTick, sweepTicks,
      definition.wateringTicks ?? CROP_WATERING_TICKS)) continue;
    let protectedSeasons = greenhouses.get(soil.spaceId);
    if (protectedSeasons === undefined) {
      protectedSeasons = cropGreenhouseProtected(ctx, soil.spaceId);
      greenhouses.set(soil.spaceId, protectedSeasons);
    }
    let spaceIrrigators = irrigators.get(soil.spaceId);
    if (spaceIrrigators === undefined) {
      spaceIrrigators = [...ctx.db.world_placeable.by_chunk.filter(soil.spaceId)]
        .filter((placeable) => placeable.carriedBy === undefined
          && runtimeObjectIrrigatesTile(registry, placeable, placeable.tileX, placeable.tileY));
      irrigators.set(soil.spaceId, spaceIrrigators);
    }
    const settled = cropGrowthAt(
      definition,
      crop.growthTicks,
      crop.growthUpdatedAtTick,
      soil.wateredAtTick,
      authorityTick,
      soil.watered,
      spaceIrrigators.some((placeable) => runtimeObjectIrrigatesTile(
        registry, placeable, crop.tileX, crop.tileY,
      )),
      calendarOffset,
      protectedSeasons,
    );
    ctx.db.world_crop.id.update({
      ...crop,
      growthTicks: settled.growthTicks,
      growthUpdatedAtTick: authorityTick,
    });
    ctx.db.world_soil.id.update({ ...soil, watered: true, wateredAtTick: authorityTick });
    recordTickRowTouch(counters, undefined, 2);
  }
}

/** A greenhouse is an estate-scale seasonal upgrade. Its authored building
 * footprint is solid and cannot contain farm tiles, so protecting the owning
 * Homestead avoids an unreachable "inside the footprint" planting rule. */
function cropGreenhouseProtected(ctx: WorldReducerContext, spaceId: number): boolean {
  const registry = contentRegistry(ctx);
  return homesteadForSpace(ctx, spaceId) !== null
    && [...ctx.db.world_placeable.by_chunk.filter(spaceId)].some((placeable) => (
      placeable.carriedBy === undefined
      && runtimeObjectProtectsCropSeasons(registry, placeable)
    ));
}

function cropCalendarOffset(ctx: WorldReducerContext): bigint {
  const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
  const environment = ctx.db.world_environment.id.find(0);
  return environment?.cropCalendarOffset
    ?? (environment?.calendarTick ?? authorityTick) - authorityTick;
}

function cropCalendarTick(ctx: WorldReducerContext): bigint {
  return (ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n) + cropCalendarOffset(ctx);
}

function worldSoilId(spaceId: number, tileX: number, tileY: number): string {
  return spaceId === TOPSIDE_SPACE_ID ? `${tileX}:${tileY}` : `${spaceId}:${tileX}:${tileY}`;
}

const SOIL_DECAY_TIMER_MIGRATION_VERSION = 1;

function scheduleEmptyTopsideSoilDecay(
  ctx: WorldReducerContext,
  soil: WorldSoilRow,
  currentTick: bigint,
): void {
  if (soil.spaceId !== TOPSIDE_SPACE_ID) return;
  const expectedDecayAtTick = emptySoilDecayAtTick(soil.tilledAtTick, soil.wateredAtTick);
  const remainingTicks = expectedDecayAtTick > currentTick ? expectedDecayAtTick - currentTick : 1n;
  ctx.db.soil_decay_timer.insert({
    scheduledId: 0n,
    scheduledAt: ScheduleAt.time(
      ctx.timestamp.microsSinceUnixEpoch + remainingTicks * AUTHORITY_TICK_MICROS,
    ),
    soilId: soil.id,
    expectedDecayAtTick,
  });
}

/** Additive publishes do not rerun init. This bounded migration is the only
 * full soil scan; normal farming schedules exact one-shot wake-ups instead. */
function ensureSoilDecayTimers(ctx: WorldReducerContext, currentTick: bigint): void {
  const migration = ctx.db.world_scalability_migration.id.find(0);
  if ((migration?.soilDecayTimerVersion ?? 0) >= SOIL_DECAY_TIMER_MIGRATION_VERSION) return;
  for (const soil of ctx.db.world_soil.iter()) {
    if (soil.spaceId !== TOPSIDE_SPACE_ID || ctx.db.world_crop.id.find(soil.id) !== null) continue;
    scheduleEmptyTopsideSoilDecay(ctx, soil, currentTick);
  }
  const nextMigration = {
    id: 0,
    wildlifeProfileChunkVersion: migration?.wildlifeProfileChunkVersion ?? 1,
    horseDismountRecoveryVersion: migration?.horseDismountRecoveryVersion ?? 0,
    soilDecayTimerVersion: SOIL_DECAY_TIMER_MIGRATION_VERSION,
    miningVersion: migration?.miningVersion ?? 0,
    privateStateVersion: migration?.privateStateVersion ?? 0,
    legacyFarmVersion: migration?.legacyFarmVersion ?? 0,
  };
  if (migration === null) ctx.db.world_scalability_migration.insert(nextMigration);
  else ctx.db.world_scalability_migration.id.update(nextMigration);
}

function validateFruitSeedPlacement(
  ctx: WorldReducerContext, position: PlayerPositionRow, tileX: number, tileY: number,
): void {
  requireWorldModificationAuthorized(ctx, position);
  if (ctx.db.world_resource.id.find(plantedFruitTreeId(position.spaceId, tileX, tileY)) !== null) {
    throw new SenderError('tile_blocked');
  }
  const result = tilePlacementResult(position.x, position.y, tileX, tileY,
    collisionForSpace(ctx, position.spaceId), tileOverlapsAnyPlayer(ctx, position.spaceId, tileX, tileY));
  if (result !== 'ok') throw new SenderError(result);
}

function mutableFarmTileAuthorized(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  tileX: number,
  tileY: number,
): boolean {
  if (position.spaceId === TOPSIDE_SPACE_ID) {
    return !activeWildlifeFeedReservedAt(ctx, tileX, tileY);
  }
  const home = homesteadForSpace(ctx, position.spaceId);
  return home !== null
    && home.spaceId === position.spaceId
    && homesteadRoleAtLeast(homesteadRoleFor(ctx, home, position.identity), 'worker')
    && homesteadPlayableTile(
      tileX,
      tileY,
      activeSpaceDefinition(ctx, position.spaceId, home)?.sizeTiles,
    );
}

/** Homesteads are private build authorities even while their entrance gate is
 * open. Visitors may enter and leave, but they cannot mutate the owner's
 * terrain, furniture, resources, or storage. */
function requireWorldModificationAuthorized(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
): void {
  requireCombatActionReady(ctx, position.identity, ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n);
  if (effectiveSpaceAdminBoolean(ctx, position.spaceId, 'buildAllowed') === false) {
    throw new SenderError('space_build_disabled');
  }
  if (position.spaceId === TOPSIDE_SPACE_ID) return;
  const home = homesteadForSpace(ctx, position.spaceId);
  if (home !== null && homesteadRoleAtLeast(homesteadRoleFor(ctx, home, position.identity), 'worker')) return;
  throw new SenderError('homestead_owner_required');
}

function spaceAdminFlags(ctx: Pick<WorldReducerContext, 'db'>, spaceId: number): AdminJsonObject {
  const row = ctx.db.space_admin_flag.spaceId.find(spaceId);
  if (row === null) return {};
  try {
    const parsed: unknown = JSON.parse(row.flagsJson);
    return parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)
      ? parsed as AdminJsonObject
      : {};
  } catch {
    return {};
  }
}

function effectiveSpaceAdminBoolean(
  ctx: Pick<WorldReducerContext, 'db'>,
  spaceId: number,
  key: 'ownerOnly' | 'weather' | 'buildAllowed',
): boolean | undefined {
  const value = spaceAdminFlags(ctx, spaceId)[key];
  return typeof value === 'boolean' ? value : undefined;
}

function nextResidenceSpacePair(ctx: WorldReducerContext): number {
  for (let spaceId = 30_000; spaceId < DEBUG_SPACE_ID - 1; spaceId += 2) {
    if (activeSpaceDefinition(ctx, spaceId) !== undefined
      || activeSpaceDefinition(ctx, spaceId + 1) !== undefined) continue;
    if (homesteadForSpace(ctx, spaceId) === null && homesteadForSpace(ctx, spaceId + 1) === null) return spaceId;
  }
  throw new SenderError('homestead_capacity_reached');
}

const HOMESTEAD_CHILD_PORTAL_BASE = 100_000_000;

function installHomesteadChildSpaces(ctx: WorldReducerContext): void {
  for (const existing of ctx.db.homestead.iter()) {
    let home = existing;
    if (home.residenceSpaceId === undefined) {
      home = { ...home, residenceSpaceId: nextResidenceSpacePair(ctx) };
      ctx.db.homestead.spaceId.update(home);
    }
    const residenceSpaceId = home.residenceSpaceId;
    if (residenceSpaceId === undefined) throw new SenderError('homestead_residence_unavailable');
    const cellarSpaceId = residenceSpaceId + 1;
    const base = HOMESTEAD_CHILD_PORTAL_BASE + home.spaceId * 4;
    const portals = [
      { id: base, kind: `residence_enter:${home.ownerName}`, fromSpace: home.spaceId,
        fromTileX: HOMESTEAD_TENT_TILE.tileX, fromTileY: HOMESTEAD_TENT_TILE.tileY,
        toSpace: residenceSpaceId, toTileX: RESIDENCE_ENTRY_TILE.tileX, toTileY: RESIDENCE_ENTRY_TILE.tileY },
      { id: base + 1, kind: `residence_exit:${home.ownerName}`, fromSpace: residenceSpaceId,
        fromTileX: RESIDENCE_EXIT_TILE.tileX, fromTileY: RESIDENCE_EXIT_TILE.tileY,
        toSpace: home.spaceId, toTileX: HOMESTEAD_TENT_TILE.tileX, toTileY: HOMESTEAD_TENT_TILE.tileY + 1 },
      { id: base + 2, kind: `cellar_enter:${home.ownerName}`, fromSpace: residenceSpaceId,
        fromTileX: RESIDENCE_TRAPDOOR_TILE.tileX, fromTileY: RESIDENCE_TRAPDOOR_TILE.tileY,
        toSpace: cellarSpaceId, toTileX: CELLAR_ENTRY_TILE.tileX, toTileY: CELLAR_ENTRY_TILE.tileY },
      { id: base + 3, kind: `cellar_exit:${home.ownerName}`, fromSpace: cellarSpaceId,
        fromTileX: CELLAR_EXIT_TILE.tileX, fromTileY: CELLAR_EXIT_TILE.tileY,
        toSpace: residenceSpaceId, toTileX: RESIDENCE_TRAPDOOR_TILE.tileX, toTileY: RESIDENCE_TRAPDOOR_TILE.tileY + 1 },
    ] as const;
    for (const portal of portals) {
      if (ctx.db.space_portal.id.find(portal.id) === null) ctx.db.space_portal.insert(portal);
      else ctx.db.space_portal.id.update(portal);
    }
  }
}

function nextHomesteadSpaceId(ctx: WorldReducerContext): number {
  const staticIds = new Set(contentRegistry(ctx).compiled.spaces.map(space => space.spaceId));
  for (let spaceId = FIRST_HOMESTEAD_SPACE_ID; spaceId < DEBUG_SPACE_ID; spaceId += 1) {
    if (staticIds.has(spaceId)) continue;
    if (spaceId >= FIRST_ROGUE_SPACE_ID && spaceId <= LAST_ROGUE_SPACE_ID) continue;
    if (homesteadForSpace(ctx, spaceId) === null) return spaceId;
  }
  throw new SenderError('homestead_capacity_reached');
}

function firstIndexRow<T>(rows: Iterable<T>): T | null {
  for (const row of rows) return row;
  return null;
}

function carriedChestFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
) {
  return firstIndexRow(ctx.db.world_chest.by_carrier.filter(identity));
}

function carriedCombatTargetFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
) {
  return firstIndexRow(ctx.db.world_combat_target.by_carrier.filter(identity));
}

function carriedPlaceableFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
) {
  return firstIndexRow(ctx.db.world_placeable.by_carrier.filter(identity));
}

function handsOccupiedFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): boolean {
  return carriedChestFor(ctx, identity) !== null
    || carriedCombatTargetFor(ctx, identity) !== null
    || carriedPlaceableFor(ctx, identity) !== null;
}

function mountedNpcFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
) {
  return firstIndexRow(ctx.db.world_npc.by_rider.filter(identity));
}

function horseAllowedInSpace(ctx: WorldReducerContext, spaceId: number): boolean {
  const definition = activeSpaceDefinition(ctx, spaceId, instanceForSpace(ctx, spaceId));
  return definition?.generator === 'island' || definition?.generator === 'homestead';
}

function updateWorldNpc(ctx: WorldReducerContext, row: WorldNpcRow): void {
  ctx.db.world_npc.id.update(row);
  const profile = ctx.db.world_wildlife_profile.npcId.find(row.id);
  if (profile !== null && (profile.chunkX !== row.chunkX || profile.chunkY !== row.chunkY
    || profile.spaceId !== row.spaceId)) {
    ctx.db.world_wildlife_profile.npcId.update({
      ...profile,
      chunkX: row.chunkX,
      chunkY: row.chunkY,
      spaceId: row.spaceId,
    });
  }
  const rogueProfile = ctx.db.rogue_enemy_profile.npcId.find(row.id);
  if (rogueProfile !== null && (rogueProfile.chunkX !== row.chunkX || rogueProfile.chunkY !== row.chunkY
    || rogueProfile.spaceId !== row.spaceId)) {
    ctx.db.rogue_enemy_profile.npcId.update({
      ...rogueProfile,
      chunkX: row.chunkX,
      chunkY: row.chunkY,
      spaceId: row.spaceId,
    });
  }
  const outdoorProfile = ctx.db.outdoor_enemy_profile.npcId.find(row.id);
  if (outdoorProfile !== null && (outdoorProfile.chunkX !== row.chunkX || outdoorProfile.chunkY !== row.chunkY
    || outdoorProfile.spaceId !== row.spaceId)) {
    ctx.db.outdoor_enemy_profile.npcId.update({
      ...outdoorProfile, chunkX: row.chunkX, chunkY: row.chunkY, spaceId: row.spaceId,
    });
  }
}

function recoverLegacyDismountHorses(ctx: WorldReducerContext, authorityTick: bigint): void {
  const migration = ctx.db.world_scalability_migration.id.find(0);
  if ((migration?.horseDismountRecoveryVersion ?? 0) >= 1) return;
  let allRecoverable = true;
  const starter = runtimeStarterHorseDefinition(contentRegistry(ctx));
  const recoveries = [
    ...(starter === null ? [] : [{ id: BigInt(starter.runtimeId), tileX: 334, tileY: 359 }]),
    { id: BigInt(WILDLIFE_FIRST_NPC_ID + 5), tileX: 335, tileY: 359 },
  ];
  for (const recovery of recoveries) {
    const horse = ctx.db.world_npc.id.find(recovery.id);
    if (horse === null || runtimeNpcMount(contentRegistry(ctx), horse)?.adapter !== 'horse') continue;
    if (horse.rider !== undefined) {
      allRecoverable = false;
      continue;
    }
    const x = recovery.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
    const y = recovery.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
    updateWorldNpc(ctx, {
      ...horse,
      x,
      y,
      homeX: x,
      homeY: y,
      chunkX: chunkAt(x),
      chunkY: chunkAt(y),
      spaceId: TOPSIDE_SPACE_ID,
      facing: 'down',
      moving: false,
      wanderDirection: 'rest',
      nextDecisionTick: authorityTick + 60n,
      authorityTick,
    });
  }
  if (!allRecoverable) return;
  const nextMigration = {
    id: 0,
    wildlifeProfileChunkVersion: migration?.wildlifeProfileChunkVersion ?? 1,
    horseDismountRecoveryVersion: 1,
    soilDecayTimerVersion: migration?.soilDecayTimerVersion ?? 0,
    miningVersion: migration?.miningVersion ?? 0,
    privateStateVersion: migration?.privateStateVersion ?? 0,
    legacyFarmVersion: migration?.legacyFarmVersion ?? 0,
  };
  if (migration === null) ctx.db.world_scalability_migration.insert(nextMigration);
  else ctx.db.world_scalability_migration.id.update(nextMigration);
}

const TICK_TELEMETRY_LOG_TICKS = 20n;
let tickTelemetryTicks = 0;
let tickTelemetryRowsTouched = 0;
let tickTelemetryPlayerPositionUpdates = 0;
let tickTelemetryPlayerPositionNoopSkips = 0;
let tickTelemetryNpcUpdates = 0;
let tickTelemetryNonWildlifeNpcUpdates = 0;
let tickTelemetryNonWildlifeNpcNoopSkips = 0;
let tickTelemetryChestUpdates = 0;
let tickTelemetryItemDeletes = 0;
let tickTelemetryAuditDeletes = 0;
let tickTelemetryRowsScanned = 0;
let tickTelemetryTradeRowsScanned = 0;
let tickTelemetryOverflowRowsScanned = 0;
let tickTelemetryRegrowthRowsScanned = 0;
let tickTelemetryEffectRowsScanned = 0;
let tickTelemetryInviteRowsScanned = 0;
let tickTelemetryItemRowsScanned = 0;
let tickTelemetryAuditRowsScanned = 0;
let tickTelemetrySpeechRowsScanned = 0;
let tickTelemetryObstacleTotal = 0;

function finishTickTelemetry(
  authorityTick: bigint,
  counters: ReturnType<typeof emptyTickUpdateCounters>,
  obstacleCount: number,
): void {
  tickTelemetryTicks += 1;
  tickTelemetryRowsTouched += counters.rowsTouched;
  tickTelemetryPlayerPositionUpdates += counters.playerPositionUpdates;
  tickTelemetryPlayerPositionNoopSkips += counters.playerPositionNoopSkips;
  tickTelemetryNpcUpdates += counters.npcUpdates;
  tickTelemetryNonWildlifeNpcUpdates += counters.nonWildlifeNpcUpdates;
  tickTelemetryNonWildlifeNpcNoopSkips += counters.nonWildlifeNpcNoopSkips;
  tickTelemetryChestUpdates += counters.chestUpdates;
  tickTelemetryItemDeletes += counters.itemDeletes;
  tickTelemetryAuditDeletes += counters.auditDeletes;
  tickTelemetryRowsScanned += counters.rowsScanned;
  tickTelemetryTradeRowsScanned += counters.tradeRowsScanned;
  tickTelemetryOverflowRowsScanned += counters.overflowRowsScanned;
  tickTelemetryRegrowthRowsScanned += counters.regrowthRowsScanned;
  tickTelemetryEffectRowsScanned += counters.effectRowsScanned;
  tickTelemetryInviteRowsScanned += counters.inviteRowsScanned;
  tickTelemetryItemRowsScanned += counters.itemRowsScanned;
  tickTelemetryAuditRowsScanned += counters.auditRowsScanned;
  tickTelemetrySpeechRowsScanned += counters.speechRowsScanned;
  tickTelemetryObstacleTotal += obstacleCount;
  if (authorityTick % TICK_TELEMETRY_LOG_TICKS === 0n) {
    console.info(JSON.stringify({
      event: 'tick_telemetry_1hz',
      ticks: tickTelemetryTicks,
      rowsTouched: tickTelemetryRowsTouched,
      playerPositionUpdates: tickTelemetryPlayerPositionUpdates,
      playerPositionNoopSkips: tickTelemetryPlayerPositionNoopSkips,
      npcUpdates: tickTelemetryNpcUpdates,
      nonWildlifeNpcUpdates: tickTelemetryNonWildlifeNpcUpdates,
      nonWildlifeNpcNoopSkips: tickTelemetryNonWildlifeNpcNoopSkips,
      chestUpdates: tickTelemetryChestUpdates,
      itemDeletes: tickTelemetryItemDeletes,
      auditDeletes: tickTelemetryAuditDeletes,
      rowsScanned: tickTelemetryRowsScanned,
      tradeRowsScanned: tickTelemetryTradeRowsScanned,
      overflowRowsScanned: tickTelemetryOverflowRowsScanned,
      regrowthRowsScanned: tickTelemetryRegrowthRowsScanned,
      effectRowsScanned: tickTelemetryEffectRowsScanned,
      inviteRowsScanned: tickTelemetryInviteRowsScanned,
      itemRowsScanned: tickTelemetryItemRowsScanned,
      auditRowsScanned: tickTelemetryAuditRowsScanned,
      speechRowsScanned: tickTelemetrySpeechRowsScanned,
      averageObstacleCount: tickTelemetryTicks === 0
        ? 0
        : Math.round(tickTelemetryObstacleTotal / tickTelemetryTicks),
      alertThresholdMs: 30,
      timingSpans: ['expiry', 'collision', 'projectiles', 'movement', 'npc'],
    }));
    tickTelemetryTicks = 0;
    tickTelemetryRowsTouched = 0;
    tickTelemetryPlayerPositionUpdates = 0;
    tickTelemetryPlayerPositionNoopSkips = 0;
    tickTelemetryNpcUpdates = 0;
    tickTelemetryNonWildlifeNpcUpdates = 0;
    tickTelemetryNonWildlifeNpcNoopSkips = 0;
    tickTelemetryChestUpdates = 0;
    tickTelemetryItemDeletes = 0;
    tickTelemetryAuditDeletes = 0;
    tickTelemetryRowsScanned = 0;
    tickTelemetryTradeRowsScanned = 0;
    tickTelemetryOverflowRowsScanned = 0;
    tickTelemetryRegrowthRowsScanned = 0;
    tickTelemetryEffectRowsScanned = 0;
    tickTelemetryInviteRowsScanned = 0;
    tickTelemetryItemRowsScanned = 0;
    tickTelemetryAuditRowsScanned = 0;
    tickTelemetrySpeechRowsScanned = 0;
    tickTelemetryObstacleTotal = 0;
  }
  if (authorityTick % TICK_TELEMETRY_LOG_TICKS === 0n) {
    console.timeEnd('step_world.tick');
  }
}

function tickStageTiming(enabled: boolean, stage: string, ending = false): void {
  if (!enabled) return;
  const label = `step_world.${stage}`;
  if (ending) console.timeEnd(label);
  else console.time(label);
}

const STATISTIC_TIME_FLUSH_TICKS = 20n;

function playerStatisticRowId(identityHex: string, kind: PlayerStatisticKind, subjectKind: string): string {
  return JSON.stringify([identityHex, kind, subjectKind]);
}

function playerStatisticMilestoneId(
  identityHex: string,
  kind: PlayerStatisticKind,
  subjectKind: string,
  threshold: bigint,
): string {
  return JSON.stringify([identityHex, kind, subjectKind, threshold.toString()]);
}

/** The only authority write path for lifetime statistics. Keeping this helper
 * typed means a reducer cannot silently create a misspelled permanent key. */
function recordPlayerStatistic(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  kind: PlayerStatisticKind,
  input: bigint,
  authorityTick: bigint,
  subjectKind = '',
): void {
  const definition = runtimeStatisticDefinition(contentRegistry(ctx), kind);
  if (definition === null) throw new Error(`unknown_player_statistic:${kind}`);
  if (definition.reserved === true) throw new Error(`reserved_statistic:${kind}`);
  if (!statisticSubjectIsValidForDefinition(definition, subjectKind)) {
    throw new Error(`invalid_statistic_subject:${kind}`);
  }
  if (input === 0n) return;
  const identityHex = identity.toHexString();
  const id = playerStatisticRowId(identityHex, kind, subjectKind);
  const existing = ctx.db.player_statistic.id.find(id);
  const previous = existing?.value ?? 0n;
  const value = statisticValueAfterDefinition(definition, previous, input);
  if (value === previous) return;
  if (existing === null) {
    ctx.db.player_statistic.insert({
      id, identity, statisticKind: kind, subjectKind, value,
      createdTick: authorityTick, updatedTick: authorityTick,
    });
  } else {
    ctx.db.player_statistic.id.update({ ...existing, value, updatedTick: authorityTick });
  }
  for (const threshold of statisticMilestonesCrossedForDefinition(definition, previous, value)) {
    const milestoneId = playerStatisticMilestoneId(identityHex, kind, subjectKind, threshold);
    if (ctx.db.player_statistic_milestone.id.find(milestoneId) !== null) continue;
    ctx.db.player_statistic_milestone.insert({
      id: milestoneId,
      identity,
      statisticKind: kind,
      subjectKind,
      threshold,
      achievedTick: authorityTick,
    });
  }
  refreshPlayerQuests(ctx, identity, authorityTick);
  raiseSenderBehaviourEvent(ctx, {
    type: 'statistic',
    actor: { entityType: 'player', id: identityHex },
    kind,
    ...(subjectKind === '' ? {} : { subject: subjectKind }),
    delta: value - previous,
  });
}

function playerQuestId(identityHex: string, questId: string): string {
  return JSON.stringify([identityHex, questId]);
}

function playerQuestBaselineId(identityHex: string, questId: string, objectiveId: string): string {
  return JSON.stringify([identityHex, questId, objectiveId]);
}

function playerSkillTrackId(identityHex: string, track: string): string {
  return JSON.stringify([identityHex, track]);
}

function playerSkillNodeId(identityHex: string, nodeId: string): string {
  return JSON.stringify([identityHex, nodeId]);
}

function ensurePlayerSkillTrack(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  track: SkillTrack,
) {
  const id = playerSkillTrackId(identity.toHexString(), track);
  const existing = ctx.db.player_skill_track.id.find(id);
  if (existing !== null) return existing;
  return ctx.db.player_skill_track.insert({
    id, identity, track, experience: 0n, spentPoints: 0, bonusPoints: 0, respecCount: 0,
  });
}

function grantSkillExperience(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  track: SkillTrack,
  amount: bigint,
): void {
  if (amount <= 0n) return;
  const progress = ensurePlayerSkillTrack(ctx, identity, track);
  const maximum = (1n << 64n) - 1n;
  ctx.db.player_skill_track.id.update({
    ...progress,
    experience: progress.experience >= maximum - amount ? maximum : progress.experience + amount,
  });
}

function playerSkillRanks(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): Readonly<Record<string, number>> {
  return Object.fromEntries(
    [...ctx.db.player_skill_node.by_identity.filter(identity)].map((row) => [row.nodeId, row.rank]),
  );
}

/** Skill branches are registry-owned. Re-homing a node (notably Mining from
 * Explorer to Farming) updates live rows and rebuilds each track's spent-point
 * total so old characters neither lose ranks nor pay from the wrong tree. */
function normalizePlayerSkillTracks(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): void {
  const spent = new Map<SkillTrack, number>([['combat', 0], ['explorer', 0], ['farming', 0]]);
  for (const row of ctx.db.player_skill_node.by_identity.filter(identity)) {
    const definition = runtimeSkillNodeDefinition(contentRegistry(ctx), row.nodeId);
    if (definition === null) continue;
    if (row.track !== definition.track) {
      ctx.db.player_skill_node.id.update({ ...row, track: definition.track });
    }
    spent.set(definition.track, (spent.get(definition.track) ?? 0) + definition.pointCost * row.rank);
  }
  for (const track of ['combat', 'explorer', 'farming'] as const) {
    const progress = ensurePlayerSkillTrack(ctx, identity, track);
    const spentPoints = Math.min(65_535, spent.get(track) ?? 0);
    if (progress.spentPoints !== spentPoints) {
      ctx.db.player_skill_track.id.update({ ...progress, spentPoints });
    }
  }
}

function questWorldItemId(identityHex: string, questId: string, objectiveId: string): string {
  return JSON.stringify([identityHex, questId, objectiveId]);
}

function residenceFurnishingFor(ctx:ContentReadContext & {readonly db:{
  readonly homestead:{readonly by_owner:Pick<WorldReducerContext['db']['homestead']['by_owner'],'filter'>};
  readonly world_placeable:{readonly by_chunk:Pick<WorldReducerContext['db']['world_placeable']['by_chunk'],'filter'>};
}},identity:WorldReducerContext['sender']){
  const home=firstIndexRow(ctx.db.homestead.by_owner.filter(identity));
  return hearthFurnishingCounts(contentRegistry(ctx),home?.residenceSpaceId===undefined?[]:
    [...ctx.db.world_placeable.by_chunk.filter(home.residenceSpaceId)]
      .filter(row=>resolvePlaceableObject(contentRegistry(ctx),row).stateJsonValid));
}

function expeditionPreparationFor(ctx:ContentReadContext & {readonly db:{readonly inventory_slot:{readonly by_identity:Pick<WorldReducerContext['db']['inventory_slot']['by_identity'],'filter'>}}},identity:WorldReducerContext['sender']){
  return hearthExpeditionPreparation(contentRegistry(ctx),[...ctx.db.inventory_slot.by_identity.filter(identity)]);
}

function questProgressSourceFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): QuestProgressSource {
  const statistics = new Map<string, bigint>();
  for (const row of ctx.db.player_statistic.by_identity.filter(identity)) {
    statistics.set(`${row.statisticKind}:${row.subjectKind}`, row.value);
  }
  const itemCounts = new Map<string, number>();
  for (const row of ctx.db.inventory_slot.by_identity.filter(identity)) {
    if (row.itemKind === 'empty' || row.quantity === 0) continue;
    itemCounts.set(row.itemKind, (itemCounts.get(row.itemKind) ?? 0) + row.quantity);
  }
  const cursor = ctx.db.inventory_cursor.identity.find(identity);
  if (cursor !== null && cursor.itemKind !== 'empty' && cursor.quantity > 0) {
    itemCounts.set(cursor.itemKind, (itemCounts.get(cursor.itemKind) ?? 0) + cursor.quantity);
  }
  let furnishing:ReturnType<typeof residenceFurnishingFor>|undefined;
  let equipment:ReturnType<typeof expeditionPreparationFor>|undefined;
  return {
    equipmentCount:category=>(equipment??=expeditionPreparationFor(ctx,identity))[category],
    furnishingCount:category=>(furnishing??=residenceFurnishingFor(ctx,identity))[category],
    statistic: (kind, subject) => statistics.get(`${kind}:${subject}`) ?? 0n,
    itemCount: (itemKind) => itemCounts.get(itemKind) ?? 0,
  };
}

function questBaselinesFor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  questId: string,
): Readonly<Record<string, bigint>> {
  return Object.fromEntries(
    [...ctx.db.player_quest_baseline.by_identity.filter(identity)]
      .filter((row) => row.questId === questId)
      .map((row) => [row.objectiveId, row.value]),
  );
}

function refreshPlayerQuests(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
): void {
  const rows = [...ctx.db.player_quest.by_identity.filter(identity)];
  if (!rows.some((row) => row.state === 'active' || row.state === 'complete')) return;
  const source = questProgressSourceFor(ctx, identity);
  for (const row of rows) {
    if (row.state !== 'active' && row.state !== 'complete') continue;
    const definition = runtimeQuestDefinition(contentRegistry(ctx), row.questId);
    if (definition === null) continue;
    const complete = questIsComplete(
      definition,
      questBaselinesFor(ctx, identity, row.questId),
      source,
    );
    if (complete && row.state === 'active') {
      ctx.db.player_quest.id.update({ ...row, state: 'complete', completedTick: authorityTick });
      raiseSenderBehaviourEvent(ctx, {
        type: 'questState', actor: { entityType: 'player', id: identity.toHexString() },
        questId: row.questId, from: 'active', to: 'complete',
      });
    } else if (!complete && row.state === 'complete') {
      ctx.db.player_quest.id.update({ ...row, state: 'active', completedTick: undefined });
      raiseSenderBehaviourEvent(ctx, {
        type: 'questState', actor: { entityType: 'player', id: identity.toHexString() },
        questId: row.questId, from: 'complete', to: 'active',
      });
    }
  }
}

function refreshSenderQuestsFromInventory(ctx: WorldReducerContext): void {
  refreshPlayerQuests(
    ctx,
    ctx.sender,
    ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n,
  );
}

function acceptQuest(
  ctx: WorldReducerContext,
  definition: QuestDefinition,
  authorityTick: bigint,
): void {
  const identityHex = ctx.sender.toHexString();
  const id = playerQuestId(identityHex, definition.id);
  if (ctx.db.player_quest.id.find(id) !== null) throw new SenderError('quest_not_available');
  if (definition.prerequisiteQuestIds?.some((questId) => (
    ctx.db.player_quest.id.find(playerQuestId(identityHex, questId))?.state !== 'turned_in'
  )) === true) throw new SenderError('quest_prerequisite_incomplete');
  const source = questProgressSourceFor(ctx, ctx.sender);
  const baselines = questAcceptBaselines(definition, source);
  ctx.db.player_quest.insert({
    id, identity: ctx.sender, questId: definition.id, state: 'active',
    acceptedTick: authorityTick, completedTick: undefined, turnedInTick: undefined, pinned: true,
  });
  for (const objective of definition.objectives) {
    ctx.db.player_quest_baseline.insert({
      id: playerQuestBaselineId(identityHex, definition.id, objective.id),
      identity: ctx.sender,
      questId: definition.id,
      objectiveId: objective.id,
      value: baselines[objective.id] ?? 0n,
    });
  }
  for (const item of definition.acceptItems ?? []) {
    if (!insertPlayerCarriedItem(ctx, item.itemKind, item.count)) {
      throw new SenderError('quest_accept_inventory_full');
    }
    recordPlayerStatistic(ctx, ctx.sender, 'items_obtained', BigInt(item.count), authorityTick, item.itemKind);
  }
  for (const item of definition.world?.surfaceItemsOnAccept ?? []) {
    ctx.db.quest_world_item.insert({
      id: questWorldItemId(identityHex, definition.id, item.objectiveId),
      identity: ctx.sender,
      questId: definition.id,
      objectiveId: item.objectiveId,
      surfaceId: item.surfaceId,
      slot: item.slot,
      itemKind: item.itemKind,
    });
  }
  raiseSenderBehaviourEvent(ctx, {
    type: 'questState', actor: { entityType: 'player', id: identityHex },
    questId: definition.id, from: 'available', to: 'active',
  });
  recordPlayerStatistic(ctx, ctx.sender, 'quests_accepted', 1n, authorityTick, definition.id);
}

/** Called only after an admitted NPC dialogue choice accepts a quest. Does not
 * fabricate lifetime talk counters or credit earlier conversations elsewhere. */
function creditQuestAcceptanceAtNpc(ctx:WorldReducerContext,questId:string,npcId:bigint,authorityTick:bigint):void {
  const definition=runtimeQuestDefinition(contentRegistry(ctx),questId);
  if(definition===null)return;
  const identityHex=ctx.sender.toHexString();
  const quest=ctx.db.player_quest.id.find(playerQuestId(identityHex,definition.id));
  if(quest?.state!=='active'||quest.acceptedTick!==authorityTick)return;
  const credited=questAcceptBaselines(definition,questProgressSourceFor(ctx,ctx.sender),npcId);
  for(const objective of definition.objectives){
    if(objective.kind!=='talk')continue;
    const baseline=ctx.db.player_quest_baseline.id.find(playerQuestBaselineId(identityHex,definition.id,objective.id));
    const value=credited[objective.id];
    if(baseline!==null&&value!==undefined&&value<baseline.value)ctx.db.player_quest_baseline.id.update({...baseline,value});
  }
  const position=ctx.db.player_position.identity.find(ctx.sender);
  if(position!==null)refreshPlayerQuestLocations(ctx,position,authorityTick);
  refreshPlayerQuests(ctx,ctx.sender,authorityTick);
}

function grantQuestRewards(
  ctx: WorldReducerContext,
  definition: QuestDefinition,
): void {
  for (const item of definition.rewards.items) {
    if (!insertPlayerCarriedItem(ctx, item.itemKind, item.count)) throw new SenderError('quest_reward_inventory_full');
  }
  const wallet = ctx.db.player_wallet.identity.find(ctx.sender);
  if (wallet === null) throw new SenderError('wallet_not_ready');
  ctx.db.player_wallet.identity.update({ ...wallet, balanceBronze: wallet.balanceBronze + definition.rewards.bronze });
  const identityHex = ctx.sender.toHexString();
  for (const reward of definition.rewards.experience) {
    const id = playerSkillTrackId(identityHex, reward.track);
    const existing = ctx.db.player_skill_track.id.find(id);
    if (existing === null) {
      ctx.db.player_skill_track.insert({
        id, identity: ctx.sender, track: reward.track, experience: reward.amount, spentPoints: 0,
        bonusPoints: 0, respecCount: 0,
      });
    } else {
      ctx.db.player_skill_track.id.update({ ...existing, experience: existing.experience + reward.amount });
    }
  }
  if (definition.rewards.homesteadSizeTier !== undefined) {
    const home = [...ctx.db.homestead.by_owner.filter(ctx.sender)][0];
    if (home === undefined) throw new SenderError('homestead_required');
    if (home.sizeTier < definition.rewards.homesteadSizeTier) {
      ctx.db.homestead.spaceId.update({
        ...home,
        sizeTier: definition.rewards.homesteadSizeTier,
      });
    }
  }
}

function turnInQuest(
  ctx: WorldReducerContext,
  definition: QuestDefinition,
  authorityTick: bigint,
): void {
  refreshPlayerQuests(ctx, ctx.sender, authorityTick);
  const id = playerQuestId(ctx.sender.toHexString(), definition.id);
  const row = ctx.db.player_quest.id.find(id);
  if (row === null || row.state !== 'complete') throw new SenderError('quest_objectives_incomplete');
  const source = questProgressSourceFor(ctx, ctx.sender);
  if (!questIsComplete(definition, questBaselinesFor(ctx, ctx.sender, definition.id), source)) {
    throw new SenderError('quest_objectives_incomplete');
  }
  // Deliver objectives are re-derived and consumed inside this transaction.
  // The first shipped quest uses an action item, but later definitions can add
  // collection objectives without trusting a client inventory snapshot.
  for (const objective of definition.objectives) {
    if (objective.kind !== 'collect' || objective.consumeOnTurnIn !== true) continue;
    for (const item of objective.items) removePlayerCarriedItem(ctx, item.itemKind, item.count);
  }
  grantQuestRewards(ctx, definition);
  ctx.db.player_quest.id.update({ ...row, state: 'turned_in', turnedInTick: authorityTick });
  raiseSenderBehaviourEvent(ctx, {
    type: 'questState', actor: { entityType: 'player', id: ctx.sender.toHexString() },
    questId: definition.id, from: 'complete', to: 'turned_in',
  });
  recordPlayerStatistic(ctx, ctx.sender, 'quests_completed', 1n, authorityTick, definition.id);
}

function refreshPlayerQuestLocations(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  authorityTick: bigint,
): void {
  const identityHex = position.identity.toHexString();
  for (const row of ctx.db.player_quest.by_identity.filter(position.identity)) {
    if (row.state !== 'active') continue;
    const definition = runtimeQuestDefinition(contentRegistry(ctx), row.questId);
    if (definition === null) continue;
    for (const objective of definition.objectives) {
      if (objective.kind !== 'location') continue;
      const id = playerQuestBaselineId(identityHex, row.questId, objective.id);
      const present = ctx.db.player_quest_reach_presence.id.find(id);
      const inside = questLocationContains(objective, position);
      if (inside && present === null) {
        ctx.db.player_quest_reach_presence.insert({
          id, identity: position.identity, questId: row.questId, objectiveId: objective.id,
        });
        recordPlayerStatistic(
          ctx, position.identity, 'quest_locations_reached', 1n, authorityTick,
          `${row.questId}:${objective.id}`,
        );
      } else if (!inside && present !== null) ctx.db.player_quest_reach_presence.id.delete(id);
    }
  }
}

/** Reset the online-time anchor without adding offline ticks. */
function beginPlayerStatisticSession(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
): void {
  const id = playerStatisticRowId(identity.toHexString(), 'time_played', '');
  const existing = ctx.db.player_statistic.id.find(id);
  if (existing === null) {
    ctx.db.player_statistic.insert({
      id,
      identity,
      statisticKind: 'time_played',
      subjectKind: '',
      value: 0n,
      createdTick: authorityTick,
      updatedTick: authorityTick,
    });
  } else if (existing.updatedTick !== authorityTick) {
    ctx.db.player_statistic.id.update({ ...existing, updatedTick: authorityTick });
  }
}

function flushPlayerStatisticTime(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
  force: boolean,
): void {
  const id = playerStatisticRowId(identity.toHexString(), 'time_played', '');
  const existing = ctx.db.player_statistic.id.find(id);
  if (existing === null) {
    beginPlayerStatisticSession(ctx, identity, authorityTick);
    return;
  }
  if (authorityTick <= existing.updatedTick) return;
  const elapsed = authorityTick - existing.updatedTick;
  if (!force && elapsed < STATISTIC_TIME_FLUSH_TICKS) return;
  recordPlayerStatistic(ctx, identity, 'time_played', elapsed, authorityTick);
}

function storedStack(
  ctx: Pick<WorldReducerContext, 'db'>,
  itemKind: string,
  quantity: number,
  durability: number,
  lit = true,
): ContainerSnapshot['slots'][number] {
  return itemKind === 'empty' || quantity === 0
    ? null
    : {
        itemKind,
        quantity,
        ...(runtimeDurabilityDefinition(contentRegistry(ctx), itemKind) === null ? {} : { durability }),
        lit,
      };
}

function storedDurability(ctx: Pick<WorldReducerContext, 'db'>, itemKind: string, durability?: number): number {
  return runtimeDurabilityDefinition(contentRegistry(ctx), itemKind) === null
    ? 0 : runtimeNormalizeDurability(contentRegistry(ctx), itemKind, durability);
}

function storedLit(_itemKind: string, lit?: boolean): boolean {
  return lit ?? true;
}

function sameStoredStack(
  left: ContainerSnapshot['slots'][number] | undefined,
  right: ContainerSnapshot['slots'][number] | undefined,
): boolean {
  return left?.itemKind === right?.itemKind
    && left?.quantity === right?.quantity
    && left?.durability === right?.durability
    && left?.lit === right?.lit;
}

const WORLD_ITEM_MERGE_RADIUS_FIXED = 8 * FIXED_UNITS_PER_PIXEL;
const PROJECTILE_HIT_RETENTION_TICKS = 6n;

interface WorldItemDrop {
  readonly itemKind: string;
  readonly quantity: number;
  readonly x: number;
  readonly y: number;
  readonly droppedAtTick: bigint;
  readonly durability: number;
  readonly lit?: boolean;
  readonly spaceId: number;
  readonly reservedFor?: WorldReducerContext['sender'];
  readonly reservedUntilTick?: bigint;
}

function worldItemExpiryTick(
  registry: ContentRegistry,
  itemKind: string,
  durability: number,
  droppedAtTick: bigint,
): bigint {
  const lifetimeTicks = runtimeIsRecoverableProjectileItem(registry, itemKind, durability)
    ? RECOVERABLE_ARROW_LIFETIME_TICKS
    : runtimeWorldPolicyBalance(registry)?.itemDespawnTicks ?? 0;
  return droppedAtTick + BigInt(lifetimeTicks);
}

function worldItemExpiredForRow(
  registry: ContentRegistry,
  item: WorldItemRow,
  authorityTick: bigint,
): boolean {
  return worldItemExpired(
    item.droppedAtTick,
    authorityTick,
    runtimeIsRecoverableProjectileItem(registry, item.itemKind, item.durability)
      ? RECOVERABLE_ARROW_LIFETIME_TICKS
      : runtimeWorldPolicyBalance(registry)?.itemDespawnTicks ?? 0,
  );
}

function worldItemsInChunkNeighborhood(
  ctx: WorldReducerContext,
  spaceId: number,
  x: number,
  y: number,
): WorldItemRow[] {
  const centerChunkX = chunkAt(x);
  const centerChunkY = chunkAt(y);
  const rows: WorldItemRow[] = [];
  for (let chunkY = centerChunkY - 1; chunkY <= centerChunkY + 1; chunkY += 1) {
    for (let chunkX = centerChunkX - 1; chunkX <= centerChunkX + 1; chunkX += 1) {
      rows.push(...ctx.db.world_item.by_chunk.filter([spaceId, chunkX, chunkY]));
    }
  }
  return rows;
}

/** Adds a recoverable world stack without proliferating rows at one drop
 * point. Compatible nearby rows fill first, then capped remainder rows are
 * inserted. Durable/non-stackable items intentionally remain distinct. */
function dropWorldItemStack(ctx: WorldReducerContext, drop: WorldItemDrop): void {
  const registry = contentRegistry(ctx);
  const maximum = runtimeMaxStack(registry, drop.itemKind);
  if (maximum === null || !Number.isSafeInteger(drop.quantity) || drop.quantity <= 0) {
    throw new SenderError('invalid_item_stack');
  }
  let remaining = drop.quantity;
  const lit = storedLit(drop.itemKind, drop.lit);
  // Projectile-landed arrows retain an angle in their otherwise-unused
  // durability column. Keep them as individual timed pickups rather than
  // merging them into an ordinary manually dropped arrow stack.
  if (maximum > 1 && !runtimeIsRecoverableProjectileItem(registry, drop.itemKind, drop.durability)) {
    const mergeRadiusSquared = WORLD_ITEM_MERGE_RADIUS_FIXED ** 2;
    const compatible = worldItemsInChunkNeighborhood(ctx, drop.spaceId, drop.x, drop.y)
      .filter((item) => {
        if (item.spaceId !== drop.spaceId || item.itemKind !== drop.itemKind
          || item.durability !== drop.durability || item.lit !== lit
          || (item.reservedFor === undefined) !== (drop.reservedFor === undefined)
          || (item.reservedFor !== undefined
            && drop.reservedFor !== undefined
            && !item.reservedFor.isEqual(drop.reservedFor))
          || runtimeIsRecoverableProjectileItem(registry, item.itemKind, item.durability)
          || item.quantity >= maximum) return false;
        const dx = item.x - drop.x;
        const dy = item.y - drop.y;
        return dx * dx + dy * dy <= mergeRadiusSquared;
      })
      .sort((left, right) => {
        const leftDistance = (left.x - drop.x) ** 2 + (left.y - drop.y) ** 2;
        const rightDistance = (right.x - drop.x) ** 2 + (right.y - drop.y) ** 2;
        if (leftDistance !== rightDistance) return leftDistance - rightDistance;
        return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
      });
    for (const item of compatible) {
      const inserted = Math.min(remaining, maximum - item.quantity);
      if (inserted <= 0) continue;
      ctx.db.world_item.id.update({
        ...item,
        quantity: item.quantity + inserted,
        droppedAtTick: drop.droppedAtTick,
        expiresTick: worldItemExpiryTick(registry, drop.itemKind, drop.durability, drop.droppedAtTick),
      });
      remaining -= inserted;
      if (remaining === 0) return;
    }
  }
  while (remaining > 0) {
    const quantity = Math.min(remaining, maximum);
    ctx.db.world_item.insert({
      id: 0n,
      itemKind: drop.itemKind,
      quantity,
      x: drop.x,
      y: drop.y,
      chunkX: chunkAt(drop.x),
      chunkY: chunkAt(drop.y),
      droppedAtTick: drop.droppedAtTick,
      durability: drop.durability,
      lit,
      spaceId: drop.spaceId,
      reservedFor: drop.reservedFor,
      reservedUntilTick: drop.reservedUntilTick ?? 0n,
      expiresTick: worldItemExpiryTick(registry, drop.itemKind, drop.durability, drop.droppedAtTick),
    });
    remaining -= quantity;
  }
}

function authoredReferenceSlug(reference: string, kind: 'effect' | 'statistic'): string | null {
  const prefix = `${kind}:`;
  const slug = reference.startsWith(prefix) ? reference.slice(prefix.length) : reference;
  return slug.length > 0 && !slug.includes(':') ? slug : null;
}

function applyOrRefreshPlayerEffect(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  effectKind: string,
  authorityTick: bigint,
  appliedStacks = 1,
): void {
  const registry = contentRegistry(ctx);
  const definition = runtimeEffectDefinition(registry, effectKind);
  if (definition === null) throw new SenderError('behaviour_effect_invalid');
  const existing = [...ctx.db.player_effect.by_identity.filter(identity)]
    .find((effect) => effect.effectKind === effectKind) ?? null;
  const refreshed = refreshEffect(existing === null ? null : {
    id: existing.id,
    effectKind,
    stacks: existing.stacks,
    appliedTick: existing.appliedTick,
    expiresTick: existing.expiresTick,
  }, effectKind, authorityTick, definition, existing?.id, appliedStacks);
  if (existing === null) ctx.db.player_effect.insert({ ...refreshed, identity });
  else ctx.db.player_effect.id.update({ ...existing, ...refreshed });
}

function isVitalsToolKind(ctx: WorldReducerContext, value: string): boolean {
  return runtimeToolDefinition(contentRegistry(ctx), value) !== null
    && runtimeVigourDefinition(contentRegistry(ctx), value) !== null;
}

function activePlayerModifiers(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
  actionItemKind?: string,
): readonly Modifier[] {
  const registry = contentRegistry(ctx);
  const effects = [...ctx.db.player_effect.by_identity.filter(identity)];
  const inventory = [...ctx.db.inventory_slot.by_identity.filter(identity)];
  const selectedSlot = ctx.db.player_survival.identity.find(identity)?.selectedSlot ?? 0;
  const loadout = compileEquipmentLoadout({
    registry, inventory, selectedSlot,
    trainedRanks: playerSkillRanks(ctx, identity),
    skillPriority: ctx.db.player_equipment_preferences.identity.find(identity)?.skillPriority ?? [],
    bowDrawn: ctx.db.bow_charge.identity.find(identity) !== null,
    ...(actionItemKind === undefined ? {} : {context: skillEffectContextForItem(registry,actionItemKind)}),
  });
  const hunger = ctx.db.player_survival.identity.find(identity)?.hungerCenti ?? HUNGER_MAX_CENTI;
  const hungerModifiers = modifiersForHunger(hunger);
  const run = rogueRunForIdentity(ctx, identity);
  const rogueModifiers: Modifier[] = run === null ? [] : [...ctx.db.rogue_run_upgrade.by_run.filter(run.id)]
    .flatMap((upgrade): readonly Modifier[] => {
      const definition = rogueUpgradeDefinition(registry,upgrade.upgradeId);
      if (definition === null || definition.modifierKind === 'healing'
        || definition.modifierKind === 'move_speed' || definition.modifierKind === 'knockback') return [];
      const target: Modifier['target'] = definition.modifierKind === 'sword_damage' ? 'attackPower'
        : definition.modifierKind === 'bow_damage' ? 'rangedPower'
          : definition.modifierKind === 'attack_speed' ? 'swingSpeed'
            : definition.modifierKind === 'max_health' ? 'maxHealth'
              : definition.modifierKind === 'critical_chance' ? 'criticalChance'
              : 'attackPower';
      const direction = definition.modifierKind === 'attack_speed' ? -1 : 1;
      return [{
        id: `rogue.${upgrade.upgradeId}`,
        target,
        layer: 'pctAdd',
        value: direction * upgrade.magnitudePermille * 10,
        source: 'environment',
      }];
    });
  return [
    ...loadout.modifiers,
    ...hungerModifiers,
    ...modifiersForEffects(effects, authorityTick, (effectKind) => (
      runtimeEffectDefinition(registry, effectKind)
    )),
    ...rogueModifiers,
  ];
}

function rogueUpgradeMagnitude(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  modifierKind: NonNullable<ReturnType<typeof rogueUpgradeDefinition>>['modifierKind'],
): number {
  const run = rogueRunForIdentity(ctx, identity);
  if (run === null) return 0;
  return [...ctx.db.rogue_run_upgrade.by_run.filter(run.id)].reduce((total, upgrade) => {
    const definition = rogueUpgradeDefinition(contentRegistry(ctx),upgrade.upgradeId);
    return definition?.modifierKind === modifierKind
      ? total + upgrade.magnitudePermille
      : total;
  }, 0);
}

function spendPlayerHunger(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  amountCenti: number,
): void {
  const row = ctx.db.player_survival.identity.find(identity);
  if (row === null) throw new SenderError('player_not_ready');
  const next = spendHunger(row, amountCenti);
  if (next.hungerCenti !== row.hungerCenti) ctx.db.player_survival.identity.update({ ...row, ...next });
}

function vitalStateFromRow(row: {
  readonly healthCenti: number; readonly manaCenti: number; readonly vigourCenti: number;
  readonly healthRemainder: number; readonly manaRemainder: number; readonly vigourRemainder: number;
  readonly regenTick: bigint;
}): VitalState {
  return {
    healthCenti: row.healthCenti, manaCenti: row.manaCenti, vigourCenti: row.vigourCenti,
    healthRemainder: row.healthRemainder, manaRemainder: row.manaRemainder,
    vigourRemainder: row.vigourRemainder, regenTick: row.regenTick,
  };
}

function resolvedStatsForRow(
  ctx: WorldReducerContext,
  row: { readonly str: number; readonly dex: number; readonly con: number; readonly int: number; readonly wis: number; readonly cha: number },
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
) {
  return resolveStatsWithProfile(
    activeCharacterCombatBalance(ctx),
    { str: row.str, dex: row.dex, con: row.con, int: row.int, wis: row.wis, cha: row.cha },
    activePlayerModifiers(ctx, identity, authorityTick),
  );
}

function playerCanAffordSprintStep(
  ctx: WorldReducerContext,
  row: {
    readonly str: number; readonly dex: number; readonly con: number;
    readonly int: number; readonly wis: number; readonly cha: number;
    readonly vigourCenti: number;
  },
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
): boolean {
  const modifiers = activePlayerModifiers(ctx, identity, authorityTick);
  const resolved = resolveStatsWithProfile(activeCharacterCombatBalance(ctx), {
    str: row.str, dex: row.dex, con: row.con,
    int: row.int, wis: row.wis, cha: row.cha,
  }, modifiers);
  const sprintDefinition = runtimeSprintAbilityDefinition(contentRegistry(ctx));
  if (sprintDefinition === null) return false;
  const sprint = resolveSprintAbility(
    sprintDefinition, resolved.attributes, modifiers, activeCharacterCombatBalance(ctx),
  );
  return sprintIntentSuppressesVigourRegen(
    true,
    row.vigourCenti,
    sprintVigourCostForSteps(sprint.vigourDrainCentiPerSecond, 1),
  );
}

function ensurePlayerStats(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
) {
  const existing = ctx.db.player_stats.identity.find(identity);
  if (existing !== null) return existing;
  const profile = activeCharacterCombatBalance(ctx);
  const baseAttributes = createBaseAttributesWithProfile(profile);
  const resolved = resolveStatsWithProfile(profile, baseAttributes);
  const vitals = createFullVitalState(resolved, authorityTick);
  return ctx.db.player_stats.insert({
    identity,
    ...baseAttributes,
    ...vitals,
    lastSwingTick: 0n,
  });
}

/** Every action that settles vitals must honor the same activity policy as the
 * periodic sweep. Otherwise repeated inventory/selection actions can regenerate
 * Vigour between suppressed sweep ticks. Explicit suppression is additive. */
function activitySuppressesVigourRegen(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
): boolean {
  const defense = ctx.db.player_combat_state.identity.find(identity);
  if (defense?.kind === 'block' || defense?.kind === 'dodge') return true;
  if (ctx.db.bow_charge.identity.find(identity) !== null) return true;
  const input = ctx.db.player_input.identity.find(identity);
  if (input === null || !((input.sprinting && input.direction !== 'idle')
    || input.settleDirection.includes('!'))
    || inputIsStale(input.updatedAtMicros, ctx.timestamp.microsSinceUnixEpoch)
    || mountedNpcFor(ctx, identity) !== null) return false;
  const stats = ctx.db.player_stats.identity.find(identity);
  return stats !== null && playerCanAffordSprintStep(ctx, stats, identity, authorityTick);
}

/** Cancellation cannot fail or become free after swapping/dropping the weapon.
 * Snapshot costs at draw start; legacy draws use the authored weapon fallback.
 * Fire pays through the weapon lifecycle and marks its token already settled. */
function clearBowCharge(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  alreadyPaid = false,
): void {
  const charge = ctx.db.bow_charge.identity.find(identity);
  if (charge === null) return;
  const tick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
  const stats = advancePlayerStats(ctx, identity, tick);
  if (!alreadyPaid) {
    const balance = runtimeVigourDefinition(contentRegistry(ctx), charge.itemKind);
    const cost = charge.fullChargeCostCenti || balance?.costCenti;
    if (cost === undefined) throw new SenderError('tool_vigour_not_authored');
    const elapsed = authorityBowChargeMs(charge.startedTick, tick, BOW_MAX_CHARGE_MS);
    ctx.db.player_stats.identity.update({ ...stats,
      vigourCenti: Math.max(0, stats.vigourCenti - bowChargeVigourCostCenti(elapsed, cost)),
      lastSwingTick: tick,
    });
    combatRecovery(ctx, identity, tick, tick + BigInt(charge.minimumSwingTicks || balance?.minimumSwingTicks || 1));
    spendPlayerHunger(ctx, identity, HUNGER_WEAPON_USE_CENTI);
  }
  ctx.db.bow_charge.identity.delete(identity);
  advancePlayerStats(ctx, identity, tick);
}

function advancePlayerStats(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
  suppressVigourRegen = false,
) {
  const row = ensurePlayerStats(ctx, identity, authorityTick);
  const resolved = resolvedStatsForRow(ctx, row, identity, authorityTick);
  const advanced = advanceVitals(
    vitalStateFromRow(row),
    (suppressVigourRegen || activitySuppressesVigourRegen(ctx, identity, authorityTick))
      ? { ...resolved, vigourRegenCentiPerSecond: 0 } : resolved,
    authorityTick,
  );
  if (advanced.healthCenti === row.healthCenti && advanced.manaCenti === row.manaCenti
    && advanced.vigourCenti === row.vigourCenti && advanced.healthRemainder === row.healthRemainder
    && advanced.manaRemainder === row.manaRemainder && advanced.vigourRemainder === row.vigourRemainder
    && advanced.regenTick === row.regenTick) return row;
  return ctx.db.player_stats.identity.update({ ...row, ...advanced });
}

function previewPlayerStats(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  authorityTick: bigint,
  suppressVigourRegen = false,
) {
  const row = ctx.db.player_stats.identity.find(identity);
  if (row === null) throw new SenderError('player_not_ready');
  const resolved = resolvedStatsForRow(ctx, row, identity, authorityTick);
  return {
    ...row,
    ...advanceVitals(
      vitalStateFromRow(row),
      (suppressVigourRegen || activitySuppressesVigourRegen(ctx, identity, authorityTick))
      ? { ...resolved, vigourRegenCentiPerSecond: 0 } : resolved,
      authorityTick,
    ),
  };
}

function validateToolVigourSpend(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  itemKind: string,
  authorityTick: bigint,
  whiff: boolean,
  baseCostOverride?: number,
  suppressVigourRegen = false,
): void {
  requireCombatActionReady(ctx, identity, authorityTick);
  const row = previewPlayerStats(ctx, identity, authorityTick, suppressVigourRegen);
  const ranks = playerSkillRanks(ctx, identity);
  const registry = contentRegistry(ctx);
  if (!runtimeCanUseToolWithSkillRanks(registry, itemKind, ranks)) {
    throw new SenderError(`tool_skill_required:${runtimeToolQualityRequiredRanks(registry, itemKind)}`);
  }
  const modifiers = activePlayerModifiers(ctx, identity, authorityTick, itemKind);
  const balance = runtimeVigourDefinition(registry, itemKind);
  if (runtimeToolDefinition(registry, itemKind) === null || balance === null) {
    throw new SenderError('tool_vigour_not_authored');
  }
  const profile = activeCharacterCombatBalance(ctx);
  const interval = Math.max(1, resolveModifierTarget(
    'swingSpeed', balance.minimumSwingTicks, modifiers, profile,
  ));
  const fullCost = resolveModifierTarget(
    'toolVigourCost', baseCostOverride ?? balance.costCenti, modifiers, profile,
  );
  const result = toolSpendResult(
    row.vigourCenti, row.lastSwingTick, authorityTick, fullCost, interval, whiff,
  );
  if (!result.ok) throw new SenderError(result.code);
}

function spendToolVigour(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  itemKind: string,
  authorityTick: bigint,
  whiff: boolean,
  baseCostOverride?: number,
  suppressVigourRegen = false,
): void {
  requireCombatActionReady(ctx, identity, authorityTick);
  const row = advancePlayerStats(ctx, identity, authorityTick, suppressVigourRegen);
  const ranks = playerSkillRanks(ctx, identity);
  const registry = contentRegistry(ctx);
  if (!runtimeCanUseToolWithSkillRanks(registry, itemKind, ranks)) {
    throw new SenderError(`tool_skill_required:${runtimeToolQualityRequiredRanks(registry, itemKind)}`);
  }
  const modifiers = activePlayerModifiers(ctx, identity, authorityTick, itemKind);
  const balance = runtimeVigourDefinition(registry, itemKind);
  if (runtimeToolDefinition(registry, itemKind) === null || balance === null) {
    throw new SenderError('tool_vigour_not_authored');
  }
  const profile = activeCharacterCombatBalance(ctx);
  const interval = Math.max(1, resolveModifierTarget(
    'swingSpeed', balance.minimumSwingTicks, modifiers, profile,
  ));
  const fullCost = resolveModifierTarget(
    'toolVigourCost', baseCostOverride ?? balance.costCenti, modifiers, profile,
  );
  const result = toolSpendResult(
    row.vigourCenti,
    row.lastSwingTick,
    authorityTick,
    fullCost,
    interval,
    whiff,
  );
  if (!result.ok) throw new SenderError(result.code);
  ctx.db.player_stats.identity.update({
    ...row,
    vigourCenti: result.vigourCenti,
    lastSwingTick: result.lastSwingTick,
  });
  const item = runtimeItemDefinition(contentRegistry(ctx), itemKind);
  const weaponUse = item?.tags.includes('item.melee_weapon') === true
    || item?.tags.includes('item.ranged_weapon') === true;
  spendPlayerHunger(
    ctx,
    identity,
    weaponUse ? HUNGER_WEAPON_USE_CENTI : HUNGER_TOOL_USE_CENTI,
  );
}

function requireUsableTool<T extends { readonly itemKind: string; readonly durability: number }>(
  ctx: WorldReducerContext,
  slot: T | null,
): asserts slot is T {
  if (slot === null || runtimeDurabilityDefinition(contentRegistry(ctx), slot.itemKind) === null) {
    throw new SenderError('wrong_tool');
  }
  if (slot.durability === 0) throw new SenderError('tool_broken');
}

/** Single-row runtime custody changes may alter selected or equipped benefits.
 * Multi-slot menu transactions settle the complete loadout in writePlayerInventory. */
function writeInventorySlot(ctx: WorldReducerContext, row: InventorySlotRow): void {
  const survival = ctx.db.player_survival.identity.find(row.identity);
  const affectsLoadout = row.slot === survival?.selectedSlot
    || (row.slot >= EQUIPMENT_SLOT_OFFSET && row.slot < CRAFTING_SLOT_OFFSET);
  const tick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
  if (affectsLoadout) advancePlayerStats(ctx, row.identity, tick);
  ctx.db.inventory_slot.id.update(row);
  if (affectsLoadout) {
    updateEquippedForIdentity(ctx, row.identity);
    advancePlayerStats(ctx, row.identity, tick);
  }
}

function wearInventoryTool(
  ctx: WorldReducerContext,
  slot: {
    readonly id: string;
    readonly identity: WorldReducerContext['sender'];
    readonly itemKind: string;
    readonly durability: number;
  },
  wear = 1,
): void {
  const worn = runtimeWearTool(contentRegistry(ctx), slot.itemKind, slot.durability, wear);
  const row = ctx.db.inventory_slot.id.find(slot.id);
  if (row === null) throw new SenderError('inventory_slot_missing');
  writeInventorySlot(ctx, { ...row, durability: worn.durability });
  if (worn.broken) {
    recordPlayerStatistic(
      ctx,
      slot.identity,
      'tools_broken',
      1n,
      ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n,
      slot.itemKind,
    );
  }
}

function loadPlayerInventory(
  ctx: Pick<WorldReducerContext, 'db'>,
  identity: WorldReducerContext['sender'],
) {
  const rows = [...ctx.db.inventory_slot.by_identity.filter(identity)];
  const rowBySlot = new Map(rows.map((row) => [row.slot, row]));
  const carriedCapacity = equippedInventoryCapacity(ctx, rows);
  const make = (id: InventoryContainerId): ContainerSnapshot => {
    const capacity = accessibleInventoryContainerCapacity(id, carriedCapacity, playerDebugBackpackSlots(ctx, identity));
    const offset = inventorySlotOffset(id);
    return {
      id,
      capacity,
      slots: Array.from({ length: capacity }, (_, index) => {
        const row = rowBySlot.get(offset + index);
        return row === undefined ? null : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
      }),
      ...(id === 'equipment' ? { restrictions: EQUIPMENT_SLOT_RESTRICTIONS } : {}),
    };
  };
  return {
    rows,
    rowBySlot,
    containers: {
      hotbar: make('hotbar'),
      backpack: make('backpack'),
      equipment: make('equipment'),
      crafting: make('crafting'),
    },
  };
}

function loadAdminInventoryState(
  ctx: Pick<WorldReducerContext, 'db'>,
  identity: WorldReducerContext['sender'],
): { readonly inventory: ReturnType<typeof loadPlayerInventory>; readonly state: AdminInventoryState } {
  const inventory = loadPlayerInventory(ctx, identity);
  const cursorRow = ctx.db.inventory_cursor.identity.find(identity);
  const overflowRows = [...ctx.db.inventory_overflow.by_identity.filter(identity)]
    .sort((left, right) => left.id < right.id ? -1 : left.id > right.id ? 1 : 0);
  return {
    inventory,
    state: {
      containers: inventory.containers,
      cursor: cursorRow === null
        ? null
        : storedStack(ctx, cursorRow.itemKind, cursorRow.quantity, cursorRow.durability, cursorRow.lit),
      overflow: overflowRows.flatMap((row) => {
        const stack = storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
        return stack === null ? [] : [stack];
      }),
    },
  };
}

function writePlayerInventory(
  ctx: WorldReducerContext,
  rowBySlot: ReturnType<typeof loadPlayerInventory>['rowBySlot'],
  before: Readonly<Record<string, ContainerSnapshot>>,
  after: Readonly<Record<string, ContainerSnapshot>>,
): void {
  const registry = contentRegistry(ctx);
  const equipmentChanged=Array.from({length:EQUIPMENT_SLOT_COUNT},(_,index)=>index).some(index=>
    !sameStoredStack(before.equipment?.slots[index],after.equipment?.slots[index]));
  const owner=rowBySlot.values().next().value?.identity;
  const tick=ctx.db.world_clock.id.find(0)?.authorityTick??0n;
  if (equipmentChanged && owner!==undefined) advancePlayerStats(ctx,owner,tick);

  const carriedCapacity = (containers: Readonly<Record<string, ContainerSnapshot>>): number => {
    const equipped = containers.equipment?.slots[4];
    return equipped === null || equipped === undefined
      ? DEFAULT_BACKPACK_CAPACITY
      : runtimeItemInventoryCapacity(registry, equipped.itemKind) ?? DEFAULT_BACKPACK_CAPACITY;
  };
  const beforeCapacity = carriedCapacity(before);
  const afterCapacity = carriedCapacity(after);
  if (afterCapacity < beforeCapacity && after.backpack?.slots
    .slice(afterCapacity).some((stack) => stack !== null)) {
    throw new SenderError('backpack_in_use');
  }
  for (const id of ['hotbar', 'backpack', 'equipment', 'crafting'] as const) {
    const previousContainer = before[id];
    const nextContainer = after[id];
    if (previousContainer === undefined || nextContainer === undefined) continue;
    const offset = inventorySlotOffset(id);
    for (let index = 0; index < nextContainer.capacity; index += 1) {
      const previous = previousContainer.slots[index];
      const next = nextContainer.slots[index];
      if (sameStoredStack(previous, next)) continue;
      const row = rowBySlot.get(offset + index);
      if (row === undefined) throw new SenderError('inventory_slot_missing');
      ctx.db.inventory_slot.id.update({
        ...row,
        itemKind: next?.itemKind ?? 'empty',
        quantity: next?.quantity ?? 0,
        durability: storedDurability(ctx, next?.itemKind ?? 'empty', next?.durability),
        lit: storedLit(next?.itemKind ?? 'empty', next?.lit),
      });
      if (ctx.db.inventory_overflow_retry.identity.find(row.identity) !== null) {
        ctx.db.inventory_overflow_retry.identity.delete(row.identity);
      }
    }
  }
  // Unequip clamps to the lower maximum immediately. Re-equipping never heals
  // that discarded reserve or retroactively applies the new gear to regeneration.
  if (equipmentChanged && owner!==undefined) advancePlayerStats(ctx,owner,tick);

}

function playerInventoryCursor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): ItemStack | null {
  const row = ctx.db.inventory_cursor.identity.find(identity);
  return row === null ? null : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
}

function writePlayerInventoryCursor(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  stack: ItemStack | null,
): void {
  const current = ctx.db.inventory_cursor.identity.find(identity);
  if (stack === null) {
    if (current !== null) ctx.db.inventory_cursor.identity.delete(identity);
    return;
  }
  const next = {
    identity,
    itemKind: stack.itemKind,
    quantity: stack.quantity,
    durability: storedDurability(ctx, stack.itemKind, stack.durability),
    lit: storedLit(stack.itemKind, stack.lit),
  };
  if (current === null) ctx.db.inventory_cursor.insert(next);
  else ctx.db.inventory_cursor.identity.update({ ...current, ...next });
}

interface OpenMenuInventory {
  readonly inventory: ReturnType<typeof loadPlayerInventory>;
  readonly containers: Readonly<Record<string, ContainerSnapshot>>;
  readonly stash?: {readonly container:ContainerSnapshot;readonly rowsBySlot:ReadonlyMap<number,ReturnType<typeof loadHearthStashRows>[number]>};
  readonly chest?: {
    readonly container: ContainerSnapshot;
    readonly rowsBySlot: ReadonlyMap<number, ReturnType<typeof ensureChestStorageRows>[number]>;
  };
  readonly placeable?: {
    readonly placeable: WorldPlaceableRow;
    readonly container: ContainerSnapshot;
    readonly rowsBySlot: ReadonlyMap<number, ReturnType<typeof loadOpenPlaceableRows>[number]>;
  };
}

/** Lazily materializes interface slots so tagging an already-placed prop is a
 * complete migration: its next settlement/interaction gains the UI without a
 * bespoke data backfill. */
function loadOpenPlaceableRows(ctx: WorldReducerContext, placeable: WorldPlaceableRow) {
  const rows = [...ctx.db.world_placeable_slot.by_placeable.filter(placeable.id)];
  const occupied = new Set(rows.map((row) => row.slot));
  for (let slot = 0; slot < genericPlaceableCapacity(ctx, placeable); slot += 1) {
    if (occupied.has(slot)) continue;
    rows.push(ctx.db.world_placeable_slot.insert({
      id: `${placeable.id}:${slot}`,
      placeableId: placeable.id,
      slot,
      itemKind: 'empty',
      quantity: 0,
      durability: 0,
      lit: true,
    }));
  }
  return rows.sort((left, right) => left.slot - right.slot);
}

const processorBehaviourDependencies: ProcessorBehaviourDependencies = {
  contentRegistry,
  loadOpenPlaceableRows,
  storedStack,
  sameStoredStack,
  storedDurability,
  storedLit,
  maxStackForItem: (ctx, itemKind) => runtimeMaxStack(contentRegistry(ctx), itemKind),
  grantSkillExperience,
  recordPlayerStatistic,
  homesteadUpgradeRank,
  barrelingRank: (ctx, spaceId) => farmingSkillEffects(contentRegistry(ctx), playerSkillRanks(ctx,
    homesteadForSpace(ctx, spaceId)?.owner ?? ctx.sender)).barreling,
  processCompleted: (ctx, placeable, unitsSettled) => {
    raiseProcessorProcessCompleteEvent(ctx, placeable, unitsSettled);
  },
};

const lootAuthorityDependencies: LootAuthorityDependencies = {
  insertPlayerCarriedItem,
  dropWorldItemStack,
  recordPlayerStatistic,
};

function registeredLifecycleLoot(
  ctx: WorldReducerContext,
  event: LifecycleEvent,
  target: BehaviourObjectSnapshot,
  seedParts: Parameters<typeof resolveLifecycleLootEffects>[2]['seedParts'],
  context?: Parameters<typeof resolveLifecycleLootEffects>[2]['context'],
) {
  const result = raiseEvent(
    currentWorldBehaviourHandlers(ctx),
    event,
    timerBehaviourSnapshot(ctx, target),
  );
  if (isBlockedHandlerResult(result)) throw new SenderError(result.blocked);
  const resolved = resolveLifecycleLootEffects(contentRegistry(ctx).loots, result.effects, {
    seedParts,
    ...(context === undefined ? {} : { context }),
  });
  if (resolved.remainingEffects.length !== 0) {
    throw new SenderError('behaviour_loot_effect_unavailable');
  }
  return resolved;
}

function settleProcessorPlaceable(ctx: WorldReducerContext, placeable: WorldPlaceableRow): WorldPlaceableRow {
  return settleProcessorPlaceableBehaviour(ctx, placeable, processorBehaviourDependencies);
}

function cellarInterfaceForPlaceable(
  ctx: Pick<WorldReducerContext, 'db'>,
  placeable: WorldPlaceableRow,
): CellarProcessorInterface | null {
  return cellarInterfaceForPlaceableBehaviour(contentRegistry(ctx), placeable);
}

function placeableWithOpenState(placeable: WorldPlaceableRow, open: boolean): WorldPlaceableRow {
  let state: Record<string, unknown> = {};
  try {
    const parsed: unknown = JSON.parse(placeable.stateJson);
    if (parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)) {
      state = parsed as Record<string, unknown>;
    }
  } catch { /* Preserve a playable row even if unrelated legacy state was malformed. */ }
  return { ...placeable, open, stateJson: JSON.stringify({ ...state, open }) };
}

function clearActivePlaceable(ctx: WorldReducerContext, identity: WorldReducerContext['sender']): void {
  clearActiveHearthStash(ctx,identity);
  const active = ctx.db.active_placeable.identity.find(identity);
  if (active === null) return;
  ctx.db.active_placeable.identity.delete(identity);
  const placeable = ctx.db.world_placeable.id.find(active.placeableId);
  if (placeable !== null && (processorAdapterForPlaceableBehaviour(contentRegistry(ctx), placeable) === 'barrel'
    || genericChest(ctx, placeable))
    && [...ctx.db.active_placeable.by_placeable.filter(placeable.id)].length === 0) {
    const closed = placeableWithOpenState(placeable, false);
    ctx.db.world_placeable.id.update(closed);
    if (genericChest(ctx, placeable)) syncGenericChestLegacyMirror(ctx, closed);
  }
}

function hearthStashWithinReach(ctx:WorldReducerContext, endpointId: string = 'delve_lobby'):boolean {
  const position=ctx.db.player_position.identity.find(ctx.sender);
  const stats=ctx.db.player_stats.identity.find(ctx.sender);
  const supplyCache=runtimeHearthSupplyCache(contentRegistry(ctx),endpointId);
  if (supplyCache !== null) {
    if (position === null || stats === null || stats.healthCenti <= 0 || position.spaceId !== supplyCache.spaceId
      || mountedNpcFor(ctx, ctx.sender) !== null || handsOccupiedFor(ctx, ctx.sender)
      || ctx.db.bow_charge.identity.find(ctx.sender) !== null || ctx.db.player_seat.identity.find(ctx.sender) !== null) return false;
    const tick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
    const action = ctx.db.player_combat_state.identity.find(ctx.sender);
    if (action !== null && (action.kind === 'block' || tick < action.readyTick)) return false;
    return hearthSupplyCacheInstalled(supplyCache,compiledLiveIslandRuntime(ctx)?.document ?? null)
      && hearthSupplyCacheApproachClear(supplyCache,position, collisionForSpace(ctx, position.spaceId));
  }
  if (endpointId !== 'delve_lobby') return false;
  const lobby=activeHearthLobbyDefinition(contentRegistry(ctx));
  if(position===null||stats===null||stats.healthCenti===0||lobby===null
    ||position.spaceId!==lobby.spaceId)return false;
  const point={x:(lobby.points.stash.tileX+.5)*TILE_SIZE_FIXED,
    y:(lobby.points.stash.tileY+.5)*TILE_SIZE_FIXED};
  const collision=collisionForSpace(ctx,position.spaceId);
  return Math.hypot(position.x-point.x,position.y-point.y)<=1.5*TILE_SIZE_FIXED
    && !positionCollides(position,collision)&&!positionCollides(point,collision)
    && !combatSegmentObstructed(position,point,collision);
}
function hearthStashSessionAvailable(ctx:WorldReducerContext):boolean {
  const active=ctx.db.active_hearth_stash.identity.find(ctx.sender);
  return ctx.connectionId!==null&&active!==null&&active.connectionId.isEqual(ctx.connectionId)
    &&hearthStashWithinReach(ctx, active.endpointId ?? 'delve_lobby');
}
function clearActiveHearthStash(ctx:WorldReducerContext,identity:WorldReducerContext['sender']):void {
  ctx.db.active_hearth_stash.identity.delete(identity);
}
function loadHearthStashRows(ctx:WorldReducerContext){
  const capacity=activeHearthLobbyDefinition(contentRegistry(ctx))?.stashCapacity;
  if(capacity===undefined)throw new SenderError('stash_unavailable');
  const rows=[...ctx.db.hearth_stash_slot.by_identity.filter(ctx.sender)];
  const occupied=new Set(rows.map(row=>row.slot));
  for(let slot=0;slot<capacity;slot++){
    if(!occupied.has(slot))rows.push(ctx.db.hearth_stash_slot.insert({
      id:`${ctx.sender.toHexString()}:${slot}`,identity:ctx.sender,slot,itemKind:'empty',quantity:0,durability:0,lit:true,
    }));
  }
  return rows;
}
function openHearthStashEndpoint(ctx: WorldReducerContext, endpointId: string): void {
  requireAuthorizedSender(ctx.senderAuth.jwt,ctx.db.membership.identity.find(ctx.sender));
  requirePersistentInventoryAvailable(ctx,ctx.sender);
  if(ctx.connectionId===null||!hearthStashWithinReach(ctx, endpointId))throw new SenderError('stash_out_of_reach');
  if (runtimeHearthSupplyCache(contentRegistry(ctx),endpointId) !== null) {
    const tick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
    if (advancePlayerStats(ctx, ctx.sender, tick).healthCenti <= 0) throw new SenderError('player_not_ready');
  }
  returnInventoryCursorToStorage(ctx,ctx.sender);
  const activeChest=ctx.db.active_chest.identity.find(ctx.sender);
  const legacyChest=activeChest===null?null:ctx.db.world_chest.id.find(activeChest.chestId);
  ctx.db.active_chest.identity.delete(ctx.sender);
  if(legacyChest!==null)syncLegacyChestGenericMirror(ctx,legacyChest);
  clearActivePlaceable(ctx,ctx.sender);
  ctx.db.active_dialogue.identity.delete(ctx.sender);
  loadHearthStashRows(ctx);
  const next={identity:ctx.sender,connectionId:ctx.connectionId,endpointId};
  if(ctx.db.active_hearth_stash.identity.find(ctx.sender)===null)ctx.db.active_hearth_stash.insert(next);
  else ctx.db.active_hearth_stash.identity.update(next);
}
export const openHearthStash=spacetimedb.reducer({},ctx=>openHearthStashEndpoint(ctx, 'delve_lobby'));
export const openHearthSupplyCache=spacetimedb.reducer({},ctx=>{
  const cache=runtimeHearthSupplyCache(contentRegistry(ctx));
  if(cache===null)throw new SenderError('stash_out_of_reach');
  openHearthStashEndpoint(ctx,cache.endpointId);
});
export const closeHearthStash=spacetimedb.reducer({},ctx=>{
  requireAuthorizedSender(ctx.senderAuth.jwt,ctx.db.membership.identity.find(ctx.sender));
  const active=ctx.db.active_hearth_stash.identity.find(ctx.sender);
  if(active===null||ctx.connectionId===null||!active.connectionId.isEqual(ctx.connectionId))return;
  returnInventoryCursorToStorage(ctx,ctx.sender);
  clearActiveHearthStash(ctx,ctx.sender);
});

/** Resolves the complete menu visible to this sender. Private active-menu rows
 * and reach checks prevent a forged container id from accessing remote data. */
function loadOpenMenuInventory(ctx: WorldReducerContext): OpenMenuInventory {
  requirePersistentInventoryAvailable(ctx, ctx.sender);
  const inventory = loadPlayerInventory(ctx, ctx.sender);
  const containers: Record<string, ContainerSnapshot> = { ...inventory.containers };
  let stashResult:OpenMenuInventory['stash'];
  if(hearthStashSessionAvailable(ctx)){
    const capacity=activeHearthLobbyDefinition(contentRegistry(ctx))?.stashCapacity;
    if(capacity===undefined)throw new SenderError('stash_unavailable');
    const rowsBySlot=new Map(loadHearthStashRows(ctx).map(row=>[row.slot,row]));
    const container:ContainerSnapshot={id:'stash',capacity,
      slots:Array.from({length:capacity},(_,slot)=>{
        const row=rowsBySlot.get(slot)!;
        return storedStack(ctx,row.itemKind,row.quantity,row.durability,row.lit);
      })};
    containers.stash=container;stashResult={container,rowsBySlot};
  }
  let chestResult: OpenMenuInventory['chest'];
  const activeChest = ctx.db.active_chest.identity.find(ctx.sender);
  if (activeChest !== null) {
    const chest = ctx.db.world_chest.id.find(activeChest.chestId);
    const position = ctx.db.player_position.identity.find(ctx.sender);
    if (chest !== null && chest.carriedBy === undefined && position !== null
      && chest.spaceId === position.spaceId && chestWithinReach(position.x, position.y, chest)) {
      const rows = ensureChestStorageRows(ctx, chest.id);
      const rowsBySlot = new Map(rows.map((row) => [row.slot, row]));
      const container: ContainerSnapshot = {
        id: 'chest', capacity: CHEST_STORAGE_CAPACITY,
        slots: Array.from({ length: CHEST_STORAGE_CAPACITY }, (_, index) => {
          const row = rowsBySlot.get(index);
          return row === undefined ? null : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
        }),
      };
      containers.chest = container;
      chestResult = { container, rowsBySlot };
    }
  }
  let placeableResult: OpenMenuInventory['placeable'];
  const activePlaceable = ctx.db.active_placeable.identity.find(ctx.sender);
  if (activePlaceable !== null) {
    let placeable = ctx.db.world_placeable.id.find(activePlaceable.placeableId);
    if (placeable !== null
      && processorAdapterForPlaceableBehaviour(contentRegistry(ctx), placeable) !== null) {
      placeable = settleProcessorPlaceable(ctx, placeable);
    }
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const capacity = placeable === null ? 0 : genericPlaceableCapacity(ctx, placeable);
    if (placeable !== null && position !== null && placeable.spaceId === position.spaceId
      && chestWithinReach(position.x, position.y, placeable) && capacity > 0) {
      const rows = loadOpenPlaceableRows(ctx, placeable);
      const rowsBySlot = new Map(rows.map((row) => [row.slot, row]));
      const restrictions = placeableFrameRestrictions(contentRegistry(ctx), placeable);
      const containerId = genericChest(ctx, placeable) ? 'chest' : 'placeable';
      const container: ContainerSnapshot = {
        id: containerId, capacity,
        ...(Object.keys(restrictions).length === 0 ? {} : { restrictions }),
        slots: Array.from({ length: capacity }, (_, index) => {
          const row = rowsBySlot.get(index);
          return row === undefined ? null : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
        }),
      };
      containers[containerId] = container;
      placeableResult = { placeable, container, rowsBySlot };
    }
  }
  return {
    inventory, containers,
    ...(stashResult===undefined?{}:{stash:stashResult}),
    ...(chestResult === undefined ? {} : { chest: chestResult }),
    ...(placeableResult === undefined ? {} : { placeable: placeableResult }),
  };
}

function writeOpenMenuInventory(
  ctx: WorldReducerContext,
  menu: OpenMenuInventory,
  containers: Readonly<Record<string, ContainerSnapshot>>,
): void {
  if(menu.stash!==undefined){
    requirePersistentInventoryAvailable(ctx,ctx.sender);
    if(!hearthStashSessionAvailable(ctx))throw new SenderError('stash_out_of_reach');
  }
  const placeableContainerId = menu.placeable?.container.id ?? 'placeable';
  const sharedContainerIds = ['chest', 'placeable', 'stash'] as const;
  const uniqueCounts = (source: Readonly<Record<string, ContainerSnapshot>>): Map<string, number> => {
    const counts = new Map<string, number>();
    for (const containerId of sharedContainerIds) {
      for (const stack of source[containerId]?.slots ?? []) {
        if (stack !== null && runtimeItemHasTag(
          contentRegistry(ctx), stack.itemKind, UNIQUE_QUEST_ITEM_TAG,
        )) {
          counts.set(stack.itemKind, (counts.get(stack.itemKind) ?? 0) + stack.quantity);
        }
      }
    }
    return counts;
  };
  const previousUniqueCounts = uniqueCounts(menu.containers);
  for (const [itemKind, quantity] of uniqueCounts(containers)) {
    if (quantity > (previousUniqueCounts.get(itemKind) ?? 0)) {
      throw new SenderError('item_not_tradeable');
    }
  }
  const placeableProcessor = menu.placeable === undefined ? null
    : processorRuntimeForPlaceableBehaviour(contentRegistry(ctx), menu.placeable.placeable);
  const placeableProcessorComponent = placeableProcessor?.object.components.processor;
  const barrelInputKinds = new Set(placeableProcessor?.definitions
    .filter((definition) => definition.adapter === 'barrel')
    .map((definition) => definition.input.item.slice('item:'.length)) ?? []);
  const barrelOutputKinds = new Set(placeableProcessor?.definitions
    .filter((definition) => definition.adapter === 'barrel')
    .flatMap((definition) => definition.outputs.map(({ item }) => item.slice('item:'.length))) ?? []);
  if (menu.placeable !== undefined && placeableProcessor?.adapter === 'barrel'
    && !barrelMutationIsValid(
      menu.placeable.container.slots,
      containers[placeableContainerId]?.slots ?? [],
      menu.placeable.placeable.barrelSealedTick,
      barrelCellarBatchCapacity(
        placeableProcessorComponent?.maximumBatch ?? placeableProcessorComponent?.catchUpCap ?? 0,
        homesteadUpgradeRank(ctx, menu.placeable.placeable.spaceId, 'barrel'),
      ),
      (itemKind) => barrelInputKinds.has(itemKind),
      (itemKind) => barrelOutputKinds.has(itemKind),
    )) throw new SenderError('barrel_contents_restricted');
  writePlayerInventory(ctx, menu.inventory.rowBySlot, menu.inventory.containers, containers);
  updateEquippedForIdentity(ctx, ctx.sender, containers);
  if(menu.stash!==undefined){
    const after=containers.stash;
    const capacity=activeHearthLobbyDefinition(contentRegistry(ctx))?.stashCapacity;
    if(after===undefined||capacity===undefined||after.capacity!==capacity)throw new SenderError('stash_invalid');
    for(let slot=0;slot<after.capacity;slot++){
      const next=after.slots[slot],previous=menu.stash.container.slots[slot];
      if(sameStoredStack(previous,next))continue;
      const row=menu.stash.rowsBySlot.get(slot);
      if(row===undefined||!row.identity.isEqual(ctx.sender))throw new SenderError('stash_slot_missing');
      ctx.db.hearth_stash_slot.id.update({...row,itemKind:next?.itemKind??'empty',quantity:next?.quantity??0,
        durability:storedDurability(ctx,next?.itemKind??'empty',next?.durability),lit:storedLit(next?.itemKind??'empty',next?.lit)});
    }
  }
  if (menu.chest !== undefined) {
    const after = containers.chest!;
    for (let index = 0; index < after.capacity; index += 1) {
      const previous = menu.chest.container.slots[index];
      const next = after.slots[index];
      if (sameStoredStack(previous, next)) continue;
      const position = ctx.db.player_position.identity.find(ctx.sender);
      if (position === null) throw new SenderError('player_not_ready');
      requireWorldModificationAuthorized(ctx, position);
      const row = menu.chest.rowsBySlot.get(index);
      if (row === undefined) throw new SenderError('chest_slot_missing');
      ctx.db.world_chest_slot.id.update({
        ...row, itemKind: next?.itemKind ?? 'empty', quantity: next?.quantity ?? 0,
        durability: storedDurability(ctx, next?.itemKind ?? 'empty', next?.durability),
        lit: storedLit(next?.itemKind ?? 'empty', next?.lit),
      });
    }
    const legacyChest = ctx.db.world_chest.id.find(menu.chest.rowsBySlot.get(0)?.chestId ?? 0n);
    if (legacyChest !== null) syncLegacyChestGenericMirror(ctx, legacyChest);
  }
  if (menu.placeable !== undefined) {
    const after = containers[placeableContainerId]!;
    const processorRuntime = processorRuntimeForPlaceableBehaviour(
      contentRegistry(ctx), menu.placeable.placeable,
    );
    const processorInputSlot = processorRuntime?.topology.inputSlots[0];
    const previousCookingInput = processorInputSlot === undefined
      ? null : menu.placeable.container.slots[processorInputSlot] ?? null;
    const nextCookingInput = processorInputSlot === undefined
      ? null : after.slots[processorInputSlot] ?? null;
    const cookingInputChanged = processorRuntime?.adapter === 'campfire_cooking'
      && previousCookingInput?.itemKind !== nextCookingInput?.itemKind;
    const cellarCapability = cellarInterfaceForPlaceable(ctx, menu.placeable.placeable);
    const previousCellarInput = previousCookingInput;
    const nextCellarInput = nextCookingInput;
    const cellarInputChanged = cellarCapability !== null
      && previousCellarInput?.itemKind !== nextCellarInput?.itemKind;
    for (let index = 0; index < after.capacity; index += 1) {
      const previous = menu.placeable.container.slots[index];
      const next = after.slots[index];
      if (sameStoredStack(previous, next)) continue;
      const position = ctx.db.player_position.identity.find(ctx.sender);
      if (position === null) throw new SenderError('player_not_ready');
      requireWorldModificationAuthorized(ctx, position);
      const row = menu.placeable.rowsBySlot.get(index);
      if (row === undefined) throw new SenderError('placeable_slot_missing');
      ctx.db.world_placeable_slot.id.update({
        ...row, itemKind: next?.itemKind ?? 'empty', quantity: next?.quantity ?? 0,
        durability: storedDurability(ctx, next?.itemKind ?? 'empty', next?.durability),
        lit: storedLit(next?.itemKind ?? 'empty', next?.lit),
      });
    }
    if (cookingInputChanged) {
      const current = ctx.db.world_placeable.id.find(menu.placeable.placeable.id);
      if (current !== null) ctx.db.world_placeable.id.update({
        ...current,
        cookStartTick: undefined,
        cookStartedBy: nextCookingInput === null ? undefined : ctx.sender,
        cookInputKind: undefined,
      });
    }
    if (cellarCapability !== null) {
      const current = ctx.db.world_placeable.id.find(menu.placeable.placeable.id);
      if (current !== null && (cellarInputChanged
        || (nextCellarInput !== null && current.processStartTick === undefined
          && current.processStartedBy === undefined))) {
        ctx.db.world_placeable.id.update({
          ...current,
          processStartTick: cellarInputChanged ? undefined : current.processStartTick,
          processStartedBy: nextCellarInput === null ? undefined : ctx.sender,
          processInputKind: undefined,
        });
      }
    }
    for (let index = 0; index < after.capacity; index += 1) {
      const previous = menu.placeable.container.slots[index] ?? null;
      const next = after.slots[index] ?? null;
      if (sameStoredStack(previous, next)) continue;
      raisePlaceableSlotChangedEvent(
        ctx,
        menu.placeable.placeable.id,
        index,
        previous,
        next,
        after,
      );
    }
    const latest = ctx.db.world_placeable.id.find(menu.placeable.placeable.id);
    if (latest !== null && genericChest(ctx, latest)) syncGenericChestLegacyMirror(ctx, latest);
  }
  updateEquippedForIdentity(ctx, ctx.sender, containers);
}

function stashOverflow(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  stack: { readonly itemKind: string; readonly quantity: number; readonly durability?: number; readonly lit?: boolean },
): void {
  const maximum = runtimeMaxStack(contentRegistry(ctx), stack.itemKind);
  if (maximum === null || stack.quantity <= 0) throw new SenderError('invalid_overflow_item');
  if (ctx.db.inventory_overflow_retry.identity.find(identity) !== null) {
    ctx.db.inventory_overflow_retry.identity.delete(identity);
  }
  let remaining = stack.quantity;
  while (remaining > 0) {
    const quantity = Math.min(remaining, maximum);
    ctx.db.inventory_overflow.insert({
      id: 0n, identity, itemKind: stack.itemKind, quantity,
      durability: storedDurability(ctx, stack.itemKind, stack.durability),
      lit: storedLit(stack.itemKind, stack.lit),
    });
    remaining -= quantity;
  }
}

/** Recovery is deterministic and transactional: an overflow row is only
 * changed after its exact moved quantity has been written into player slots. */
function drainPlayerOverflow(ctx: WorldReducerContext, identity: WorldReducerContext['sender']): void {
  const overflowRows = [...ctx.db.inventory_overflow.by_identity.filter(identity)]
    .sort((left, right) => left.id < right.id ? -1 : left.id > right.id ? 1 : 0);
  if (overflowRows.length === 0) {
    if (ctx.db.inventory_overflow_retry.identity.find(identity) !== null) {
      ctx.db.inventory_overflow_retry.identity.delete(identity);
    }
    return;
  }
  const inventory = loadPlayerInventory(ctx, identity);
  let containers: Readonly<Record<string, ContainerSnapshot>> = inventory.containers;
  for (const row of overflowRows) {
    const sourceId = `overflow:${row.id}`;
    const moved = quickMoveItemStack({
      ...containers,
      [sourceId]: { id: sourceId, capacity: 1, slots: [{
        itemKind: row.itemKind, quantity: row.quantity,
        ...(runtimeDurabilityDefinition(contentRegistry(ctx), row.itemKind) === null
          ? {} : { durability: row.durability }),
        lit: row.lit,
      }] },
    }, { fromContainer: sourceId, fromIndex: 0, toContainers: ['hotbar', 'backpack'] }, activeItemContainerContent(ctx));
    if (!moved.ok) {
      if (moved.code === 'container_full') break;
      throw new SenderError(moved.code);
    }
    containers = {
      hotbar: moved.containers.hotbar!,
      backpack: moved.containers.backpack!,
      equipment: moved.containers.equipment!,
      crafting: moved.containers.crafting!,
    };
    const remainder = moved.containers[sourceId]!.slots[0];
    if (remainder == null) ctx.db.inventory_overflow.id.delete(row.id);
    else ctx.db.inventory_overflow.id.update({
      ...row, quantity: remainder.quantity,
      durability: storedDurability(ctx, remainder.itemKind, remainder.durability),
      lit: storedLit(remainder.itemKind, remainder.lit),
    });
  }
  writePlayerInventory(ctx, inventory.rowBySlot, inventory.containers, containers);
  updateEquippedForIdentity(ctx, identity, containers);
  const remainsBlocked = firstIndexRow(ctx.db.inventory_overflow.by_identity.filter(identity)) !== null;
  const retry = ctx.db.inventory_overflow_retry.identity.find(identity);
  if (remainsBlocked && retry === null) ctx.db.inventory_overflow_retry.insert({ identity });
  else if (!remainsBlocked && retry !== null) ctx.db.inventory_overflow_retry.identity.delete(identity);
}

function writeAdminInventoryState(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  loaded: ReturnType<typeof loadAdminInventoryState>,
  after: AdminInventoryState,
): void {
  writePlayerInventory(ctx, loaded.inventory.rowBySlot, loaded.inventory.containers, after.containers);
  writePlayerInventoryCursor(ctx, identity, after.cursor);
  const previousOverflow = [...ctx.db.inventory_overflow.by_identity.filter(identity)]
    .sort((left, right) => left.id < right.id ? -1 : left.id > right.id ? 1 : 0);
  for (let index = 0; index < after.overflow.length; index += 1) {
    const stack = after.overflow[index]!;
    const values = {
      identity,
      itemKind: stack.itemKind,
      quantity: stack.quantity,
      durability: storedDurability(ctx, stack.itemKind, stack.durability),
      lit: storedLit(stack.itemKind, stack.lit),
    };
    const existing = previousOverflow[index];
    if (existing === undefined) ctx.db.inventory_overflow.insert({ id: 0n, ...values });
    else ctx.db.inventory_overflow.id.update({ ...existing, ...values });
  }
  for (const row of previousOverflow.slice(after.overflow.length)) {
    ctx.db.inventory_overflow.id.delete(row.id);
  }
  const retry = ctx.db.inventory_overflow_retry.identity.find(identity);
  if (after.overflow.length === 0 && retry !== null) ctx.db.inventory_overflow_retry.identity.delete(identity);
  else if (after.overflow.length > 0 && retry === null) ctx.db.inventory_overflow_retry.insert({ identity });
  updateEquippedForIdentity(ctx, identity, after.containers);
  refreshPlayerQuests(ctx, identity, ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n);
}

function loadAdminProgressionState(
  ctx: Pick<WorldReducerContext, 'db'>,
  identity: WorldReducerContext['sender'],
): AdminProgressionState {
  const wallet = ctx.db.player_wallet.identity.find(identity);
  const stats = ctx.db.player_stats.identity.find(identity);
  const survival = ctx.db.player_survival.identity.find(identity);
  if (wallet === null || stats === null || survival === null) throw new SenderError('admin_target_not_found');
  const skillTracks = [...ctx.db.player_skill_track.by_identity.filter(identity)].map((row) => {
    if (!isSkillTrack(row.track)) throw new SenderError('admin_payload_invalid');
    return { track: row.track, experience: row.experience, spentPoints: row.spentPoints,
      bonusPoints: row.bonusPoints, respecCount: row.respecCount };
  }).sort((left, right) => left.track.localeCompare(right.track));
  const skillNodes = [...ctx.db.player_skill_node.by_identity.filter(identity)].map((row) => {
    if (!isSkillTrack(row.track)) throw new SenderError('admin_payload_invalid');
    return { track: row.track, nodeId: row.nodeId, rank: row.rank };
  }).sort((left, right) => left.nodeId.localeCompare(right.nodeId));
  const quests = [...ctx.db.player_quest.by_identity.filter(identity)].map((row) => {
    if (row.state !== 'active' && row.state !== 'complete' && row.state !== 'turned_in') {
      throw new SenderError('admin_payload_invalid');
    }
    const state: AdminQuestStateValue = row.state;
    return {
      questId: row.questId, state, acceptedTick: row.acceptedTick,
      completedTick: row.completedTick ?? null, turnedInTick: row.turnedInTick ?? null,
      pinned: row.pinned,
    };
  }).sort((left, right) => left.questId.localeCompare(right.questId));
  return {
    walletBronze: wallet.balanceBronze,
    stats: { str: stats.str, dex: stats.dex, con: stats.con, int: stats.int, wis: stats.wis, cha: stats.cha },
    vitals: {
      healthCenti: stats.healthCenti, manaCenti: stats.manaCenti,
      vigourCenti: stats.vigourCenti, hungerCenti: survival.hungerCenti,
    },
    skillTracks,
    skillNodes,
    quests,
    questBaselines: [...ctx.db.player_quest_baseline.by_identity.filter(identity)]
      .map((row) => ({ questId: row.questId, objectiveId: row.objectiveId, value: row.value }))
      .sort((left, right) => `${left.questId}:${left.objectiveId}`.localeCompare(`${right.questId}:${right.objectiveId}`)),
    questWorldItems: [...ctx.db.quest_world_item.by_identity.filter(identity)]
      .map((row) => ({ questId: row.questId, objectiveId: row.objectiveId,
        surfaceId: row.surfaceId, slot: row.slot, itemKind: row.itemKind }))
      .sort((left, right) => `${left.questId}:${left.objectiveId}`.localeCompare(`${right.questId}:${right.objectiveId}`)),
  };
}

function writeAdminProgressionState(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  after: AdminProgressionState,
  mutation: {
    readonly operation: AdminProgressionMutation['operation'];
    readonly state?: string;
    readonly questId?: string;
  },
  cleanupAuxiliaryState = true,
): void {
  const wallet = ctx.db.player_wallet.identity.find(identity);
  const stats = ctx.db.player_stats.identity.find(identity);
  const survival = ctx.db.player_survival.identity.find(identity);
  if (wallet === null || stats === null || survival === null) throw new SenderError('admin_target_not_found');
  ctx.db.player_wallet.identity.update({ ...wallet, balanceBronze: after.walletBronze });
  ctx.db.player_stats.identity.update({
    ...stats,
    ...after.stats,
    healthCenti: after.vitals.healthCenti,
    manaCenti: after.vitals.manaCenti,
    vigourCenti: after.vitals.vigourCenti,
  });
  ctx.db.player_survival.identity.update({ ...survival, hungerCenti: after.vitals.hungerCenti });

  const tracks = new Map([...ctx.db.player_skill_track.by_identity.filter(identity)].map((row) => [row.track, row]));
  for (const next of after.skillTracks) {
    const row = tracks.get(next.track);
    if (row === undefined) throw new SenderError('admin_payload_invalid');
    ctx.db.player_skill_track.id.update({ ...row, ...next });
  }
  const nextNodes = new Map(after.skillNodes.map((row) => [row.nodeId, row]));
  for (const row of [...ctx.db.player_skill_node.by_identity.filter(identity)]) {
    const next = nextNodes.get(row.nodeId);
    if (next === undefined) ctx.db.player_skill_node.id.delete(row.id);
    else if (row.track !== next.track || row.rank !== next.rank) {
      ctx.db.player_skill_node.id.update({ ...row, ...next });
    }
    nextNodes.delete(row.nodeId);
  }
  for (const next of nextNodes.values()) {
    ctx.db.player_skill_node.insert({
      id: playerSkillNodeId(identity.toHexString(), next.nodeId),
      identity,
      ...next,
    });
  }

  const identityHex = identity.toHexString();
  const nextQuests = new Map(after.quests.map((row) => [row.questId, row]));
  for (const row of [...ctx.db.player_quest.by_identity.filter(identity)]) {
    const next = nextQuests.get(row.questId);
    if (next === undefined) ctx.db.player_quest.id.delete(row.id);
    else ctx.db.player_quest.id.update({
      ...row, ...next,
      completedTick: next.completedTick ?? undefined,
      turnedInTick: next.turnedInTick ?? undefined,
    });
    nextQuests.delete(row.questId);
  }
  for (const next of nextQuests.values()) ctx.db.player_quest.insert({
    id: playerQuestId(identityHex, next.questId), identity, ...next,
    completedTick: next.completedTick ?? undefined,
    turnedInTick: next.turnedInTick ?? undefined,
  });

  const nextBaselines = new Map(after.questBaselines.map((row) => [
    `${row.questId}:${row.objectiveId}`, row,
  ]));
  for (const row of [...ctx.db.player_quest_baseline.by_identity.filter(identity)]) {
    const key = `${row.questId}:${row.objectiveId}`;
    const next = nextBaselines.get(key);
    if (next === undefined) ctx.db.player_quest_baseline.id.delete(row.id);
    else if (row.value !== next.value) ctx.db.player_quest_baseline.id.update({ ...row, value: next.value });
    nextBaselines.delete(key);
  }
  for (const next of nextBaselines.values()) ctx.db.player_quest_baseline.insert({
    id: playerQuestBaselineId(identityHex, next.questId, next.objectiveId), identity, ...next,
  });

  const nextWorldItems = new Map(after.questWorldItems.map((row) => [
    `${row.questId}:${row.objectiveId}`, row,
  ]));
  for (const row of [...ctx.db.quest_world_item.by_identity.filter(identity)]) {
    const key = `${row.questId}:${row.objectiveId}`;
    const next = nextWorldItems.get(key);
    if (next === undefined) ctx.db.quest_world_item.id.delete(row.id);
    else if (row.surfaceId !== next.surfaceId || row.slot !== next.slot || row.itemKind !== next.itemKind) {
      ctx.db.quest_world_item.id.update({ ...row, ...next });
    }
    nextWorldItems.delete(key);
  }
  for (const next of nextWorldItems.values()) {
    ctx.db.quest_world_item.insert({
      id: questWorldItemId(identityHex, next.questId, next.objectiveId),
      identity,
      ...next,
    });
  }
  const resetAllQuests = cleanupAuxiliaryState && mutation.operation === 'reset_quests';
  const resetQuestId = cleanupAuxiliaryState && mutation.operation === 'set_quest_state' && mutation.state === 'available'
    ? mutation.questId
    : null;
  for (const row of [...ctx.db.player_quest_reach_presence.by_identity.filter(identity)]) {
    if (resetAllQuests || row.questId === resetQuestId) ctx.db.player_quest_reach_presence.id.delete(row.id);
  }
  if (resetAllQuests) {
    for (const row of [...ctx.db.player_quest_flag.by_identity.filter(identity)]) {
      // The Delve lifetime receipt is not quest progress and survives quest resets.
      if (row.id !== `${identityHex}:${DELVE_COMPLETION_FLAG}`) ctx.db.player_quest_flag.id.delete(row.id);
    }
    if (ctx.db.player_thought.identity.find(identity) !== null) ctx.db.player_thought.identity.delete(identity);
  }
}

/** Version 22 centered the unchanged legacy island inside a much larger ocean.
 * Shift every persistent spatial row exactly once so player-authored state
 * remains attached to the same relative island tile. Generated resources are
 * rebuilt by the normal terrain migration immediately afterwards. */
function migrateWorldForOceanExpansion(ctx: WorldReducerContext, installedVersion: number): void {
  if (installedVersion >= WORLD_OCEAN_EXPANSION_VERSION) return;
  const shiftedFixed = (value: number): number => value + WORLD_OCEAN_SHIFT_FIXED;
  const shiftedTile = (value: number): number => value + SURVIVAL_ISLAND_OFFSET_TILES;

  for (const row of ctx.db.player_position.iter()) {
    const x = shiftedFixed(row.x);
    const y = shiftedFixed(row.y);
    ctx.db.player_position.identity.update({
      ...row,
      x,
      y,
      chunkX: chunkAt(x),
      chunkY: chunkAt(y),
      jumpFromX: row.jumpFromX === undefined ? undefined : shiftedFixed(row.jumpFromX),
      jumpFromY: row.jumpFromY === undefined ? undefined : shiftedFixed(row.jumpFromY),
    });
  }
  for (const row of ctx.db.world_speech.iter()) {
    ctx.db.world_speech.id.update({ ...row, x: shiftedFixed(row.x), y: shiftedFixed(row.y) });
  }
  for (const row of ctx.db.world_tree.iter()) {
    const x = shiftedFixed(row.x);
    const y = shiftedFixed(row.y);
    ctx.db.world_tree.id.update({ ...row, x, y, chunkX: chunkAt(x), chunkY: chunkAt(y) });
  }
  for (const row of [...ctx.db.world_soil.iter()]) {
    const tileX = shiftedTile(row.tileX);
    const tileY = shiftedTile(row.tileY);
    ctx.db.world_soil.id.delete(row.id);
    ctx.db.world_soil.insert({
      ...row,
      id: `${tileX}:${tileY}`,
      tileX,
      tileY,
      chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
      chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
    });
  }
  for (const row of ctx.db.world_item.iter()) {
    const x = shiftedFixed(row.x);
    const y = shiftedFixed(row.y);
    ctx.db.world_item.id.update({ ...row, x, y, chunkX: chunkAt(x), chunkY: chunkAt(y) });
  }
  // Projectiles are short-lived and cannot be meaningfully resumed across a
  // module migration; dropping them avoids translating an in-flight trace.
  ctx.db.world_projectile.clear();
  ctx.db.projectile_charge.clear();
  for (const row of ctx.db.world_chest.iter()) {
    const tileX = shiftedTile(row.tileX);
    const tileY = shiftedTile(row.tileY);
    const shifted = {
      ...row,
      tileX,
      tileY,
      chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
      chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
    };
    ctx.db.world_chest.id.update(shifted);
    syncLegacyChestGenericMirror(ctx, shifted);
  }
  for (const row of ctx.db.world_npc.iter()) {
    const x = shiftedFixed(row.x);
    const y = shiftedFixed(row.y);
    updateWorldNpc(ctx, {
      ...row,
      x,
      y,
      homeX: shiftedFixed(row.homeX),
      homeY: shiftedFixed(row.homeY),
      chunkX: chunkAt(x),
      chunkY: chunkAt(y),
    });
  }
  for (const row of ctx.db.world_hive.iter()) {
    const tileX = shiftedTile(row.tileX);
    const tileY = shiftedTile(row.tileY);
    ctx.db.world_hive.id.update({
      ...row,
      tileX,
      tileY,
      chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
      chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
    });
  }
  for (const row of ctx.db.farm_parcel.iter()) {
    ctx.db.farm_parcel.id.update({
      ...row,
      originX: shiftedTile(row.originX),
      originY: shiftedTile(row.originY),
    });
  }
  for (const row of ctx.db.crop_patch.iter()) {
    const tileX = shiftedTile(row.tileX);
    const tileY = shiftedTile(row.tileY);
    ctx.db.crop_patch.id.update({
      ...row,
      tileX,
      tileY,
      chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
      chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
    });
  }
}

type GeneratedSurvivalResource = ReturnType<typeof generateSurvivalResources>[number];

function generatedWorldResourceRow(resource: GeneratedSurvivalResource, registry: ContentRegistry) {
  const definition = runtimeResourceDefinition(registry, resource.kind);
  if (definition === null) throw new SenderError('resource_definition_missing');
  const mining = definition.interaction.mode === 'mine';
  const fishing = definition.interaction.mode === 'fish';
  const nodeClass: MiningNodeClass | '' = mining
    ? resource.nodeClass ?? definition.mining?.nodeClass ?? 'mixed'
    : '';
  const maximumRichness = fishing
    ? resource.richness ?? 2
    : mining
    ? resource.richness ?? 1 + statelessRoll(
      [SURVIVAL_WORLD_SEED, resource.id, 'mining.generated_richness'], MINING_MAX_RICHNESS,
    )
    : 0;
  return {
    id: BigInt(resource.id),
    kind: resource.kind,
    tileX: resource.tileX,
    tileY: resource.tileY,
    chunkX: Math.floor(resource.tileX / SURVIVAL_CHUNK_TILES),
    chunkY: Math.floor(resource.tileY / SURVIVAL_CHUNK_TILES),
    health: mining || fishing ? maximumRichness : definition.health.initial,
    depleted: false,
    growthStage: TREE_GROWTH_STAGE_BIG,
    regrowthProgress: TREE_REGROWTH_PROGRESS_MAX,
    spaceId: TOPSIDE_SPACE_ID,
    miningClass: nodeClass,
    richness: maximumRichness,
    maximumRichness,
    yieldProgress: 0,
    yieldsProduced: 0,
    producedOre: false,
    spawnSiteId: BigInt(resource.spawnSiteId ?? 0),
    activationOrdinal: resource.activationOrdinal ?? 0,
    respawnAtTick: 0n,
    miningClaimedBy: undefined,
    miningPartyId: undefined,
    miningClaimUntilTick: 0n,
    definitionId: definition.id,
    fruitReadyAtTick: 0n,
  };
}

/** A terrain version may move generated resources off new contour walls, but
 * unchanged rows retain depletion and regrowth progress. Player inventories,
 * soil, chests, and placeables are never part of this reconciliation. */
function reconcileGeneratedSurvivalResources(ctx: WorldReducerContext): void {
  const existingRows = [...ctx.db.world_resource.iter()];
  const registry = contentRegistry(ctx);
  // Validate the entire reserved cohort before any legacy migration writes.
  for (const row of existingRows) {
    const activeSite = runtimeHearthResourceSite(registry, row.id);
    if (activeSite !== null && !runtimeHearthResourceRowMatchesSite(registry, row)) {
      throw new SenderError('hearth_resource_site_conflict');
    }
  }
  const placements = new Map((compiledLiveIslandRuntime(ctx)?.document.resourcePlacements ?? [])
    .map(placement => [BigInt(placement.id), placement]));
  const desired = new Map(generateSurvivalResources(SURVIVAL_WORLD_SEED, registry)
    .map(resource => {
      const placement = placements.get(BigInt(resource.id));
      return [BigInt(resource.id), placement === undefined ? resource
        : {...resource, tileX: placement.tileX, tileY: placement.tileY}] as const;
    }));
  for (const existing of existingRows) {
    if (existing.spaceId !== TOPSIDE_SPACE_ID
      || isPlantedFruitTreeId(existing.id)
      || isAuthoredHearthResourceSiteId(registry, existing.id)) continue;
    const generated = desired.get(existing.id);
    if (generated === undefined) {
      if (placements.has(existing.id)) continue;
      ctx.db.world_resource_mining_claim.resourceId.delete(existing.id);
      ctx.db.world_resource.id.delete(existing.id);
      continue;
    }
    desired.delete(existing.id);
    const nextBase = generatedWorldResourceRow(generated, registry);
    if (existing.kind !== generated.kind) {
      ctx.db.world_resource_mining_claim.resourceId.delete(existing.id);
      ctx.db.world_resource.id.update(nextBase);
      continue;
    }
    if ((isMineableOreKind(existing.kind, registry) || isBreakableRockKind(existing.kind, registry))
      && existing.maximumRichness === 0) {
      ctx.db.world_resource.id.update({
        ...existing,
        ...nextBase,
        depleted: existing.depleted,
        richness: existing.depleted ? 0 : nextBase.richness,
        health: existing.depleted ? 0 : nextBase.health,
      });
      continue;
    }
    if (existing.tileX !== generated.tileX || existing.tileY !== generated.tileY
      || existing.chunkX !== nextBase.chunkX || existing.chunkY !== nextBase.chunkY) {
      ctx.db.world_resource.id.update({
        ...existing,
        tileX: generated.tileX,
        tileY: generated.tileY,
        chunkX: nextBase.chunkX,
        chunkY: nextBase.chunkY,
      });
    }
  }
  for (const resource of desired.values()) ctx.db.world_resource.insert(generatedWorldResourceRow(resource, registry));
}

const MINING_MIGRATION_VERSION = 1;
const MINING_DROP_RESERVATION_TICKS = BigInt(10 * AUTHORITY_HZ);
const MINING_RESPAWN_SWEEP_TICKS = BigInt(5 * AUTHORITY_HZ);
const MINING_CLAIM_TICKS = BigInt(30 * AUTHORITY_HZ);

function playerPartyId(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
): bigint | undefined {
  return ctx.db.player_party_member.identity.find(identity)?.partyId;
}

function miningClassForResource(registry: ContentRegistry, resource: WorldResourceRow): MiningNodeClass {
  const authored = runtimeResourceDefinition(registry, resource)?.mining?.nodeClass;
  if (authored === 'rock') return 'rock';
  if (resource.miningClass === 'pure' || resource.miningClass === 'pristine'
    || resource.miningClass === 'mixed') return resource.miningClass;
  return resource.spaceId === TOPSIDE_SPACE_ID ? authored ?? 'mixed' : 'pure';
}

function miningRespawnDelayTicks(
  nodeClass: MiningNodeClass,
  seedParts: readonly (string | number | bigint)[],
): bigint {
  const [minimumMinutes, maximumMinutes] = nodeClass === 'rock' ? [5, 10]
    : nodeClass === 'pure' ? [15, 30] : [10, 20];
  const minimum = minimumMinutes * 60 * AUTHORITY_HZ;
  const spread = (maximumMinutes - minimumMinutes) * 60 * AUTHORITY_HZ;
  return BigInt(minimum + statelessRoll([...seedParts, 'mining.respawn'], spread + 1));
}

function fishingRespawnDelayTicks(seedParts: readonly (string | number | bigint)[]): bigint {
  const minimum = 3 * 60 * AUTHORITY_HZ;
  const spread = 5 * 60 * AUTHORITY_HZ;
  return BigInt(minimum + statelessRoll([...seedParts, 'fishing.respawn'], spread + 1));
}

/** Existing underground veins and rocks gain deterministic richness once.
 * The generated surface population is replaced separately by world version 27. */
function ensureMiningMigration(ctx: WorldReducerContext): void {
  const migration = ctx.db.world_scalability_migration.id.find(0);
  if ((migration?.miningVersion ?? 0) >= MINING_MIGRATION_VERSION) return;
  const seed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
  const registry = contentRegistry(ctx);
  for (const resource of ctx.db.world_resource.iter()) {
    if (isAuthoredHearthResourceSiteId(registry, resource.id)) continue;
    if ((!isMineableOreKind(resource.kind, registry) && !isBreakableRockKind(resource.kind, registry))
      || resource.maximumRichness > 0) continue;
    const nodeClass = miningClassForResource(registry, resource);
    const maximumRichness = nodeClass === 'mixed'
      ? 1 + statelessRoll([seed, resource.id, 'mining.legacy_surface'], 2)
      : 1 + statelessRoll([seed, resource.id, 'mining.legacy_richness'], MINING_MAX_RICHNESS);
    ctx.db.world_resource.id.update({
      ...resource,
      miningClass: nodeClass,
      richness: resource.depleted ? 0 : maximumRichness,
      maximumRichness,
      health: resource.depleted ? 0 : maximumRichness,
      yieldProgress: 0,
      yieldsProduced: 0,
      producedOre: false,
      respawnAtTick: 0n,
    });
  }
  const nextMigration = {
    id: 0,
    wildlifeProfileChunkVersion: migration?.wildlifeProfileChunkVersion ?? 1,
    horseDismountRecoveryVersion: migration?.horseDismountRecoveryVersion ?? 0,
    soilDecayTimerVersion: migration?.soilDecayTimerVersion ?? 0,
    miningVersion: MINING_MIGRATION_VERSION,
    privateStateVersion: migration?.privateStateVersion ?? 0,
    legacyFarmVersion: migration?.legacyFarmVersion ?? 0,
  };
  if (migration === null) ctx.db.world_scalability_migration.insert(nextMigration);
  else ctx.db.world_scalability_migration.id.update(nextMigration);
}

const PRIVATE_STATE_MIGRATION_VERSION = 1;

/** T10 additive cutover. Legacy public columns are read exactly once, then all
 * authority reads and writes use the narrow companion state below. */
function ensurePrivateStateMigration(ctx: WorldReducerContext): void {
  const migration = ctx.db.world_scalability_migration.id.find(0);
  if ((migration?.privateStateVersion ?? 0) >= PRIVATE_STATE_MIGRATION_VERSION) return;
  const authorityTick = ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n;
  for (const position of ctx.db.player_position.iter()) {
    const input = ctx.db.player_input.identity.find(position.identity);
    if (input !== null && input.lastProcessedSequence !== position.lastProcessedSequence) {
      ctx.db.player_input.identity.update({
        ...input,
        lastProcessedSequence: position.lastProcessedSequence,
      });
    }
    if (position.jumpFromX === undefined || position.jumpFromY === undefined
      || position.jumpUntilTick === undefined || position.jumpUntilTick < authorityTick
      || ctx.db.player_jump_state.identity.find(position.identity) !== null) continue;
    ctx.db.player_jump_state.insert({
      identity: position.identity,
      fromX: position.jumpFromX,
      fromY: position.jumpFromY,
      untilTick: position.jumpUntilTick,
      spaceId: position.spaceId,
      chunkX: position.chunkX,
      chunkY: position.chunkY,
    });
  }
  for (const resource of ctx.db.world_resource.iter()) {
    if (resource.miningClaimedBy === undefined || resource.miningClaimUntilTick <= authorityTick
      || ctx.db.world_resource_mining_claim.resourceId.find(resource.id) !== null) continue;
    ctx.db.world_resource_mining_claim.insert({
      resourceId: resource.id,
      claimedBy: resource.miningClaimedBy,
      partyId: resource.miningPartyId,
      claimUntilTick: resource.miningClaimUntilTick,
    });
  }
  const nextMigration = {
    id: 0,
    wildlifeProfileChunkVersion: migration?.wildlifeProfileChunkVersion ?? 1,
    horseDismountRecoveryVersion: migration?.horseDismountRecoveryVersion ?? 0,
    soilDecayTimerVersion: migration?.soilDecayTimerVersion ?? 0,
    miningVersion: migration?.miningVersion ?? 0,
    privateStateVersion: PRIVATE_STATE_MIGRATION_VERSION,
    legacyFarmVersion: migration?.legacyFarmVersion ?? 0,
  };
  if (migration === null) ctx.db.world_scalability_migration.insert(nextMigration);
  else ctx.db.world_scalability_migration.id.update(nextMigration);
}

function surfaceOreRespawnTileBlocked(
  tileX: number,
  tileY: number,
  activeOres: readonly WorldResourceRow[],
  occupiedTiles: ReadonlySet<string>,
): boolean {
  if (activeOres.some((ore) => Math.hypot(ore.tileX - tileX, ore.tileY - tileY) < ORE_MIN_SPACING_TILES)) {
    return true;
  }
  return occupiedTiles.has(`${tileX}:${tileY}`);
}

function hearthResourceSiteEnabled(ctx: WorldReducerContext, resource: WorldResourceRow): boolean {
  const registry = contentRegistry(ctx);
  const site = runtimeHearthResourceSite(registry, resource.id);
  if (site === null || !runtimeHearthResourceRowMatchesSite(registry, resource)) return false;
  // Content can be republished after installation. Suspend work/refill rather
  // than consume tools for missing rewards or replenish a retired loot cohort.
  if (!hearthGatheringContentReady(registry)) return false;
  const policy = compiledLiveIslandRuntime(ctx)?.combatPolicy;
  const camp = ctx.db.outdoor_encounter.id.find(site.encounterId);
  return policy !== undefined && camp !== null && camp.conflict === ''
    && policy.allowsHostileDamage({ spaceId: TOPSIDE_SPACE_ID, tileX: site.tileX + .5, tileY: site.tileY + .5 })
    && !liveMapGeneratedResourceSuppressed(ctx, resource.spaceId, resource.id);
}

/** Hearth nodes are authored, never opportunistically accepted by kind alone.
 * Exclude only the target resource from collision so a swing can reach its own
 * solid body while retaining cliffs, furniture, chests and other resources. */
function requireHearthResourceHarvestAccess(ctx: WorldReducerContext, position: PlayerPositionRow, resource: WorldResourceRow): void {
  const registry = contentRegistry(ctx);
  const site = runtimeHearthResourceSite(registry, resource.id);
  const hearthKind = isAuthoredHearthResourceSiteId(registry, resource.id)
    || activeHearthResourceSites(registry).some((candidate) => candidate.kind === resource.kind)
    || runtimeHearthResourceDefinition(registry, resource) !== null;
  if (site === null && !hearthKind) return;
  if (site === null || !runtimeHearthResourceRowMatchesSite(registry, resource)
    || position.spaceId !== resource.spaceId) {
    throw new SenderError('target_not_ready');
  }
  if (!hearthResourceSiteEnabled(ctx, resource)) throw new SenderError('target_not_ready');
  if (site.maturityGrowthStage !== null
    && resource.growthStage !== site.maturityGrowthStage) throw new SenderError('resource_not_mature');
  const collision = outdoorCollisionMap(ctx, resource.id);
  if (!hearthResourceGeometryAllows(position, resource.id, collision, registry)) throw new SenderError('target_out_of_reach');
}

/** Explicit owner operation for the final reviewed release, never startup or
 * legacy generator reconciliation. Asset deployment/readiness is a release gate;
 * clients cannot assert it with a ready flag. The exact live map/content snapshot
 * and all authority geometry/custody are rechecked in this transaction. */
function installHearthResourceSites(ctx: WorldReducerContext, expectedMapRevision: number,
  expectedMapHash: string, expectedContentHash: string): void {
  const map = ctx.db.live_map_document.mapId.find(LIVE_ISLAND_MAP_ID);
  const registry = contentRegistry(ctx);
  if (map === null || map.revision !== expectedMapRevision || map.contentHash !== expectedMapHash
    || registry.contentHash !== expectedContentHash) throw new SenderError('hearth_resource_snapshot_changed');
  const receipt = ctx.db.hearth_resource_installation.id.find(0);
  const missing: bigint[] = [];
  for (const site of activeHearthResourceSites(registry)) {
    const existing = ctx.db.world_resource.id.find(site.id);
    if (existing !== null) {
      if (!runtimeHearthResourceRowMatchesSite(registry, existing)) throw new SenderError('hearth_resource_site_conflict');
      continue; // Matching mutable harvest state and both custody tables are untouched.
    }
    if (receipt !== null || ctx.db.world_resource_mining_claim.resourceId.find(site.id) !== null
      || ctx.db.hearth_resource_depletion.resourceId.find(site.id) !== null) throw new SenderError('hearth_resource_custody_conflict');
    missing.push(site.id);
  }
  if (receipt !== null) {
    if (receipt.version !== 1) throw new SenderError('hearth_resource_installation_version');
    return;
  }
  const rows = missing.map((id) => {
    const row = initialHearthResourceState(id, registry)!;
    const definitionId = runtimeResourceDefinitionId(registry, row);
    if (definitionId === null) throw new SenderError('resource_definition_missing');
    return { ...row, definitionId, fruitReadyAtTick: 0n };
  });
  if (!hearthGatheringContentReady(registry)) throw new SenderError('hearth_resource_content_missing');
  const players = [...ctx.db.player_position.iter()].filter(player => player.spaceId === TOPSIDE_SPACE_ID);
  for (const row of rows) {
    if (!hearthResourceSiteEnabled(ctx, row)) throw new SenderError('hearth_resource_site_disabled');
    const site = runtimeHearthResourceSite(registry, row.id)!;
    const definition = runtimeHearthEncounterDefinition(registry, site.encounterDefinitionId);
    if (definition === null) throw new SenderError('hearth_resource_encounter_missing');
    const camp = ctx.db.outdoor_encounter.id.find(site.encounterId)!;
    if (!['dormant', 'active', 'completed'].includes(camp.phase) || (camp.phase === 'active' && camp.activated))
      throw new SenderError('hearth_resource_encounter_busy');
    if (players.some(player => ctx.db.player_public.identity.find(player.identity)?.online
      && outdoorInsideCamp(definition, player, OUTDOOR_SIGHT_PADDING_TILES))) throw new SenderError('hearth_resource_in_sight');
    const base = runtimeResourceObstacle(registry, row, row.tileX, row.tileY);
    if (base === null) throw new SenderError('resource_definition_missing');
    if (players.some(player => boundsOverlap(base, playerHitboxBounds(player)))) throw new SenderError('hearth_resource_player_occupied');
    for (let y = row.chunkY - 1; y <= row.chunkY + 1; y++) for (let x = row.chunkX - 1; x <= row.chunkX + 1; x++) {
      if ([...ctx.db.world_npc.by_chunk.filter([TOPSIDE_SPACE_ID, x, y])].some(npc => npc.health > 0
        && Math.abs(npc.x / TILE_SIZE_FIXED - (row.tileX + .5)) < 2
        && Math.abs(npc.y / TILE_SIZE_FIXED - (row.tileY + .5)) < 2)) throw new SenderError('hearth_resource_npc_occupied');
      const cultivated = [...ctx.db.world_soil.by_chunk.filter([TOPSIDE_SPACE_ID, x, y]),
        ...ctx.db.crop_patch.by_chunk.filter([TOPSIDE_SPACE_ID, x, y])];
      if (cultivated.some(tile => Math.abs(tile.tileX - row.tileX) <= 1 && Math.abs(tile.tileY - row.tileY) <= 1))
        throw new SenderError('hearth_resource_cultivated');
    }
  }
  // Installation proves routes across the whole island, so the camp-scoped
  // tick collision is insufficient: it can omit resources on detour corridors.
  const collision = hearthResourceInstallationGeometry(collisionForSpace(ctx, TOPSIDE_SPACE_ID), missing, registry);
  const runtime = compiledLiveIslandRuntime(ctx);
  const policy = runtime?.combatPolicy;
  const regions = runtime?.document.combatRegions;
  if (collision === null || runtime === null || policy === undefined || regions === undefined)
    throw new SenderError('hearth_resource_geometry_conflict');
  const recovery = outdoorRecoveryPosition(ctx, policy, collision);
  if (recovery === null || !hearthResourceInstallationRoutes(collision, missing, recovery, {
    spaceId: TOPSIDE_SPACE_ID,
    regions,
  }, registry))
    throw new SenderError('hearth_resource_route_conflict');
  if (activeHearthEncounterDefinitions(registry).some(camp => camp.members.some(member => {
    const home = { x: (member.tileX + .5) * TILE_SIZE_FIXED, y: (member.tileY + .5) * TILE_SIZE_FIXED };
    return !outdoorMovementAllowed(policy, camp, home, home, collision);
  }))) throw new SenderError('hearth_resource_camp_conflict');
  // All validation precedes the first write. Receipt and nodes commit together.
  for (const row of rows) ctx.db.world_resource.insert(row);
  ctx.db.hearth_resource_installation.insert({ id: 0, version: 1, mapRevision: map.revision,
    mapHash: map.contentHash, contentHash: registry.contentHash, installedAt: ctx.timestamp, installedBy: ctx.sender });
}

export const installHearthGatheringSites = spacetimedb.reducer({ expectedMapRevision: t.u32(),
  expectedMapHash: t.string(), expectedContentHash: t.string() }, (ctx, args) => {
  requireWorldOwner(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  installHearthResourceSites(ctx, args.expectedMapRevision, args.expectedMapHash, args.expectedContentHash);
});

function recordHearthResourceDepletion(ctx: WorldReducerContext, resource: WorldResourceRow, tick: bigint): void {
  const registry = contentRegistry(ctx);
  if (!runtimeHearthResourceRowMatchesSite(registry, resource)) return;
  const old = ctx.db.hearth_resource_depletion.resourceId.find(resource.id);
  if (old !== null) return; // Never restart an existing cooldown or repair a stale generation silently.
  const state = beginHearthResourceDepletion(resource.id, resource.activationOrdinal, tick, registry);
  ctx.db.hearth_resource_depletion.insert({ ...state, quietSinceTick: undefined,
    lastObservedMicros: ctx.timestamp.microsSinceUnixEpoch });
}
/** Bounded authored-site probes. Observe presence every tick, persisting quiet samples at
 * one hertz plus immediate interruptions. Refills and tracker deletion share the
 * authority transaction; no timer callback can replay a reward or generation. */
function stepHearthResourceRespawns(ctx: WorldReducerContext, tick: bigint, players: readonly PlayerPositionRow[]): void {
  let collision: CollisionMap | undefined;
  const now = ctx.timestamp.microsSinceUnixEpoch;
  const registry = contentRegistry(ctx);
  for (const site of activeHearthResourceSites(registry)) {
    const resource = ctx.db.world_resource.id.find(site.id);
    if (resource === null || !resource.depleted
      || !runtimeHearthResourceRowMatchesSite(registry, resource)) continue;
    let stored = ctx.db.hearth_resource_depletion.resourceId.find(site.id);
    if (stored === null) {
      // Conservative recovery of an old depleted row: never invent its old cooldown.
      recordHearthResourceDepletion(ctx, resource, tick);
      continue;
    }
    if (stored.activationOrdinal !== resource.activationOrdinal) continue;
    const definition = runtimeHearthEncounterDefinition(registry, site.encounterDefinitionId);
    if (definition === null) continue;
    const camp = ctx.db.outdoor_encounter.id.find(site.encounterId);
    const enabled = hearthResourceSiteEnabled(ctx, resource);
    const visible = players.some(player => player.spaceId === TOPSIDE_SPACE_ID
      && outdoorInsideCamp(definition, player, OUTDOOR_SIGHT_PADDING_TILES));
    const engaged = camp === null || !['dormant', 'active', 'completed'].includes(camp.phase)
      || (camp.phase === 'active' && camp.activated);
    const interrupted = !enabled || visible || engaged;
    if (tick % BigInt(AUTHORITY_HZ) !== 0n && !(interrupted && stored.quietSinceTick !== undefined)) continue;
    let clear = false;
    if (!interrupted) {
      collision ??= outdoorCollisionMap(ctx);
      // Conservative 3x3 approach envelope; native node installation must also
      // validate the authored footprint before creating any manifest row.
      clear = [-1, 0, 1].every(dx => [-1, 0, 1].every(dy => {
        const point = { x: (site.tileX + dx + .5) * TILE_SIZE_FIXED, y: (site.tileY + dy + .5) * TILE_SIZE_FIXED };
        return !positionCollides(point, collision!) && combatElevationAt(collision!, point.x, point.y) === site.elevation;
      }));
      if (clear) for (let y = resource.chunkY - 1; y <= resource.chunkY + 1; y++) {
        for (let x = resource.chunkX - 1; x <= resource.chunkX + 1; x++) {
          if ([...ctx.db.world_npc.by_chunk.filter([TOPSIDE_SPACE_ID, x, y])].some(npc => npc.health > 0
            && Math.abs(npc.x / TILE_SIZE_FIXED - (site.tileX + .5)) < 2
            && Math.abs(npc.y / TILE_SIZE_FIXED - (site.tileY + .5)) < 2)) clear = false;
        }
      }
    }
    const elapsedMicros = now - stored.lastObservedMicros;
    const plan = planHearthResourceRespawn({ ...stored, quietSinceTick: stored.quietSinceTick ?? null }, {
      tick, activationOrdinal: resource.activationOrdinal, depleted: resource.depleted,
      siteEnabled: enabled, playerInSight: visible, encounterEngaged: engaged, footprintClear: clear,
      continuousObservation: elapsedMicros > 0n && elapsedMicros <= 1_500_000n,
    }, registry);
    if (plan.respawn) {
      ctx.db.world_resource.id.update({ ...resource, health: site.health, depleted: false,
        growthStage: site.maturityGrowthStage ?? 3, regrowthProgress: site.regrowthProgress,
        richness: site.richness, maximumRichness: site.richness,
        miningClass: site.nodeClass,
        yieldProgress: 0, yieldsProduced: 0, producedOre: false, respawnAtTick: 0n,
        activationOrdinal: plan.nextActivationOrdinal,
        miningClaimedBy: undefined, miningPartyId: undefined, miningClaimUntilTick: 0n });
      ctx.db.world_resource_mining_claim.resourceId.delete(site.id);
      ctx.db.hearth_resource_depletion.resourceId.delete(site.id);
    } else if (plan.state.lastObservedTick !== stored.lastObservedTick) {
      stored = { ...plan.state, quietSinceTick: plan.state.quietSinceTick ?? undefined, lastObservedMicros: now };
      ctx.db.hearth_resource_depletion.resourceId.update(stored);
    }
  }
}

function respawnMiningResources(ctx: WorldReducerContext, authorityTick: bigint): void {
  if (authorityTick % MINING_RESPAWN_SWEEP_TICKS !== 0n) return;
  const seed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
  const registry = contentRegistry(ctx);
  const activeSurfaceOres = [...ctx.db.world_resource.by_chunk.filter(TOPSIDE_SPACE_ID)]
    .filter((resource) => legacySurfaceOreSlot(resource, registry) !== null && !resource.depleted);
  const activeFishPools = [...ctx.db.world_resource.by_chunk.filter(TOPSIDE_SPACE_ID)]
    .filter((resource) => runtimeResourceDefinition(registry, resource)?.respawn?.profile === 'fishing_pool'
      && !resource.depleted);
  const occupiedSurfaceTiles = new Set<string>();
  for (const player of ctx.db.player_position.iter()) {
    if (player.spaceId !== TOPSIDE_SPACE_ID) continue;
    occupiedSurfaceTiles.add(
      `${Math.floor(player.x / TILE_SIZE_FIXED)}:${Math.floor(player.y / TILE_SIZE_FIXED)}`,
    );
  }
  for (const soil of ctx.db.world_soil.by_chunk.filter(TOPSIDE_SPACE_ID)) {
    occupiedSurfaceTiles.add(`${soil.tileX}:${soil.tileY}`);
  }
  for (const placeable of ctx.db.world_placeable.by_chunk.filter(TOPSIDE_SPACE_ID)) {
    if (placeable.carriedBy === undefined) occupiedSurfaceTiles.add(`${placeable.tileX}:${placeable.tileY}`);
  }
  for (const chest of ctx.db.world_chest.by_chunk.filter(TOPSIDE_SPACE_ID)) {
    if (chest.carriedBy === undefined) occupiedSurfaceTiles.add(`${chest.tileX}:${chest.tileY}`);
  }
  for (const resource of [...ctx.db.world_resource.by_depleted.filter(true)]) {
    if (isAuthoredHearthResourceSiteId(registry, resource.id)) continue;
    const definition = runtimeResourceDefinition(registry, resource);
    if ((definition === null || (definition.interaction.mode !== 'mine' && definition.interaction.mode !== 'fish'))
      || resource.respawnAtTick === 0n || resource.respawnAtTick > authorityTick) continue;
    ctx.db.world_resource_mining_claim.resourceId.delete(resource.id);
    if (definition.respawn?.profile === 'fishing_pool' && resource.spaceId === TOPSIDE_SPACE_ID
      && resource.id >= BigInt(FISH_POOL_RESOURCE_ID_BASE)) {
      const slot = Number(resource.id - BigInt(FISH_POOL_RESOURCE_ID_BASE));
      const activationOrdinal = resource.activationOrdinal + 1;
      const activeSiteIds = new Set(activeFishPools.map((pool) => pool.spawnSiteId.toString()));
      const site = fishPoolRespawnCandidates(slot, activationOrdinal, seed, registry).find((candidate) => (
        !activeSiteIds.has(BigInt(candidate.id).toString())
        && !occupiedSurfaceTiles.has(`${candidate.tileX}:${candidate.tileY}`)
        && !activeFishPools.some((pool) => (
          Math.hypot(pool.tileX - candidate.tileX, pool.tileY - candidate.tileY)
            < FISH_POOL_MIN_SPACING_TILES
        ))
      ));
      if (site === undefined) continue;
      const generated = fishPoolResourceAtSite(site, slot, activationOrdinal, registry);
      const replacement = generatedWorldResourceRow(generated, registry);
      ctx.db.world_resource.id.update(replacement);
      activeFishPools.push(replacement);
      continue;
    }
    const nodeClass = miningClassForResource(contentRegistry(ctx), resource);
    const slot = legacySurfaceOreSlot(resource, registry);
    if (slot !== null) {
      const activationOrdinal = resource.activationOrdinal + 1;
      const activeSiteIds = new Set(activeSurfaceOres.map((ore) => ore.spawnSiteId.toString()));
      const site = surfaceOreRespawnCandidates(slot, activationOrdinal, seed, registry).find((candidate) => (
        !activeSiteIds.has(BigInt(candidate.id).toString())
        && !surfaceOreRespawnTileBlocked(
          candidate.tileX, candidate.tileY, activeSurfaceOres, occupiedSurfaceTiles,
        )
      ));
      if (site === undefined) continue;
      const generated = surfaceOreResourceAtSite(site, slot, activationOrdinal);
      const replacement = generatedWorldResourceRow(generated, registry);
      ctx.db.world_resource.id.update(replacement);
      activeSurfaceOres.push(replacement);
      continue;
    }
    const maximumRichness = 1 + statelessRoll(
      [seed, resource.id, resource.activationOrdinal + 1, 'mining.respawn_richness'], MINING_MAX_RICHNESS,
    );
    ctx.db.world_resource.id.update({
      ...resource,
      miningClass: nodeClass,
      health: maximumRichness,
      depleted: false,
      richness: maximumRichness,
      maximumRichness,
      yieldProgress: 0,
      yieldsProduced: 0,
      producedOre: false,
      activationOrdinal: resource.activationOrdinal + 1,
      respawnAtTick: 0n,
    });
  }
}

