export const prioritizeEquipmentSkill = spacetimedb.reducer(
  { nodeId: t.string() },
  (ctx,{nodeId}) => {
    requireAuthorizedSender(ctx.senderAuth.jwt,ctx.db.membership.identity.find(ctx.sender));
    requirePersistentInventoryAvailable(ctx, ctx.sender);
    const nodes=[...contentRegistry(ctx).skillTrees.values()].filter(tree=>tree.retired!==true).flatMap(tree=>tree.nodes);
    if (!nodes.some(node=>node.id===nodeId && node.gearBoostable===true)) throw new SenderError('equipment_skill_not_eligible');
    const previous=ctx.db.player_equipment_preferences.identity.find(ctx.sender);
    const allowed=new Set(nodes.filter(node=>node.gearBoostable===true).map(node=>node.id));
    const skillPriority=[nodeId,...(previous?.skillPriority??[]).filter(id=>id!==nodeId && allowed.has(id))].slice(0,16);
    const next={identity:ctx.sender,skillPriority};
    const tick=ctx.db.world_clock.id.find(0)?.authorityTick??0n;
    advancePlayerStats(ctx,ctx.sender,tick);
    if (previous===null) ctx.db.player_equipment_preferences.insert(next);
    else ctx.db.player_equipment_preferences.identity.update(next);
    advancePlayerStats(ctx,ctx.sender,tick);
  },
);

