function applyMountLifecycle(
  ctx: WorldReducerContext,
  npcId: bigint,
  action: 'mount' | 'dismount',
  mutate = true,
): void {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  const npc = ctx.db.world_npc.id.find(npcId);
  const registry = contentRegistry(ctx);
  const mount = runtimeNpcMount(registry, npc);
  if (position === null || clock === null) throw new SenderError('player_not_ready');
  requireCombatActionReady(ctx, ctx.sender, clock.authorityTick);
  if (npc === null || mount === null || npc.spaceId !== position.spaceId) {
    throw new SenderError('mount_not_ready');
  }
  const currentMount = mountedNpcFor(ctx, ctx.sender);
  let landing: { readonly x: number; readonly y: number } | null = npc;
  if (action === 'mount') {
    if (currentMount !== null) throw new SenderError('mounted_action_forbidden');
    if (npc.health === 0) throw new SenderError('mount_not_ready');
    if (npc.rider !== undefined) throw new SenderError('mount_already_ridden');
    const ranks = playerSkillRanks(ctx, ctx.sender);
    if (mount.requiredSkill !== undefined
      && runtimeSkillNodeRank(registry, ranks, mount.requiredSkill) < 1) {
      throw new SenderError(`${mount.requiredSkill}_required`);
    }
    if (!isMountWithinReach(position, npc, mount)) throw new SenderError('mount_out_of_range');
  } else {
    if (currentMount?.id !== npc.id || npc.rider?.isEqual(ctx.sender) !== true) {
      throw new SenderError('mount_not_owned');
    }
    const ground = collisionForSpace(ctx, position.spaceId);
    const collision = runtimeActorCollision(registry, ground, { kind: 'player',
      effects: [...ctx.db.player_effect.by_identity.filter(position.identity)] }, clock.authorityTick,
      traversalSolidGeometry(ground, waterCollisionForSpace(ctx, position.spaceId)));
    landing = mount.adapter === 'boat'
      ? findBoatDismountPosition(npc, boatFacingForDirection(parseDirection(npc.facing) ?? 'right'), collision)
      : findHorseDismountPosition(npc, parseNpcFacing(npc.facing), collision, mount);
    if (landing === null) throw new SenderError('no_safe_dismount_position');
  }
  if (mount.adapter === 'horse' && !horseAllowedInSpace(ctx, position.spaceId)) {
    throw new SenderError('horses_outdoors_only');
  }
  if (!mutate) return;
  const plan = vehicleCustodyPlan(npc, position, {
    actor: ctx.sender, action, adapter: mount.adapter, tick: clock.authorityTick, landing,
  });
  ctx.db.player_jump_state.identity.delete(ctx.sender);
  updateWorldNpc(ctx, plan.npc);
  ctx.db.player_position.identity.update(plan.player);
  if (mount.adapter === 'horse') {
    recordPlayerStatistic(ctx, ctx.sender,
      action === 'mount' ? 'horse_mounts' : 'horse_dismounts', 1n, clock.authorityTick);
  }
}

/** Compatibility transport for already-open clients. Capability dispatch stays
 * lifecycle-owned; retire alongside regenerated client reducer bindings. */
export const interactHorse = spacetimedb.reducer(
  { horseId: t.u64() },
  (ctx, { horseId }) => {
    interactEntityBehaviour(ctx, { targetKind: 'npc', entityId: horseId, verb: 'use' }, behaviourActionAuthority);
  },
);

export const jumpHorse = spacetimedb.reducer((ctx) => {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || clock === null) throw new SenderError('player_not_ready');
  requireCombatActionReady(ctx, ctx.sender, clock.authorityTick);
  const horse = mountedNpcFor(ctx, ctx.sender);
  const horseMount = runtimeNpcMount(contentRegistry(ctx), horse);
  const activeJump = ctx.db.player_jump_state.identity.find(ctx.sender);
  if (activeJump !== null && activeJump.untilTick >= clock.authorityTick) {
    throw new SenderError('jump_cooldown');
  }
  const collision = collisionForSpace(ctx, position.spaceId);
  const ranks = playerSkillRanks(ctx, ctx.sender);
  const mountedHorse = horse !== null && horseMount?.adapter === 'horse'
    ? { npc: horse, mount: horseMount }
    : null;
  if (horse !== null && mountedHorse === null) throw new SenderError('jump_requires_foot_or_horse');
  if (mountedHorse !== null && !horseAllowedInSpace(ctx, position.spaceId)) {
    throw new SenderError('horses_outdoors_only');
  }
  const jumpSkill = horseMount?.adapter === 'horse' ? horseMount.jumpSkill : undefined;
  const registry = contentRegistry(ctx);
  if (mountedHorse !== null && jumpSkill !== undefined
    && runtimeSkillNodeRank(registry, ranks, jumpSkill) < 1) {
    throw new SenderError(`${jumpSkill}_required`);
  }
  const skillCapabilities = runtimeSkillCapabilities(registry, ranks);
  const facing = mountedHorse === null
    ? parseDirection(position.facing) ?? 'down'
    : parseNpcFacing(mountedHorse.npc.facing);
  const landing = mountedHorse === null
    ? findPlayerJumpLanding(
        { x: position.x, y: position.y }, facing, collision,
        skillCapabilities.maximumFootGapTiles,
        skillCapabilities.maximumFootCliffLevels,
      )
    : findHorseJumpLanding(
        { x: position.x, y: position.y }, parseNpcFacing(mountedHorse.npc.facing), collision,
        mountedHorse.mount,
      );
  if (mountedHorse === null && skillCapabilities.maximumFootGapTiles < 1
    && skillCapabilities.maximumFootCliffLevels < 1) {
    throw new SenderError('surefooted_required');
  }
  if (landing === null) throw new SenderError('jump_no_safe_landing');
  const jumpUntilTick = clock.authorityTick + BigInt(
    mountedHorse === null ? PLAYER_JUMP_DURATION_TICKS : mountedHorse.mount.jump.durationTicks,
  );
  const jumpState = {
    identity: ctx.sender,
    fromX: position.x,
    fromY: position.y,
    untilTick: jumpUntilTick,
    spaceId: position.spaceId,
    chunkX: chunkAt(landing.x),
    chunkY: chunkAt(landing.y),
  };
  if (activeJump === null) ctx.db.player_jump_state.insert(jumpState);
  else ctx.db.player_jump_state.identity.update(jumpState);
  ctx.db.player_position.identity.update({
    ...position,
    x: landing.x,
    y: landing.y,
    chunkX: chunkAt(landing.x),
    chunkY: chunkAt(landing.y),
    facing,
    moving: false,
    authorityTick: clock.authorityTick,
    actionKind: mountedHorse === null ? 'jump' : 'horse_jump',
    actionStartedTick: clock.authorityTick,
  });
  if (mountedHorse !== null) updateWorldNpc(ctx, {
    ...mountedHorse.npc,
    x: landing.x,
    y: landing.y,
    chunkX: chunkAt(landing.x),
    chunkY: chunkAt(landing.y),
    facing,
    moving: true,
    wanderDirection: 'idle',
    authorityTick: clock.authorityTick,
  });
  const input = ctx.db.player_input.identity.find(ctx.sender);
  if (input !== null) ctx.db.player_input.identity.update({
    ...input,
    direction: 'idle',
    sprinting: false,
    appliedSteps: 0n,
    settleDirection: 'idle',
    settleSteps: 0,
    settledSequence: input.sequence,
    pendingSequence: 0n,
  });
  const jumpDistance = BigInt(Math.abs(landing.x - position.x) + Math.abs(landing.y - position.y));
  recordPlayerStatistic(ctx, ctx.sender, mountedHorse === null ? 'player_jumps' : 'horse_jumps', 1n, clock.authorityTick);
  recordPlayerStatistic(
    ctx, ctx.sender, 'distance_travelled', jumpDistance, clock.authorityTick,
    mountedHorse === null ? 'jump' : 'horse',
  );
  if (mountedHorse !== null) {
    recordPlayerStatistic(ctx, ctx.sender, 'longest_horse_jump', jumpDistance, clock.authorityTick);
  }
});

export const dropSelected = spacetimedb.reducer((ctx) => {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  requirePersistentInventoryAvailable(ctx, ctx.sender);
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const survival = ctx.db.player_survival.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
  if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
  if (mountedNpcFor(ctx, ctx.sender) !== null) {
    throw new SenderError('mounted_action_forbidden');
  }
  const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
  if (slot === null || slot.itemKind === 'empty' || slot.quantity === 0) throw new SenderError('selected_slot_empty');
  if (!runtimeItemIsDroppable(contentRegistry(ctx), slot.itemKind)
    || runtimeItemHasTag(contentRegistry(ctx), slot.itemKind, UNIQUE_QUEST_ITEM_TAG)) {
    throw new SenderError('item_not_droppable');
  }
  const facing = parseDirection(position.facing) ?? 'down';
  const drop = itemDropPosition(position.x, position.y, facing);
  advancePlayerStats(ctx, ctx.sender, clock.authorityTick);
  ctx.db.inventory_slot.id.update({ ...slot, itemKind: 'empty', quantity: 0, durability: 0, lit: true });
  ctx.db.player_position.identity.update({
    ...position,
    actionKind: 'drop',
    actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
  });
  updateEquippedForIdentity(ctx, ctx.sender);
  advancePlayerStats(ctx, ctx.sender, clock.authorityTick);
  dropWorldItemStack(ctx, {
    itemKind: slot.itemKind,
    quantity: slot.quantity,
    x: drop.x,
    y: drop.y,
    droppedAtTick: clock.authorityTick,
    durability: slot.durability,
    lit: slot.lit,
    spaceId: position.spaceId,
  });
  recordPlayerStatistic(
    ctx, ctx.sender, 'items_dropped', BigInt(slot.quantity), clock.authorityTick, slot.itemKind,
  );
});

export const pickupWorldItem = spacetimedb.reducer(
  { itemId: t.u64() },
  (ctx, { itemId }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const item = ctx.db.world_item.id.find(itemId);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || item === null || clock === null) throw new SenderError('item_not_ready');
    if (worldItemExpiredForRow(contentRegistry(ctx), item, clock.authorityTick)) {
      throw new SenderError('item_not_ready');
    }
    if (item.reservedFor !== undefined && item.reservedUntilTick > clock.authorityTick
      && !item.reservedFor.isEqual(ctx.sender)) throw new SenderError('item_reserved');
    if (item.spaceId !== position.spaceId) throw new SenderError('item_not_ready');
    if (!itemWithinPickupReach(position.x, position.y, item.x, item.y)) throw new SenderError('item_out_of_range');
    const maximum = runtimeMaxStack(contentRegistry(ctx), item.itemKind);
    if (maximum === null) throw new SenderError('unknown_item_kind');
    const slots = [...ctx.db.inventory_slot.by_identity.filter(ctx.sender)].sort((left, right) => left.slot - right.slot);
    const carriedCapacity = equippedInventoryCapacity(ctx, slots);
    const capacity = BACKPACK_SLOT_OFFSET + accessibleInventoryContainerCapacity(
      'backpack', carriedCapacity, playerDebugBackpackSlots(ctx, ctx.sender),
    );
    const carried: ContainerSnapshot = {
      id: 'carried',
      capacity,
      slots: Array.from({ length: capacity }, (_, index) => {
        const row = slots.find((slot) => slot.slot === index);
        return row === undefined || row.itemKind === 'empty' || row.quantity === 0
          ? null
          : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
      }),
    };
    const candidates: WorldItemRow[] = maximum === 1
      ? [item]
      : worldItemsInChunkNeighborhood(ctx, position.spaceId, position.x, position.y)
        .filter((candidate) => candidate.spaceId === position.spaceId
          && candidate.itemKind === item.itemKind
          && candidate.durability === item.durability
          && candidate.lit === item.lit
          && (candidate.reservedFor === undefined
            || candidate.reservedUntilTick <= clock.authorityTick
            || candidate.reservedFor.isEqual(ctx.sender))
          && !worldItemExpiredForRow(contentRegistry(ctx), candidate, clock.authorityTick)
          && itemWithinPickupReach(position.x, position.y, candidate.x, candidate.y))
        .sort((left, right) => {
          if (left.id === item.id) return -1;
          if (right.id === item.id) return 1;
          const leftDistance = (left.x - position.x) ** 2 + (left.y - position.y) ** 2;
          const rightDistance = (right.x - position.x) ** 2 + (right.y - position.y) ** 2;
          if (leftDistance !== rightDistance) return leftDistance - rightDistance;
          return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
        });
    let nextCarried = carried;
    let totalInserted = 0;
    const consumed: { readonly row: WorldItemRow; readonly quantity: number }[] = [];
    for (const candidate of candidates) {
      const inserted = insertItemStackPartial(nextCarried, {
        itemKind: candidate.itemKind,
        quantity: candidate.quantity,
        ...(runtimeDurabilityDefinition(contentRegistry(ctx), candidate.itemKind) === null
          ? {} : { durability: candidate.durability }),
        lit: candidate.lit,
      }, activeItemContainerContent(ctx));
      if (!inserted.ok) {
        if (inserted.code === 'container_full') break;
        throw new SenderError(inserted.code);
      }
      nextCarried = inserted.container;
      totalInserted += inserted.insertedQuantity;
      consumed.push({ row: candidate, quantity: inserted.insertedQuantity });
      if (inserted.remainderQuantity > 0) break;
    }
    if (totalInserted === 0) throw new SenderError('inventory_full');
    let destinationSlot: number | null = null;
    for (let slot = 0; slot < nextCarried.capacity; slot += 1) {
      const before = carried.slots[slot];
      const after = nextCarried.slots[slot];
      if (sameStoredStack(before, after)) continue;
      const row = slots.find((candidate) => candidate.slot === slot);
      if (row === undefined) throw new SenderError('inventory_slot_missing');
      ctx.db.inventory_slot.id.update({
        ...row,
        itemKind: after?.itemKind ?? 'empty',
        quantity: after?.quantity ?? 0,
        durability: storedDurability(ctx, after?.itemKind ?? 'empty', after?.durability),
        lit: storedLit(after?.itemKind ?? 'empty', after?.lit),
      });
      if (destinationSlot === null) destinationSlot = slot;
    }
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    ctx.db.player_position.identity.update({
      ...position,
      equippedKind: survival?.selectedSlot === destinationSlot ? item.itemKind : position.equippedKind,
      equippedLit: survival?.selectedSlot === destinationSlot ? storedLit(item.itemKind, item.lit) : position.equippedLit,
      actionKind: 'pickup',
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    recordPlayerStatistic(
      ctx, ctx.sender, 'items_picked_up', BigInt(totalInserted), clock.authorityTick, item.itemKind,
    );
    recordPlayerStatistic(
      ctx, ctx.sender, 'items_obtained', BigInt(totalInserted), clock.authorityTick, item.itemKind,
    );
    for (const entry of consumed) {
      const remainder = entry.row.quantity - entry.quantity;
      if (remainder === 0) ctx.db.world_item.id.delete(entry.row.id);
      else ctx.db.world_item.id.update({ ...entry.row, quantity: remainder });
    }
  },
);

/** Recovers an arrow while it is visibly embedded in a combat target. The
 * projectile id is only a lookup hint: state, kind, lifetime, space, reach,
 * and destination capacity are all revalidated by the authority. */
export const pickupEmbeddedArrow = spacetimedb.reducer(
  { projectileId: t.u64() },
  (ctx, { projectileId }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const projectile = ctx.db.world_projectile.id.find(projectileId);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || projectile === null || clock === null
      || projectile.state !== 'hit' || projectile.hitKind !== 'combat_target'
      || projectile.expiresTick <= clock.authorityTick
      || projectile.spaceId !== position.spaceId) throw new SenderError('arrow_not_recoverable');
    if (!itemWithinPickupReach(position.x, position.y, projectile.x, projectile.y)) {
      throw new SenderError('item_out_of_range');
    }
    if (projectile.projectileKind !== 'arrow') throw new SenderError('arrow_not_recoverable');
    if (!insertPlayerCarriedItem(ctx, projectile.ammunitionItemKind, 1)) {
      throw new SenderError('inventory_full');
    }
    ctx.db.world_projectile.id.delete(projectile.id);
    ctx.db.projectile_charge.projectileId.delete(projectile.id);
    ctx.db.player_position.identity.update({
      ...position,
      actionKind: 'pickup',
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    recordPlayerStatistic(
      ctx, ctx.sender, 'items_picked_up', 1n, clock.authorityTick, projectile.ammunitionItemKind,
    );
    recordPlayerStatistic(
      ctx, ctx.sender, 'items_obtained', 1n, clock.authorityTick, projectile.ammunitionItemKind,
    );
  },
);


/** Common gather authentication/space/hands/mount checks run before this path. */
function pickOrchardFruit(
  ctx: WorldReducerContext, position: PlayerPositionRow, resource: WorldResourceRow, authorityTick: bigint,
): void {
  requirePersistentInventoryAvailable(ctx, ctx.sender);
  if (advancePlayerStats(ctx, ctx.sender, authorityTick).healthCenti <= 0) {
    throw new SenderError('player_not_alive');
  }
  const registry = contentRegistry(ctx);
  requireHearthResourceHarvestAccess(ctx, position, resource);
  const result = orchardHarvestResult(registry, resource, position.x, position.y, authorityTick);
  if (result !== 'ok') throw new SenderError(result);
  const harvest = runtimeResourceDefinition(registry, resource)!.fruitHarvest!;
  const drops = [{ itemKind: harvest.item.slice('item:'.length), quantity: harvest.quantity }];
  const seed = fruitSeedDrop(registry, resource, drops,
    farmingSkillEffects(registry, playerSkillRanks(ctx, ctx.sender)).orchardSeedSaver,
    [ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED, resource.id, resource.activationOrdinal]);
  if (seed !== null) drops.push(seed);
  ctx.db.world_resource.id.update({ ...resource,
    fruitReadyAtTick: authorityTick + BigInt(harvest.cooldownTicks),
    activationOrdinal: (resource.activationOrdinal + 1) >>> 0,
  });
  applyLootDropsBehaviour(ctx, drops, {
    x: position.x, y: position.y, spaceId: resource.spaceId, authorityTick,
    recipient: ctx.sender, inventoryFirst: true,
    reservedUntilTick: authorityTick + MINING_DROP_RESERVATION_TICKS,
    recordItemsObtained: true,
  }, lootAuthorityDependencies);
  ctx.db.player_position.identity.update({ ...position, actionKind: 'pickup',
    actionStartedTick: nextActionStartedTick(position.actionStartedTick, authorityTick) });
  recordPlayerStatistic(ctx, ctx.sender, 'resources_gathered', 1n, authorityTick, resource.kind);
  grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'orchard_harvest', harvest.quantity));
}

export const gatherWorldResource = spacetimedb.reducer(
  { resourceId: t.u64() },
  (ctx, { resourceId }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const resource = ctx.db.world_resource.id.find(resourceId);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || resource === null || clock === null) throw new SenderError('target_not_ready');
    if (resource.spaceId !== position.spaceId) throw new SenderError('target_not_ready');
    if (liveMapGeneratedResourceSuppressed(ctx, resource.spaceId, resource.id)) {
      throw new SenderError('target_not_ready');
    }
    requireWorldModificationAuthorized(ctx, position);
    if (handsOccupiedFor(ctx, ctx.sender)) {
      throw new SenderError('hands_occupied');
    }
    if (mountedNpcFor(ctx, ctx.sender) !== null) {
      throw new SenderError('mounted_action_forbidden');
    }
    const registry = contentRegistry(ctx);
    if (runtimeResourceDefinition(registry, resource)?.fruitHarvest !== undefined) {
      pickOrchardFruit(ctx, position, resource, clock.authorityTick);
      return;
    }
    const result = resourceGatherResult(position.x, position.y, resource, registry);
    if (result !== 'ok') throw new SenderError(result);
    const definition = runtimeResourceDefinition(registry, resource);
    if (definition?.interaction.mode !== 'gather') throw new SenderError('not_gatherable');
    const target: BehaviourObjectSnapshot = {
      entityType: 'object',
      id: resource.id.toString(),
      definitionId: definition.id,
      tags: definition.tags,
      tile: {
        spaceId: resource.spaceId.toString(),
        x: resource.tileX,
        y: resource.tileY,
        tags: [],
      },
      state: { depleted: resource.depleted, health: resource.health },
    };
    const [drop] = registeredLifecycleLoot(ctx, {
      type: 'use',
      actor: { entityType: 'player', id: ctx.sender.toHexString() },
      target: { entityType: 'object', id: target.id, definitionId: target.definitionId },
    }, target, [
      ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED,
      resource.id,
      resource.activationOrdinal,
    ], { values: { remainingHealth: 0, treeGrowthStage: 3 } }).drops;
    if (drop === undefined) throw new SenderError('not_gatherable');
    const seed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
    const statsRow = advancePlayerStats(ctx, ctx.sender, clock.authorityTick);
    const modifiers = activePlayerModifiers(ctx, ctx.sender, clock.authorityTick);
    const resolved = resolvedStatsForRow(ctx, statsRow, ctx.sender, clock.authorityTick);
    const forageBonus = forageFindBonusWithProfile(
      activeCharacterCombatBalance(ctx),
      [seed, ctx.sender.toHexString(), clock.authorityTick, resource.id],
      resolved.attributes.wis,
      modifiers,
    );
    const found = { ...drop, quantity: drop.quantity + forageBonus };

    const slots = [...ctx.db.inventory_slot.by_identity.filter(ctx.sender)].sort((left, right) => left.slot - right.slot);
    const carriedCapacity = equippedInventoryCapacity(ctx, slots);
    const capacity = BACKPACK_SLOT_OFFSET + accessibleInventoryContainerCapacity(
      'backpack', carriedCapacity, playerDebugBackpackSlots(ctx, ctx.sender),
    );
    const carried: ContainerSnapshot = {
      id: 'carried',
      capacity,
      slots: Array.from({ length: capacity }, (_, index) => {
        const row = slots.find((slot) => slot.slot === index);
        return row === undefined || row.itemKind === 'empty' || row.quantity === 0
          ? null
          : storedStack(ctx, row.itemKind, row.quantity, row.durability, row.lit);
      }),
    };
    const inserted = insertItemStackPartial(carried, found, activeItemContainerContent(ctx));
    if (!inserted.ok || inserted.remainderQuantity > 0) {
      throw new SenderError(!inserted.ok && inserted.code !== 'container_full'
        ? inserted.code
        : 'inventory_full');
    }
    let destinationSlot: number | null = null;
    for (let slot = 0; slot < inserted.container.capacity; slot += 1) {
      const before = carried.slots[slot];
      const after = inserted.container.slots[slot];
      if (sameStoredStack(before, after)) continue;
      const row = slots.find((candidate) => candidate.slot === slot);
      if (row === undefined) throw new SenderError('inventory_slot_missing');
      ctx.db.inventory_slot.id.update({
        ...row,
        itemKind: after?.itemKind ?? 'empty',
        quantity: after?.quantity ?? 0,
        durability: storedDurability(ctx, after?.itemKind ?? 'empty', after?.durability),
        lit: storedLit(after?.itemKind ?? 'empty', after?.lit),
      });
      if (destinationSlot === null) destinationSlot = slot;
    }
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const resourceFacing = directionFromAim(
      resource.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      resource.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );
    ctx.db.player_position.identity.update({
      ...position,
      facing: resourceFacing ?? position.facing,
      equippedKind: survival?.selectedSlot === destinationSlot ? found.itemKind : position.equippedKind,
      equippedLit: survival?.selectedSlot === destinationSlot
        ? storedLit(found.itemKind)
        : position.equippedLit,
      actionKind: 'pickup',
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    ctx.db.world_resource.id.update({ ...resource, health: 0, depleted: true });
    recordPlayerStatistic(ctx, ctx.sender, 'resources_gathered', 1n, clock.authorityTick, resource.kind);
    recordPlayerStatistic(ctx, ctx.sender, 'resources_depleted', 1n, clock.authorityTick, resource.kind);
    recordPlayerStatistic(
      ctx, ctx.sender, 'items_obtained', BigInt(found.quantity), clock.authorityTick, found.itemKind,
    );
    if (forageBonus > 0) {
      recordPlayerStatistic(
        ctx, ctx.sender, 'forage_bonus_items', BigInt(forageBonus), clock.authorityTick, found.itemKind,
      );
    }
  },
);

function cellarExcavationId(spaceId: number, tileX: number, tileY: number): string {
  return JSON.stringify([spaceId, tileX, tileY]);
}

function cellarTileIsDug(ctx: WorldReducerContext, spaceId: number, tileX: number, tileY: number): boolean {
  return cellarPlayableTile(tileX, tileY)
    || cellarExcavationAnchorsAffectingTile(
      tileX,
      tileY,
      CELLAR_SIZE_TILES,
      CELLAR_SIZE_TILES,
    ).some((anchor) => (
      ctx.db.cellar_excavation.id.find(cellarExcavationId(spaceId, anchor.tileX, anchor.tileY)) !== null
    ));
}

/** Pickaxe strikes turn solid cellar tiles into persistent walkable terrain.
 * Damage is shared; an ore node is materialised only after its tile opens. */
function applyDigCellarTileLifecycle(
  ctx: WorldReducerContext,
  tileX: number,
  tileY: number,
  mutate = true,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
    const definition = activeSpaceDefinition(ctx, position.spaceId, instanceForSpace(ctx, position.spaceId));
    if (definition?.generator !== 'cellar') throw new SenderError('cellar_only');
    requireWorldModificationAuthorized(ctx, position);
    if (tileX <= 0 || tileY <= 0 || tileX >= CELLAR_SIZE_TILES - 1 || tileY >= CELLAR_SIZE_TILES - 1) {
      throw new SenderError('cellar_boundary_reached');
    }
    if (!tileTargetWithinFixedReach(position.x, position.y, { tileX, tileY }, 2 * TILE_SIZE_FIXED)) {
      throw new SenderError('target_out_of_range');
    }
    if (cellarTileIsDug(ctx, position.spaceId, tileX, tileY)) throw new SenderError('cellar_tile_already_dug');
    const neighbours = [[0, -1], [1, 0], [0, 1], [-1, 0]] as const;
    if (!neighbours.some(([offsetX, offsetY]) => (
      cellarTileIsDug(ctx, position.spaceId, tileX + offsetX, tileY + offsetY)
    ))) throw new SenderError('cellar_wall_not_exposed');

    const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    requireUsableTool(ctx, slot);
    const registry = contentRegistry(ctx);
    if (runtimeToolSpecialization(registry, slot.itemKind) !== 'mining') {
      throw new SenderError('wrong_tool');
    }
    const seed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
    // Every strike on a macro-cell shares one progress row and persists one
    // aligned anchor, so the cave stays a union of aligned 2x2 cells.
    const anchor = cellarExcavationAnchor(tileX, tileY);
    const id = cellarExcavationId(position.spaceId, anchor.tileX, anchor.tileY);
    const progress = ctx.db.cellar_dig_progress.id.find(id);
    const skillCapabilities = runtimeSkillCapabilities(registry, playerSkillRanks(ctx, ctx.sender));
    const { hits, work, opensWall } = cellarWallStrikeProgress(
      cellarWallHitsRequired(seed, position.spaceId, anchor.tileX, anchor.tileY),
      progress, skillCapabilities.efficientStrikesRank,
    );
    const wallOutputKind = opensWall
      ? runtimeItemKindForUniqueTag(registry, CELLAR_WALL_OUTPUT_ITEM_TAG)
      : null;
    if (opensWall && wallOutputKind === null) throw new SenderError('ambient_output_content_missing');
    const bonusDrops = opensWall ? resolveMiningRockBonus(registry.loots,
      [seed, position.spaceId, anchor.tileX, anchor.tileY, 'mining.cellar_wall'],
      skillCapabilities.rockhoundRank) : [];
    if (!mutate) {
      validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
      return;
    }
    spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
    wearInventoryTool(ctx, slot, CELLAR_WALL_TOOL_WEAR);
    const wallFacing = directionFromAim(
      tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );
    ctx.db.player_position.identity.update({
      ...position,
      facing: wallFacing ?? position.facing,
      actionKind: runtimeItemAvatarAction(registry, slot.itemKind) ?? 'tool',
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, slot.itemKind);

    if (!opensWall) {
      const row = {
        id, spaceId: position.spaceId, tileX: anchor.tileX, tileY: anchor.tileY, hits, work, lastHitTick: clock.authorityTick,
      };
      if (progress === null) ctx.db.cellar_dig_progress.insert(row);
      else ctx.db.cellar_dig_progress.id.update(row);
      return;
    }

    if (progress !== null) ctx.db.cellar_dig_progress.id.delete(id);
    ctx.db.cellar_excavation.insert({
      id,
      spaceId: position.spaceId,
      tileX: anchor.tileX,
      tileY: anchor.tileY,
      chunkX: Math.floor(anchor.tileX / SURVIVAL_CHUNK_TILES),
      chunkY: Math.floor(anchor.tileY / SURVIVAL_CHUNK_TILES),
      dugAtTick: clock.authorityTick,
    });
    const oreKind = cellarOreKindAt(seed, position.spaceId, tileX, tileY);
    if (oreKind !== null) {
      const resourceDefinition = runtimeResourceDefinition(contentRegistry(ctx), oreKind);
      if (resourceDefinition === null) throw new SenderError('resource_definition_missing');
      const resourceId = cellarOreResourceId(position.spaceId, tileX, tileY);
      const maximumRichness = 1 + statelessRoll(
        [seed, position.spaceId, tileX, tileY, 'mining.cellar_richness'], MINING_MAX_RICHNESS,
      );
      if (ctx.db.world_resource.id.find(resourceId) === null) ctx.db.world_resource.insert({
        id: resourceId,
        kind: oreKind,
        tileX,
        tileY,
        chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
        chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
        health: maximumRichness,
        depleted: false,
        growthStage: TREE_GROWTH_STAGE_BIG,
        regrowthProgress: TREE_REGROWTH_PROGRESS_MAX,
        spaceId: position.spaceId,
        miningClass: 'pure',
        richness: maximumRichness,
        maximumRichness,
        yieldProgress: 0,
        yieldsProduced: 0,
        producedOre: false,
        spawnSiteId: 0n,
        activationOrdinal: 0,
        respawnAtTick: 0n,
        miningClaimedBy: undefined,
        miningPartyId: undefined,
        miningClaimUntilTick: 0n,
        definitionId: resourceDefinition.id,
        fruitReadyAtTick: 0n,
      });
    }
    dropWorldItemStack(ctx, {
      itemKind: wallOutputKind!,
      quantity: cellarWallStoneQuantity(seed, position.spaceId, tileX, tileY),
      x: tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
      y: tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
      droppedAtTick: clock.authorityTick,
      durability: 0,
      spaceId: position.spaceId,
    });
    applyLootDropsBehaviour(ctx, bonusDrops, {
      x: tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
      y: tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
      spaceId: position.spaceId, authorityTick: clock.authorityTick,
      recipient: ctx.sender, reservedUntilTick: clock.authorityTick + MINING_DROP_RESERVATION_TICKS,
      recordItemsObtained: true,
    }, lootAuthorityDependencies);
    recordPlayerStatistic(ctx, ctx.sender, 'rocks_broken', 1n, clock.authorityTick);
}

function npcTraversalActor(ctx: WorldReducerContext, npc: WorldNpcRow): RuntimeTraversalActor {
  const registry = contentRegistry(ctx);
  const wildlife = ctx.db.world_wildlife_profile.npcId.find(npc.id);
  if (wildlife !== null) return { kind: 'definition', definitionId: runtimeCreatureDefinition(registry, wildlife.species)?.id ?? '' };
  const outdoor = ctx.db.outdoor_enemy_profile.npcId.find(npc.id);
  if (outdoor !== null) return { kind: 'definition', definitionId: runtimeHearthEnemyDefinition(registry, outdoor.enemyKind)?.definitionId ?? '' };
  const authored = runtimeNpcDefinition(registry, npc);
  if (authored !== null) return { kind: 'definition', definitionId: authored.id };
  const enemies = [...registry.enemies.values()].filter(row => row.retired !== true
    && (row.npcKind === npc.kind || row.aliases?.includes(npc.kind)));
  const signatures = new Set(enemies.map(row => JSON.stringify([...(row.traversalAbilities ?? [])].sort())));
  return { kind: 'definition', definitionId: signatures.size === 1 ? enemies[0]?.id ?? '' : '' };
}

function collisionForWildlife(
  ctx: WorldReducerContext,
  npc: Pick<WorldNpcRow, 'spaceId'>,
  species: string,
) {
  const medium = runtimeWildlifeMovementMedium(contentRegistry(ctx), species);
  if (medium === null) return null;
  const ground = collisionForSpace(ctx, npc.spaceId);
  const water = waterCollisionForSpace(ctx, npc.spaceId);
  const legacy = medium === 'ground' ? ground : medium === 'water' ? water
    : createAuthoritySpaceCollisionMap(contentRegistry(ctx), npc.spaceId, [], [], medium, [], homesteadForSpace(ctx, npc.spaceId));
  return runtimeActorCollision(contentRegistry(ctx), legacy,
    { kind: 'definition', definitionId: runtimeCreatureDefinition(contentRegistry(ctx), species)?.id ?? '' },
    ctx.db.world_clock.id.find(0)?.authorityTick ?? 0n, traversalSolidGeometry(ground, water));
}

function panicNearbyWildlife(
  ctx: WorldReducerContext,
  attackedNpc: WorldNpcRow,
  attackedSpecies: string,
  attacker: WorldReducerContext['sender'],
  threat: { readonly x: number; readonly y: number },
  authorityTick: bigint,
): void {
  const registry = contentRegistry(ctx);
  const definition = runtimeWildlifeDefinition(registry, attackedSpecies);
  const group = runtimeWildlifePanicGroup(registry, attackedSpecies);
  if (definition === null || group === null) return;
  const panicUntilTick = authorityTick + BigInt(definition.panic.durationTicks);
  const panicRadiusSquared = definition.panic.radiusFixed * definition.panic.radiusFixed;
  for (const nearby of ctx.db.world_npc.by_chunk.filter(attackedNpc.spaceId)) {
    if (nearby.id === attackedNpc.id || nearby.health === 0 || nearby.rider !== undefined) continue;
    const dx = nearby.x - attackedNpc.x;
    const dy = nearby.y - attackedNpc.y;
    if (dx * dx + dy * dy > panicRadiusSquared) continue;
    const profile = ctx.db.world_wildlife_profile.npcId.find(nearby.id);
    if (profile === null || runtimeWildlifePanicGroup(registry, profile.species) !== group) continue;
    updateWorldNpc(ctx, {
      ...nearby,
      moving: true,
      wanderDirection: 'panic',
      nextDecisionTick: panicUntilTick,
      authorityTick,
      panicUntilTick: nearby.panicUntilTick !== undefined && nearby.panicUntilTick > panicUntilTick
        ? nearby.panicUntilTick
        : panicUntilTick,
      panicSource: attacker,
      panicSourceX: threat.x,
      panicSourceY: threat.y,
    });
  }
}

function damageHuntableWildlife(
  ctx: WorldReducerContext,
  npc: WorldNpcRow,
  attacker: WorldReducerContext['sender'],
  damageCenti: number,
  critical: boolean,
  authorityTick: bigint,
): number {
  const profile = ctx.db.world_wildlife_profile.npcId.find(npc.id);
  const registry = contentRegistry(ctx);
  const creatureDefinition = profile === null ? null : runtimeWildlifeDefinition(registry, profile.species);
  const respawnTicks = profile === null ? null : runtimeCreatureRespawnTicks(registry, profile.species);
  const combatExperience = profile === null ? null
    : runtimeCreatureCombatExperience(registry, profile.species);
  if (profile === null || creatureDefinition === null
    || !runtimeCreatureIsHuntable(registry, profile.species)
    || respawnTicks === null || combatExperience === null
    || npc.health === 0) return 0;
  const protectorDefinition = [...contentRegistry(ctx).npcs.values()].find((definition) => (
    definition.home.spaceId === npc.spaceId
      && definition.protectedPack !== undefined
      && BigInt(definition.protectedPack.packId) === profile.packId
  ));
  const protection = protectorDefinition?.protectedPack;
  const protectorId = protectorDefinition === undefined ? null : BigInt(protectorDefinition.runtimeId);
  const protector = protectorId === null ? null : ctx.db.world_npc.id.find(protectorId);
  if (protectorDefinition !== undefined && protection !== undefined && protector !== null) {
    if (![...ctx.db.world_speech.iter()].some((speech) => (
      speech.speakerNpcId === protector.id && speech.expiresTick > authorityTick
    ))) {
      ctx.db.world_speech.insert({
        id: 0n,
        speaker: attacker,
        speakerNpcId: protector.id,
        speakerDisplayName: protector.displayName,
        kind: 'shout',
        body: protection.response,
        x: protector.x,
        y: protector.y,
        createdTick: authorityTick,
        expiresTick: authorityTick + BigInt(protection.durationTicks),
        spaceId: protector.spaceId,
      });
    }
    return 0;
  }
  const damage = Math.max(1, Math.ceil(damageCenti / 100));
  const nextHealth = Math.max(0, npc.health - damage);
  const applied = npc.health - nextHealth;
  const attackerPosition = ctx.db.player_position.identity.find(attacker);
  const threat = attackerPosition !== null && attackerPosition.spaceId === npc.spaceId
    ? { x: attackerPosition.x, y: attackerPosition.y }
    : { x: npc.x - FIXED_UNITS_PER_PIXEL, y: npc.y };
  const collision = collisionForWildlife(ctx, npc, profile.species);
  if (collision === null) return 0;
  const knocked = runtimeKnockbackWildlife(registry, { x: npc.x, y: npc.y }, {
    species: profile.species,
    collision,
    threat,
    seed: ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED,
  });
  if (knocked === null) return 0;
  const panicUntilTick = authorityTick + BigInt(creatureDefinition.panic.durationTicks);
  updateWorldNpc(ctx, {
    ...npc,
    x: knocked.x,
    y: knocked.y,
    chunkX: chunkAt(knocked.x),
    chunkY: chunkAt(knocked.y),
    health: nextHealth,
    moving: nextHealth !== 0,
    wanderDirection: nextHealth === 0 ? 'defeated' : 'panic',
    nextDecisionTick: nextHealth === 0
      ? authorityTick + BigInt(respawnTicks) : panicUntilTick,
    authorityTick,
    lastHitCritical: critical,
    panicUntilTick: nextHealth === 0 ? undefined : panicUntilTick,
    panicSource: nextHealth === 0 ? undefined : attacker,
    panicSourceX: threat.x,
    panicSourceY: threat.y,
  });
  panicNearbyWildlife(ctx, npc, profile.species, attacker, threat, authorityTick);
  recordPlayerStatistic(ctx, attacker, 'damage_dealt', BigInt(applied * 100), authorityTick, profile.species);
  if (nextHealth === 0) {
    const target: BehaviourObjectSnapshot = {
      entityType: 'object',
      id: npc.id.toString(),
      definitionId: creatureDefinition.id,
      tags: ['wildlife'],
      tile: {
        spaceId: npc.spaceId.toString(),
        x: Math.floor(knocked.x / TILE_SIZE_FIXED),
        y: Math.floor(knocked.y / TILE_SIZE_FIXED),
        tags: [],
      },
      state: { health: nextHealth, defeated: true },
    };
    const loot = registeredLifecycleLoot(ctx, {
      type: 'break',
      actor: { entityType: 'player', id: attacker.toHexString() },
      object: { entityType: 'object', id: target.id, definitionId: target.definitionId },
      tool: { kind: 'combat' },
    }, target, [
      ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED,
      npc.id,
      authorityTick,
    ]);
    applyLootDropsBehaviour(ctx, loot.drops, {
      x: knocked.x,
      y: knocked.y,
      spaceId: npc.spaceId,
      authorityTick,
    }, lootAuthorityDependencies);
    grantSkillExperience(ctx, attacker, 'combat', BigInt(combatExperience));
    recordPlayerStatistic(ctx, attacker, 'animals_hunted', 1n, authorityTick, profile.species);
  }
  return applied;
}

const OUTDOOR_NPC_ID_BASE=8_900_000_000_000n;
type OutdoorProfileRow=NonNullable<ReturnType<WorldReducerContext['db']['outdoor_enemy_profile']['npcId']['find']>>;
function clearOutdoorAdds(ctx:WorldReducerContext,encounterId:string):void {
  for(const profile of [...ctx.db.outdoor_enemy_profile.by_encounter.filter(encounterId)])if(profile.role==='add'){
    ctx.db.enemy_attack.npcId.delete(profile.npcId);ctx.db.world_npc.id.delete(profile.npcId);
    ctx.db.outdoor_enemy_profile.npcId.delete(profile.npcId);OUTDOOR_RETURN_PATHS.delete(profile.npcId);
  }
}
function prepareOutdoorAdds(ctx:WorldReducerContext,definition:HearthEncounterDefinition,boss:WorldNpcRow,profile:OutdoorProfileRow,tick:bigint):void {
  const summons=definition.summons,authored=summons===undefined?null:runtimeHearthEnemyDefinition(contentRegistry(ctx),summons.definitionId);
  if(summons===undefined||authored===null){disableOutdoorEncounter(ctx,definition.id,'summon_content_missing',tick);return;}
  const slots=summons.offsets.map((offset,slot)=>({id:boss.id+BigInt(slot+1),
    x:(definition.tileX+offset.tileX+.5)*TILE_SIZE_FIXED,y:(definition.tileY+offset.tileY+.5)*TILE_SIZE_FIXED}));
  if(slots.some(slot=>ctx.db.world_npc.id.find(slot.id)!==null||ctx.db.outdoor_enemy_profile.npcId.find(slot.id)!==null)){
    disableOutdoorEncounter(ctx,definition.id,'summon_slot_conflict',tick);return;
  }
  for(const slot of slots)ctx.db.outdoor_enemy_profile.insert({...profile,npcId:slot.id,enemyKind:authored.runtimeKind,
    maximumHealth:authored.health,damageCenti:authored.damageCenti,attackCycle:0,role:'add',summonState:'pending',
    summonTick:0n,summonLastTick:0n,summonX:slot.x,summonY:slot.y,phaseCueUntilTick:0n,nextAttackTick:0n,
    chunkX:chunkAt(slot.x),chunkY:chunkAt(slot.y)});
}
/** Slot state is authoritative even before an NPC exists. A blocked pad defers
 * that slot; it never relocates the summon underneath a player. */
function stepOutdoorSummons(ctx:WorldReducerContext,definition:HearthEncounterDefinition,tick:bigint,
  players:readonly PlayerPositionRow[],policy:CombatRegionPolicy,collision:CollisionMap):void {
  const camp=ctx.db.outdoor_encounter.id.find(definition.id);
  if(camp?.phase!=='active'||camp.conflict)return;
  const profiles=[...ctx.db.outdoor_enemy_profile.by_encounter.filter(definition.id)];
  const bossProfile=profiles.find(profile=>profile.role!=='add'
    &&runtimeHearthEnemyDefinition(contentRegistry(ctx),profile.enemyKind)?.behavior.engine==='warden');
  if(bossProfile===undefined||definition.summons===undefined||bossProfile.wardenPhase!==definition.summons.phase)return;
  const boss=ctx.db.world_npc.id.find(bossProfile.npcId);if(boss===null||boss.health===0)return;
  for(const profile of profiles.filter(row=>row.role==='add')){
    if(profile.generation!==camp.generation||profile.summonState==='spawned'||profile.summonState==='dead')continue;
    if(profile.summonState==='pending'&&tick%20n!==0n)continue;
    const point={x:profile.summonX,y:profile.summonY};
    let clear=outdoorMovementAllowed(policy,definition,point,point,collision)
      &&players.every(player=>(player.x-point.x)**2+(player.y-point.y)**2>=(2*TILE_SIZE_FIXED)**2);
    for(let dy=-1;clear&&dy<=1;dy++)for(let dx=-1;clear&&dx<=1;dx++){
      clear=![...ctx.db.world_npc.by_chunk.filter([TOPSIDE_SPACE_ID,chunkAt(point.x)+dx,chunkAt(point.y)+dy])]
        .some(npc=>npc.health>0&&(npc.x-point.x)**2+(npc.y-point.y)**2<(2*TILE_SIZE_FIXED)**2);
    }
    if(clear){
      const route=outdoorReturnWaypoint({...boss,id:profile.npcId,...point,homeX:boss.homeX,homeY:boss.homeY},definition,policy,collision);
      OUTDOOR_RETURN_PATHS.delete(profile.npcId);clear=route!==null;
    }
    if(!clear){
      if(profile.summonState==='marking')ctx.db.outdoor_enemy_profile.npcId.update({...profile,summonState:'pending',summonTick:0n,summonLastTick:0n});
      continue;
    }
    if(profile.summonState==='pending'||tick>profile.summonLastTick+1n){
      ctx.db.outdoor_enemy_profile.npcId.update({...profile,summonState:'marking',summonTick:tick,summonLastTick:tick});continue;
    }
    if(tick<profile.summonTick+20n){
      ctx.db.outdoor_enemy_profile.npcId.update({...profile,summonLastTick:tick});continue;
    }
    const ready=tick+20n+(profile.npcId-boss.id-1n)*6n;
    const authored=runtimeHearthEnemyDefinition(contentRegistry(ctx),profile.enemyKind);
    if(authored===null){disableOutdoorEncounter(ctx,definition.id,'summon_content_missing',tick);return;}
    ctx.db.world_npc.insert({...boss,id:profile.npcId,kind:authored.npcKind,displayName:authored.displayName,
      ...point,homeX:point.x,homeY:point.y,chunkX:chunkAt(point.x),chunkY:chunkAt(point.y),health:profile.maximumHealth,
      moving:false,wanderDirection:'summoned',nextDecisionTick:ready,authorityTick:tick,lastHitCritical:false});
    ctx.db.outdoor_enemy_profile.npcId.update({...profile,summonState:'spawned',nextAttackTick:ready,phaseCueUntilTick:ready});
  }
}
function outdoorHostileSegment(policy:CombatRegionPolicy,from:{x:number;y:number},to:{x:number;y:number}):boolean {
  return policy.allowsHostileSegment({spaceId:TOPSIDE_SPACE_ID,tileX:from.x/TILE_SIZE_FIXED,tileY:from.y/TILE_SIZE_FIXED},
    {spaceId:TOPSIDE_SPACE_ID,tileX:to.x/TILE_SIZE_FIXED,tileY:to.y/TILE_SIZE_FIXED});
}
function outdoorInsideCamp(definition:HearthEncounterDefinition,point:{x:number;y:number},extra=0):boolean {
  return Math.abs(point.x/TILE_SIZE_FIXED-(definition.tileX+.5))<=definition.radiusTiles+extra
    &&Math.abs(point.y/TILE_SIZE_FIXED-(definition.tileY+.5))<=definition.radiusTiles+extra;
}
function outdoorMovementAllowed(policy:CombatRegionPolicy,definition:HearthEncounterDefinition,
  from:{x:number;y:number},to:{x:number;y:number},collision:CollisionMap):boolean {
  if(!outdoorInsideCamp(definition,to,2)||positionCollides(to,collision)
    ||combatElevationAt(collision,to.x,to.y)!==definition.elevation||combatSegmentObstructed(from,to,collision))return false;
  // Protect the physical footprint as well as the logical anchor on sanctuary edges.
  return [-.4,0,.4].every(dx=>[-.75,0].every(dy=>outdoorHostileSegment(policy,
    {x:from.x+dx*TILE_SIZE_FIXED,y:from.y+dy*TILE_SIZE_FIXED},
    {x:to.x+dx*TILE_SIZE_FIXED,y:to.y+dy*TILE_SIZE_FIXED})));
}
/** One bounded resource/chest/target gather for all authored camps and recovery.
 * The caller reuses this map throughout its reducer; never cache mutable collision
 * across reducers. A chunk of padding includes neighboring resource footprints. */
function outdoorCollisionMap(ctx:WorldReducerContext, excludedResourceId?: bigint):CollisionMap {
  const chunks=new Map<string,readonly [number,number]>();
  const arrival=HEARTH_ISLANDS.cinderwake.arrival;
  const regions=[...activeHearthEncounterDefinitions(contentRegistry(ctx)).map(camp=>({x:camp.tileX,y:camp.tileY,radius:camp.radiusTiles+4})),
    {x:arrival.tileX,y:arrival.tileY,radius:6}];
  for(const region of regions) {
    const minimumX=Math.floor((region.x-region.radius)/SURVIVAL_CHUNK_TILES)-1;
    const maximumX=Math.floor((region.x+region.radius)/SURVIVAL_CHUNK_TILES)+1;
    const minimumY=Math.floor((region.y-region.radius)/SURVIVAL_CHUNK_TILES)-1;
    const maximumY=Math.floor((region.y+region.radius)/SURVIVAL_CHUNK_TILES)+1;
    for(let y=minimumY;y<=maximumY;y++)for(let x=minimumX;x<=maximumX;x++)chunks.set(`${x},${y}`,[x,y]);
  }
  const resources:WorldResourceRow[]=[],chests:WorldChestRow[]=[],combatTargets:WorldCombatTargetRow[]=[];
  for(const [x,y] of chunks.values()) {
    resources.push(...ctx.db.world_resource.by_chunk.filter([TOPSIDE_SPACE_ID,x,y]));
    chests.push(...ctx.db.world_chest.by_chunk.filter([TOPSIDE_SPACE_ID,x,y]));
    combatTargets.push(...ctx.db.world_combat_target.by_chunk.filter([TOPSIDE_SPACE_ID,x,y]));
  }
  return collisionForSpace(ctx,TOPSIDE_SPACE_ID,undefined,{resources: resources.filter(resource => resource.id !== excludedResourceId),chests,combatTargets,chunkScope:new Set(chunks.keys())},liveIslandCollisionRuntime(ctx));
}
function outdoorRecoveryPosition(ctx:WorldReducerContext,policy:CombatRegionPolicy,prefetchedCollision?:CollisionMap):{x:number;y:number}|null {
  const arrival=HEARTH_ISLANDS.cinderwake.arrival,collision=prefetchedCollision??outdoorCollisionMap(ctx);
  for(let radius=0;radius<=4;radius++)for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++) {
    if(Math.max(Math.abs(dx),Math.abs(dy))!==radius)continue;
    const point={x:(arrival.tileX+dx+.5)*TILE_SIZE_FIXED,y:(arrival.tileY+dy+.5)*TILE_SIZE_FIXED};
    if(policy.regionAt({spaceId:TOPSIDE_SPACE_ID,tileX:point.x/TILE_SIZE_FIXED,tileY:point.y/TILE_SIZE_FIXED})?.policy==='sanctuary'
      &&!positionCollides(point,collision))return point;
  }
  return null;
}
function recoverOutdoorKnockout(ctx:WorldReducerContext,player:PlayerPositionRow,tick:bigint,policy:CombatRegionPolicy,collision:CollisionMap):void {
  const landing=outdoorRecoveryPosition(ctx,policy,collision);
  if(landing===null)return; // Damage preflight refuses impacts while recovery is blocked.
  clearBowCharge(ctx,player.identity);
  teleportPlayer(ctx,player,TOPSIDE_SPACE_ID,landing.x,landing.y);
  const stats=advancePlayerStats(ctx,player.identity,tick),resolved=resolvedStatsForRow(ctx,stats,player.identity,tick);
  ctx.db.player_stats.identity.update({...stats,healthCenti:Math.max(1,Math.ceil(resolved.maxHealthCenti*.35)),
    vigourCenti:Math.max(stats.vigourCenti,Math.ceil(resolved.maxVigourCenti*.25)),healthRemainder:0,vigourRemainder:0,regenTick:tick});
  combatRecovery(ctx,player.identity,tick,tick+60n);
  // Inventory, equipped items, currency and reserved claims are deliberately untouched.
}
function disableOutdoorEncounter(ctx:WorldReducerContext,id:string,reason:string,tick:bigint):void {
  const camp=ctx.db.outdoor_encounter.id.find(id);
  clearOutdoorAdds(ctx,id);
  if(camp!==null&&camp.conflict!==reason) {
    ctx.db.outdoor_encounter.id.update({...camp,conflict:reason});
    console.warn(`Outdoor encounter disabled: ${id}: ${reason}`);
  }
  for(const profile of ctx.db.outdoor_enemy_profile.by_encounter.filter(id)) {
    ctx.db.enemy_attack.npcId.delete(profile.npcId);
    const npc=ctx.db.world_npc.id.find(profile.npcId);
    if(npc!==null&&(npc.moving||npc.wanderDirection!=='idle'))updateWorldNpc(ctx,{...npc,moving:false,wanderDirection:'idle',authorityTick:tick});
  }
}
function spawnOutdoorEncounter(ctx:WorldReducerContext,definition:HearthEncounterDefinition,tick:bigint,
  policy:CombatRegionPolicy,collision:CollisionMap):boolean {
  const old=ctx.db.outdoor_encounter.id.find(definition.id),registry=contentRegistry(ctx);
  if(outdoorRecoveryPosition(ctx,policy,collision)===null)return false;
  if(definition.reward.drops.some(drop=>runtimeItemDefinition(registry,drop.itemKind)===null))return false;
  const members=definition.members.map((member,slot)=>({member,
    authored:runtimeHearthEnemyDefinition(registry,{enemyKind:member.kind,definitionId:member.definitionId}),
    id:OUTDOOR_NPC_ID_BASE+BigInt(definition.runtimeIndex*16+slot),
    x:(member.tileX+.5)*TILE_SIZE_FIXED,y:(member.tileY+.5)*TILE_SIZE_FIXED}));
  if(members.some(({authored})=>authored===null))return false;
  if(members.some(member=>!outdoorMovementAllowed(policy,definition,member,member,collision)))return false;
  // Check every ID before any mutation. A foreign occupant is never overwritten.
  if(members.some(member=>{
    const npc=ctx.db.world_npc.id.find(member.id),profile=ctx.db.outdoor_enemy_profile.npcId.find(member.id);
    return (profile!==null&&profile.encounterId!==definition.id)||(npc!==null&&profile===null);
  }))return false;
  const generation=old===null?1n:old.phase==='completed'?old.generation+1n:old.generation;
  const state=newOutdoorEncounter(definition.id,members.reduce((sum,{authored})=>sum+authored!.health*100,0),
    old===null?definition.reward:parseEncounterRewardProfile(old.rewardJson),old?.worldSeed??ctx.db.world_seed.id.find(0)?.seed??SURVIVAL_WORLD_SEED,generation);
  const row={id:definition.id,generation,phase:definition.activation==='interact'?'dormant':'active',
    maximumHealthCenti:state.maximumHealthCenti,healthCenti:state.healthCenti,worldSeed:state.worldSeed,rewardJson:JSON.stringify(state.reward),
    respawnAfterTick:0n,respawnDelayTicks:definition.respawnDelayTicks,lastNearbyTick:tick,lastTargetTick:tick,returnStartedTick:0n,
    activated:false,conflict:''};
  clearOutdoorAdds(ctx,definition.id);
  if(old===null)ctx.db.outdoor_encounter.insert(row);else ctx.db.outdoor_encounter.id.update(row);
  for(const contribution of [...ctx.db.outdoor_encounter_contribution.by_encounter.filter(definition.id)])ctx.db.outdoor_encounter_contribution.id.delete(contribution.id);
  for(const [slot,{authored,id,x,y}] of members.entries()) {
    ctx.db.enemy_attack.npcId.delete(id);OUTDOOR_RETURN_PATHS.delete(id);
    const npc={id,kind:authored!.npcKind,displayName:authored!.displayName,x,y,homeX:x,homeY:y,
      chunkX:chunkAt(x),chunkY:chunkAt(y),facing:'down',moving:false,rider:undefined,wanderDirection:definition.activation==='interact'?'dormant':'idle',nextDecisionTick:tick+20n,
      authorityTick:tick,health:authored!.health,spaceId:TOPSIDE_SPACE_ID,lastHitCritical:false,panicUntilTick:undefined,
      panicSource:undefined,panicSourceX:0,panicSourceY:0};
    if(ctx.db.world_npc.id.find(id)===null)ctx.db.world_npc.insert(npc);else updateWorldNpc(ctx,npc);
    const profile={npcId:id,encounterId:definition.id,generation,enemyKind:authored!.runtimeKind,maximumHealth:authored!.health,
      damageCenti:authored!.damageCenti,nextAttackTick:tick+20n+BigInt(slot*6),attackCycle:0,wardenPhase:1,phaseCueUntilTick:0n,role:'base',summonState:'',summonTick:0n,summonLastTick:0n,summonX:0,summonY:0,
      spaceId:TOPSIDE_SPACE_ID,chunkX:npc.chunkX,chunkY:npc.chunkY};
    if(ctx.db.outdoor_enemy_profile.npcId.find(id)===null)ctx.db.outdoor_enemy_profile.insert(profile);else ctx.db.outdoor_enemy_profile.npcId.update(profile);
  }
  return true;
}
/** Navigation cache only: restart recomputes the same bounded route from the
 * authoritative position. Every cached next segment is checked against live collision. */
const OUTDOOR_RETURN_PATHS=new Map<bigint,{x:number;y:number}[]>();
function outdoorReturnWaypoint(npc:WorldNpcRow,definition:HearthEncounterDefinition,policy:CombatRegionPolicy,
  collision:CollisionMap):{x:number;y:number}|null {
  const home={x:npc.homeX,y:npc.homeY},unit=TILE_SIZE_FIXED;
  let path=OUTDOOR_RETURN_PATHS.get(npc.id);
  while(path!==undefined&&path.length>0&&(path[0]!.x-npc.x)**2+(path[0]!.y-npc.y)**2<=(unit*.15)**2)path.shift();
  if(path!==undefined&&path.length>0&&outdoorMovementAllowed(policy,definition,npc,path[0]!,collision))return path[0]!;
  OUTDOOR_RETURN_PATHS.delete(npc.id);
  if(outdoorMovementAllowed(policy,definition,npc,home,collision))return home;
  const start={x:Math.floor(npc.x/unit),y:Math.floor(npc.y/unit)},goal={x:Math.floor(home.x/unit),y:Math.floor(home.y/unit)};
  const key=(point:{x:number;y:number})=>`${point.x},${point.y}`;
  const queue=[start],parents=new Map<string,{x:number;y:number}|null>([[key(start),null]]);
  for(let cursor=0;cursor<queue.length&&cursor<1024;cursor++) {
    const cell=queue[cursor]!;
    if(cell.x===goal.x&&cell.y===goal.y) {
      path=[];let current:{x:number;y:number}|null=cell;
      while(current!==null&&key(current)!==key(start)) {
        path.unshift({x:(current.x+.5)*unit,y:(current.y+.5)*unit});current=parents.get(key(current))??null;
      }
      OUTDOOR_RETURN_PATHS.set(npc.id,path);return path[0]??home;
    }
    const from=cursor===0?npc:{x:(cell.x+.5)*unit,y:(cell.y+.5)*unit};
    for(const [dx,dy] of [[0,-1],[-1,0],[1,0],[0,1]] as const) {
      const next={x:cell.x+dx,y:cell.y+dy};if(parents.has(key(next)))continue;
      const point={x:(next.x+.5)*unit,y:(next.y+.5)*unit};
      if(!outdoorMovementAllowed(policy,definition,from,point,collision))continue;
      parents.set(key(next),cell);queue.push(next);
    }
  }
  return null;
}
function moveOutdoorNpc(ctx:WorldReducerContext,npc:WorldNpcRow,target:{x:number;y:number},definition:HearthEncounterDefinition,
  policy:CombatRegionPolicy,collision:CollisionMap,tick:bigint,activity:string,speedPermille=1000):boolean {
  const stepped=stepNpcTowardPoint({id:npc.id,position:npc,home:{x:npc.homeX,y:npc.homeY},facing:parseNpcFacing(npc.facing),
    moving:npc.moving,wanderDirection:null,nextDecisionTick:Number(npc.nextDecisionTick)},target,Number(tick),collision,TILE_SIZE_FIXED*.1);
  const distance=hearthEnemyStepDistance(tick,speedPermille),baseStep=FIXED_UNITS_PER_PIXEL/2;
  const candidate={x:npc.x+Math.round((stepped.position.x-npc.x)*distance/baseStep),
    y:npc.y+Math.round((stepped.position.y-npc.y)*distance/baseStep)};
  if(!outdoorMovementAllowed(policy,definition,npc,candidate,collision))return false;
  updateWorldNpc(ctx,{...npc,x:candidate.x,y:candidate.y,chunkX:chunkAt(candidate.x),chunkY:chunkAt(candidate.y),
    facing:stepped.facing,moving:stepped.moving,wanderDirection:activity,authorityTick:tick});
  return stepped.moving;
}
/** Five indexed camp probes, with no island-wide NPC/resource scan. Existing
 * generations/claims survive restarts; only a completed quiet camp advances. */
function stepOutdoorEncounters(ctx:WorldReducerContext,tick:bigint,onlinePlayers:readonly PlayerPositionRow[]):void {
  const registry=contentRegistry(ctx),definitions=activeHearthEncounterDefinitions(registry);
  const policy=compiledLiveIslandRuntime(ctx)?.combatPolicy;
  let tickCollision:CollisionMap|undefined;
  const getCollision=()=>tickCollision??=outdoorCollisionMap(ctx);
  for(const definition of definitions) {
    let camp=ctx.db.outdoor_encounter.id.find(definition.id);
    const players=onlinePlayers.filter(player=>player.spaceId===TOPSIDE_SPACE_ID);
    const near=players.some(player=>outdoorInsideCamp(definition,player,OUTDOOR_SIGHT_PADDING_TILES));
    if(camp===null) {
      // Prewarm the seven authored bodies before anyone can see an arrival;
      // waiting for proximity would exclude the first visitor at the dock.
      if(policy!==undefined&&!near&&tick%20n===0n)spawnOutdoorEncounter(ctx,definition,tick,policy,getCollision());
      continue;
    }
    if(policy===undefined||!policy.allowsHostileDamage({spaceId:TOPSIDE_SPACE_ID,tileX:definition.tileX+.5,tileY:definition.tileY+.5})) {
      disableOutdoorEncounter(ctx,definition.id,'combat_policy_removed',tick);continue;
    }
    if(near&&camp.lastNearbyTick!==tick) {
      camp={...camp,lastNearbyTick:tick};ctx.db.outdoor_encounter.id.update(camp);
    }
    if(camp.conflict) {
      if(tick%20n!==0n)continue;
      const collision=getCollision();
      if(outdoorRecoveryPosition(ctx,policy,collision)===null||definition.members.some(member=>{
        const home={x:(member.tileX+.5)*TILE_SIZE_FIXED,y:(member.tileY+.5)*TILE_SIZE_FIXED};
        return !outdoorMovementAllowed(policy,definition,home,home,collision);
      }))continue;
      const restoredMembers=[...ctx.db.outdoor_enemy_profile.by_encounter.filter(definition.id)].filter(profile=>profile.role!=='add')
        .map(profile=>({profile,npc:ctx.db.world_npc.id.find(profile.npcId)}));
      if(restoredMembers.length!==definition.members.length||restoredMembers.some(({profile,npc})=>npc===null
        ||profile.generation!==camp!.generation||runtimeHearthEnemyDefinition(registry,profile.enemyKind)===null))continue;
      if(camp.conflict==='return_path_blocked'&&restoredMembers.some(({npc})=>npc!.health>0
        &&outdoorReturnWaypoint(npc!,definition,policy,collision)===null))continue;
      // Resume interrupted fights by returning and resetting, never by granting
      // another generation. Completed packs retain their paid cooldown.
      camp={...camp,conflict:'',phase:camp.phase==='active'?'returning':camp.phase,
        returnStartedTick:tick,lastNearbyTick:tick,activated:false};
      ctx.db.outdoor_encounter.id.update(camp);
    }
    if(camp.phase==='completed') {
      if(!near&&tick>=camp.respawnAfterTick&&tick>=camp.lastNearbyTick+600n&&tick%20n===0n)
        spawnOutdoorEncounter(ctx,definition,tick,policy,getCollision());
      continue;
    }
    if(!camp.activated&&camp.phase!=='returning'&&!players.some(player=>outdoorInsideCamp(definition,player,6)))continue;
    const collision=getCollision();
    const profiles=[...ctx.db.outdoor_enemy_profile.by_encounter.filter(definition.id)];
    const bossId=OUTDOOR_NPC_ID_BASE+BigInt(definition.runtimeIndex*16),summon=definition.summons;
    if(profiles.some(profile=>profile.role==='add'&&(summon===undefined
      ||!summon.offsets.some((_offset,slot)=>profile.npcId===bossId+BigInt(slot+1))||profile.generation!==camp!.generation
      ||profile.enemyKind!==summon.kind||!['pending','marking','spawned','dead'].includes(profile.summonState)))){
      disableOutdoorEncounter(ctx,definition.id,'summon_state_conflict',tick);continue;
    }
    const members=profiles.filter(profile=>profile.role!=='add'||profile.summonState==='spawned'
      ||profile.summonState==='dead'&&ctx.db.world_npc.id.find(profile.npcId)!==null)
      .map(profile=>({profile,npc:ctx.db.world_npc.id.find(profile.npcId)}));
    if(members.filter(({profile})=>profile.role!=='add').length!==definition.members.length||members.some(({profile,npc})=>npc===null||profile.generation!==camp!.generation
      ||npc.spaceId!==TOPSIDE_SPACE_ID||runtimeHearthEnemyDefinition(registry,profile.enemyKind)===null)) {
      disableOutdoorEncounter(ctx,definition.id,'member_state_conflict',tick);continue;
    }
    if(members.some(({npc})=>!outdoorMovementAllowed(policy,definition,{x:npc!.homeX,y:npc!.homeY},{x:npc!.homeX,y:npc!.homeY},collision))) {
      disableOutdoorEncounter(ctx,definition.id,'home_blocked',tick);continue;
    }
    if(outdoorRecoveryPosition(ctx,policy,collision)===null){disableOutdoorEncounter(ctx,definition.id,'recovery_blocked',tick);continue;}
    if(camp.phase==='dormant'){
      for(const {npc} of members)if(npc!.wanderDirection!=='dormant')updateWorldNpc(ctx,{...npc!,moving:false,wanderDirection:'dormant',authorityTick:tick});
      continue;
    }
    const targets=players.filter(player=>outdoorInsideCamp(definition,player,2)
      &&combatElevationAt(collision,player.x,player.y)===definition.elevation
      &&outdoorHostileSegment(policy,player,player));
    const reachable=targets.filter(player=>members.some(({npc})=>npc!.health>0&&!combatSegmentObstructed(npc!,player,collision)));
    const engaged=camp.activated||camp.healthCenti<camp.maximumHealthCenti||(reachable.length>0&&members.some(({npc,profile})=>{
      const authored=runtimeHearthEnemyDefinition(registry,profile.enemyKind);
      return authored!==null&&targets.some(player=>(player.x-npc!.x)**2+(player.y-npc!.y)**2
        <=(authored.aggroTiles*TILE_SIZE_FIXED)**2);
    }));
    if(camp.phase==='active'&&engaged&&reachable.length>0) {
      if(!camp.activated)for(const [slot,{profile}] of members.entries())
        ctx.db.outdoor_enemy_profile.npcId.update({...profile,nextAttackTick:tick+BigInt(slot*6
          +(runtimeHearthEnemyDefinition(registry,profile.enemyKind)?.behavior.engine==='orbit'?20:0))});
      camp={...camp,activated:true,lastTargetTick:tick};ctx.db.outdoor_encounter.id.update(camp);
    }
    if(camp.phase==='active'&&engaged&&tick>=camp.lastTargetTick+80n) {
      camp={...camp,phase:'returning',returnStartedTick:tick,activated:false};ctx.db.outdoor_encounter.id.update(camp);
    }
    if(camp.phase==='returning') {
      clearOutdoorAdds(ctx,definition.id);
      for(const {npc,profile} of members.filter(member=>member.profile.role!=='add')) {
        ctx.db.enemy_attack.npcId.delete(profile.npcId);
        if(npc!.health>0) {
          const actorCollision=runtimeActorCollision(registry,collision,npcTraversalActor(ctx,npc!),tick,
            traversalSolidGeometry(collision,waterCollisionForSpace(ctx,npc!.spaceId)));
          const waypoint=outdoorReturnWaypoint(npc!,definition,policy,actorCollision);
          if(waypoint===null){disableOutdoorEncounter(ctx,definition.id,'return_path_blocked',tick);break;}
          moveOutdoorNpc(ctx,npc!,waypoint,definition,policy,actorCollision,tick,'returning');
        }
      }
      const home=members.filter(member=>member.profile.role!=='add').every(({npc})=>npc!.health===0||(npc!.x-npc!.homeX)**2+(npc!.y-npc!.homeY)**2<=(TILE_SIZE_FIXED*.15)**2);
      if(home&&!near&&tick>=camp.lastNearbyTick+600n)spawnOutdoorEncounter(ctx,definition,tick,policy,collision);
      else if(!home&&tick>camp.returnStartedTick+400n)disableOutdoorEncounter(ctx,definition.id,'return_path_blocked',tick);
      continue;
    }
    if(!engaged)continue;
    stepOutdoorSummons(ctx,definition,tick,players,policy,collision);
    for(const {profile:originalProfile} of members) {
      let profile=ctx.db.outdoor_enemy_profile.npcId.find(originalProfile.npcId);
      const npc=ctx.db.world_npc.id.find(originalProfile.npcId);
      if(profile===null||npc===null||ctx.db.outdoor_encounter.id.find(definition.id)?.phase!=='active')continue;
      if(npc!.health===0||profile.role==='add'&&tick<profile.phaseCueUntilTick)continue;
      const actorCollision=runtimeActorCollision(registry,collision,npcTraversalActor(ctx,npc),tick,
        traversalSolidGeometry(collision,waterCollisionForSpace(ctx,npc.spaceId)));
      const attack=ctx.db.enemy_attack.npcId.find(profile.npcId);
      if(attack!==null) {
        const target=targets.find(player=>player.identity.isEqual(attack.targetIdentity));
        if(target===undefined||!outdoorHostileSegment(policy,npc!,target))ctx.db.enemy_attack.npcId.delete(npc!.id);
        else if(stepCommittedRogueAttack(ctx,npc!,attack,tick,actorCollision,{players,policy,definition}))continue;
      }
      const target=reachable.slice().sort((a,b)=>(a.x-npc!.x)**2+(a.y-npc!.y)**2-((b.x-npc!.x)**2+(b.y-npc!.y)**2))[0];
      if(target===undefined)continue;
      const authored=runtimeHearthEnemyDefinition(registry,profile.enemyKind);
      if(authored===null){disableOutdoorEncounter(ctx,definition.id,'enemy_content_missing',tick);break;}
      if(authored.behavior.engine==='warden') {
        if(tick<profile.phaseCueUntilTick)continue;
        const desired=hearthWardenDesiredPhase(profile.wardenPhase as HearthWardenPhase,npc!.health,profile.maximumHealth);
        if(desired>profile.wardenPhase&&tick>=profile.nextAttackTick) {
          profile={...profile,wardenPhase:desired,attackCycle:0,phaseCueUntilTick:tick+BigInt(WARDEN_PHASE_CUE_TICKS),
            nextAttackTick:tick+BigInt(WARDEN_PHASE_CUE_TICKS)};
          ctx.db.outdoor_enemy_profile.npcId.update(profile);
          updateWorldNpc(ctx,{...npc!,moving:false,wanderDirection:`phase_${desired}`,authorityTick:tick});
          if(desired===3){prepareOutdoorAdds(ctx,definition,npc,profile,tick);stepOutdoorSummons(ctx,definition,tick,players,policy,collision);}
          continue;
        }
      }
      const attackProfile=authored.behavior.engine==='warden'?hearthWardenAttack(profile.wardenPhase as HearthWardenPhase,profile.attackCycle)
        :hearthEnemyAttack(authored,profile.attackCycle),range=attackProfile.maximumRange;
      const distanceSquared=(target.x-npc!.x)**2+(target.y-npc!.y)**2;
      if(npc!.wanderDirection==='recovery'&&tick<profile.nextAttackTick&&authored.behavior.engine!=='orbit')continue;
      if(distanceSquared<=range*range&&distanceSquared>=attackProfile.minimumRange**2&&tick>=profile.nextAttackTick
        &&[...ctx.db.enemy_attack.by_target.filter(target.identity)].length<MAX_COMMITTED_ATTACKERS
        &&outdoorHostileSegment(policy,npc!,target)&&!combatSegmentObstructed(npc!,target,actorCollision)) {
        const baseCommitment=commitEnemyAttack(attackProfile.pattern,tick,tick,npc!,target,range);
        const timing=authored.behavior.engine==='warden'?hearthWardenAttack(profile.wardenPhase as HearthWardenPhase,profile.attackCycle):baseCommitment;
        const commitment={...baseCommitment,tellTicks:timing.tellTicks,activeTicks:timing.activeTicks,recoveryTicks:timing.recoveryTicks};
        if(definition.roles.includes('coordinated_attacks')&&!hearthAttackImpactsSeparated(commitment,
          profiles.filter(other=>other.npcId!==profile!.npcId).flatMap(other=>{
            const row=ctx.db.enemy_attack.npcId.find(other.npcId);return row===null?[]:[attackCommitmentFromRow(row)];
          })))continue;
        ctx.db.enemy_attack.insert({...commitment,npcId:npc!.id,targetIdentity:target.identity,lastProcessedTick:tick,
          elevation:definition.elevation,damageCenti:attackProfile.damageCenti,hitIdentities:[],spaceId:TOPSIDE_SPACE_ID,chunkX:npc!.chunkX,chunkY:npc!.chunkY});
        ctx.db.outdoor_enemy_profile.npcId.update({...profile,attackCycle:(profile.attackCycle+1)%(authored.behavior.engine==='warden'?2:(authored.behavior.alternateAttack?.cycleModulo??3)),
          nextAttackTick:tick+BigInt(commitment.tellTicks+commitment.activeTicks+commitment.recoveryTicks+attackProfile.repositionTicks)});
        updateWorldNpc(ctx,{...npc!,facing:npcFacingTowardPoint(npc!,target,parseNpcFacing(npc!.facing)),moving:false,wanderDirection:'tell',authorityTick:tick});
      }else {
        const movement=hearthEnemyMovement(authored,npc!,target,npc!.id%2n===0n);
        if(movement.moving)moveOutdoorNpc(ctx,npc!,movement.target,definition,policy,actorCollision,tick,movement.activity,authored.speedPermille);
        else if(npc!.moving||npc!.wanderDirection!==movement.activity)updateWorldNpc(ctx,{...npc!,moving:false,
          facing:npcFacingTowardPoint(npc!,target,parseNpcFacing(npc!.facing)),wanderDirection:movement.activity,authorityTick:tick});
      }
    }
  }
}
export const activateOutdoorEncounter=spacetimedb.reducer({encounterId:t.string()},(ctx,{encounterId})=>{
  requireAuthorizedSender(ctx.senderAuth.jwt,ctx.db.membership.identity.find(ctx.sender));
  const definition=runtimeHearthEncounterDefinition(contentRegistry(ctx),encounterId),camp=ctx.db.outdoor_encounter.id.find(encounterId);
  const player=ctx.db.player_position.identity.find(ctx.sender),policy=compiledLiveIslandRuntime(ctx)?.combatPolicy;
  if(definition===null||definition.activation!=='interact'||camp?.phase!=='dormant'||camp.conflict||player===null
    ||player.spaceId!==TOPSIDE_SPACE_ID||policy===undefined)throw new SenderError('encounter_unavailable');
  const point={x:(definition.tileX+.5)*TILE_SIZE_FIXED,y:(definition.tileY+.5)*TILE_SIZE_FIXED};
  const collision=collisionForSpace(ctx,TOPSIDE_SPACE_ID);
  if((point.x-player.x)**2+(point.y-player.y)**2>(3*TILE_SIZE_FIXED)**2||!outdoorHostileSegment(policy,player,point)
    ||combatElevationAt(collision,player.x,player.y)!==definition.elevation||combatSegmentObstructed(player,point,collision))throw new SenderError('encounter_out_of_reach');
  const tick=ctx.db.world_clock.id.find(0)?.authorityTick??0n;
  if(advancePlayerStats(ctx,ctx.sender,tick).healthCenti<=0)throw new SenderError('encounter_unavailable');
  ctx.db.outdoor_encounter.id.update({...camp,phase:'active',activated:true,lastTargetTick:tick});
  for(const [slot,profile] of [...ctx.db.outdoor_enemy_profile.by_encounter.filter(encounterId)].entries()){
    ctx.db.outdoor_enemy_profile.npcId.update({...profile,nextAttackTick:tick+20n+BigInt(slot*6)});
    const npc=ctx.db.world_npc.id.find(profile.npcId);
    if(npc!==null)updateWorldNpc(ctx,{...npc,wanderDirection:'alert',authorityTick:tick});
  }
});

function outdoorProjectileSegmentAllowed(policy:CombatRegionPolicy|undefined,spaceId:number,
  from:{x:number;y:number},to:{x:number;y:number}):boolean {
  if(spaceId!==TOPSIDE_SPACE_ID||policy===undefined)return true;
  const source={spaceId,tileX:from.x/TILE_SIZE_FIXED,tileY:from.y/TILE_SIZE_FIXED};
  const destination={spaceId,tileX:to.x/TILE_SIZE_FIXED,tileY:to.y/TILE_SIZE_FIXED};
  return !(policy.allowsHostileDamage(source)||policy.allowsHostileDamage(destination))
    ||policy.allowsHostileSegment(source,destination);
}

function outdoorEnemyDamageAllowed(ctx:WorldReducerContext,npc:WorldNpcRow,attacker:WorldReducerContext['sender'],
  attackOrigin?:{x:number;y:number}):boolean {
  const profile=ctx.db.outdoor_enemy_profile.npcId.find(npc.id);
  const player=ctx.db.player_position.identity.find(attacker);
  if(profile===null||player===null||npc.health===0||npc.spaceId!==TOPSIDE_SPACE_ID||player.spaceId!==npc.spaceId)return false;
  const camp=ctx.db.outdoor_encounter.id.find(profile.encounterId);
  if(camp===null||camp.phase!=='active'||camp.conflict||camp.generation!==profile.generation)return false;
  const origin=attackOrigin??player;
  const definition=runtimeHearthEncounterDefinition(contentRegistry(ctx),camp.id);
  if(definition===null||runtimeHearthEnemyDefinition(contentRegistry(ctx),profile.enemyKind)===null
    ||!outdoorInsideCamp(definition,npc,2)||!outdoorInsideCamp(definition,origin,2))return false;
  const policy=compiledLiveIslandRuntime(ctx)?.combatPolicy;
  if(policy===undefined)return false;
  const collision=outdoorCollisionMap(ctx);
  if(outdoorRecoveryPosition(ctx,policy,collision)===null||!policy.allowsHostileSegment(
    {spaceId:npc.spaceId,tileX:origin.x/TILE_SIZE_FIXED,tileY:origin.y/TILE_SIZE_FIXED},
    {spaceId:npc.spaceId,tileX:npc.x/TILE_SIZE_FIXED,tileY:npc.y/TILE_SIZE_FIXED}))return false;
  return combatElevationAt(collision,npc.x,npc.y)===definition.elevation
    &&combatElevationAt(collision,origin.x,origin.y)===definition.elevation
    && !combatSegmentObstructed(origin,npc,collision);
}

function damageOutdoorEnemy(ctx:WorldReducerContext,npc:WorldNpcRow,attacker:WorldReducerContext['sender'],
  damageCenti:number,critical:boolean,tick:bigint,attackOrigin?:{x:number;y:number}):number {
  if(!outdoorEnemyDamageAllowed(ctx,npc,attacker,attackOrigin))return 0;
  const profile=ctx.db.outdoor_enemy_profile.npcId.find(npc.id)!;
  const applied=Math.min(npc.health,Math.max(1,Math.ceil(damageCenti/100)));
  if(damageCenti<=0)return 0;
  if(profile.role!=='add'){
    const credited=persistOutdoorEncounterDamage(ctx,profile.encounterId,attacker,applied*100,tick);
    if(credited!==applied*100)throw new SenderError('encounter_health_conflict');
  }
  const health=npc.health-applied;
  updateWorldNpc(ctx,{...npc,health,moving:false,wanderDirection:health===0?'defeated':npc.wanderDirection,
    authorityTick:tick,lastHitCritical:critical});
  if(health===0){
    ctx.db.enemy_attack.npcId.delete(npc.id);
    if(profile.role==='add')ctx.db.outdoor_enemy_profile.npcId.update({...profile,summonState:'dead'});
    else if(ctx.db.outdoor_encounter.id.find(profile.encounterId)?.phase==='completed')clearOutdoorAdds(ctx,profile.encounterId);
  }
  recordPlayerStatistic(ctx,attacker,'damage_dealt',BigInt(applied*100),tick,profile.enemyKind);
  return applied;
}

function persistOutdoorEncounterDamage(ctx:WorldReducerContext,encounterId:string,attacker:WorldReducerContext['sender']|null,
  appliedDamageCenti:number,tick:bigint):number {
  const encounter=ctx.db.outdoor_encounter.id.find(encounterId);
  if(encounter===null||encounter.phase!=='active')return 0;
  const registry=contentRegistry(ctx),definition=runtimeHearthEncounterDefinition(registry,encounterId);
  if(definition===null)return 0;
  const storedReward=parseEncounterRewardProfile(encounter.rewardJson);
  if(storedReward.drops.some(drop=>runtimeItemDefinition(registry,drop.itemKind)===null))return 0;
  if (definition.completionStatistics.some((statistic) => {
    const resolved = runtimeStatisticDefinition(registry, statistic.kind);
    return resolved === null || resolved.reserved === true
      || !statisticSubjectIsValidForDefinition(resolved, statistic.subject ?? '');
  })) return 0;
  const completionKey=`${encounterId}:${encounter.generation}`;
  if(ctx.db.outdoor_encounter_completion.id.find(completionKey)!==null)throw new SenderError('encounter_completion_conflict');
  const contributions=[...ctx.db.outdoor_encounter_contribution.by_encounter.filter(encounterId)];
  const state:OutdoorEncounterState={encounterId,generation:encounter.generation,phase:'active',
    maximumHealthCenti:encounter.maximumHealthCenti,healthCenti:encounter.healthCenti,
    worldSeed:encounter.worldSeed,reward:storedReward,
    respawnAfterTick:encounter.respawnAfterTick,completion:null,
    contributions:contributions.filter(row=>row.generation===encounter.generation).map(row=>({
      identity:row.identity.toHexString(),damageCenti:row.damageCenti,supportCenti:row.supportCenti,lastUsefulTick:row.lastUsefulTick,
    }))};
  const result=damageOutdoorEncounter(state,attacker?.toHexString()??null,appliedDamageCenti,tick,encounter.respawnDelayTicks);
  if(result.appliedDamageCenti===0)return 0;
  const retained=new Set(result.state.contributions.map(row=>row.identity));
  for(const row of contributions)if(row.generation!==encounter.generation||!retained.has(row.identity.toHexString()))ctx.db.outdoor_encounter_contribution.id.delete(row.id);
  for(const contribution of result.state.contributions) {
    const identity=Identity.fromString(contribution.identity),id=`${completionKey}:${contribution.identity}`;
    const row={...contribution,identity,id,encounterId,generation:encounter.generation};
    if(ctx.db.outdoor_encounter_contribution.id.find(id)===null)ctx.db.outdoor_encounter_contribution.insert(row);
    else ctx.db.outdoor_encounter_contribution.id.update(row);
  }
  ctx.db.outdoor_encounter.id.update({...encounter,healthCenti:result.state.healthCenti,phase:result.state.phase,
    respawnAfterTick:result.state.respawnAfterTick,activated:true,lastTargetTick:tick});
  const completion=result.completion;
  if(completion!==null) {
    ctx.db.outdoor_encounter_completion.insert({id:completion.key,encounterId,generation:completion.generation,
      completedTick:completion.completedTick,rewardRevision:completion.rewardRevision});
    for(const grant of completion.grants) {
      const identity=Identity.fromString(grant.identity),id=`${completion.key}:${grant.identity}`;
      ctx.db.outdoor_reward_claim.insert({id,identity,completionId:completion.key,itemsJson:JSON.stringify(grant.items),
        combatExperience:grant.combatExperience,claimed:false,claimedTick:0n});
      // Both this XP and its receipt commit with the final death. Reconnect and
      // item collection never issue XP a second time.
      grantSkillExperience(ctx,identity,'combat',BigInt(grant.combatExperience));
      for (const statistic of definition.completionStatistics ?? []) {
        recordPlayerStatistic(
          ctx,
          identity,
          statistic.kind,
          BigInt(statistic.delta),
          tick,
          statistic.subject ?? '',
        );
      }
    }
  }
  return result.appliedDamageCenti;
}

/** Entitlements stay reserved indefinitely until collected. Full inventory
 * rejects the whole transaction, preserving the exact stored grant for retry. */
export const claimOutdoorReward=spacetimedb.reducer({claimId:t.string()},(ctx,{claimId})=>{
  requireAuthorizedSender(ctx.senderAuth.jwt,ctx.db.membership.identity.find(ctx.sender));
  requirePersistentInventoryAvailable(ctx,ctx.sender);
  const claim=ctx.db.outdoor_reward_claim.id.find(claimId);
  if(claim===null||!claim.identity.isEqual(ctx.sender))throw new SenderError('reward_not_found');
  if(claim.claimed)return;
  const items:unknown=JSON.parse(claim.itemsJson);
  if(!Array.isArray(items)||items.length>16)throw new SenderError('reward_data_invalid');
  const registry=contentRegistry(ctx);
  const offers=items.flatMap((item:unknown,index:number)=>{
    if(item===null||typeof item!=='object'||Array.isArray(item))throw new SenderError('reward_data_invalid');
    const row=item as Record<string,unknown>;
    if(typeof row.itemKind!=='string'||!Number.isSafeInteger(row.quantity)||Number(row.quantity)<1||Number(row.quantity)>16000)throw new SenderError('reward_data_invalid');
    const definition=runtimeItemDefinition(registry,row.itemKind);
    if(definition===null)throw new SenderError('reward_content_unavailable');
    const stacks=[];
    for(let offset=0;offset<Number(row.quantity);offset+=definition.maxStack)stacks.push({
      id:`${claim.id}:${index}:${offset}`,itemKind:row.itemKind,quantity:Math.min(definition.maxStack,Number(row.quantity)-offset),
      durability:runtimeDurabilityDefinition(registry,row.itemKind)?.maximum??0,lit:false,
    });
    return stacks;
  });
  insertEscrowStacksIntoInventory(ctx,ctx.sender,offers,false,'reward_inventory_full');
  ctx.db.outdoor_reward_claim.id.update({...claim,claimed:true,claimedTick:ctx.db.world_clock.id.find(0)?.authorityTick??0n});
});

function damageRogueEnemy(
  ctx: WorldReducerContext,
  npc: WorldNpcRow,
  profile: RogueEnemyProfileRow,
  attacker: WorldReducerContext['sender'],
  damageCenti: number,
  critical: boolean,
  authorityTick: bigint,
): number {
  const run = ctx.db.rogue_run.id.find(profile.runId);
  const member = ctx.db.rogue_run_member.identity.find(attacker);
  if (run === null || member?.runId !== run.id || run.phase !== 'combat'
    || npc.spaceId !== run.spaceId || npc.health === 0) return 0;
  const damage = Math.max(1, Math.ceil(damageCenti / 100));
  const nextHealth = Math.max(0, npc.health - damage);
  const applied = npc.health - nextHealth;
  const attackerPosition = ctx.db.player_position.identity.find(attacker);
  const dx = npc.x - (attackerPosition?.x ?? npc.x - FIXED_UNITS_PER_PIXEL);
  const dy = npc.y - (attackerPosition?.y ?? npc.y);
  const length = Math.max(1, Math.hypot(dx, dy));
  const knockbackPermille = 1_000 + rogueUpgradeMagnitude(ctx, attacker, 'knockback');
  const knockbackFixed = Math.round(8 * FIXED_UNITS_PER_PIXEL * knockbackPermille / 1_000);
  const candidate = {
    x: npc.x + Math.round(dx / length * knockbackFixed),
    y: npc.y + Math.round(dy / length * knockbackFixed),
  };
  const ground = collisionForSpace(ctx, npc.spaceId);
  const actorCollision = runtimeActorCollision(contentRegistry(ctx), ground, npcTraversalActor(ctx, npc), authorityTick,
    traversalSolidGeometry(ground, waterCollisionForSpace(ctx, npc.spaceId)));
  const knocked = positionCollides(candidate, actorCollision)
    ? { x: npc.x, y: npc.y }
    : candidate;
  updateWorldNpc(ctx, {
    ...npc,
    ...knocked,
    chunkX: chunkAt(knocked.x),
    chunkY: chunkAt(knocked.y),
    health: nextHealth,
    moving: nextHealth !== 0,
    wanderDirection: nextHealth === 0 ? 'defeated' : 'alert',
    nextDecisionTick: nextHealth === 0
      ? authorityTick + ROGUE_ENEMY_DEFEAT_RETENTION_TICKS
      : npc.nextDecisionTick,
    authorityTick,
    lastHitCritical: critical,
  });
  if (nextHealth === 0) {
    ctx.db.enemy_attack.npcId.delete(npc.id);
    const rewarded = { ...run, currency: Math.min(65_535, run.currency + profile.rewardCurrency), updatedTick: authorityTick };
    ctx.db.rogue_run.id.update(rewarded);
    completeRogueEnemyDefeat(ctx, rewarded, authorityTick);
  }
  return applied;
}

function clearTraversalHazards(ctx: WorldReducerContext, actor: string): void {
  for (const row of ctx.db.traversal_hazard_state.by_actor.filter(actor)) ctx.db.traversal_hazard_state.id.delete(row.id);
}
/** One observed authority tick; skipped/offline time never becomes exposure. */
function traversalHazardDamage(ctx: WorldReducerContext, actorKey: string, actor: RuntimeTraversalActor,
  position: {spaceId:number;x:number;y:number}, maximumHealth: number, tick: bigint, cachedCollision?: CollisionMap): number {
  const registry = contentRegistry(ctx), policy = runtimeTraversalPolicy(registry);
  if (policy?.mode !== 'active' || maximumHealth <= 0) return 0;
  const abilities = runtimeTraversalAbilities(registry, policy, actor, tick);
  if (abilities === null) return 0;
  const collision = cachedCollision ?? collisionForSpace(ctx, position.spaceId), channels = collision.traversalChannels;
  if (channels === undefined) return 0;
  const x = Math.floor(position.x / TILE_SIZE_FIXED), y = Math.floor(position.y / TILE_SIZE_FIXED);
  const medium = x < 0 || y < 0 || x >= channels.width || y >= channels.height ? 'void'
    : RULE_MEDIA[channels.medium[y * channels.width + x]!] ?? 'void';
  let damage = 0;
  const retained = new Set<string>();
  for (const source of RULE_MEDIA) for (const hazard of policy.media[source].hazards) {
    const id = `${actorKey}:${source}:${hazard.id}`;
    const stored = ctx.db.traversal_hazard_state.id.find(id);
    const immune = hazard.immunityAbilities.some(ability => abilities.has(ability));
    const exposed = source === medium;
    if (immune || (!exposed && (stored === null || stored.numerator === 0n))) {
      if (stored !== null) ctx.db.traversal_hazard_state.id.delete(id);
      continue;
    }
    retained.add(id);
    if (stored?.lastTick === tick) continue;
    const signature = JSON.stringify([policy.id, hazard]);
    const previous = stored !== null && stored.spaceId === position.spaceId && stored.policy === signature
      && stored.lastTick + 1n === tick ? stored : { numerator: 0n, elapsedTicks: 0 };
    const step = advanceHazardDamage(previous, hazard, maximumHealth, 1, AUTHORITY_HZ, exposed, false);
    damage += step.damage;
    const row = { id, actor: actorKey, policy: signature, spaceId: position.spaceId, ...step.state, lastTick: tick };
    if (stored === null) ctx.db.traversal_hazard_state.insert(row);
    else ctx.db.traversal_hazard_state.id.update(row);
  }
  for (const row of ctx.db.traversal_hazard_state.by_actor.filter(actorKey)) {
    if (!retained.has(row.id)) ctx.db.traversal_hazard_state.id.delete(row.id);
  }
  return damage;
}
function stepTraversalHazards(ctx: WorldReducerContext, tick: bigint,
  players: readonly PlayerPositionRow[], npcs: readonly WorldNpcRow[], collisions?: ReadonlyMap<number, CollisionMap>): void {
  const registry = contentRegistry(ctx), policy = runtimeTraversalPolicy(registry);
  // Disabling/replacing policy must not retain debt for a later activation.
  for (const row of ctx.db.traversal_hazard_state.iter()) {
    if (policy?.mode !== 'active' || row.lastTick + 1n < tick) ctx.db.traversal_hazard_state.id.delete(row.id);
  }
  if (policy?.mode !== 'active') return;
  for (const snapshot of players) {
    const player = ctx.db.player_position.identity.find(snapshot.identity);
    if (player === null) continue;
    const key = `player:${player.identity.toHexString()}`;
    const stats = advancePlayerStats(ctx, player.identity, tick);
    if (stats.healthCenti === 0) { clearTraversalHazards(ctx, key); continue; }
    const maximum = resolvedStatsForRow(ctx, stats, player.identity, tick).maxHealthCenti;
    const damage = traversalHazardDamage(ctx, key, { kind: 'player', mount: mountedNpcFor(ctx, player.identity),
      effects: [...ctx.db.player_effect.by_identity.filter(player.identity)] }, player, maximum, tick, collisions?.get(player.spaceId));
    if (damage === 0) continue;
    const nextHealth = Math.max(0, stats.healthCenti - damage);
    const member = ctx.db.rogue_run_member.identity.find(player.identity);
    const run = member === null ? null : ctx.db.rogue_run.id.find(member.runId);
    const combat = compiledLiveIslandRuntime(ctx)?.combatPolicy;
    const recoveryCollision = collisionForSpace(ctx, TOPSIDE_SPACE_ID);
    // Same recovery preflight as combat: never strand a zero-health character
    // when authored arrival content has no safe recovery point.
    if (nextHealth === 0 && run === null && (combat === undefined || outdoorRecoveryPosition(ctx, combat, recoveryCollision) === null)) continue;
    cancelFishingCastFor(ctx, player.identity, tick);
    ctx.db.player_stats.identity.update({ ...stats, healthCenti: nextHealth, healthRemainder: 0, regenTick: tick });
    if (nextHealth === 0) {
      clearTraversalHazards(ctx, key);
      if (run !== null) finishRogueRun(ctx, run);
      else recoverOutdoorKnockout(ctx, player, tick, combat!, recoveryCollision);
    }
  }
  for (const snapshot of npcs) {
    const npc = ctx.db.world_npc.id.find(snapshot.id);
    const key = `npc:${snapshot.id}`;
    if (npc === null || npc.health === 0) { clearTraversalHazards(ctx, key); continue; }
    const wildlife = ctx.db.world_wildlife_profile.npcId.find(npc.id);
    const rogue = ctx.db.rogue_enemy_profile.npcId.find(npc.id);
    const outdoor = ctx.db.outdoor_enemy_profile.npcId.find(npc.id);
    const maximum = rogue?.maxHealth ?? outdoor?.maximumHealth ?? (wildlife === null
      ? runtimeNpcDefinition(registry, npc)?.health
      : Math.ceil((runtimeResolveCreatureStats(registry, wildlife.species)?.maxHealthCenti ?? 0) / 100));
    if (maximum === undefined || maximum <= 0) continue;
    let damage = Math.min(npc.health, traversalHazardDamage(ctx, key, npcTraversalActor(ctx, npc), npc, maximum, tick, collisions?.get(npc.spaceId)));
    if (damage === 0) continue;
    if (outdoor !== null && outdoor.role !== 'add') damage = Math.floor(persistOutdoorEncounterDamage(ctx, outdoor.encounterId, null, damage * 100, tick) / 100);
    if (damage === 0) continue;
    const health = npc.health - damage;
    if (health === 0 && runtimeNpcMount(registry, npc)?.adapter === 'boat') {
      clearTraversalHazards(ctx, key);
      sinkBoat(ctx, npc, tick, collisionForSpace(ctx, npc.spaceId));
      continue;
    }
    updateWorldNpc(ctx, { ...npc, health, lastHitCritical: false, authorityTick: tick,
      ...(health === 0 ? { rider: undefined, moving: false, wanderDirection: 'defeated', nextDecisionTick: tick + (wildlife === null
        ? ROGUE_ENEMY_DEFEAT_RETENTION_TICKS : BigInt(runtimeCreatureRespawnTicks(registry, wildlife.species) ?? 0)) } : {}) });
    if (health === 0) {
      clearTraversalHazards(ctx, key);
      ctx.db.enemy_attack.npcId.delete(npc.id);
      if (outdoor?.role === 'add') ctx.db.outdoor_enemy_profile.npcId.update({ ...outdoor, summonState: 'dead' });
      else if (outdoor !== null && ctx.db.outdoor_encounter.id.find(outdoor.encounterId)?.phase === 'completed') {
        clearOutdoorAdds(ctx, outdoor.encounterId);
      }
      if (rogue !== null) {
        const run = ctx.db.rogue_run.id.find(rogue.runId);
        if (run !== null && run.phase === 'combat') {
          const rewarded = { ...run, currency: Math.min(65_535, run.currency + rogue.rewardCurrency), updatedTick: tick };
          ctx.db.rogue_run.id.update(rewarded);
          completeRogueEnemyDefeat(ctx, rewarded, tick);
        }
      }
    }
  }
}

function combatElevationAt(collision: CollisionMap, x:number, y:number): number {
  const tileX=Math.floor(x/TILE_SIZE_FIXED),tileY=Math.floor(y/TILE_SIZE_FIXED);
  if(tileX<0||tileY<0||tileX>=collision.width||tileY>=collision.height)return -32768;
  return collision.elevations?.[tileY*collision.width+tileX]??0;
}

function projectilePlayerTarget(ctx: WorldReducerContext, identity: WorldReducerContext['sender'], spaceId: number) {
  const player = ctx.db.player_position.identity.find(identity);
  if (player === null || player.spaceId !== spaceId) return null;
  return { kind: 'player' as const, id: identity.toHexString(), ...playerHitboxBounds(player) };
}

function attackCommitmentFromRow(row:EnemyAttackRow) {
  return {...row,pattern:row.pattern as EnemyAttackPattern};
}

/** Same-tick order: player movement/defense precedes NPC sweep, damage and death.
 * A skipped tick cancels a stale commitment; never catch up attacks on arrivals. */
function stepCommittedRogueAttack(
  ctx:WorldReducerContext,npc:WorldNpcRow,attack:EnemyAttackRow,authorityTick:bigint,collision:CollisionMap,
  outdoor?:{players:readonly PlayerPositionRow[];policy:CombatRegionPolicy;definition:HearthEncounterDefinition},
): boolean {
  if(outdoor!==undefined){
    const liveNpc=ctx.db.world_npc.id.find(npc.id),profile=ctx.db.outdoor_enemy_profile.npcId.find(npc.id);
    const camp=profile===null?null:ctx.db.outdoor_encounter.id.find(profile.encounterId);
    if(liveNpc===null||liveNpc.health===0||profile===null||camp?.phase!=='active'||camp.conflict||camp.generation!==profile.generation){
      ctx.db.enemy_attack.npcId.delete(npc.id);return false;
    }
  }
  const commitment=attackCommitmentFromRow(attack);
  const run=outdoor===undefined?rogueRunForIdentity(ctx,attack.targetIdentity):null;
  if(npc.health===0||(outdoor===undefined&&(run===null||run.phase!=='combat'||run.spaceId!==npc.spaceId))
    ||attack.spaceId!==npc.spaceId||authorityTick>attack.lastProcessedTick+1n
    ||enemyAttackPhaseAt(commitment,authorityTick)==='complete'){
    ctx.db.enemy_attack.npcId.delete(npc.id);return false;
  }
  const phase=enemyAttackPhaseAt(commitment,authorityTick);
  let x=npc.x,y=npc.y;
  if(phase==='active' && (attack.pattern==='charge'||attack.pattern==='dive'||attack.pattern==='pulse')) {
    const moveTicks=attack.pattern==='pulse'?Math.max(1,attack.activeTicks-1):attack.activeTicks;
    const elapsed=Number(authorityTick-attack.startedTick)-attack.tellTicks+1;
    const progress=Math.min(1,elapsed/moveTicks);
    const candidate={x:Math.round(attack.originX+(attack.targetX-attack.originX)*progress),
      y:Math.round(attack.originY+(attack.targetY-attack.originY)*progress)};
    if(positionCollides(candidate,collision) || combatSegmentObstructed(npc,candidate,collision)
      ||combatElevationAt(collision,candidate.x,candidate.y)!==attack.elevation
      ||(outdoor!==undefined&&!outdoorMovementAllowed(outdoor.policy,outdoor.definition,npc,candidate,collision))){
      // A blocked lunge still exposes its authored recovery. Retain quota and
      // a recovery-only row instead of letting the next tick immediately move.
      ctx.db.enemy_attack.npcId.update({...attack,startedTick:authorityTick,lastProcessedTick:authorityTick,tellTicks:0,activeTicks:0});
      if(outdoor!==undefined){
        const profile=ctx.db.outdoor_enemy_profile.npcId.find(npc.id);
        const authored=profile===null?null:runtimeHearthEnemyDefinition(contentRegistry(ctx),profile.enemyKind);
        if(profile===null||authored===null){ctx.db.enemy_attack.npcId.delete(npc.id);return false;}
        ctx.db.outdoor_enemy_profile.npcId.update({...profile,nextAttackTick:authorityTick
          +BigInt(attack.recoveryTicks+hearthEnemyAttack(authored,profile.attackCycle).repositionTicks)});
      }
      updateWorldNpc(ctx,{...npc,moving:false,wanderDirection:'recovery',authorityTick});return true;
    }
    x=candidate.x;y=candidate.y;
  }
  let updated={...attack,lastProcessedTick:authorityTick};
  const segment=enemyAttackSegmentAt(commitment,authorityTick);
  if(segment!==null) {
    // Frozen foot-plane and the complete origin-to-impact obstruction test stop
    // attacks passing through a wall or hitting a different cliff course.
    const clear=!combatSegmentObstructed({x:attack.originX,y:attack.originY},segment.to,collision)
      &&combatElevationAt(collision,segment.to.x,segment.to.y)===attack.elevation
      &&(outdoor===undefined||outdoorHostileSegment(outdoor.policy,{x:attack.originX,y:attack.originY},segment.to));
    const members=outdoor?.players??[...ctx.db.rogue_run_member.by_run.filter(run!.id)];
    if(clear)for(const member of members) {
      if(updated.hitIdentities.some(identity=>identity.isEqual(member.identity)))continue;
      const victim=ctx.db.player_position.identity.find(member.identity);
      const radius=(attack.pattern==='pulse'||attack.pattern==='burst'?0.9:0.6)*TILE_SIZE_FIXED;
      if(victim===null||victim.spaceId!==attack.spaceId
        ||combatElevationAt(collision,victim.x,victim.y)!==attack.elevation
        ||!combatPointWithinSegment(victim,segment.from,segment.to,radius))continue;
      const contact=closestCombatPointOnSegment(victim,segment.from,segment.to);
      if(combatSegmentObstructed(contact,victim,collision)
        ||(outdoor!==undefined&&(!outdoorHostileSegment(outdoor.policy,contact,victim)
          ||outdoorRecoveryPosition(ctx,outdoor.policy,collision)===null)))continue;
      const stats=advancePlayerStats(ctx,member.identity,authorityTick);
      const incoming=resolveDefendedPlayerHit(ctx,member.identity,authorityTick,
        attack.pattern==='pulse'||attack.pattern==='burst'?segment.to:{x:attack.originX,y:attack.originY},attack.damageCenti);
      const nextHealth=Math.max(0,stats.healthCenti-incoming.damageCenti);
      updated={...updated,hitIdentities:[...updated.hitIdentities,member.identity]};
      if(incoming.damageCenti>0)cancelFishingCastFor(ctx,member.identity,authorityTick);
      ctx.db.player_stats.identity.update({...stats,healthCenti:nextHealth,vigourCenti:incoming.vigourCenti,healthRemainder:0,regenTick:authorityTick});
      if(nextHealth===0){
        if(outdoor!==undefined)recoverOutdoorKnockout(ctx,victim,authorityTick,outdoor.policy,collision);
        else {ctx.db.enemy_attack.npcId.delete(npc.id);finishRogueRun(ctx,run!);return true;}
      }
    }
  }
  ctx.db.enemy_attack.npcId.update(updated);
  const activity=phase==='tell'?'tell':phase==='active'?'attack':'recovery';
  const moving=x!==npc.x||y!==npc.y;
  if(moving||npc.moving||npc.wanderDirection!==activity)updateWorldNpc(ctx,{...npc,x,y,
    chunkX:chunkAt(x),chunkY:chunkAt(y),moving,wanderDirection:activity,authorityTick});
  return true;
}

function stepRogueEnemy(
  ctx: WorldReducerContext,
  npc: WorldNpcRow,
  profile: RogueEnemyProfileRow,
  authorityTick: bigint,
  collision: CollisionMap,
  lifecycleHandlers: BehaviourHandlerRegistry,
  registrySnapshot: ReturnType<typeof behaviourRegistrySnapshot>,
): void {
  const run = ctx.db.rogue_run.id.find(profile.runId);
  if (run === null) {
    raiseEntityDespawnEvent(
      ctx, behaviourNpcSnapshot(npc, `npc:${npc.kind}`), lifecycleHandlers, registrySnapshot,
    );
    ctx.db.enemy_attack.npcId.delete(profile.npcId);
    ctx.db.rogue_enemy_profile.npcId.delete(profile.npcId);
    ctx.db.world_npc.id.delete(npc.id);
    return;
  }
  if (npc.health === 0) {
    if (authorityTick >= npc.nextDecisionTick) {
      raiseEntityDespawnEvent(
        ctx, behaviourNpcSnapshot(npc, `npc:${npc.kind}`), lifecycleHandlers, registrySnapshot,
      );
      ctx.db.enemy_attack.npcId.delete(profile.npcId);
    ctx.db.rogue_enemy_profile.npcId.delete(profile.npcId);
      ctx.db.world_npc.id.delete(npc.id);
    }
    return;
  }
  const committed=ctx.db.enemy_attack.npcId.find(npc.id);
  if(committed!==null && stepCommittedRogueAttack(ctx,npc,committed,authorityTick,collision))return;
  if (run.phase !== 'combat') {
    if (npc.moving || npc.wanderDirection !== 'idle') updateWorldNpc(ctx, {
      ...npc, moving: false, wanderDirection: 'idle', authorityTick,
    });
    return;
  }
  const players = [...ctx.db.rogue_run_member.by_run.filter(run.id)]
    .map((member) => ctx.db.player_position.identity.find(member.identity))
    .filter((position) => position !== null && position.spaceId === run.spaceId);
  if (players.length === 0) return;
  const target = players.sort((left, right) => (
    (left!.x - npc.x) ** 2 + (left!.y - npc.y) ** 2
      - ((right!.x - npc.x) ** 2 + (right!.y - npc.y) ** 2)
  ))[0]!;
  const dx = target.x - npc.x;
  const dy = target.y - npc.y;
  const distanceSquared = dx * dx + dy * dy;
  const ranged = profile.archetype === 'ranged' || profile.archetype === 'mage';
  const attackRange = (ranged ? 6 : 1.25) * TILE_SIZE_FIXED;
  const retreatRange = ranged ? 3 * TILE_SIZE_FIXED : 0;
  const facing = npcFacingTowardPoint(
    { x: npc.x, y: npc.y }, { x: target.x, y: target.y }, parseNpcFacing(npc.facing),
  );
  if (distanceSquared <= attackRange * attackRange && authorityTick >= profile.nextAttackTick
    && [...ctx.db.enemy_attack.by_target.filter(target.identity)].length < MAX_COMMITTED_ATTACKERS
    && combatElevationAt(collision,npc.x,npc.y)===combatElevationAt(collision,target.x,target.y)
    && !combatSegmentObstructed(npc,target,collision)) {
    const pattern=runtimeRogueEnemyAttackPattern(contentRegistry(ctx),npc.kind,profile.archetype);
    if(pattern!==null){
      const commitment=commitEnemyAttack(pattern,authorityTick,authorityTick,npc,target,attackRange);
      ctx.db.enemy_attack.insert({...commitment,npcId:npc.id,targetIdentity:target.identity,
        lastProcessedTick:authorityTick,elevation:combatElevationAt(collision,npc.x,npc.y),
        damageCenti:profile.damage*100,hitIdentities:[],spaceId:npc.spaceId,chunkX:npc.chunkX,chunkY:npc.chunkY});
      ctx.db.rogue_enemy_profile.npcId.update({...profile,nextAttackTick:authorityTick
        +BigInt(commitment.tellTicks+commitment.activeTicks+commitment.recoveryTicks)});
      updateWorldNpc(ctx,{...npc,facing,moving:false,wanderDirection:'tell',authorityTick});
      return;
    }
  }

  let movementTarget = { x: target.x, y: target.y };
  if (ranged && distanceSquared < retreatRange * retreatRange) {
    movementTarget = { x: npc.x - dx, y: npc.y - dy };
  } else if (ranged && distanceSquared <= attackRange * attackRange) {
    if (npc.moving || npc.facing !== facing || npc.wanderDirection !== 'aim') updateWorldNpc(ctx, {
      ...npc, facing, moving: false, wanderDirection: 'aim', authorityTick,
    });
    return;
  }
  let stepped: Parameters<typeof stepNpcTowardPoint>[0] = {
    id: npc.id,
    position: { x: npc.x, y: npc.y },
    home: { x: npc.homeX, y: npc.homeY },
    facing: parseNpcFacing(npc.facing),
    moving: npc.moving,
    wanderDirection: (npc.wanderDirection === 'up' || npc.wanderDirection === 'down'
      || npc.wanderDirection === 'left' || npc.wanderDirection === 'right')
      ? parseNpcFacing(npc.wanderDirection) : null,
    nextDecisionTick: Number(npc.nextDecisionTick),
  };
  const steps = Math.max(1, Math.min(3, Math.round(profile.speedPermille / 650)));
  for (let step = 0; step < steps; step += 1) {
    stepped = stepNpcTowardPoint(stepped, movementTarget, Number(authorityTick), collision, 0);
  }
  updateWorldNpc(ctx, {
    ...npc,
    x: stepped.position.x,
    y: stepped.position.y,
    chunkX: chunkAt(stepped.position.x),
    chunkY: chunkAt(stepped.position.y),
    facing: stepped.facing,
    moving: stepped.moving,
    wanderDirection: stepped.wanderDirection ?? 'alert',
    nextDecisionTick: BigInt(stepped.nextDecisionTick),
    authorityTick,
  });
}

const TOOL_SWING_RESISTANCE = new Set([
  'wrong_tool', 'pickaxe_tier_too_low', 'mining_claimed_by_other_party',
  'space_build_disabled', 'homestead_owner_required', 'landmark_not_movable',
  'campfire_in_use', 'target_not_ready', 'resource_not_mature', 'resource_depleted',
  'target_out_of_range', 'target_out_of_reach',
]);

function applyToolSwingLifecycle(ctx: WorldReducerContext, mutate = true): void {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const survival = ctx.db.player_survival.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
  if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
  if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
  const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
  requireUsableTool(ctx, slot);
  const registry = contentRegistry(ctx);
  const tool = runtimeToolDefinition(registry, slot.itemKind);
  const geometry = tool?.swing;
  const actionKind = runtimeItemAvatarAction(registry, slot.itemKind);
  if (geometry === undefined || actionKind === null) throw new SenderError('tool_swing_not_authored');
  const facing = parseDirection(position.facing);
  if (facing === null || facing === undefined) throw new SenderError('invalid_facing');
  const chunks = toolSwingChunks(position, geometry.rangeFixed);
  const resources = chunks.flatMap(([x, y]) => [...ctx.db.world_resource.by_chunk.filter([position.spaceId, x, y])]);
  const chests = chunks.flatMap(([x, y]) => [...ctx.db.world_chest.by_chunk.filter([position.spaceId, x, y])]);
  const combatTargets = chunks.flatMap(([x, y]) => [...ctx.db.world_combat_target.by_chunk.filter([position.spaceId, x, y])]);
  const collision = collisionForSpace(ctx, position.spaceId, undefined, {
    resources, chests, combatTargets, chunkScope: new Set(chunks.map(([x, y]) => `${x}:${y}`)),
  });
  const terrainCollision = { ...collision, obstacles: [] };
  const contacts: SwingTarget[] = [];
  // The sector is anchored at the actor's position, so every reach point must be
  // expressed in that frame. A resource's contact point is authored relative to
  // the interaction origin at chest height; measuring it from the feet instead
  // shortened an upward swing by the body offset — more than half a pick's
  // reach — and lengthened a downward one. Elevation and line of sight still
  // use the contact's true world point.
  const include = (
    kind: SwingTarget['kind'],
    id: bigint,
    point: { x: number; y: number },
    reachPoint: { x: number; y: number } = point,
  ) => {
    if (!toolSwingContains(position, facing, reachPoint, geometry)
      || combatElevationAt(collision, position.x, position.y) !== combatElevationAt(collision, point.x, point.y)
      || combatSegmentObstructed(position, point, terrainCollision)) return false;
    contacts.push({ kind, id });
    return true;
  };
  const tilePoint = (row: { tileX: number; tileY: number }) => ({
    x: (row.tileX + 0.5) * TILE_SIZE_FIXED, y: (row.tileY + 0.5) * TILE_SIZE_FIXED,
  });
  for (const [x, y] of chunks) {
    const chunk = [position.spaceId, x, y] as const;
    for (const npc of ctx.db.world_npc.by_chunk.filter(chunk)) {
      if (npc.health > 0 && npc.rider === undefined) include('npc', npc.id, npc);
    }
    for (const resource of ctx.db.world_resource.by_chunk.filter(chunk)) {
      if (!resource.depleted && !liveMapGeneratedResourceSuppressed(ctx, resource.spaceId, resource.id)
        && runtimeResourceDefinition(registry, resource) !== null) {
        const vector = runtimeResourceTargetVector(registry, resource, position.x, position.y, resource.tileX, resource.tileY);
        const origin = playerInteractionOrigin(position);
        if (vector !== null) include('resource', resource.id,
          { x: origin.x + vector.x, y: origin.y + vector.y },
          { x: position.x + vector.x, y: position.y + vector.y });
      }
    }
    for (const target of ctx.db.world_combat_target.by_chunk.filter(chunk)) {
      if (target.carriedBy === undefined && activeCombatTargetHealth(ctx, target) !== null) include('combat_target', target.id, target);
    }
    for (const placeable of ctx.db.world_placeable.by_chunk.filter(chunk)) {
      if (placeable.carriedBy !== undefined || authoredHitsDamageable(ctx, placeable) === null) continue;
      if (genericChest(ctx, placeable) && ctx.db.chest_migration_mapping.placeableId.find(placeable.id) !== null
        && !chestMigrationReadsUsePlaceables(ctx)) continue;
      for (const tile of runtimeObjectFootprintTiles(registry, placeable)) {
        if (include('placeable', placeable.id, tilePoint(tile))) break;
      }
    }
    for (const chest of ctx.db.world_chest.by_chunk.filter(chunk)) {
      if (chest.carriedBy !== undefined || legacyChestDamageable(ctx) === null) continue;
      if (ctx.db.chest_migration_mapping.chestId.find(chest.id) !== null && chestMigrationReadsUsePlaceables(ctx)) continue;
      include('chest', chest.id, tilePoint(chest));
    }
  }
  validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, contacts.length === 0);
  const swing = { prepaid: true } as const;
  const apply = (target: SwingTarget, write: boolean) => {
    if (target.kind === 'npc' || target.kind === 'combat_target') {
      applySwordMeleeLifecycle(ctx, { kind: target.kind, id: target.id }, write, swing);
    } else if (target.kind === 'resource') {
      applyHarvestResourceLifecycle(ctx, target.id, write, swing);
    } else if (target.kind === 'chest') {
      if (write) harvestChestTransaction(ctx, target.id, swing);
      else validateChestHarvestEffect(ctx, target.id, swing);
    } else {
      const row = ctx.db.world_placeable.id.find(target.id);
      if (row === null) throw new SenderError('target_not_ready');
      if (genericChest(ctx, row)) {
        if (write) harvestPlaceableChestTransaction(ctx, target.id, swing);
        else validatePlaceableChestHarvestEffect(ctx, target.id, swing);
      } else applyHarvestPlaceableLifecycle(ctx, target.id, write, swing);
    }
  };
  executeToolSwing(contacts, {
    validate: target => apply(target, false),
    resisted: error => error instanceof SenderError && TOOL_SWING_RESISTANCE.has(error.message),
    spend: empty => spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, empty),
    hit: target => apply(target, true),
    finish: wear => {
      if (wear > 0) wearInventoryTool(ctx, slot, wear);
      const current = ctx.db.player_position.identity.find(ctx.sender)!;
      ctx.db.player_position.identity.update({ ...current, actionKind,
        actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick) });
      recordPlayerStatistic(ctx, ctx.sender, wear === 0 ? 'tool_whiffs' : 'tool_uses', 1n, clock.authorityTick, slot.itemKind);
    },
  }, mutate);
}

type SwordMeleeTarget = {
  readonly kind: 'combat_target' | 'npc';
  readonly id: bigint;
} | null;

/** Authority-owned implementation used by the authored sword lifecycle. A
 * missing target remains an intentional whiff used for responsive free swings. */
function applySwordMeleeLifecycle(
  ctx: WorldReducerContext,
  attackTarget: SwordMeleeTarget,
  mutate = true,
  swing?: ToolSwingContact): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
    const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    if (slot === null) throw new SenderError('wrong_tool');
    const registry = contentRegistry(ctx);
    const actionKind = runtimeItemAvatarAction(registry, slot.itemKind);
    const weaponBaseCenti = runtimeWeaponBaseDamageCenti(registry, slot.itemKind, 'melee')
      ?? (swing === undefined ? null : runtimeToolDefinition(registry, slot.itemKind)?.swing?.baseDamageCenti ?? null);
    if (weaponBaseCenti === null) throw new SenderError('weapon_damage_not_authored');
    const toolDefinition = runtimeToolDefinition(registry, slot.itemKind);
    if ((swing === undefined && !runtimeItemHasTag(registry, slot.itemKind, 'item.melee_weapon'))
      || actionKind === null || toolDefinition === null) throw new SenderError('wrong_tool');
    requireUsableTool(ctx, slot);

    if (attackTarget === null) {
      if (!mutate) {
        if (swing === undefined) validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, true);
        return;
      }
      if (swing === undefined) spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, true);
      if (swing === undefined) ctx.db.player_position.identity.update({
        ...position,
        actionKind,
        actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
      });
      recordPlayerStatistic(ctx, ctx.sender, 'tool_whiffs', 1n, clock.authorityTick, slot.itemKind);
      return;
    }

    const targetId = attackTarget.id;
    const storedTarget = attackTarget.kind === 'combat_target'
      ? ctx.db.world_combat_target.id.find(targetId)
      : null;
    const wildlife = attackTarget.kind === 'npc'
      ? ctx.db.world_npc.id.find(targetId)
      : null;
    const profile = wildlife === null ? null : ctx.db.world_wildlife_profile.npcId.find(wildlife.id);
    const rogueProfile = wildlife === null ? null : ctx.db.rogue_enemy_profile.npcId.find(wildlife.id);
    const targetHealth = storedTarget === null ? null : activeCombatTargetHealth(ctx, storedTarget);
    const validWildlife = wildlife !== null && wildlife.spaceId === position.spaceId && wildlife.health > 0
      && profile !== null && runtimeWildlifeDefinition(registry, profile.species) !== null
      && runtimeCreatureIsHuntable(registry, profile.species);
    const validOutdoorEnemy = wildlife !== null && outdoorEnemyDamageAllowed(ctx,wildlife,ctx.sender);
    const validRogueEnemy = wildlife !== null && wildlife.spaceId === position.spaceId && wildlife.health > 0
      && rogueProfile !== null && rogueRunForIdentity(ctx, ctx.sender)?.id === rogueProfile.runId;
    if ((storedTarget === null || targetHealth === null
      || storedTarget.spaceId !== position.spaceId || storedTarget.carriedBy !== undefined)
      && !validWildlife && !validRogueEnemy && !validOutdoorEnemy) {
      throw new SenderError('target_not_ready');
    }
    const tile = storedTarget === null ? null : combatTargetTile(storedTarget);
    const targetX = wildlife?.x ?? (tile!.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2);
    const targetY = wildlife?.y ?? (tile!.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2);
    const swingFacing = decodeDirection(position.facing);
    if (swingFacing === undefined || swingFacing === null) throw new SenderError('invalid_facing');
    if (swing === undefined && !forwardSwingTargetInReach(
      position.x, position.y, swingFacing, targetX, targetY, toolDefinition,
    )) throw new SenderError('target_out_of_range');

    if (!mutate) {
      if (swing === undefined) validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
      return;
    }
    if (swing === undefined) spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
    const facing = directionFromAim(targetX - position.x, targetY - position.y);
    if (swing === undefined) ctx.db.player_position.identity.update({
      ...position,
      facing: facing ?? position.facing,
      actionKind,
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });

    const statsRow = advancePlayerStats(ctx, ctx.sender, clock.authorityTick);
    const modifiers = activePlayerModifiers(ctx, ctx.sender, clock.authorityTick);
    const characterBalance = activeCharacterCombatBalance(ctx);
    const resolved = resolveStatsWithProfile(characterBalance, {
      str: statsRow.str, dex: statsRow.dex, con: statsRow.con,
      int: statsRow.int, wis: statsRow.wis, cha: statsRow.cha,
    }, modifiers);
    const seed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
    const damage = resolveCombatDamageWithProfile(characterBalance, {
      attackKind: 'melee',
      weaponBaseCenti,
      scalingAttribute: resolved.attributes.str,
      armorCenti: 0,
      armorPctBasisPoints: 0,
      seedParts: [seed, ctx.sender.toHexString(), clock.authorityTick, targetId, slot.itemKind],
      attackerModifiers: modifiers,
    });
    if ((validWildlife || validRogueEnemy || validOutdoorEnemy) && wildlife !== null) {
      if (validOutdoorEnemy) damageOutdoorEnemy(ctx,wildlife,ctx.sender,damage.damageCenti,damage.critical,clock.authorityTick);
      else if (validRogueEnemy && rogueProfile !== null) damageRogueEnemy(
        ctx, wildlife, rogueProfile, ctx.sender, damage.damageCenti, damage.critical, clock.authorityTick,
      );
      else damageHuntableWildlife(
        ctx, wildlife, ctx.sender, damage.damageCenti, damage.critical, clock.authorityTick,
      );
      if (!validRogueEnemy) {
        if (swing === undefined) wearInventoryTool(ctx, slot, 1);
        if (swing === undefined) recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, slot.itemKind);
      }
      return;
    }
    const target = regenerateCombatTarget(ctx, storedTarget!, clock.authorityTick);
    const minimumHealthCenti = Math.min(
      target.healthCenti,
      target.maxHealthCenti,
      targetHealth!.minimumHealthCenti,
    );
    const nextHealth = Math.max(minimumHealthCenti, target.healthCenti - damage.damageCenti);
    const appliedDamage = target.healthCenti - nextHealth;
    if (appliedDamage > 0) {
      ctx.db.world_combat_target.id.update({
        ...target,
        healthCenti: nextHealth,
        regenTick: clock.authorityTick,
        lastDamagedTick: clock.authorityTick,
        lastHitCritical: damage.critical,
      });
      recordPlayerStatistic(
        ctx, ctx.sender, 'damage_dealt', BigInt(appliedDamage), clock.authorityTick, target.kind,
      );
    }
    if (swing === undefined) wearInventoryTool(ctx, slot);
    if (swing === undefined) recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, slot.itemKind);
}

function applyHarvestResourceLifecycle(
  ctx: WorldReducerContext,
  resourceId: bigint,
  mutate = true,
  swing?: ToolSwingContact): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    if (mountedNpcFor(ctx, ctx.sender) !== null) {
      throw new SenderError('mounted_action_forbidden');
    }
    const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    const registry = contentRegistry(ctx);
    const actionKind = runtimeItemAvatarAction(registry, slot?.itemKind ?? 'empty');
    if (actionKind === null) throw new SenderError('selected_tool_has_no_action');
    requireUsableTool(ctx, slot);
    if (!isVitalsToolKind(ctx, slot.itemKind)) throw new SenderError('wrong_tool');
    const toolDefinition = runtimeToolDefinition(registry, slot.itemKind);
    if (toolDefinition === null) throw new SenderError('wrong_tool');

    if (resourceId === 0n) {
      if (!mutate) {
        if (swing === undefined) validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, true);
        return;
      }
      if (swing === undefined) spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, true);
      if (swing === undefined) ctx.db.player_position.identity.update({
        ...position,
        actionKind,
        actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
      });
      recordPlayerStatistic(ctx, ctx.sender, 'tool_whiffs', 1n, clock.authorityTick, slot.itemKind);
      return;
    }

    const resource = ctx.db.world_resource.id.find(resourceId);
    if (resource === null) throw new SenderError('target_not_ready');
    if (resource.spaceId !== position.spaceId) throw new SenderError('target_not_ready');
    if (liveMapGeneratedResourceSuppressed(ctx, resource.spaceId, resource.id)) {
      throw new SenderError('target_not_ready');
    }
    requireWorldModificationAuthorized(ctx, position);
    requireHearthResourceHarvestAccess(ctx, position, resource);
    const result = resourceHarvestResult(
      position.x, position.y, slot.itemKind, resource, toolDefinition, registry,
    );
    if (result === 'depleted') throw new SenderError('resource_depleted');
    if (result === 'wrong_tool') throw new SenderError('wrong_tool');
    if (swing === undefined && result === 'out_of_range') throw new SenderError('target_out_of_range');

    const resourceDefinition = runtimeResourceDefinition(registry, resource);
    if (resourceDefinition === null) throw new SenderError('resource_definition_missing');
    if (resourceDefinition.interaction.mode === 'mine') {
      const nodeClass = miningClassForResource(registry, resource);
      const miningKind = resource.kind;
      if (!runtimeToolCanMineResource(registry, slot.itemKind, miningKind)) {
        throw new SenderError('pickaxe_tier_too_low');
      }
      const ranks = playerSkillRanks(ctx, ctx.sender);
      const skillCapabilities = runtimeSkillCapabilities(registry, ranks);
      const partyId = playerPartyId(ctx, ctx.sender);
      const storedClaim = ctx.db.world_resource_mining_claim.resourceId.find(resource.id);
      const activeClaim = storedClaim !== null && storedClaim.claimUntilTick > clock.authorityTick;
      const ownsSoloClaim = activeClaim && storedClaim?.claimedBy.isEqual(ctx.sender) === true;
      const sharesPartyClaim = activeClaim && storedClaim?.partyId !== undefined
        && partyId !== undefined && storedClaim.partyId === partyId;
      if (activeClaim && !ownsSoloClaim && !sharesPartyClaim) {
        throw new SenderError('mining_claimed_by_other_party');
      }
      if (!mutate) {
        if (swing === undefined) validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
        return;
      }
      if (swing === undefined) spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
      const resourceFacing = directionFromAim(
        resource.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
        resource.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
      );
      if (swing === undefined) ctx.db.player_position.identity.update({
        ...position,
        facing: resourceFacing ?? position.facing,
        actionKind,
        actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
      });
      const continuingClaim = activeClaim && (ownsSoloClaim || sharesPartyClaim);
      const work = miningWorkPerHit(skillCapabilities.efficientStrikesRank);
      const accumulatedWork = (continuingClaim ? resource.yieldProgress : 0) + work;
      const claim = {
        resourceId: resource.id,
        claimedBy: continuingClaim && storedClaim !== null ? storedClaim.claimedBy : ctx.sender,
        partyId: continuingClaim && storedClaim !== null ? storedClaim.partyId : partyId,
        claimUntilTick: clock.authorityTick + MINING_CLAIM_TICKS,
      };
      if (storedClaim === null) ctx.db.world_resource_mining_claim.insert(claim);
      else ctx.db.world_resource_mining_claim.resourceId.update(claim);
      if (swing === undefined) wearInventoryTool(ctx, slot);
      if (swing === undefined) recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, slot.itemKind);
      recordPlayerStatistic(ctx, ctx.sender, 'resource_hits', 1n, clock.authorityTick, resource.kind);
      if (accumulatedWork < MINING_YIELD_WORK) {
        ctx.db.world_resource.id.update({ ...resource, yieldProgress: accumulatedWork });
        return;
      }

      const maximumRichness = resource.maximumRichness > 0
        ? resource.maximumRichness
        : Math.max(1, Math.min(MINING_MAX_RICHNESS, resource.health));
      const richness = resource.richness > 0 ? resource.richness : Math.max(1, resource.health);
      const resolved = resolveMiningLoot(contentRegistry(ctx).loots, {
        kind: miningKind,
        lootId: resourceDefinition.loot,
        nodeClass,
        richnessRemaining: richness,
        maximumRichness,
        yieldsProduced: resource.yieldsProduced,
        producedOre: resource.producedOre,
      }, [
        ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED,
        resource.id,
        resource.activationOrdinal,
        resource.yieldsProduced,
        ctx.sender.toHexString(),
      ], skillCapabilities.oreDressingRank, skillCapabilities.rockhoundRank,
      skillCapabilities.motherLodeRank);
      const nextRichness = Math.max(0, richness - 1);
      const depleted = nextRichness === 0;
      ctx.db.world_resource.id.update({
        ...resource,
        miningClass: nodeClass,
        health: nextRichness,
        depleted,
        richness: nextRichness,
        maximumRichness,
        yieldProgress: Math.max(0, accumulatedWork - MINING_YIELD_WORK),
        yieldsProduced: resource.yieldsProduced + 1,
        producedOre: resource.producedOre || resolved.producedOre,
        respawnAtTick: depleted
          ? clock.authorityTick + miningRespawnDelayTicks(nodeClass, [
            resource.id, resource.activationOrdinal, resource.yieldsProduced,
          ])
          : 0n,
      });
      if (depleted) {
        ctx.db.world_resource_mining_claim.resourceId.delete(resource.id);
        recordHearthResourceDepletion(ctx, resource, clock.authorityTick);
      }
      if (depleted) {
        recordPlayerStatistic(ctx, ctx.sender, 'resources_depleted', 1n, clock.authorityTick, resource.kind);
        if (resourceDefinition.statistics.depletion === 'rock') {
          recordPlayerStatistic(ctx, ctx.sender, 'rocks_broken', 1n, clock.authorityTick);
        } else if (resourceDefinition.statistics.depletion === 'ore') {
          recordPlayerStatistic(ctx, ctx.sender, 'ore_nodes_depleted', 1n, clock.authorityTick, resource.kind);
        }
      }
      const itemX = resource.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 + 10 * FIXED_UNITS_PER_PIXEL;
      const itemY = (resource.tileY + 1) * TILE_SIZE_FIXED + 3 * FIXED_UNITS_PER_PIXEL;
      applyLootDropsBehaviour(ctx, resolved.drops, {
        x: itemX,
        y: itemY,
        spaceId: resource.spaceId,
        authorityTick: clock.authorityTick,
        recipient: ctx.sender,
        reservedUntilTick: clock.authorityTick + MINING_DROP_RESERVATION_TICKS,
        horizontalSpacing: 4 * FIXED_UNITS_PER_PIXEL,
        recordItemsObtained: true,
      }, lootAuthorityDependencies);
      const payoutExperience = runtimeActivityExperience(contentRegistry(ctx), nodeClass === 'rock' ? 'mine_rock'
        : nodeClass === 'mixed' ? (resolved.producedOre ? 'mine_mixed_ore' : 'mine_mixed_stone') : 'mine_ore');
      grantSkillExperience(
        ctx,
        ctx.sender,
        'farming',
        payoutExperience + (depleted ? runtimeActivityExperience(contentRegistry(ctx), 'mine_depletion', maximumRichness) : 0n),
      );
      return;
    }

    if (!mutate) {
      if (swing === undefined) validateToolVigourSpend(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
      return;
    }
    if (swing === undefined) spendToolVigour(ctx, ctx.sender, slot.itemKind, clock.authorityTick, false);
    const resourceFacing = directionFromAim(
      resource.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      resource.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );
    if (swing === undefined) ctx.db.player_position.identity.update({
      ...position,
      facing: resourceFacing ?? position.facing,
      actionKind,
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    const nextHealth = Math.max(0, resource.health - 1);
    const treeGrowthStage = normalizeTreeGrowthStage(resource.growthStage);
    const ripeFruitBeforeFell = nextHealth === 0
      && resourceDefinition.fruitHarvest !== undefined
      && orchardFruitStatus(resource, clock.authorityTick) === 'ok';
    ctx.db.world_resource.id.update({
      ...resource,
      health: nextHealth,
      depleted: nextHealth === 0,
      regrowthProgress: nextHealth === 0 && resourceDefinition.regrowth?.enabled === true
        ? 0
        : resource.regrowthProgress,
    });
    if (swing === undefined) wearInventoryTool(ctx, slot);
    if (swing === undefined) recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, slot.itemKind);
    recordPlayerStatistic(ctx, ctx.sender, 'resource_hits', 1n, clock.authorityTick, resource.kind);
    if (nextHealth === 0) {
      recordHearthResourceDepletion(ctx, resource, clock.authorityTick);
      recordPlayerStatistic(ctx, ctx.sender, 'resources_depleted', 1n, clock.authorityTick, resource.kind);
      if (resourceDefinition.statistics.depletion === 'tree') {
        recordPlayerStatistic(ctx, ctx.sender, 'trees_cut_down', 1n, clock.authorityTick);
      } else if (resourceDefinition.statistics.depletion === 'cactus') {
        recordPlayerStatistic(ctx, ctx.sender, 'cacti_cut_down', 1n, clock.authorityTick);
      } else if (resourceDefinition.statistics.depletion === 'rock') {
        recordPlayerStatistic(ctx, ctx.sender, 'rocks_broken', 1n, clock.authorityTick);
      } else if (resourceDefinition.statistics.depletion === 'ore') {
        recordPlayerStatistic(ctx, ctx.sender, 'ore_nodes_depleted', 1n, clock.authorityTick, resource.kind);
      }
    }
    if (nextHealth !== 0) return;
    const target: BehaviourObjectSnapshot = {
      entityType: 'object',
      id: resource.id.toString(),
      definitionId: resourceDefinition.id,
      tags: resourceDefinition.tags,
      tile: {
        spaceId: resource.spaceId.toString(),
        x: resource.tileX,
        y: resource.tileY,
        tags: [],
      },
      state: { depleted: true, health: nextHealth, treeGrowthStage },
    };
    const drops = [...registeredLifecycleLoot(ctx, {
      type: 'break',
      actor: { entityType: 'player', id: ctx.sender.toHexString() },
      object: { entityType: 'object', id: target.id, definitionId: target.definitionId },
      tool: { kind: slot.itemKind, instanceId: slot.id },
    }, target, [
      ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED,
      resource.id,
      resource.activationOrdinal,
    ], { values: { remainingHealth: nextHealth, treeGrowthStage } }).drops];
    let consumedFruitReadyAtTick: bigint | null = null;
    if (resourceDefinition.fruitHarvest !== undefined) {
      for (let i = drops.length - 1; i >= 0; i--) {
        if (runtimeItemHasTag(registry, drops[i]!.itemKind, 'crop.fruit')
          || `item:${drops[i]!.itemKind}` === resourceDefinition.seedItem) drops.splice(i, 1);
      }
      if (ripeFruitBeforeFell) {
        const harvest = resourceDefinition.fruitHarvest;
        drops.push({ itemKind: harvest.item.slice('item:'.length), quantity: harvest.quantity });
        const ripeSeed = fruitSeedDrop(contentRegistry(ctx), resource, drops,
          farmingSkillEffects(contentRegistry(ctx), playerSkillRanks(ctx, ctx.sender)).orchardSeedSaver,
          [ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED, resource.id, resource.activationOrdinal]);
        if (ripeSeed !== null) drops.push(ripeSeed);
        consumedFruitReadyAtTick = clock.authorityTick + BigInt(harvest.cooldownTicks);
      }
    }
    const seedDrop = resourceDefinition.fruitHarvest === undefined && treeGrowthStage === 3 && resourceDefinition.seedItem !== undefined
      ? fruitSeedDrop(contentRegistry(ctx), resource, drops,
      farmingSkillEffects(contentRegistry(ctx), playerSkillRanks(ctx, ctx.sender)).orchardSeedSaver,
      [ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED, resource.id, resource.activationOrdinal]) : null;
    if (seedDrop !== null) drops.push(seedDrop);
    if (resourceDefinition.tags.includes('resource.fruit_tree')) {
      const current = ctx.db.world_resource.id.find(resource.id)!;
      ctx.db.world_resource.id.update({
        ...current,
        activationOrdinal: (resource.activationOrdinal + 1) >>> 0,
        ...(consumedFruitReadyAtTick === null ? {} : { fruitReadyAtTick: consumedFruitReadyAtTick }),
      });
    }
    if (drops.length === 0) return;
    const itemX = resource.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 + 10 * FIXED_UNITS_PER_PIXEL;
    const itemY = (resource.tileY + 1) * TILE_SIZE_FIXED + 3 * FIXED_UNITS_PER_PIXEL;
    applyLootDropsBehaviour(ctx, drops, {
      x: itemX,
      y: itemY,
      spaceId: resource.spaceId,
      authorityTick: clock.authorityTick,
      ...(resourceDefinition.lootDelivery === 'actor_reserved' ? { recipient: ctx.sender,
        reservedUntilTick: clock.authorityTick + MINING_DROP_RESERVATION_TICKS,
        recordItemsObtained: true } : {}),
      horizontalSpacing: 4 * FIXED_UNITS_PER_PIXEL,
    }, lootAuthorityDependencies);
    for (const drop of drops) {
      if (runtimeItemHasTag(contentRegistry(ctx), drop.itemKind, 'crop.fruit')) {
        grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'resource_fruit_harvest', drop.quantity));
      }
    }
}

function activePersonalQuestResource(
  ctx: WorldReducerContext,
  identity: WorldReducerContext['sender'],
  resourceId: bigint,
) {
  const identityHex = identity.toHexString();
  for (const row of ctx.db.player_quest.by_identity.filter(identity)) {
    if (row.state !== 'active') continue;
    const definition = runtimeQuestDefinition(contentRegistry(ctx), row.questId);
    if (definition === null) continue;
    const resource = definition.world?.personalResource;
    if (resource === undefined || resource.resourceId !== resourceId) continue;
    const objective = definition.objectives.find(({ id }) => id === resource.objectiveId);
    if (objective?.kind !== 'statistic') return null;
    const baseline = ctx.db.player_quest_baseline.id.find(playerQuestBaselineId(
      identityHex, definition.id, objective.id,
    ))?.value ?? 0n;
    const lifetime = ctx.db.player_statistic.id.find(playerStatisticRowId(
      identityHex, objective.statisticKind, objective.subjectKind,
    ))?.value ?? 0n;
    const caught = lifetime > baseline ? lifetime - baseline : 0n;
    return {
      ...resource,
      statisticKind: objective.statisticKind,
      subjectKind: objective.subjectKind,
      maximum: objective.count,
      remaining: Number(objective.count > caught ? objective.count - caught : 0n),
    };
  }
  return null;
}

/** Starts a server-timed cast at an authoritative water tile. A pool on that
 * exact tile can produce a catch; ordinary open water retains the deliberate
 * half-Vigour whiff path while still creating a visible line and bobber. */
function applyFishingCastLifecycle(
  ctx: WorldReducerContext,
  poolId: bigint,
  targetTileX: number,
  targetTileY: number,
  mutate = true,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
    const selected = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    const registry = contentRegistry(ctx);
    if (selected === null || selected.quantity < 1
      || runtimeToolSpecialization(registry, selected.itemKind) !== 'fishing') {
      throw new SenderError('wrong_tool');
    }
    const toolDefinition = runtimeToolDefinition(registry, selected.itemKind);
    const reachFixed = runtimeToolReachFixed(registry, selected.itemKind);
    if (toolDefinition === null || reachFixed === null) throw new SenderError('wrong_tool');
    requireUsableTool(ctx, selected);
    if (ctx.db.fishing_cast.identity.find(ctx.sender) !== null) {
      throw new SenderError('fishing_already_cast');
    }
    const targetTile = { tileX: targetTileX, tileY: targetTileY };
    if (!tileTargetWithinFixedReach(
      position.x,
      position.y,
      targetTile,
      reachFixed,
    )) throw new SenderError('target_out_of_range');
    if (tileTargetIsBlocked(waterCollisionForSpace(ctx, position.spaceId), targetTile)) {
      throw new SenderError('fishing_requires_water');
    }

    const personalResource = activePersonalQuestResource(ctx, ctx.sender, poolId);
    const pool = personalResource !== null
      ? personalResource.remaining <= 0 ? null : {
          id: personalResource.resourceId,
          kind: personalResource.resourceKind,
          tileX: personalResource.tileX,
          tileY: personalResource.tileY,
          depleted: false,
          spaceId: personalResource.spaceId,
        }
      : poolId === 0n ? null : ctx.db.world_resource.id.find(poolId);
    if (poolId !== 0n && (pool === null || runtimeResourceDefinition(registry, pool)?.interaction.mode !== 'fish'
      || pool.spaceId !== position.spaceId
      || pool.tileX !== targetTileX || pool.tileY !== targetTileY)) {
      throw new SenderError('target_not_ready');
    }
    if (pool !== null && personalResource === null
      && liveMapGeneratedResourceSuppressed(ctx, pool.spaceId, pool.id)) {
      throw new SenderError('target_not_ready');
    }
    requireWorldModificationAuthorized(ctx, position);
    if (pool !== null) {
      const result = resourceHarvestResult(
        position.x, position.y, selected.itemKind, pool, toolDefinition, registry,
      );
      if (result === 'depleted') throw new SenderError('resource_depleted');
      if (result === 'out_of_range') throw new SenderError('target_out_of_range');
      if (result !== 'ok') throw new SenderError('wrong_tool');
    }
    if (!mutate) return;
    spendToolVigour(ctx, ctx.sender, selected.itemKind, clock.authorityTick, pool === null);
    const facing = directionFromAim(
      targetTileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      targetTileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );
    ctx.db.fishing_cast.insert({
      identity: ctx.sender,
      poolId,
      startedTick: clock.authorityTick,
      targetTileX,
      targetTileY,
    });
    ctx.db.player_position.identity.update({
      ...position,
      facing: facing ?? position.facing,
      actionKind: runtimeItemAvatarAction(registry, selected.itemKind) ?? 'fish_cast',
      actionStartedTick: clock.authorityTick,
      equippedKind: selected.itemKind,
      equippedLit: true,
    });
    if (pool === null) {
      recordPlayerStatistic(ctx, ctx.sender, 'tool_whiffs', 1n, clock.authorityTick, selected.itemKind);
    }
}

function applyFishingReelLifecycle(ctx: WorldReducerContext, mutate = true): void {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const cast = ctx.db.fishing_cast.identity.find(ctx.sender);
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const survival = ctx.db.player_survival.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
  const selected = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
  const registry = contentRegistry(ctx);
  if (selected === null || selected.quantity < 1
    || runtimeToolSpecialization(registry, selected.itemKind) !== 'fishing') {
    throw new SenderError('wrong_tool');
  }
  const toolDefinition = runtimeToolDefinition(registry, selected.itemKind);
  if (toolDefinition === null) throw new SenderError('wrong_tool');
  requireUsableTool(ctx, selected);
  if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
  if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
  // Multiple connected clients can observe the same completed cast and reel
  // concurrently. Once its row is gone, completion has no remaining effects.
  // Keep authorization and tool checks above this idempotent terminal state.
  if (cast === null) return;
  if (clock.authorityTick - cast.startedTick < FISHING_CAST_TICKS) {
    throw new SenderError('fishing_too_soon');
  }
  if (!mutate) return;
  const personalResource = activePersonalQuestResource(ctx, ctx.sender, cast.poolId);
  if (personalResource !== null) {
    const personalPool = {
      kind: personalResource.resourceKind,
      tileX: personalResource.tileX,
      tileY: personalResource.tileY,
      depleted: personalResource.remaining <= 0,
    };
    if (position.spaceId !== personalResource.spaceId
      || personalResource.remaining <= 0
      || resourceHarvestResult(
        position.x, position.y, selected.itemKind, personalPool, toolDefinition, registry,
      ) !== 'ok') {
      cancelFishingCastFor(ctx, ctx.sender, clock.authorityTick);
      return;
    }
    ctx.db.fishing_cast.identity.delete(ctx.sender);
    if (!insertPlayerCarriedItem(ctx, personalResource.itemKind, 1)) {
      dropWorldItemStack(ctx, {
        itemKind: personalResource.itemKind, quantity: 1, x: position.x, y: position.y,
        droppedAtTick: clock.authorityTick, durability: 0, spaceId: position.spaceId,
        reservedFor: ctx.sender,
        reservedUntilTick: clock.authorityTick + MINING_DROP_RESERVATION_TICKS,
      });
    }
    recordPlayerStatistic(ctx, ctx.sender, 'items_obtained', 1n, clock.authorityTick, personalResource.itemKind);
    // Personal quest-resource catches are fixed at one item so their remaining
    // count stays identical to quest progress and bonus rolls cannot skip steps.
    recordPlayerStatistic(
      ctx, ctx.sender, personalResource.statisticKind, 1n,
      clock.authorityTick, personalResource.subjectKind,
    );
    recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, selected.itemKind);
    wearInventoryTool(ctx, selected);
    grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'fish_catch'));
    ctx.db.player_position.identity.update({
      ...position,
      actionKind: 'fish_reel',
      actionStartedTick: clock.authorityTick,
      equippedKind: selected.itemKind,
      equippedLit: true,
    });
    return;
  }
  const pool = ctx.db.world_resource.id.find(cast.poolId);
  const poolDefinition = pool === null ? null : runtimeResourceDefinition(registry, pool);
  if (pool === null || poolDefinition?.interaction.mode !== 'fish' || pool.spaceId !== position.spaceId
    || pool.tileX !== cast.targetTileX || pool.tileY !== cast.targetTileY
    || pool.depleted || pool.richness === 0
    || liveMapGeneratedResourceSuppressed(ctx, pool.spaceId, pool.id)) {
    cancelFishingCastFor(ctx, ctx.sender, clock.authorityTick);
    return;
  }
  const reach = resourceHarvestResult(
    position.x, position.y, selected.itemKind, pool, toolDefinition, registry,
  );
  if (reach !== 'ok') {
    cancelFishingCastFor(ctx, ctx.sender, clock.authorityTick);
    return;
  }

  const stats = ensurePlayerStats(ctx, ctx.sender, clock.authorityTick);
  const modifiers = activePlayerModifiers(ctx, ctx.sender, clock.authorityTick);
  const characterBalance = activeCharacterCombatBalance(ctx);
  const resolvedStats = resolveStatsWithProfile(
    characterBalance,
    { str: stats.str, dex: stats.dex, con: stats.con, int: stats.int, wis: stats.wis, cha: stats.cha },
    modifiers,
  );
  const worldSeed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
  const catchResult = resolveFishingLoot(contentRegistry(ctx).loots, [
    worldSeed,
    ctx.sender.toHexString(),
    pool.id,
    pool.richness,
    'fishing.catch',
  ], resolvedStats.attributes.dex, pool.richness, modifiers, poolDefinition.loot, characterBalance);
  const fishCaught = runtimeTaggedLootTotals(registry, catchResult.drops, 'food.fish');
  if (fishCaught === null) throw new SenderError('loot_item_definition_missing');
  ctx.db.fishing_cast.identity.delete(ctx.sender);
  applyLootDropsBehaviour(ctx, catchResult.drops, {
    x: position.x,
    y: position.y,
    spaceId: position.spaceId,
    authorityTick: clock.authorityTick,
    recipient: ctx.sender,
    inventoryFirst: true,
    reservedUntilTick: clock.authorityTick + MINING_DROP_RESERVATION_TICKS,
    recordItemsObtained: true,
  }, lootAuthorityDependencies);
  for (const fish of fishCaught) recordPlayerStatistic(
    ctx, ctx.sender, 'fish_caught', BigInt(fish.quantity), clock.authorityTick, fish.subjectKind,
  );
  recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, selected.itemKind);
  wearInventoryTool(ctx, selected);

  const richness = pool.richness - 1;
  const depleted = richness === 0;
  ctx.db.world_resource.id.update({
    ...pool,
    richness,
    health: richness,
    depleted,
    respawnAtTick: depleted
      ? clock.authorityTick + fishingRespawnDelayTicks([
        worldSeed, pool.id, pool.activationOrdinal + 1,
      ])
      : 0n,
  });
  grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'fish_catch'));
  if (depleted) {
    grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'fish_depletion'));
    recordPlayerStatistic(ctx, ctx.sender, 'resources_depleted', 1n, clock.authorityTick, pool.kind);
  }
  ctx.db.player_position.identity.update({
    ...position,
    actionKind: 'fish_reel',
    actionStartedTick: clock.authorityTick,
    equippedKind: selected.itemKind,
    equippedLit: true,
  });
}

function authorityBowChargeMs(
  startedTick: bigint,
  authorityTick: bigint,
  requestedChargeMs: number,
): number {
  const elapsedTicks = authorityTick > startedTick
    ? authorityTick - startedTick
    : 0n;
  const elapsedMs = Math.floor(Number(elapsedTicks) * 1_000 / AUTHORITY_HZ);
  return Math.min(BOW_MAX_CHARGE_MS, requestedChargeMs, elapsedMs);
}

/** Registers the authority timestamp that bounds both eventual range and
 * Vigour cost. The client duration is only a lower cap, so it can request a
 * cheaper shorter shot but can never fabricate extra charge. */
function applyBowBeginLifecycle(ctx: WorldReducerContext, mutate = true): void {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const survival = ctx.db.player_survival.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
  requireCombatActionReady(ctx, ctx.sender, clock.authorityTick);
  if (handsOccupiedFor(ctx, ctx.sender)) {
    throw new SenderError('hands_occupied');
  }
  const selected = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
  const registry = contentRegistry(ctx);
  const ranged = selected === null
    ? null
    : runtimeRangedWeaponDefinition(registry, selected.itemKind);
  if (selected === null || selected.quantity < 1 || ranged === null) {
    throw new SenderError('wrong_tool');
  }
  if (runtimeWeaponBaseDamageCenti(registry, selected.itemKind, 'ranged') === null) {
    throw new SenderError('weapon_damage_not_authored');
  }
  requireUsableTool(ctx, selected);
  const hasArrow = [...ctx.db.inventory_slot.by_identity.filter(ctx.sender)]
    .some((row) => row.itemKind === ranged.ammunitionItemKind && row.quantity > 0);
  if (!hasArrow && rogueRunForIdentity(ctx, ctx.sender) === null) throw new SenderError('out_of_arrows');
  const vigour = runtimeVigourDefinition(registry, selected.itemKind);
  if (vigour === null) throw new SenderError('tool_vigour_not_authored');
  // Settle all regeneration before draw starts; release/cancel then suppresses
  // regeneration across exactly the charging interval.
  const stats = mutate
    ? advancePlayerStats(ctx, ctx.sender, clock.authorityTick)
    : previewPlayerStats(ctx, ctx.sender, clock.authorityTick);
  const modifiers = activePlayerModifiers(ctx, ctx.sender, clock.authorityTick);
  const characterBalance = activeCharacterCombatBalance(ctx);
  const minimumCost = resolveModifierTarget(
    'toolVigourCost', bowChargeVigourCostCenti(0, vigour.costCenti), modifiers, characterBalance,
  );
  const minimumInterval = Math.max(
    1,
    resolveModifierTarget(
      'swingSpeed', vigour.minimumSwingTicks, modifiers, characterBalance,
    ),
  );
  const readiness = toolSpendResult(
    stats.vigourCenti,
    stats.lastSwingTick,
    clock.authorityTick,
    minimumCost,
    minimumInterval,
    false,
  );
  if (!readiness.ok) throw new SenderError(readiness.code);
  const existingCharge = ctx.db.bow_charge.identity.find(ctx.sender);
  if (existingCharge !== null) throw new SenderError('bow_already_charging');
  if (!mutate) return;
  ctx.db.bow_charge.insert({
    identity: ctx.sender,
    startedTick: clock.authorityTick,
    itemKind: selected.itemKind,
    fullChargeCostCenti: resolveModifierTarget(
      'toolVigourCost', vigour.costCenti, modifiers, characterBalance,
    ),
    minimumSwingTicks: minimumInterval,
  });
  advancePlayerStats(ctx, ctx.sender, clock.authorityTick);
  ctx.db.player_position.identity.update({
    ...position,
    actionKind: ranged.avatarAction,
    actionStartedTick: clock.authorityTick,
    equippedKind: selected.itemKind,
    equippedLit: true,
  });
}

function applyBowCancelLifecycle(
  ctx: WorldReducerContext,
  _chargeMs: number,
  mutate = true,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    const charge = ctx.db.bow_charge.identity.find(ctx.sender);
    if (charge === null) throw new SenderError('bow_not_charged');
    const selected = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    if (selected === null || selected.itemKind !== charge.itemKind
      || runtimeRangedWeaponDefinition(contentRegistry(ctx), selected.itemKind) === null) {
      throw new SenderError('wrong_tool');
    }
    const vigour = runtimeVigourDefinition(contentRegistry(ctx), selected.itemKind);
    if (vigour === null) throw new SenderError('tool_vigour_not_authored');
    // Client duration may shorten a shot, but never the cost of cancelling a
    // held draw. Cancellation remains possible after Vigour is exhausted.
    if (!mutate) return;
    clearBowCharge(ctx, ctx.sender);
    ctx.db.player_position.identity.update({
      ...position,
      actionKind: 'none',
      actionStartedTick: clock.authorityTick,
    });
    updateEquippedForIdentity(ctx, ctx.sender);
}

function applyBowFireLifecycle(
  ctx: WorldReducerContext,
  aimX: number,
  aimY: number,
  chargeMs: number,
  mutate = true,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (handsOccupiedFor(ctx, ctx.sender)) {
      throw new SenderError('hands_occupied');
    }
    const mount = mountedNpcFor(ctx, ctx.sender);
    const selected = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    const registry = contentRegistry(ctx);
    const ranged = selected === null
      ? null
      : runtimeRangedWeaponDefinition(registry, selected.itemKind);
    if (selected === null || selected.quantity < 1 || ranged === null) {
      throw new SenderError('wrong_tool');
    }
    if (runtimeWeaponBaseDamageCenti(registry, selected.itemKind, 'ranged') === null) {
      throw new SenderError('weapon_damage_not_authored');
    }
    requireUsableTool(ctx, selected);
    const rogueRun = rogueRunForIdentity(ctx, ctx.sender);
    const arrow = [...ctx.db.inventory_slot.by_identity.filter(ctx.sender)]
      .filter((row) => row.itemKind === ranged.ammunitionItemKind && row.quantity > 0)
      .sort((left, right) => left.slot - right.slot)[0];
    if (arrow === undefined && rogueRun === null) throw new SenderError('out_of_arrows');
    const charge = ctx.db.bow_charge.identity.find(ctx.sender);
    if (charge === null || charge.itemKind !== selected.itemKind) throw new SenderError('bow_not_charged');
    const vigour = runtimeVigourDefinition(registry, selected.itemKind);
    if (vigour === null) throw new SenderError('tool_vigour_not_authored');
    const authoritativeChargeMs = authorityBowChargeMs(charge.startedTick, clock.authorityTick, chargeMs);
    const chargedRangePixels = bowChargedRangePixels(
      authoritativeChargeMs, BOW_MAX_TARGET_RANGE_PIXELS,
    );
    const aim = normalizedBowAim(aimX, aimY);
    const shot = bowShotForTarget(aimX, aimY, chargedRangePixels);
    const facing = directionFromAim(aimX, aimY);
    if (aim === null || shot === null || facing === null) throw new SenderError('invalid_aim');
    if (!mutate) {
      validateToolVigourSpend(
        ctx, ctx.sender, selected.itemKind, clock.authorityTick, false,
        bowChargeVigourCostCenti(authoritativeChargeMs, vigour.costCenti), true,
      );
      return;
    }
    spendToolVigour(
      ctx,
      ctx.sender,
      selected.itemKind,
      clock.authorityTick,
      false,
      bowChargeVigourCostCenti(authoritativeChargeMs, vigour.costCenti),
      true,
    );
    const launchStats=advancePlayerStats(ctx,ctx.sender,clock.authorityTick);
    const launchModifiers=activePlayerModifiers(ctx,ctx.sender,clock.authorityTick,selected.itemKind);
    const characterBalance=activeCharacterCombatBalance(ctx);
    const launchAttributes=resolveStatsWithProfile(characterBalance,{str:launchStats.str,dex:launchStats.dex,con:launchStats.con,
      int:launchStats.int,wis:launchStats.wis,cha:launchStats.cha},launchModifiers).attributes;
    clearBowCharge(ctx, ctx.sender, true);
    if (rogueRun === null) {
      wearInventoryTool(ctx, selected);
      ctx.db.inventory_slot.id.update({
        ...arrow!,
        itemKind: arrow!.quantity === 1 ? 'empty' : ranged.ammunitionItemKind,
        quantity: arrow!.quantity - 1,
      });
    }
    const origin = bowProjectileOrigin(position, aim, mount !== undefined);
    const { x, y } = origin;
    const projectile = ctx.db.world_projectile.insert({
      id: 0n,
      owner: ctx.sender,
      x,
      y,
      velocityX: shot.velocityX,
      velocityY: shot.velocityY,
      chunkX: chunkAt(x),
      chunkY: chunkAt(y),
      spawnedTick: clock.authorityTick,
      // The projectile is stepped on ticks after spawn. The extra tick lets it
      // complete exactly `lifetimeTicks` moves before becoming a ground item.
      expiresTick: clock.authorityTick + BigInt(shot.lifetimeTicks) + 1n,
      state: 'flying',
      hitKind: '',
      hitId: '',
      spaceId: position.spaceId,
      weaponItemKind: selected.itemKind,
      ammunitionItemKind: ranged.ammunitionItemKind,
      projectileKind: ranged.projectileKind,
    });
    const launchDamage=resolveCombatDamageWithProfile(characterBalance,{
      attackKind:'ranged',weaponBaseCenti:runtimeWeaponBaseDamageCenti(registry,selected.itemKind,'ranged')!,
      scalingAttribute:launchAttributes.dex,armorCenti:0,armorPctBasisPoints:0,
      seedParts:[ctx.db.world_seed.id.find(0)?.seed??SURVIVAL_WORLD_SEED,ctx.sender.toHexString(),clock.authorityTick,projectile.id,selected.itemKind],
      attackerModifiers:launchModifiers,
    });
    ctx.db.projectile_charge.insert({
      projectileId: projectile.id, chargeMs: authoritativeChargeMs,
      damageCenti:bowChargeScaledDamageCenti(launchDamage.damageCenti,authoritativeChargeMs),critical:launchDamage.critical,
    });
    ctx.db.player_position.identity.update({
      ...position,
      facing,
      actionKind: ranged.avatarAction,
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
      equippedKind: selected.itemKind,
      equippedLit: true,
    });
    updateEquippedForIdentity(ctx, ctx.sender);
    if (rogueRun === null) {
      recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, selected.itemKind);
      recordPlayerStatistic(ctx, ctx.sender, 'arrows_fired', 1n, clock.authorityTick);
    }
}

export const decayEmptyTopsideSoil = spacetimedb.reducer(
  { onSchedule: soil_decay_timer },
  { scheduledMessage: soil_decay_timer.rowType },
  (ctx, { scheduledMessage }) => {
    if (!ctx.sender.isEqual(ctx.databaseIdentity)) throw new SenderError('scheduled_reducer_only');
    const soil = ctx.db.world_soil.id.find(scheduledMessage.soilId);
    const clock = ctx.db.world_clock.id.find(0);
    if (soil === null || clock === null || soil.spaceId !== TOPSIDE_SPACE_ID) return;
    const expectedDecayAtTick = emptySoilDecayAtTick(soil.tilledAtTick, soil.wateredAtTick);
    if (expectedDecayAtTick !== scheduledMessage.expectedDecayAtTick) return;
    const cropOccupiesTile = ctx.db.world_crop.id.find(soil.id) !== null;
    if (!emptySoilDecayDue(clock.authorityTick, expectedDecayAtTick, cropOccupiesTile)) {
      // Wall-clock scheduling can wake just ahead of the authority tick after
      // stalls. Planted tiles wait for harvest, which creates a fresh timer.
      if (!cropOccupiesTile && clock.authorityTick < expectedDecayAtTick) {
        scheduleEmptyTopsideSoilDecay(ctx, soil, clock.authorityTick);
      }
      return;
    }
    ctx.db.world_soil.id.delete(soil.id);
  },
);

type FarmToolLifecycleAction = 'use' | 'restore';

/**
 * Preflights the authored farm-tool capability without exposing database rows
 * to authored code or performing a prefix of durable writes. The mutation
 * functions below repeat these checks inside the same reducer transaction and
 * retain the legacy mechanics verbatim.
 */
function validateFarmToolLifecycleAction(
  ctx: WorldReducerContext,
  action: FarmToolLifecycleAction,
  tileX: number,
  tileY: number,
): void {
  requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const position = ctx.db.player_position.identity.find(ctx.sender);
  const survival = ctx.db.player_survival.identity.find(ctx.sender);
  const clock = ctx.db.world_clock.id.find(0);
  if (position === null || survival === null || clock === null) {
    throw new SenderError('player_not_ready');
  }
  if (!mutableFarmTileAuthorized(ctx, position, tileX, tileY)) {
    throw new SenderError('homestead_owner_required');
  }
  if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
  const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
  const selectedItem = slot?.itemKind ?? 'empty';
  const registry = contentRegistry(ctx);
  const farmToolDefinition = runtimeToolDefinition(registry, selectedItem);
  const farmMode = runtimeItemHasTag(registry, selectedItem, 'tool.farming.cultivate')
    ? 'cultivate'
    : runtimeItemHasTag(registry, selectedItem, 'tool.farming.water') ? 'water' : null;
  const id = worldSoilId(position.spaceId, tileX, tileY);
  const soil = ctx.db.world_soil.id.find(id);
  const cropRow = ctx.db.world_crop.id.find(id);

  if (action === 'restore') {
    if (cropRow !== null) throw new SenderError('crop_occupies_tile');
    const result = farmSoilRestoreResult(
      position.x, position.y, selectedItem, tileX, tileY, soil, farmToolDefinition, farmMode,
    );
    if (result !== 'ok') throw new SenderError(result);
    requireUsableTool(ctx, slot);
    if (!isVitalsToolKind(ctx, selectedItem)) throw new SenderError('wrong_tool');
    return;
  }

  const seed = ctx.db.world_seed.id.find(0);
  if (seed === null) throw new SenderError('player_not_ready');
  const actionKind = runtimeItemAvatarAction(registry, selectedItem);
  if (farmMode === null || actionKind === null) throw new SenderError('wrong_tool');
  requireUsableTool(ctx, slot);
  if (!isVitalsToolKind(ctx, selectedItem)) throw new SenderError('wrong_tool');
  const uprootingCrop = farmMode === 'cultivate' && soil !== null && cropRow !== null;
  const farmCollision = collisionForSpace(ctx, position.spaceId);
  const occupied = tilePlacementResult(
    position.x,
    position.y,
    tileX,
    tileY,
    farmCollision,
    tileOverlapsAnyPlayer(ctx, position.spaceId, tileX, tileY),
  ) === 'tile_blocked';
  const result = uprootingCrop
    ? farmSoilRestoreResult(position.x, position.y, selectedItem, tileX, tileY, soil, farmToolDefinition, farmMode)
    : farmToolUseResult(
      seed.seed,
      position.x,
      position.y,
      selectedItem,
      tileX,
      tileY,
      soil === null ? null : {
        watered: soil.watered && clock.authorityTick < soil.wateredAtTick + CROP_WATERING_TICKS * BigInt(4 + Math.min(3, farmingSkillEffects(registry,
            playerSkillRanks(ctx, homesteadForSpace(ctx, position.spaceId)?.owner ?? ctx.sender)).tenderHand)) / 4n,
      },
      occupied,
      farmToolDefinition,
      position.spaceId === TOPSIDE_SPACE_ID ? undefined : true,
      farmMode,
    );
  if (result !== 'ok') throw new SenderError(result);
  if (uprootingCrop && cropRow !== null && !cropRow.owner.isEqual(ctx.sender)) {
    throw new SenderError('owner_only_crop_uproot');
  }
}

function applyFarmToolLifecycleAction(
  ctx: WorldReducerContext,
  action: FarmToolLifecycleAction,
  tileX: number,
  tileY: number,
): void {
  validateFarmToolLifecycleAction(ctx, action, tileX, tileY);
  if (action === 'restore') applyFarmTileRestore(ctx, tileX, tileY);
  else applyFarmToolUse(ctx, tileX, tileY);
}

function applyFarmToolUse(
  ctx: WorldReducerContext,
  tileX: number,
  tileY: number,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    const seed = ctx.db.world_seed.id.find(0);
    if (position === null || survival === null || clock === null || seed === null) {
      throw new SenderError('player_not_ready');
    }
    if (!mutableFarmTileAuthorized(ctx, position, tileX, tileY)) {
      throw new SenderError('homestead_owner_required');
    }
    if (mountedNpcFor(ctx, ctx.sender) !== null) {
      throw new SenderError('mounted_action_forbidden');
    }
    const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    const selectedItem = slot?.itemKind ?? 'empty';
    const registry = contentRegistry(ctx);
    const farmToolDefinition = runtimeToolDefinition(registry, selectedItem);
    const actionKind = runtimeItemAvatarAction(registry, selectedItem);
    const farmMode = runtimeItemHasTag(registry, selectedItem, 'tool.farming.cultivate')
      ? 'cultivate'
      : runtimeItemHasTag(registry, selectedItem, 'tool.farming.water') ? 'water' : null;
    if (farmMode === null || actionKind === null) throw new SenderError('wrong_tool');
    requireUsableTool(ctx, slot);
    if (!isVitalsToolKind(ctx, selectedItem)) throw new SenderError('wrong_tool');
    const id = worldSoilId(position.spaceId, tileX, tileY);
    const soil = ctx.db.world_soil.id.find(id);
    const cropRow = ctx.db.world_crop.id.find(id);
    const uprootingCrop = farmMode === 'cultivate' && soil !== null && cropRow !== null;
    const farmCollision = collisionForSpace(ctx, position.spaceId);
    const occupied = tilePlacementResult(
      position.x,
      position.y,
      tileX,
      tileY,
      farmCollision,
      tileOverlapsAnyPlayer(ctx, position.spaceId, tileX, tileY),
    ) === 'tile_blocked';
    const result = uprootingCrop
      ? farmSoilRestoreResult(position.x, position.y, selectedItem, tileX, tileY, soil, farmToolDefinition, farmMode)
      : farmToolUseResult(
        seed.seed,
        position.x,
        position.y,
        selectedItem,
        tileX,
        tileY,
        soil === null ? null : {
          watered: soil.watered && clock.authorityTick < soil.wateredAtTick + CROP_WATERING_TICKS * BigInt(4 + Math.min(3, farmingSkillEffects(registry,
            playerSkillRanks(ctx, homesteadForSpace(ctx, position.spaceId)?.owner ?? ctx.sender)).tenderHand)) / 4n,
        },
        occupied,
        farmToolDefinition,
        position.spaceId === TOPSIDE_SPACE_ID ? undefined : true,
        farmMode,
      );
    if (result !== 'ok') throw new SenderError(result);
    if (uprootingCrop && cropRow !== null && !cropRow.owner.isEqual(ctx.sender)) {
      throw new SenderError('owner_only_crop_uproot');
    }
    const tillDropsOutput = farmMode === 'cultivate' && !uprootingCrop && fiberDropsFromTilling(
      seed.seed, position.spaceId, tileX, tileY, clock.authorityTick,
      activeWorldPolicyBalance(ctx).fiberTillDropPercent,
    );
    const tillOutputKind = tillDropsOutput
      ? runtimeItemKindForUniqueTag(registry, SOIL_TILL_OUTPUT_ITEM_TAG)
      : null;
    if (tillDropsOutput && tillOutputKind === null) throw new SenderError('ambient_output_content_missing');
    spendToolVigour(ctx, ctx.sender, selectedItem, clock.authorityTick, false);
    const toolFacing = directionFromAim(
      tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );

    if (farmMode === 'cultivate') {
      if (uprootingCrop && cropRow !== null && soil !== null) {
        ctx.db.world_crop.id.delete(cropRow.id);
        const refreshedSoil = ctx.db.world_soil.id.update({
          ...soil,
          tilledAtTick: clock.authorityTick,
        });
        scheduleEmptyTopsideSoilDecay(ctx, refreshedSoil, clock.authorityTick);
      } else {
        const insertedSoil = ctx.db.world_soil.insert({
          id,
          tileX,
          tileY,
          chunkX: Math.floor(tileX / SURVIVAL_CHUNK_TILES),
          chunkY: Math.floor(tileY / SURVIVAL_CHUNK_TILES),
          watered: false,
          tilledAtTick: clock.authorityTick,
          wateredAtTick: 0n,
          spaceId: position.spaceId,
        });
        scheduleEmptyTopsideSoilDecay(ctx, insertedSoil, clock.authorityTick);
        if (tillDropsOutput) {
          if (!insertPlayerCarriedItem(ctx, tillOutputKind!, 1)) {
            const x = tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
            const y = tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
            dropWorldItemStack(ctx, {
              itemKind: tillOutputKind!,
              quantity: 1,
              x,
              y,
              droppedAtTick: clock.authorityTick,
              durability: 0,
              spaceId: position.spaceId,
            });
          }
          recordPlayerStatistic(ctx, ctx.sender, 'items_obtained', 1n, clock.authorityTick, tillOutputKind!);
        }
      }
    } else if (soil !== null) {
      const definition = cropRow === null
        ? null
        : cropDefinitionForHomestead(ctx, position.spaceId, cropRow.cropKind);
      if (cropRow !== null && definition !== null) {
        const settled = cropGrowthAt(
          definition,
          cropRow.growthTicks,
          cropRow.growthUpdatedAtTick,
          soil.wateredAtTick,
          clock.authorityTick,
          soil.watered,
          cropAutomaticallyWatered(ctx, position.spaceId, cropRow.tileX, cropRow.tileY),
          cropCalendarOffset(ctx),
          cropGreenhouseProtected(ctx, position.spaceId),
        );
        ctx.db.world_crop.id.update({
          ...cropRow,
          growthTicks: settled.growthTicks,
          growthUpdatedAtTick: clock.authorityTick,
        });
      }
      const wateredSoil = ctx.db.world_soil.id.update({
        ...soil,
        watered: true,
        wateredAtTick: clock.authorityTick,
      });
      scheduleEmptyTopsideSoilDecay(ctx, wateredSoil, clock.authorityTick);
      if (cropRow !== null) {
        for (const quest of ctx.db.player_quest.by_identity.filter(ctx.sender)) {
          if (quest.state !== 'active') continue;
          const definition = runtimeQuestDefinition(contentRegistry(ctx), quest.questId);
          const triggers = definition?.world?.narrativeTriggers?.filter((trigger) => (
            trigger.event === 'water_crop' && trigger.subjectKind === cropRow.cropKind
          )) ?? [];
          for (const trigger of triggers) {
            const flagId = JSON.stringify([ctx.sender.toHexString(), trigger.id]);
            if (ctx.db.player_quest_flag.id.find(flagId) !== null) continue;
            ctx.db.player_quest_flag.insert({ id: flagId, identity: ctx.sender, flag: trigger.id });
            const thought = {
              identity: ctx.sender,
              body: trigger.body,
              tone: trigger.tone,
              issuedTick: clock.authorityTick,
              expiresTick: clock.authorityTick + BigInt(trigger.durationTicks),
            };
            if (ctx.db.player_thought.identity.find(ctx.sender) === null) ctx.db.player_thought.insert(thought);
            else ctx.db.player_thought.identity.update(thought);
          }
        }
      }
    }
    ctx.db.player_position.identity.update({
      ...position,
      facing: toolFacing ?? position.facing,
      actionKind,
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    wearInventoryTool(ctx, slot);
    recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, selectedItem);
    if (uprootingCrop && cropRow !== null) {
      recordPlayerStatistic(ctx, ctx.sender, 'crops_uprooted', 1n, clock.authorityTick, cropRow.cropKind);
    } else {
      recordPlayerStatistic(
        ctx,
        ctx.sender,
        farmMode === 'cultivate' ? 'farm_tiles_tilled' : 'farm_tiles_watered',
        1n,
        clock.authorityTick,
      );
      grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), farmMode === 'cultivate' ? 'cultivate' : 'water'));
    }
}

function applyFarmTileRestore(
  ctx: WorldReducerContext,
  tileX: number,
  tileY: number,
): void {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (!mutableFarmTileAuthorized(ctx, position, tileX, tileY)) {
      throw new SenderError('homestead_owner_required');
    }
    if (mountedNpcFor(ctx, ctx.sender) !== null) {
      throw new SenderError('mounted_action_forbidden');
    }
    const slot = ctx.db.inventory_slot.id.find(`${ctx.sender.toHexString()}:${survival.selectedSlot}`);
    const selectedItem = slot?.itemKind ?? 'empty';
    const registry = contentRegistry(ctx);
    const farmToolDefinition = runtimeToolDefinition(registry, selectedItem);
    const farmMode = runtimeItemHasTag(registry, selectedItem, 'tool.farming.cultivate')
      ? 'cultivate'
      : runtimeItemHasTag(registry, selectedItem, 'tool.farming.water') ? 'water' : null;
    const actionKind = runtimeItemAvatarAction(registry, selectedItem);
    const id = worldSoilId(position.spaceId, tileX, tileY);
    const soil = ctx.db.world_soil.id.find(id);
    if (ctx.db.world_crop.id.find(id) !== null) throw new SenderError('crop_occupies_tile');
    const result = farmSoilRestoreResult(
      position.x, position.y, selectedItem, tileX, tileY, soil, farmToolDefinition, farmMode,
    );
    if (result !== 'ok') throw new SenderError(result);
    if (actionKind === null) throw new SenderError('wrong_tool');
    requireUsableTool(ctx, slot);
    if (!isVitalsToolKind(ctx, selectedItem)) throw new SenderError('wrong_tool');
    spendToolVigour(ctx, ctx.sender, selectedItem, clock.authorityTick, false);
    const toolFacing = directionFromAim(
      tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.x,
      tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2 - position.y,
    );

    ctx.db.world_soil.id.delete(id);
    ctx.db.player_position.identity.update({
      ...position,
      facing: toolFacing ?? position.facing,
      actionKind,
      actionStartedTick: nextActionStartedTick(position.actionStartedTick, clock.authorityTick),
    });
    wearInventoryTool(ctx, slot);
    recordPlayerStatistic(ctx, ctx.sender, 'tool_uses', 1n, clock.authorityTick, selectedItem);
    recordPlayerStatistic(ctx, ctx.sender, 'farm_tiles_restored', 1n, clock.authorityTick);
}

/** Preflight only: elapsed growth is settled before the one-planting boost. */
function compostCropPlan(
  ctx: WorldReducerContext,
  position: PlayerPositionRow,
  selectedItem: string,
  tileX: number,
  tileY: number,
) {
  if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
  if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
  if (!mutableFarmTileAuthorized(ctx, position, tileX, tileY)) throw new SenderError('homestead_owner_required');
  if (!tileTargetWithinFixedReach(position.x, position.y, { tileX, tileY }, 3 * TILE_SIZE_FIXED)) {
    throw new SenderError('farm_tile_out_of_range');
  }
  if (!runtimeItemHasTag(contentRegistry(ctx), selectedItem, 'item.farming.compost')) {
    throw new SenderError('select_compost');
  }
  const clock = ctx.db.world_clock.id.find(0);
  if (clock === null) throw new SenderError('player_not_ready');
  const id = worldSoilId(position.spaceId, tileX, tileY);
  const soil = ctx.db.world_soil.id.find(id);
  if (soil === null) throw new SenderError('not_tilled');
  const crop = ctx.db.world_crop.id.find(id);
  if (crop === null) throw new SenderError('crop_not_found');
  if (homesteadForSpace(ctx, position.spaceId) === null && !crop.owner.isEqual(ctx.sender)) {
    throw new SenderError('owner_only_compost');
  }
  if (crop.composted) throw new SenderError('crop_already_composted');
  const definition = cropDefinitionForHomestead(ctx, position.spaceId, crop.cropKind);
  if (definition === null) throw new SenderError('unknown_crop_kind');
  const growth = cropGrowthAt(definition, crop.growthTicks, crop.growthUpdatedAtTick,
    soil.wateredAtTick, clock.authorityTick, soil.watered,
    cropAutomaticallyWatered(ctx, position.spaceId, tileX, tileY), cropCalendarOffset(ctx),
    cropGreenhouseProtected(ctx, position.spaceId));
  if (growth.mature) throw new SenderError('crop_already_mature');
  const advanced = growth.growthTicks + definition.growthTicks / 4n;
  return { ...crop, composted: true, growthUpdatedAtTick: clock.authorityTick,
    growthTicks: advanced > definition.growthTicks ? definition.growthTicks : advanced };
}

export const harvestCropTile = spacetimedb.reducer(
  { tileX: t.i16(), tileY: t.i16() },
  (ctx, { tileX, tileY }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const survival = ctx.db.player_survival.identity.find(ctx.sender);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || survival === null || clock === null) throw new SenderError('player_not_ready');
    if (!mutableFarmTileAuthorized(ctx, position, tileX, tileY)) {
      throw new SenderError('homestead_owner_required');
    }
    if (mountedNpcFor(ctx, ctx.sender) !== null) throw new SenderError('mounted_action_forbidden');
    if (!tileTargetWithinFixedReach(position.x, position.y, { tileX, tileY }, 3 * TILE_SIZE_FIXED)) {
      throw new SenderError('farm_tile_out_of_range');
    }
    const id = worldSoilId(position.spaceId, tileX, tileY);
    const soil = ctx.db.world_soil.id.find(id);
    if (soil === null) throw new SenderError('not_tilled');
    const existing = ctx.db.world_crop.id.find(id);
    if (existing === null) throw new SenderError('crop_not_found');

    const cropHome = homesteadForSpace(ctx, position.spaceId);
    if (cropHome === null && !existing.owner.isEqual(ctx.sender)) throw new SenderError('owner_only_harvest');
    const definition = cropDefinitionForHomestead(ctx, position.spaceId, existing.cropKind);
    if (definition === null) throw new SenderError('unknown_crop_kind');
    const growth = cropGrowthAt(
      definition,
      existing.growthTicks,
      existing.growthUpdatedAtTick,
      soil.wateredAtTick,
      clock.authorityTick,
      soil.watered,
      cropAutomaticallyWatered(ctx, position.spaceId, existing.tileX, existing.tileY),
      cropCalendarOffset(ctx),
      cropGreenhouseProtected(ctx, position.spaceId),
    );
    if (!growth.mature) throw new SenderError('crop_still_growing');
    const selectiveSeedsRank = homesteadUpgradeRank(ctx, position.spaceId, 'seed');
    const baseHarvestQuantity = selectiveSeedHarvestQuantity(
      definition.harvestQuantity,
      selectiveSeedsRank,
      Number((existing.plantedAtTick
        + BigInt(Math.abs(existing.tileX * 73_856_093 ^ existing.tileY * 19_349_663))) % 10n),
    );
    const skills = farmingSkillEffects(contentRegistry(ctx), playerSkillRanks(ctx, ctx.sender));
    const previousHarvest = [...ctx.db.player_statistic.by_identity.filter(ctx.sender)]
      .filter((row) => row.statisticKind === 'crops_harvested')
      .reduce<bigint | undefined>((last, row) => last === undefined || row.updatedTick > last ? row.updatedTick : last, undefined);
    const reward = farmingHarvestReward(baseHarvestQuantity, skills,
      Number(existing.plantedAtTick & 0xffff_ffffn) ^ Math.imul(existing.tileX, 73_856_093)
        ^ Math.imul(existing.tileY, 19_349_663), firstHarvestOfDay(clock.authorityTick, previousHarvest));
    const harvestQuantity = reward.quantity;
    const harvestRecipient = cropHome?.owner ?? ctx.sender;
    if (harvestRecipient.isEqual(ctx.sender)) {
      if (!insertPlayerCarriedItem(ctx, definition.harvestItemKind, harvestQuantity)) {
        throw new SenderError('inventory_full');
      }
    } else {
      insertEscrowStacksIntoInventory(ctx, harvestRecipient, [{
        id: `homestead-harvest:${existing.id}:${clock.authorityTick}`,
        itemKind: definition.harvestItemKind,
        quantity: harvestQuantity,
        durability: 0,
        lit: true,
      }], true);
    }
    if (reward.seeds > 0 && definition.tags?.includes('crop.quest') !== true) {
      if (harvestRecipient.isEqual(ctx.sender)) {
        if (!insertPlayerCarriedItem(ctx, definition.seedItemKind, reward.seeds)) throw new SenderError('inventory_full');
      } else {
        insertEscrowStacksIntoInventory(ctx, harvestRecipient, [{
          id: `homestead-seed:${existing.id}:${clock.authorityTick}`,
          itemKind: definition.seedItemKind, quantity: reward.seeds, durability: 0, lit: true,
        }], true);
      }
      recordPlayerStatistic(ctx, harvestRecipient, 'items_obtained', BigInt(reward.seeds), clock.authorityTick, definition.seedItemKind);
    }
    ctx.db.world_crop.id.delete(id);
    const refreshedSoil = ctx.db.world_soil.id.update({
      ...soil,
      // A harvest begins a fresh empty-soil grace period without pretending
      // the tile was watered and without changing its rendered wetness.
      tilledAtTick: clock.authorityTick,
    });
    scheduleEmptyTopsideSoilDecay(ctx, refreshedSoil, clock.authorityTick);
    recordPlayerStatistic(ctx, ctx.sender, 'crops_harvested', 1n, clock.authorityTick, definition.harvestItemKind);
    recordPlayerStatistic(
      ctx,
      harvestRecipient,
      'items_obtained',
      BigInt(harvestQuantity),
      clock.authorityTick,
      definition.harvestItemKind,
    );
    grantSkillExperience(ctx, ctx.sender, 'farming', runtimeActivityExperience(contentRegistry(ctx), 'crop_harvest', harvestQuantity));
  },
);

export const tendTree = spacetimedb.reducer(
  { treeId: t.u64() },
  (ctx, { treeId }) => {
    requireAuthorizedSender(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
    if (handsOccupiedFor(ctx, ctx.sender)) throw new SenderError('hands_occupied');
    const position = ctx.db.player_position.identity.find(ctx.sender);
    const tree = ctx.db.world_tree.id.find(treeId);
    const clock = ctx.db.world_clock.id.find(0);
    if (position === null || tree === null || clock === null) {
      throw new SenderError('target_not_ready');
    }
    if (mountedNpcFor(ctx, ctx.sender) !== null) {
      throw new SenderError('mounted_action_forbidden');
    }
    const result = canTendTree(
      position.x,
      position.y,
      tree.x,
      tree.y,
      tree.tendCount,
      tree.lastTendedTick,
      clock.authorityTick,
    );
    if (result === 'out_of_range') {
      throw new SenderError('target_out_of_range');
    }
    if (result === 'cooldown') {
      throw new SenderError('tree_recently_tended');
    }
    ctx.db.world_tree.id.update({
      ...tree,
      care: Math.min(100, tree.care + 1),
      tendCount: tree.tendCount + 1,
      lastTendedTick: clock.authorityTick,
    });
    recordPlayerStatistic(ctx, ctx.sender, 'orchard_trees_tended', 1n, clock.authorityTick);
  },
);

function runOneHertzTickMaintenance(
  ctx: WorldReducerContext,
  maintenanceAuthorityTick: bigint,
  updateCounters: ReturnType<typeof emptyTickUpdateCounters>,
): void {
  if (maintenanceAuthorityTick % BigInt(AUTHORITY_HZ) !== 0n) return;
  // Trade actions revalidate range synchronously; this cadence only expires
  // idle sessions and closes the UI after players move apart.
  for (const trade of ctx.db.player_trade_session.iter()) {
    recordTickRowScan(updateCounters, 'tradeRowsScanned');
    const requestExpired = trade.state === 'requested'
      && maintenanceAuthorityTick > trade.createdTick + PLAYER_TRADE_REQUEST_TTL_TICKS;
    if (requestExpired || !tradePlayersWithinReach(ctx, trade)) cancelPlayerTrade(ctx, trade);
  }
  // Connect-time recovery remains immediate. Owners whose last attempt
  // found no capacity sleep until writePlayerInventory clears the marker.
  const overflowOwners = new Map<string, WorldReducerContext['sender']>();
  for (const row of ctx.db.inventory_overflow.iter()) {
    recordTickRowScan(updateCounters, 'overflowRowsScanned');
    if (ctx.db.inventory_overflow_retry.identity.find(row.identity) !== null) continue;
    overflowOwners.set(row.identity.toHexString(), row.identity);
  }
  for (const identity of overflowOwners.values()) drainPlayerOverflow(ctx, identity);
}

function activePresenceLeases(ctx: WorldReducerContext): ConnectionPresenceRow[] {
  const presences: ConnectionPresenceRow[] = [];
  // The online index bounds the per-tick simulation root to connected players;
  // the identity index then resolves only those players' live transport leases.
  for (const profile of ctx.db.player_public.by_online.filter(true)) {
    presences.push(...ctx.db.connection_presence_v2.by_identity.filter(profile.identity));
  }
  return presences;
}

function expirePresenceLeases(
  ctx: WorldReducerContext,
  clock: WorldClockRow,
  presences: readonly ConnectionPresenceRow[],
): ConnectionPresenceRow[] {
  const active: ConnectionPresenceRow[] = [];
  for (const presence of presences) {
    if (!presenceLeaseExpired(
      presence.lastSeenAt.microsSinceUnixEpoch,
      ctx.timestamp.microsSinceUnixEpoch,
    )) {
      active.push(presence);
      continue;
    }
    ctx.db.connection_presence_v2.connectionId.delete(presence.connectionId);
    deleteSessionChatNoticesForConnection(ctx, presence.connectionId);
    const abandonedNotice = ctx.db.connection_notice.connectionId.find(presence.connectionId);
    if (abandonedNotice !== null) {
      const abandonedProfile = ctx.db.player_public.identity.find(presence.identity);
      ctx.db.connection_audit.insert({
        id: 0n,
        connectionId: presence.connectionId,
        identity: presence.identity,
        eventKind: 'lease_expired',
        displayName: abandonedProfile?.displayName ?? 'Unknown',
        occurredAt: ctx.timestamp,
        occurredAtMicros: ctx.timestamp.microsSinceUnixEpoch,
      });
      flushPlayerStatisticTime(ctx, presence.identity, clock.authorityTick, true);
      ctx.db.connection_notice.connectionId.delete(presence.connectionId);
    }
    const stillOnline = [
      ...ctx.db.connection_presence_v2.by_identity.filter(presence.identity),
    ].length > 0;
    if (stillOnline) continue;
    const profile = ctx.db.player_public.identity.find(presence.identity);
    if (profile !== null) {
      if (ctx.db.character_profile.identity.find(presence.identity)?.nameChosen === true) {
        broadcastSessionChatNotice(ctx, 'disconnect', worldDisconnectMessage(profile.displayName));
      }
      ctx.db.player_public.identity.update({ ...profile, online: false });
    }
    const input = ctx.db.player_input.identity.find(presence.identity);
    if (input !== null) ctx.db.player_input.identity.update({
      ...input,
      direction: 'idle',
      sprinting: false,
      settleDirection: 'idle',
      settleSteps: 0,
      settledSequence: input.sequence,
      pendingSequence: 0n,
      lastProcessedSequence: input.sequence,
    });
    ctx.db.player_jump_state.identity.delete(presence.identity);
    const position = ctx.db.player_position.identity.find(presence.identity);
    if (position !== null) {
      ctx.db.player_position.identity.update({
        ...position,
        moving: false,
        actionKind: 'none',
      });
    }
    for (const npc of ctx.db.world_npc.by_rider.filter(presence.identity)) {
      // Boats are persistent player vehicles. Keeping the rider link across
      // a presence lease expiry lets a reconnect restore the same offshore
      // mount instead of leaving the player stranded in water. Horses still
      // dismount normally so their ambient lifecycle can resume.
      if (runtimeNpcMount(contentRegistry(ctx), npc)?.adapter === 'boat') {
        updateWorldNpc(ctx, {
          ...npc,
          moving: false,
          wanderDirection: 'idle',
          authorityTick: clock.authorityTick,
        });
        continue;
      }
      updateWorldNpc(ctx, {
        ...npc,
        rider: undefined,
        moving: false,
        wanderDirection: 'idle',
        nextDecisionTick: clock.authorityTick + 20n,
      });
    }
  }
  return active;
}

export const stepWorld = spacetimedb.reducer(
  { onSchedule: movement_timer },
  { scheduledMessage: movement_timer.rowType },
  (ctx) => {
    if (!ctx.sender.isEqual(ctx.databaseIdentity)) throw new SenderError('scheduled_reducer_only');
    const clock = ctx.db.world_clock.id.find(0);
    if (clock === null) return;
    recordObjectEnvironment(ctx);
    const tickLifecycleHandlers = currentWorldBehaviourHandlers(ctx);
    const tickRegistrySnapshot = behaviourRegistrySnapshot(ctx);
    const telemetryTimingSample = (clock.authorityTick + 1n) % TICK_TELEMETRY_LOG_TICKS === 0n;
    tickStageTiming(telemetryTimingSample, 'tick');
    const updateCounters = emptyTickUpdateCounters();
    let obstacleCount = 0;
    const installedWorld = ctx.db.world_seed.id.find(0);
    if (installedWorld === null || installedWorld.version < SURVIVAL_WORLD_VERSION) {
      if (installedWorld !== null) migrateWorldForOceanExpansion(ctx, installedWorld.version);
      if (installedWorld !== null && installedWorld.version < 3) {
        ctx.db.crop_patch.clear();
        ctx.db.farm_parcel.clear();
      }
      reconcileGeneratedSurvivalResources(ctx);
      const nextWorld = {
        id: 0,
        seed: SURVIVAL_WORLD_SEED,
        version: SURVIVAL_WORLD_VERSION,
        mineVersion: installedWorld?.mineVersion ?? 0,
      };
      if (installedWorld === null) ctx.db.world_seed.insert(nextWorld);
      else ctx.db.world_seed.id.update(nextWorld);
    }
    ensureSoilDecayTimers(ctx, clock.authorityTick);
    ensureMiningMigration(ctx);
    // T10 one-shot migration; its marker makes the full scans unreachable after cutover.
    ensurePrivateStateMigration(ctx);
    // T11 one-shot migration; its marker removes compatibility scans after cutover.
    ensureLegacyFarmMigration(ctx);
    let environment = ctx.db.world_environment.id.find(0);
    if (environment === null) {
      environment = ctx.db.world_environment.insert({
        id: 0,
        calendarTick: clock.authorityTick,
        weatherMode: 'auto',
        cropCalendarOffset: 0n,
      });
    }
    // T6 additive cutover: migrate the legacy derived calendar value exactly
    // once, then leave calendarTick as a compatibility snapshot.
    const calendarOffset = environment.cropCalendarOffset
      ?? environment.calendarTick - clock.authorityTick;
    if (environment.cropCalendarOffset === undefined) {
      environment = ctx.db.world_environment.id.update({
        ...environment,
        cropCalendarOffset: calendarOffset,
      });
      recordTickRowTouch(updateCounters);
    }
    if (ctx.db.world_wind.id.find(0) === null) {
      ctx.db.world_wind.insert({ id: 0, direction: 'auto' });
    }
    const maintenanceAuthorityTick = clock.authorityTick + 1n;
    const oneHertzMaintenanceTick = maintenanceAuthorityTick % BigInt(AUTHORITY_HZ) === 0n;
    runOneHertzTickMaintenance(ctx, maintenanceAuthorityTick, updateCounters);
    const wildlifeRegistry = contentRegistry(ctx);
    const wildlifeGeneration = ctx.db.world_wildlife_generation.id.find(0);
    if (wildlifeGeneration === null || wildlifeGeneration.version < WILDLIFE_GENERATION_VERSION) {
      // Only this deterministic layer is replaced. Player identities, farms,
      // inventory, resources, and the authored starter horse are untouched.
      for (const profile of ctx.db.world_wildlife_profile.iter()) {
        if (profile.npcId >= BigInt(WILDLIFE_FIRST_NPC_ID)) {
          ctx.db.world_wildlife_profile.npcId.delete(profile.npcId);
        }
      }
      for (const npc of ctx.db.world_npc.iter()) {
        if (npc.id >= BigInt(WILDLIFE_FIRST_NPC_ID)) ctx.db.world_npc.id.delete(npc.id);
      }
      ctx.db.world_hive.clear();
      const starterHorse = runtimeStarterHorseDefinition(wildlifeRegistry);
      if (starterHorse !== null) ensureAuthoredNpcWildlifeProfile(ctx, starterHorse);
      ensureFarmerBobCows(ctx, clock.authorityTick);
      for (const animal of generateSurvivalWildlifeForRegistry(wildlifeRegistry)) {
        ctx.db.world_npc.insert(generatedWildlifeNpcRow(wildlifeRegistry, animal));
        ctx.db.world_wildlife_profile.insert(generatedWildlifeProfileRow(wildlifeRegistry, animal));
      }
      for (const hive of generateSurvivalWildlifeHivesForRegistry(wildlifeRegistry)) {
        ctx.db.world_hive.insert(generatedHiveRow(hive));
      }
      const nextGeneration = { id: 0, version: WILDLIFE_GENERATION_VERSION };
      if (wildlifeGeneration === null) ctx.db.world_wildlife_generation.insert(nextGeneration);
      else ctx.db.world_wildlife_generation.id.update(nextGeneration);
    }
    recoverLegacyDismountHorses(ctx, clock.authorityTick);
    // Additive health-column backfill runs once. The marker prevents future
    // combat-era zero-health NPCs from being mistaken for legacy rows.
    if (ctx.db.stats_migration.id.find(0) === null) {
      for (const npc of ctx.db.world_npc.iter()) {
        if (npc.health !== 0 || runtimeWildlifeDefinition(wildlifeRegistry, npc.kind) === null) continue;
        const stats = runtimeResolveCreatureStats(wildlifeRegistry, npc.kind);
        if (stats === null) continue;
        updateWorldNpc(ctx, {
          ...npc,
          health: Math.ceil(stats.maxHealthCenti / 100),
        });
      }
      ctx.db.stats_migration.insert({ id: 0, creatureHealthVersion: 1 });
    }

    const activePresences = expirePresenceLeases(ctx, clock, activePresenceLeases(ctx));
    const activePresenceCount = BigInt(activePresences.length);
    const authorityTick = clock.authorityTick + 1n;
    ctx.db.world_clock.id.update({ ...clock, authorityTick });
    const calendarTick = authorityTick + calendarOffset;
    if(authorityTick%20n===0n)settleTownStreetlamps(ctx,calendarTick);
    recordTickRowTouch(updateCounters);
    respawnMiningResources(ctx, authorityTick);
    if (authorityTick % BigInt(TREE_REGROWTH_SWEEP_TICKS) === 0n) {
      const weatherMode = isWeatherMode(environment.weatherMode) ? environment.weatherMode : 'auto';
      const raining = rainForWeatherMode(weatherMode, calendarTick);
      if (raining) waterCropsInTheRain(ctx, authorityTick, updateCounters);
      // Cadence: TREE_REGROWTH_SWEEP_TICKS. The index union bounds work to
      // active regrowth plus legacy depleted trees requiring a one-time reset.
      const regrowing = new Map<bigint, WorldResourceRow>();
      for (const resource of ctx.db.world_resource.by_depleted.filter(true)) {
        recordTickRowScan(updateCounters, 'regrowthRowsScanned');
        if (isAxeHarvestableResourceKind(resource.kind)
          && resource.regrowthProgress >= TREE_REGROWTH_PROGRESS_MAX) {
          regrowing.set(resource.id, resource);
        }
      }
      for (let progress = 0; progress < TREE_REGROWTH_PROGRESS_MAX; progress += 1) {
        for (const resource of ctx.db.world_resource.by_regrowth_progress.filter(progress)) {
          recordTickRowScan(updateCounters, 'regrowthRowsScanned');
          if (isAxeHarvestableResourceKind(resource.kind)) regrowing.set(resource.id, resource);
        }
      }
      for (const resource of regrowing.values()) {
        if (isAuthoredHearthResourceSiteId(contentRegistry(ctx), resource.id)) continue;
        const storedProgress = resource.depleted && resource.health === 0
          && resource.regrowthProgress >= TREE_REGROWTH_PROGRESS_MAX
          ? 0
          : resource.regrowthProgress;
        if (storedProgress >= TREE_REGROWTH_PROGRESS_MAX) continue;
        const progress = treeRegrowthProgressAtSweep(storedProgress, authorityTick, raining, Number(resource.id & 0xffffffffn));
        const nextStage = treeGrowthStageForProgress(progress);
        const stageChanged = nextStage !== null && nextStage !== resource.growthStage;
        const returnsToLife = nextStage !== null && resource.depleted;
        ctx.db.world_resource.id.update({
          ...resource,
          growthStage: nextStage ?? resource.growthStage,
          regrowthProgress: progress,
          health: stageChanged || returnsToLife
            ? treeHealthForGrowthStage(nextStage ?? resource.growthStage)
            : resource.health,
          depleted: nextStage === null ? resource.depleted : false,
        });
        recordTickRowTouch(updateCounters);
      }
    }
    const statisticSessions = new Map<string, WorldReducerContext['sender']>();
    for (const presence of activePresences) {
      if (ctx.db.connection_notice.connectionId.find(presence.connectionId) === null) continue;
      statisticSessions.set(presence.identity.toHexString(), presence.identity);
    }
    for (const identity of statisticSessions.values()) {
      if (authorityTick % BigInt(AUTHORITY_HZ) === 0n) {
        const position = ctx.db.player_position.identity.find(identity);
        if (position !== null) settleActiveObjectRegion(ctx, position);
      }
      flushPlayerStatisticTime(ctx, identity, authorityTick, false);
      // A one-hertz indexed re-derivation closes gaps from legacy inventory
      // reducer paths while keeping quest truth independent of client events.
      if (authorityTick % BigInt(AUTHORITY_HZ) === 0n) {
        refreshPlayerQuests(ctx, identity, authorityTick);
      }
    }
    tickStageTiming(telemetryTimingSample, 'expiry');
    if (oneHertzMaintenanceTick) {
      // Gameplay reads check expiry against authorityTick, so storage cleanup
      // can be coarse without extending an effect, invite, item, or speech.
      // Unknown/retired effect rows remain durable and inert across content
      // revisions so a rollback never loses their original IDs or tick data.
      const expiredThrough = new Range<bigint>(
        undefined,
        { tag: 'included', value: authorityTick },
      );
      const expiryRegistry = contentRegistry(ctx);
      for (const effect of ctx.db.player_effect.by_expires_tick.filter(expiredThrough)) {
        recordTickRowScan(updateCounters, 'effectRowsScanned');
        if (runtimeEffectDefinition(expiryRegistry, effect.effectKind) === null) continue;
        ctx.db.player_effect.id.delete(effect.id);
        recordTickRowTouch(updateCounters);
      }
      for (const invite of ctx.db.player_party_invite.by_expires_tick.filter(expiredThrough)) {
        recordTickRowScan(updateCounters, 'inviteRowsScanned');
        ctx.db.player_party_invite.id.delete(invite.id);
        recordTickRowTouch(updateCounters);
      }
      for (const item of ctx.db.world_item.by_expires_tick.filter(expiredThrough)) {
        recordTickRowScan(updateCounters, 'itemRowsScanned');
        if (item.expiresTick === 0n && !worldItemExpiredForRow(expiryRegistry, item, authorityTick)) {
          ctx.db.world_item.id.update({
            ...item,
            expiresTick: worldItemExpiryTick(
              expiryRegistry, item.itemKind, item.durability, item.droppedAtTick,
            ),
          });
          recordTickRowTouch(updateCounters);
          continue;
        }
        if (!worldItemExpiredForRow(expiryRegistry, item, authorityTick)) continue;
        raiseEntityDespawnEvent(ctx, {
          entityType: 'object',
          id: item.id.toString(),
          definitionId: `object:${item.itemKind}`,
          tags: ['world_item'],
          tile: {
            spaceId: item.spaceId.toString(),
            x: Math.floor(item.x / TILE_SIZE_FIXED),
            y: Math.floor(item.y / TILE_SIZE_FIXED),
            tags: [],
          },
          state: { lit: item.lit, quantity: item.quantity, expired: true },
        }, tickLifecycleHandlers, tickRegistrySnapshot);
        ctx.db.world_item.id.delete(item.id);
        recordTickRowTouch(updateCounters, 'itemDeletes');
      }
      for (const speech of ctx.db.world_speech.by_expires_tick.filter(expiredThrough)) {
        recordTickRowScan(updateCounters, 'speechRowsScanned');
        ctx.db.world_speech.id.delete(speech.id);
        recordTickRowTouch(updateCounters);
      }
    }
    if (authorityTick % AUDIT_TRIM_CADENCE_TICKS === 0n) {
      // Cadence: AUDIT_TRIM_CADENCE_TICKS. The integer range index bounds the
      // scan to expired rows and legacy zero-key rows requiring one backfill.
      const nowMicros = ctx.timestamp.microsSinceUnixEpoch;
      const retentionCutoff = nowMicros >= CONNECTION_AUDIT_RETENTION_MICROS
        ? nowMicros - CONNECTION_AUDIT_RETENTION_MICROS
        : 0n;
      const expiredAuditRange = new Range<bigint>(
        undefined,
        { tag: 'included', value: retentionCutoff },
      );
      for (const audit of ctx.db.connection_audit.by_occurred_at_micros.filter(expiredAuditRange)) {
        recordTickRowScan(updateCounters, 'auditRowsScanned');
        const occurredAtMicros = audit.occurredAtMicros === 0n
          ? audit.occurredAt.microsSinceUnixEpoch
          : audit.occurredAtMicros;
        if (!connectionAuditExpired(
          occurredAtMicros,
          nowMicros,
        )) {
          if (audit.occurredAtMicros === 0n) {
            ctx.db.connection_audit.id.update({ ...audit, occurredAtMicros });
            recordTickRowTouch(updateCounters);
          }
          continue;
        }
        ctx.db.connection_audit.id.delete(audit.id);
        recordTickRowTouch(updateCounters, 'auditDeletes');
      }
      let trimmedClientErrors = 0;
      const clientErrorRetentionCutoff = nowMicros >= CLIENT_ERROR_RETENTION_MICROS
        ? nowMicros - CLIENT_ERROR_RETENTION_MICROS
        : 0n;
      const expiredClientErrorRange = new Range<bigint>(
        undefined,
        { tag: 'included', value: clientErrorRetentionCutoff },
      );
      for (const report of ctx.db.client_error_report.by_occurred_at.filter(expiredClientErrorRange)) {
        if (!clientErrorExpired(report.occurredAtMicros, nowMicros)) continue;
        ctx.db.client_error_report.id.delete(report.id);
        recordTickRowTouch(updateCounters, 'auditDeletes');
        trimmedClientErrors += 1;
        if (trimmedClientErrors >= 256) break;
      }
    }
    tickStageTiming(telemetryTimingSample, 'expiry', true);
    // The coarse world/NPC simulation may sleep with no connected players, but
    // authority time must continue so effects expire and lazy vital regen can
    // catch up exactly on the next connection.
    if (activePresenceCount === 0n) {
      finishTickTelemetry(authorityTick, updateCounters, obstacleCount);
      return;
    }
    const characterBalance = runtimeCharacterCombatBalance(wildlifeRegistry);
    if (characterBalance !== null
      && authorityTick % BigInt(characterBalance.regenSweepTicks) === 0n) {
      const online = new Map<string, WorldReducerContext['sender']>();
      for (const presence of activePresences) {
        online.set(presence.identity.toHexString(), presence.identity);
      }
      for (const identity of online.values()) {
        const input = ctx.db.player_input.identity.find(identity);
        const hasSprintIntent = input !== null
          && ((input.sprinting && input.direction !== 'idle')
            || input.settleDirection.includes('!'))
          && !inputIsStale(input.updatedAtMicros, ctx.timestamp.microsSinceUnixEpoch)
          && mountedNpcFor(ctx, identity) === null;
        const storedStats = hasSprintIntent
          ? ctx.db.player_stats.identity.find(identity)
          : null;
        const activelySprinting = storedStats !== null
          && playerCanAffordSprintStep(ctx, storedStats, identity, authorityTick);
        const activelyChargingBow = ctx.db.bow_charge.identity.find(identity) !== null;
        advancePlayerStats(
          ctx,
          identity,
          authorityTick,
          activelySprinting || activelyChargingBow,
        );
      }
    }
    const wildlifeSeed = ctx.db.world_seed.id.find(0)?.seed ?? SURVIVAL_WORLD_SEED;
    // Cadence: HIVE_PRODUCTION_INTERVAL_TICKS via hiveProducesHoneyAtTick; the
    // deterministic generated hive roster bounds this scan independently of players.
    if (hiveProducesHoneyAtTick(calendarTick)) {
      for (const hive of ctx.db.world_hive.iter()) {
        if (hive.nextProductionTick > authorityTick || hive.honey >= HIVE_HONEY_CAPACITY) continue;
        ctx.db.world_hive.id.update({
          ...hive,
          honey: Math.min(HIVE_HONEY_CAPACITY, hive.honey + Math.max(1, hive.beeCount)),
          nextProductionTick: authorityTick + HIVE_PRODUCTION_INTERVAL_TICKS,
        });
      }
    }
    // Hives own a deterministic roster. A missing bee is recreated inside its
    // hive on a coarse cadence, preserving a fixed population without a timer
    // or lifecycle row per insect.
    if (authorityTick % 600n === 0n) {
      const generatedHives = generateSurvivalWildlifeHivesForRegistry(wildlifeRegistry, wildlifeSeed);
      const hivesByHome = new Map<string, { readonly beeCount: number }>(
        generatedHives.map((hive) => [`${hive.tileX},${hive.tileY}`, hive]),
      );
      const rosterCounts = new Map<string, number>();
      for (const animal of generateSurvivalWildlifeForRegistry(wildlifeRegistry, wildlifeSeed)) {
        if (!runtimeWildlifeUsesHive(wildlifeRegistry, animal.species)) continue;
        const key = `${animal.homeTileX},${animal.homeTileY}`;
        const hive = hivesByHome.get(key);
        if (hive === undefined) continue;
        const rosterIndex = rosterCounts.get(key) ?? 0;
        rosterCounts.set(key, rosterIndex + 1);
        if (rosterIndex >= hive.beeCount) continue;
        const npcId = BigInt(animal.id);
        if (ctx.db.world_wildlife_profile.npcId.find(npcId) === null) {
          ctx.db.world_wildlife_profile.insert(generatedWildlifeProfileRow(wildlifeRegistry, animal));
        }
        if (ctx.db.world_npc.id.find(npcId) === null) {
          ctx.db.world_npc.insert(generatedWildlifeNpcRow(wildlifeRegistry, animal, authorityTick));
        }
      }
    }
    tickStageTiming(telemetryTimingSample, 'collision');
    const onlinePlayerByIdentity = new Map<string, PlayerPositionRow>();
    for (const presence of activePresences) {
      let player = ctx.db.player_position.identity.find(presence.identity);
      const seated=ctx.db.player_seat.identity.find(presence.identity);
      if(seated!==null){
        const input=ctx.db.player_input.identity.find(presence.identity);
        if(ctx.db.world_placeable.id.find(seated.placeableId)===null||player===null||player.actionKind!=='sitting'||player.spaceId!==seated.spaceId
          ||player.x!==seated.seatedX||player.y!==seated.seatedY
          ||(input!==null&&(input.settleSteps>0||input.direction!=='idle')&&!inputIsStale(input.updatedAtMicros,ctx.timestamp.microsSinceUnixEpoch))){
          standHearthSeat(ctx,presence.identity);
          player=ctx.db.player_position.identity.find(presence.identity);
        }
      }
      const playerHome = player === null ? null : ctx.db.homestead.spaceId.find(player.spaceId);
      if (player !== null && playerHome !== null) {
        const tileX = Math.floor(player.x / TILE_SIZE_FIXED);
        const tileY = Math.floor(player.y / TILE_SIZE_FIXED);
        const homesteadSize = activeSpaceDefinition(ctx, player.spaceId, playerHome)?.sizeTiles;
        const plotBounds = homesteadPlotBounds(homesteadSize);
        // Recover only genuinely stranded legacy positions. Fence contact is
        // resolved by ordinary movement collision; teleporting on contact made
        // the closed gate feel like a rubber band.
        if (!homesteadPlayableTile(tileX, tileY, homesteadSize)
          && (tileX < plotBounds.minimumX - 1 || tileX > plotBounds.maximumX + 1
            || tileY < plotBounds.minimumY - 1 || tileY > plotBounds.maximumY + 1)) {
          teleportPlayer(
            ctx,
            player,
            player.spaceId,
            HOMESTEAD_ENTRY_TILE.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
            HOMESTEAD_ENTRY_TILE.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
          );
          player = ctx.db.player_position.identity.find(presence.identity);
        }
      }
      if (player !== null) onlinePlayerByIdentity.set(presence.identity.toHexString(), player);
    }
    const onlinePlayers = [...onlinePlayerByIdentity.values()];
    const playersBySpace = new Map<number, PlayerPositionRow[]>();
    for (const player of onlinePlayers) {
      const players = playersBySpace.get(player.spaceId) ?? [];
      players.push(player);
      playersBySpace.set(player.spaceId, players);
    }
    const collisionBySpace = new Map<number, ReturnType<typeof createAuthoritySpaceCollisionMap>>();
    const waterCollisionBySpace = new Map<number, ReturnType<typeof createAuthoritySpaceCollisionMap>>();
    const projectileCollisionBySpace = new Map<number, CollisionMap>();
    const resourcesBySpace = new Map<number, WorldResourceRow[]>();
    const chestsBySpace = new Map<number, WorldChestRow[]>();
    const combatTargetsBySpace = new Map<number, WorldCombatTargetRow[]>();
    const projectilesBySpace = new Map<number, WorldProjectileRow[]>();
    const npcsBySpace = new Map<number, WorldNpcRow[]>();
    for (const spaceId of playersBySpace.keys()) {
      const projectiles = [...ctx.db.world_projectile.by_chunk.filter(spaceId)];
      projectilesBySpace.set(spaceId, projectiles);
      // Only entities near an online player (plus active projectile sweeps) can
      // consume collision this tick. Exact composite-index probes avoid
      // materializing all ~6k island resources at 20 Hz.
      const chunkScope = tickCollisionChunkScope(playersBySpace.get(spaceId) ?? [], projectiles);
      const resources: WorldResourceRow[] = [];
      const chests: WorldChestRow[] = [];
      const combatTargets: WorldCombatTargetRow[] = [];
      const npcs: WorldNpcRow[] = [];
      for (const [chunkX, chunkY] of chunkScope.values()) {
        resources.push(...ctx.db.world_resource.by_chunk.filter([spaceId, chunkX, chunkY]));
        chests.push(...ctx.db.world_chest.by_chunk.filter([spaceId, chunkX, chunkY]));
        combatTargets.push(...ctx.db.world_combat_target.by_chunk.filter([spaceId, chunkX, chunkY]));
        npcs.push(...ctx.db.world_npc.by_chunk.filter([spaceId, chunkX, chunkY]));
      }
      resourcesBySpace.set(spaceId, resources);
      chestsBySpace.set(spaceId, chests);
      combatTargetsBySpace.set(spaceId, combatTargets);
      npcsBySpace.set(spaceId, npcs);
      // Resolve the revision-keyed live runtime once per occupied space. In
      // particular, do not repeat its indexed head/registry lookup for every
      // generated resource in the collision filter. The owner chunkAuthority
      // switch selects compiled (off, shadow) or chunk (on) collision here.
      const liveMapRuntime = spaceId === TOPSIDE_SPACE_ID
        ? liveIslandCollisionRuntime(ctx)
        : null;
      // Use the same augmented map as reducers and clients. This adds dynamic
      // Homestead POIs/tents; constructing the base map directly here caused
      // authority to walk through them while prediction correctly stopped.
      const collision = collisionForSpace(ctx, spaceId, undefined, {
        resources,
        chests,
        combatTargets,
        chunkScope: new Set(chunkScope.keys()),
      }, liveMapRuntime);
      collisionBySpace.set(spaceId, collision);
      const waterCollision = waterCollisionForSpace(
        ctx,
        spaceId,
        liveMapRuntime,
        new Set(chunkScope.keys()),
        collision,
      );
      waterCollisionBySpace.set(spaceId, waterCollision);
      // Shadow-mode sampler: null (no allocation, no work) unless shadow is on and due.
      const chunkSampleRuntime = spaceId === TOPSIDE_SPACE_ID ? chunkAuthorityDispatcher.sampleRuntime(authorityTick) : null;
      if (chunkSampleRuntime !== null) {
        sampleChunkAuthorityShadow(ctx, chunkSampleRuntime, authorityTick, playersBySpace.get(spaceId) ?? [], { ground: collision, water: waterCollision }, {
          resources, chests, combatTargets, chunkScope: new Set(chunkScope.keys()),
        });
      }
      obstacleCount += collision.obstacles?.length ?? 0;
    }
    tickStageTiming(telemetryTimingSample, 'collision', true);

    for (const targets of combatTargetsBySpace.values()) {
      for (const target of targets) regenerateCombatTarget(ctx, target, authorityTick);
    }

    tickStageTiming(telemetryTimingSample, 'movement');
    for (const row of onlinePlayers) {
      if(ctx.db.player_seat.identity.find(row.identity)!==null)continue;
      const collision = collisionBySpace.get(row.spaceId);
      if (collision === undefined) continue;
      const input = ctx.db.player_input.identity.find(row.identity);
      const mount = mountedNpcFor(ctx, row.identity);
      const mounted = mount !== null;
      const legacyMovementCollision = runtimeNpcMount(contentRegistry(ctx), mount)?.adapter === 'boat'
        ? waterCollisionBySpace.get(row.spaceId) ?? collision
        : collision;
      const movementCollision = runtimeActorCollision(contentRegistry(ctx), legacyMovementCollision,
        { kind: 'player', mount, effects: [...ctx.db.player_effect.by_identity.filter(row.identity)] }, authorityTick, traversalSolidGeometry(collision, waterCollisionBySpace.get(row.spaceId) ?? collision));
      const defended = stepPlayerDefense(ctx, row, authorityTick, movementCollision);
      const stale = input === null || inputIsStale(
        input.updatedAtMicros,
        ctx.timestamp.microsSinceUnixEpoch,
      );
      const jumpState = ctx.db.player_jump_state.identity.find(row.identity);
      const jumpActive = jumpState !== null && authorityTick <= jumpState.untilTick;
      if (jumpState !== null && !jumpActive) ctx.db.player_jump_state.identity.delete(row.identity);
      let player: PlayerState = {
        position: { x: defended?.x ?? row.x, y: defended?.y ?? row.y },
        facing: parseDirection(defended?.facing ?? row.facing) ?? 'down',
        moving: row.moving,
        location: 'estate',
      };
      const startedX = row.x;
      const startedY = row.y;
      if (input !== null && !stale && !jumpActive && defended === null) {
        const available = movementCreditAvailable(
          input.creditStartedAtMicros,
          input.creditedSteps,
          ctx.timestamp.microsSinceUnixEpoch,
        );
        const acceptedBatch = Math.min(input.settleSteps, MAX_SETTLE_STEPS_PER_TICK);
        const settledThisTick = acceptedBatch <= available ? acceptedBatch : 0;
        const drained = drainMovementRunQueue(
          input.settleDirection,
          input.settleSteps,
          settledThisTick,
        );
        const hasSprintIntent = !mounted && drained.intents.some((intent) => intent.sprinting);
        const storedSprintStats = hasSprintIntent
          ? ensurePlayerStats(ctx, row.identity, authorityTick)
          : null;
        const sprintWasAffordable = storedSprintStats !== null
          && playerCanAffordSprintStep(ctx, storedSprintStats, row.identity, authorityTick);
        const sprintStatsRow = hasSprintIntent
          ? advancePlayerStats(ctx, row.identity, authorityTick, sprintWasAffordable)
          : null;
        const sprintModifiers = sprintStatsRow === null
          ? []
          : activePlayerModifiers(ctx, row.identity, authorityTick);
        const sprintResolvedStats = sprintStatsRow === null
          ? null
          : resolveStatsWithProfile(activeCharacterCombatBalance(ctx), {
            str: sprintStatsRow.str,
            dex: sprintStatsRow.dex,
            con: sprintStatsRow.con,
            int: sprintStatsRow.int,
            wis: sprintStatsRow.wis,
            cha: sprintStatsRow.cha,
          }, sprintModifiers);
        const sprintDefinition = runtimeSprintAbilityDefinition(wildlifeRegistry);
        const sprintAbility = sprintResolvedStats === null || sprintDefinition === null
          ? null
          : resolveSprintAbility(
            sprintDefinition, sprintResolvedStats.attributes, sprintModifiers,
            activeCharacterCombatBalance(ctx),
          );
        let sprintStepsMoved = 0;
        let sprintCostCenti = 0;
        for (const intent of drained.intents) {
          const nextSprintCost = sprintAbility === null
            ? 0
            : sprintVigourCostForSteps(
              sprintAbility.vigourDrainCentiPerSecond,
              sprintStepsMoved + 1,
            );
          const canSprint = intent.sprinting
            && sprintWasAffordable
            && sprintStatsRow !== null
            && sprintAbility !== null
            && sprintStatsRow.vigourCenti >= nextSprintCost;
          const beforeX = player.position.x;
          const beforeY = player.position.y;
          const rogueMoveSpeed = mounted ? 0 : rogueUpgradeMagnitude(
            ctx, row.identity, 'move_speed',
          );
          const movementSpeedPermille = canSprint && sprintAbility !== null
            ? Math.min(4_000, sprintAbility.speedPermille + rogueMoveSpeed)
            : Math.min(2_000, 1_000 + rogueMoveSpeed);
          player = mounted
            ? movePlayerAtSpeed(player, intent.direction, movementCollision, 2)
            : movementSpeedPermille !== 1_000
                ? movePlayerAtSpeedPermille(
                  player, intent.direction, collision, movementSpeedPermille,
                )
                : movePlayer(player, intent.direction, collision);
          if (canSprint && (player.position.x !== beforeX || player.position.y !== beforeY)) {
            sprintStepsMoved += 1;
            sprintCostCenti = nextSprintCost;
          }
        }
        if (sprintStatsRow !== null && sprintCostCenti > 0) {
          ctx.db.player_stats.identity.update({
            ...sprintStatsRow,
            vigourCenti: sprintStatsRow.vigourCenti - sprintCostCenti,
            vigourRemainder: 0,
            regenTick: authorityTick,
          });
          spendPlayerHunger(
            ctx,
            row.identity,
            hungerCostForSprintVigour(sprintCostCenti),
          );
        }
        const creditedThisTick = settledThisTick;
        const remainingSettleSteps = drained.pendingSteps;
        const acknowledgement = drainMovementAcknowledgement(
          input.settledSequence,
          input.pendingSequence,
          remainingSettleSteps,
        );
        ctx.db.player_input.identity.update({
          ...input,
          appliedSteps: 0n,
          settleDirection: drained.pendingDirection,
          settleSteps: remainingSettleSteps,
          ...acknowledgement,
          creditedSteps: input.creditedSteps + BigInt(creditedThisTick),
          lastProcessedSequence: acknowledgement.settledSequence,
        });
      }
      if (input !== null && (jumpActive || defended !== null)) {
        ctx.db.player_input.identity.update({
          ...input,
          appliedSteps: 0n,
          creditStartedAtMicros: ctx.timestamp.microsSinceUnixEpoch,
          creditedSteps: 0n,
          settleDirection: 'idle',
          settleSteps: 0,
          settledSequence: input.sequence,
          pendingSequence: 0n,
          lastProcessedSequence: input.sequence,
        });
      }
      const moved = player.position.x !== startedX || player.position.y !== startedY;
      if (moved) {
        const distance = BigInt(Math.abs(player.position.x - startedX) + Math.abs(player.position.y - startedY));
        recordPlayerStatistic(
          ctx,
          row.identity,
          'distance_travelled',
          distance,
          authorityTick,
          runtimeNpcMount(contentRegistry(ctx), mount)?.adapter === 'boat' ? 'boat' : mounted ? 'horse' : 'foot',
        );
      }
      const fishingInterrupted = moved && ctx.db.fishing_cast.identity.find(row.identity) !== null;
      if (fishingInterrupted) ctx.db.fishing_cast.identity.delete(row.identity);
      const nextActionKind = defended !== null ? defended.actionKind
        : row.actionKind === 'dodge' || row.actionKind === 'block' ? 'none'
        : fishingInterrupted
        ? 'none'
        : jumpActive
        ? mounted ? 'horse_jump' : 'jump'
        : row.actionKind === 'jump' || row.actionKind === 'horse_jump'
          ? 'none'
        : mounted
          ? row.actionKind === 'ranged_weapon' ? row.actionKind : 'none'
          : avatarActionAfterMovement(row.actionKind, moved);
      const clearAction = nextActionKind === 'none' && row.actionKind !== 'none';
      const nextPosition = {
        ...row,
        x: player.position.x,
        y: player.position.y,
        chunkX: chunkAt(player.position.x),
        chunkY: chunkAt(player.position.y),
        facing: player.facing,
        moving: jumpActive ? false : moved,
        authorityTick,
        actionKind: nextActionKind,
        actionStartedTick: defended?.actionStartedTick ?? (clearAction ? authorityTick : row.actionStartedTick),
      };
      if (moved && (Math.floor(row.x / TILE_SIZE_FIXED) !== Math.floor(nextPosition.x / TILE_SIZE_FIXED)
        || Math.floor(row.y / TILE_SIZE_FIXED) !== Math.floor(nextPosition.y / TILE_SIZE_FIXED))) {
        raisePlayerWalkOntoEvent(
          ctx,
          row.identity,
          nextPosition,
          tickLifecycleHandlers,
          tickRegistrySnapshot,
        );
      }
      const positionUpdated = updateRowWhenChanged(row, nextPosition, [
        'x', 'y', 'chunkX', 'chunkY', 'facing', 'moving',
        'actionKind', 'actionStartedTick',
      ], updateCounters, 'playerPositionUpdates', (next) => {
        ctx.db.player_position.identity.update(next);
      });
      if (!positionUpdated) updateCounters.playerPositionNoopSkips += 1;
      if (moved) refreshPlayerQuestLocations(ctx, nextPosition, authorityTick);
      for (const chest of ctx.db.world_chest.by_carrier.filter(row.identity)) {
        const tileX = Math.floor(player.position.x / TILE_SIZE_FIXED);
        const tileY = Math.floor(player.position.y / TILE_SIZE_FIXED);
        const chunkX = Math.floor(tileX / SURVIVAL_CHUNK_TILES); const chunkY = Math.floor(tileY / SURVIVAL_CHUNK_TILES);
        if (chest.tileX !== tileX || chest.tileY !== tileY || chest.chunkX !== chunkX || chest.chunkY !== chunkY) {
          const moved = { ...chest, tileX, tileY, chunkX, chunkY };
          ctx.db.world_chest.id.update(moved);
          syncLegacyChestGenericMirror(ctx, moved);
          recordTickRowTouch(updateCounters, 'chestUpdates');
        }
      }
      for (const target of ctx.db.world_combat_target.by_carrier.filter(row.identity)) {
        const chunkX = chunkAt(player.position.x);
        const chunkY = chunkAt(player.position.y);
        if (target.x !== player.position.x || target.y !== player.position.y
          || target.chunkX !== chunkX || target.chunkY !== chunkY || target.spaceId !== row.spaceId) {
          moveEmbeddedArrowsWithTarget(
            ctx, target, player.position.x, player.position.y, row.spaceId,
          );
          ctx.db.world_combat_target.id.update({
            ...target,
            x: player.position.x,
            y: player.position.y,
            chunkX,
            chunkY,
            spaceId: row.spaceId,
          });
          recordTickRowTouch(updateCounters);
        }
      }
      for (const placeable of ctx.db.world_placeable.by_carrier.filter(row.identity)) {
        const tileX = Math.floor(player.position.x / TILE_SIZE_FIXED);
        const tileY = Math.floor(player.position.y / TILE_SIZE_FIXED);
        const chunkX = Math.floor(tileX / SURVIVAL_CHUNK_TILES);
        const chunkY = Math.floor(tileY / SURVIVAL_CHUNK_TILES);
        if (placeable.tileX !== tileX || placeable.tileY !== tileY
          || placeable.chunkX !== chunkX || placeable.chunkY !== chunkY
          || placeable.spaceId !== row.spaceId) {
          ctx.db.world_placeable.id.update({
            ...placeable,
            tileX,
            tileY,
            chunkX,
            chunkY,
            spaceId: row.spaceId,
          });
          recordTickRowTouch(updateCounters);
        }
      }
    }
    tickStageTiming(telemetryTimingSample, 'movement', true);

    tickStageTiming(telemetryTimingSample, 'projectiles');
    const outdoorProjectilePolicy=playersBySpace.has(TOPSIDE_SPACE_ID)?compiledLiveIslandRuntime(ctx)?.combatPolicy:undefined;
    const occupiedProjectiles = [...projectilesBySpace.values()].flat();
    for (const projectile of occupiedProjectiles) {
      let collision = projectileCollisionBySpace.get(projectile.spaceId);
      if (collision === undefined) {
        const groundCollision = collisionBySpace.get(projectile.spaceId);
        const waterCollision = waterCollisionBySpace.get(projectile.spaceId);
        if (groundCollision === undefined || waterCollision === undefined) continue;
        collision = runtimeActorCollision(contentRegistry(ctx), projectileTraversalCollision(groundCollision, waterCollision),
          { kind: 'projectile' }, authorityTick, traversalSolidGeometry(groundCollision, waterCollision));
        projectileCollisionBySpace.set(projectile.spaceId, collision);
      }
      if (projectile.expiresTick <= authorityTick) {
        ctx.db.world_projectile.id.delete(projectile.id);
        ctx.db.projectile_charge.projectileId.delete(projectile.id);
        if (rogueRunForSpace(ctx, projectile.spaceId) !== null) continue;
        const landedAtTick = projectile.hitKind === 'combat_target'
          ? authorityTick
          : projectile.state === 'hit'
            ? projectile.expiresTick - PROJECTILE_HIT_RETENTION_TICKS
          : projectile.expiresTick - 1n;
        if (!worldItemExpired(
          landedAtTick,
          authorityTick,
          RECOVERABLE_ARROW_LIFETIME_TICKS,
        )) {
          dropWorldItemStack(ctx, {
            itemKind: projectile.ammunitionItemKind,
            quantity: 1,
            x: projectile.x,
            y: projectile.y,
            droppedAtTick: landedAtTick,
            durability: recoverableArrowAngle(projectile.velocityX, projectile.velocityY),
            spaceId: projectile.spaceId,
          });
        }
        continue;
      }
      if (projectile.state !== 'flying') {
        continue;
      }
      let launch=ctx.db.projectile_charge.projectileId.find(projectile.id);
      if (launch===null || launch.damageCenti===0) {
        // Additive compatibility for arrows already in flight at module upgrade.
        // Freeze once on the first authority tick; subsequent impacts never read
        // a newer equipment state or reroll their critical result.
        const weaponBaseCenti=runtimeWeaponBaseDamageCenti(contentRegistry(ctx),projectile.weaponItemKind,'ranged');
        const ownerStats=ctx.db.player_stats.identity.find(projectile.owner);
        if (weaponBaseCenti===null || ownerStats===null) {
          ctx.db.world_projectile.id.update({...projectile,expiresTick:authorityTick});continue;
        }
        const modifiers=activePlayerModifiers(ctx,projectile.owner,authorityTick,projectile.weaponItemKind);
        const characterBalance=activeCharacterCombatBalance(ctx);
        const attributes=resolveStatsWithProfile(characterBalance,{str:ownerStats.str,dex:ownerStats.dex,con:ownerStats.con,
          int:ownerStats.int,wis:ownerStats.wis,cha:ownerStats.cha},modifiers).attributes;
        const damage=resolveCombatDamageWithProfile(characterBalance,{attackKind:'ranged',weaponBaseCenti,scalingAttribute:attributes.dex,
          armorCenti:0,armorPctBasisPoints:0,attackerModifiers:modifiers,
          seedParts:[ctx.db.world_seed.id.find(0)?.seed??SURVIVAL_WORLD_SEED,projectile.owner.toHexString(),projectile.spawnedTick,projectile.id,projectile.weaponItemKind]});
        const next={projectileId:projectile.id,chargeMs:launch?.chargeMs??0,
          damageCenti:bowChargeScaledDamageCenti(damage.damageCenti,launch?.chargeMs??0),critical:damage.critical};
        launch=launch===null?ctx.db.projectile_charge.insert(next):ctx.db.projectile_charge.projectileId.update(next);
      }
      const from = { x: projectile.x, y: projectile.y };
      const to = { x: projectile.x + projectile.velocityX, y: projectile.y + projectile.velocityY };
      if(!outdoorProjectileSegmentAllowed(outdoorProjectilePolicy,projectile.spaceId,from,to)) {
        // Expire at the last valid location; ordinary expiry preserves arrow recovery.
        ctx.db.world_projectile.id.update({...projectile,expiresTick:authorityTick});continue;
      }
      const targets = [];
      // Hulls precede riders at an overlapping landing point so an arrow can
      // sink an occupied boat instead of being swallowed by the rider hitbox.
      for (const npc of npcsBySpace.get(projectile.spaceId) ?? []) {
        if (runtimeNpcMount(contentRegistry(ctx), npc)?.adapter !== 'boat' || npc.health === 0 || npc.rider?.isEqual(projectile.owner) === true) continue;
        targets.push({ kind: 'npc', id: npc.id.toString(), ...boatProjectileBounds(npc) });
      }
      for (const previousPlayer of playersBySpace.get(projectile.spaceId) ?? []) {
        const player = ctx.db.player_position.identity.find(previousPlayer.identity);
        if (player === null || player.spaceId !== projectile.spaceId) continue;
        if (player.identity.isEqual(projectile.owner)) continue;
        const online = [
          ...ctx.db.connection_presence_v2.by_identity.filter(player.identity),
        ].length > 0;
        if (!online) continue;
        const target = projectilePlayerTarget(ctx, player.identity, projectile.spaceId);
        if (target !== null) targets.push(target);
      }
      for (const npc of npcsBySpace.get(projectile.spaceId) ?? []) {
        if (npc.rider?.isEqual(projectile.owner) === true) continue;
        if (runtimeNpcMount(contentRegistry(ctx), npc)?.adapter === 'boat') continue;
        const profile = ctx.db.world_wildlife_profile.npcId.find(npc.id);
        const rogueProfile = ctx.db.rogue_enemy_profile.npcId.find(npc.id);
        const validWildlife = profile !== null && runtimeWildlifeDefinition(wildlifeRegistry, profile.species) !== null
          && runtimeCreatureIsHuntable(wildlifeRegistry, profile.species);
        const validRogueEnemy = rogueProfile !== null
          && rogueRunForIdentity(ctx, projectile.owner)?.id === rogueProfile.runId;
        const validOutdoorEnemy=ctx.db.outdoor_enemy_profile.npcId.find(npc.id)!==null;
        if (npc.health === 0 || (!validWildlife && !validRogueEnemy && !validOutdoorEnemy)) continue;
        targets.push({
        kind: 'npc', id: npc.id.toString(),
        left: npc.x - 7 * FIXED_UNITS_PER_PIXEL,
        right: npc.x + 7 * FIXED_UNITS_PER_PIXEL,
        top: npc.y - 15 * FIXED_UNITS_PER_PIXEL,
        bottom: npc.y,
        });
      }
      for (const resource of resourcesBySpace.get(projectile.spaceId) ?? []) {
        if (resource.depleted) continue;
        const definition = runtimeResourceDefinition(contentRegistry(ctx), resource);
        if (definition?.collision.blocksMovement !== true) continue;
        const obstacle = runtimeResourceObstacle(contentRegistry(ctx), resource, resource.tileX, resource.tileY);
        if (obstacle !== null) targets.push({ kind: 'resource', id: resource.id.toString(), ...obstacle });
      }
      for (const chest of chestsBySpace.get(projectile.spaceId) ?? []) {
        if (chest.carriedBy !== undefined) continue;
        targets.push({
          kind: 'chest', id: chest.id.toString(),
          left: chest.tileX * TILE_SIZE_FIXED,
          right: (chest.tileX + 1) * TILE_SIZE_FIXED,
          top: chest.tileY * TILE_SIZE_FIXED,
          bottom: (chest.tileY + 1) * TILE_SIZE_FIXED,
        });
      }
      for (const target of combatTargetsBySpace.get(projectile.spaceId) ?? []) {
        if (target.carriedBy !== undefined) continue;
        if (activeCombatTargetHealth(ctx, target) === null) continue;
        targets.push({
          kind: 'combat_target',
          id: target.id.toString(),
          ...combatTargetProjectileBounds(target),
        });
      }
      // The parabola meets the entity plane only at its cursor-selected
      // endpoint. Earlier segments may cross a target in screen space, but
      // must not snap the embedded arrow to that leading collision edge.
      const landingStep = projectile.expiresTick === authorityTick + 1n;
      const entityHit = landingStep ? projectileTargetAtLanding(to, targets) : null;
      const terrainHit = firstProjectileTerrainHit(from, to, collision);
      const hit = entityHit === null ? terrainHit
        : terrainHit === null || entityHit.fraction <= terrainHit.fraction ? entityHit : terrainHit;
      if (hit !== null) {
        if (hit.kind === 'combat_target') {
          const storedTarget = ctx.db.world_combat_target.id.find(BigInt(hit.id));
          const damageable = storedTarget === null ? null : activeCombatTargetHealth(ctx, storedTarget);
          if (storedTarget !== null && storedTarget.spaceId === projectile.spaceId
            && storedTarget.carriedBy === undefined && damageable !== null) {
            const target = regenerateCombatTarget(ctx, storedTarget, authorityTick);
            const chargedDamageCenti=launch.damageCenti;
            const minimumHealthCenti = Math.min(
              target.healthCenti,
              target.maxHealthCenti,
              damageable.minimumHealthCenti,
            );
            const nextHealth = Math.max(
              minimumHealthCenti,
              target.healthCenti - chargedDamageCenti,
            );
            const appliedDamage = target.healthCenti - nextHealth;
            if (appliedDamage > 0) {
              ctx.db.world_combat_target.id.update({
                ...target,
                healthCenti: nextHealth,
                regenTick: authorityTick,
                lastDamagedTick: authorityTick,
                lastHitCritical: launch.critical,
              });
              recordPlayerStatistic(
                ctx, projectile.owner, 'damage_dealt', BigInt(appliedDamage), authorityTick, target.kind,
              );
            }
          }
        } else if (hit.kind === 'npc') {
          const npc = ctx.db.world_npc.id.find(BigInt(hit.id));
          if (npc !== null && npc.spaceId === projectile.spaceId && npc.health > 0) {
            if (runtimeNpcMount(contentRegistry(ctx), npc)?.adapter === 'boat') {
              if (npc.health <= 1) {
                const ground = collisionBySpace.get(npc.spaceId);
                if (ground !== undefined) sinkBoat(ctx, npc, authorityTick, ground);
              } else {
                updateWorldNpc(ctx, {
                  ...npc,
                  health: npc.health - 1,
                  lastHitCritical: false,
                  authorityTick,
                });
              }
            } else {
            const chargedDamage=launch.damageCenti;
            const rogueProfile = ctx.db.rogue_enemy_profile.npcId.find(npc.id);
            if(ctx.db.outdoor_enemy_profile.npcId.find(npc.id)!==null) {
              damageOutdoorEnemy(ctx,npc,projectile.owner,chargedDamage,launch.critical,authorityTick,from);
            } else if (rogueProfile !== null
              && rogueRunForIdentity(ctx, projectile.owner)?.id === rogueProfile.runId) {
              damageRogueEnemy(
                ctx, npc, rogueProfile, projectile.owner, chargedDamage, launch.critical, authorityTick,
              );
            } else {
              damageHuntableWildlife(
                ctx, npc, projectile.owner, chargedDamage, launch.critical, authorityTick,
              );
            }
            }
          }
        }
        ctx.db.world_projectile.id.update({
          ...projectile,
          x: hit.x,
          y: hit.y,
          chunkX: chunkAt(hit.x),
          chunkY: chunkAt(hit.y),
          state: 'hit',
          hitKind: hit.kind,
          hitId: hit.id,
          expiresTick: authorityTick + (hit.kind === 'combat_target'
            ? ARCHERY_TARGET_EMBEDDED_ARROW_TICKS
            : PROJECTILE_HIT_RETENTION_TICKS),
        });
        if (rogueRunForIdentity(ctx, projectile.owner) === null) recordPlayerStatistic(
          ctx, projectile.owner, 'arrows_hit', 1n, authorityTick, hit.kind,
        );
        ctx.db.projectile_charge.projectileId.delete(projectile.id);
        continue;
      }
      ctx.db.world_projectile.id.update({
        ...projectile,
        x: to.x,
        y: to.y,
        chunkX: chunkAt(to.x),
        chunkY: chunkAt(to.y),
      });
      recordTickRowTouch(updateCounters);
    }
    tickStageTiming(telemetryTimingSample, 'projectiles', true);



    const wildlifePlayerChunks = onlinePlayers
      .filter((player) => player.spaceId === TOPSIDE_SPACE_ID)
      .map((player) => [player.chunkX, player.chunkY] as const);
    tickStageTiming(telemetryTimingSample, 'npc');
    const outdoorPlayers = onlinePlayers.map(player => ctx.db.player_position.identity.find(player.identity))
      .filter((player): player is PlayerPositionRow => player !== null);
    stepOutdoorEncounters(ctx, authorityTick, outdoorPlayers);
    stepHearthResourceRespawns(ctx, authorityTick, outdoorPlayers);
    const occupiedNpcs = [...npcsBySpace.values()].flat();
    const activeContentRegistry = contentRegistry(ctx);
    const starterHorseDefinition = runtimeStarterHorseDefinition(activeContentRegistry);
    const starterHorseMount = starterHorseDefinition?.mount?.adapter === 'horse'
      ? starterHorseDefinition.mount
      : null;
    const starterHorseRuntimeId = starterHorseDefinition === null
      ? null
      : BigInt(starterHorseDefinition.runtimeId);
    const authoredNpcsByRuntimeId = new Map(
      [...activeContentRegistry.npcs.values()]
        .filter((definition) => definition.spawnPolicy !== 'dynamic' && definition.retired !== true)
        .map((definition) => [definition.runtimeId, definition]),
    );
    const automatedLandmarks = runtimeLandmarkCampfirePlans(contentRegistry(ctx));
    const npcLifecycleHandlers = tickLifecycleHandlers;
    for (const snapshotNpc of occupiedNpcs) {
      const npc = ctx.db.world_npc.id.find(snapshotNpc.id);
      if (npc === null) continue;
      if (ctx.db.outdoor_enemy_profile.npcId.find(npc.id) !== null) continue;
      const groundCollision = collisionBySpace.get(npc.spaceId);
      const legacyWaterCollision = waterCollisionBySpace.get(npc.spaceId);
      if (groundCollision === undefined || legacyWaterCollision === undefined) continue;
      const actor = npcTraversalActor(ctx, npc);
      const solidGeometry = traversalSolidGeometry(groundCollision, legacyWaterCollision);
      const collision = runtimeActorCollision(activeContentRegistry, groundCollision, actor, authorityTick, solidGeometry);
      const waterCollision = runtimeActorCollision(activeContentRegistry, legacyWaterCollision, actor, authorityTick, solidGeometry);
      const npcMount = runtimeNpcMount(activeContentRegistry, npc);
      const wildlifeProfile = ctx.db.world_wildlife_profile.npcId.find(npc.id) ?? undefined;
      if (runtimeTraversalPolicy(activeContentRegistry)?.mode === 'active' && npc.health === 0
        && wildlifeProfile === undefined && ctx.db.rogue_enemy_profile.npcId.find(npc.id) === null) continue;
      // A named fixed-wildlife row is retained state. If its unique authored
      // horse definition is unavailable, no compatibility behavior may move,
      // rename, heal, dismount or otherwise rewrite it.
      if (starterHorseDefinition === null
        && wildlifeProfile !== undefined
        && npc.displayName.trim() !== '') continue;
      if (npc.rider !== undefined) {
        const rider = ctx.db.player_position.identity.find(npc.rider);
        if (rider === null) {
          updateWorldNpc(ctx, {
            ...npc,
            rider: undefined,
            moving: false,
            wanderDirection: 'idle',
            nextDecisionTick: authorityTick + 20n,
            authorityTick,
          });
          recordTickRowTouch(updateCounters, 'npcUpdates');
          continue;
        }
        const riderFacing = parseDirection(rider.facing) ?? 'down';
        const facing = npcMount?.adapter === 'boat'
          ? boatFacingForDirection(riderFacing)
          : mountedHorseFacing(parseDirection(npc.facing) ?? 'down', riderFacing, rider.moving);
        const nextNpc = {
          ...npc,
          x: rider.x,
          y: rider.y,
          chunkX: rider.chunkX,
          chunkY: rider.chunkY,
          spaceId: rider.spaceId,
          facing,
          moving: rider.moving,
          wanderDirection: 'idle',
          authorityTick,
        };
        updateRowWhenChanged(npc, nextNpc, [
          'x', 'y', 'chunkX', 'chunkY', 'facing', 'moving', 'wanderDirection',
        ], updateCounters, 'npcUpdates', (next) => {
          updateWorldNpc(ctx, next);
        });
        continue;
      }

      // Empty boats stay where players leave them; they are vehicles, not
      // ambient NPCs, despite sharing the replicated world_npc substrate.
      if (npcMount?.adapter === 'boat') {
        if (npc.moving || npc.wanderDirection !== 'idle') updateWorldNpc(ctx, {
          ...npc,
          moving: false,
          wanderDirection: 'idle',
          authorityTick,
        });
        continue;
      }

      const rogueEnemyProfile = ctx.db.rogue_enemy_profile.npcId.find(npc.id);
      if (rogueEnemyProfile !== null) {
        stepRogueEnemy(
          ctx, npc, rogueEnemyProfile, authorityTick, collision,
          tickLifecycleHandlers, tickRegistrySnapshot,
        );
        recordTickRowTouch(updateCounters, 'npcUpdates');
        continue;
      }

      const wildlifeNpc = wildlifeProfile !== undefined
        && runtimeWildlifeDefinition(wildlifeRegistry, wildlifeProfile.species) !== null;
      if (firstIndexRow(ctx.db.active_dialogue.by_npc.filter(npc.id)) !== null) {
        if (npc.moving || npc.wanderDirection !== 'idle') {
          updateWorldNpc(ctx, {
            ...npc,
            moving: false,
            wanderDirection: 'idle',
            nextDecisionTick: authorityTick + 30n,
            authorityTick,
          });
          recordTickRowTouch(updateCounters, 'npcUpdates');
          if (!wildlifeNpc) updateCounters.nonWildlifeNpcUpdates += 1;
        } else if (!wildlifeNpc) {
          updateCounters.nonWildlifeNpcNoopSkips += 1;
        }
        continue;
      }

      if (wildlifeProfile !== undefined
        && runtimeWildlifeDefinition(wildlifeRegistry, wildlifeProfile.species) !== null) {
        if (npc.health === 0) {
          if (authorityTick < npc.nextDecisionTick) continue;
          const stats = runtimeResolveCreatureStats(wildlifeRegistry, wildlifeProfile.species);
          if (stats === null) continue;
          const health = Math.ceil(stats.maxHealthCenti / 100);
          updateWorldNpc(ctx, {
            ...npc,
            x: npc.homeX,
            y: npc.homeY,
            chunkX: chunkAt(npc.homeX),
            chunkY: chunkAt(npc.homeY),
            health,
            moving: false,
            wanderDirection: 'rest',
            nextDecisionTick: authorityTick + 60n,
            authorityTick,
            panicUntilTick: undefined,
            panicSource: undefined,
          });
          recordTickRowTouch(updateCounters, 'npcUpdates');
          continue;
        }
        if (npc.panicUntilTick !== undefined && authorityTick < npc.panicUntilTick) {
          const movementMedium = runtimeWildlifeMovementMedium(
            wildlifeRegistry, wildlifeProfile.species,
          );
          if (movementMedium === null) continue;
          const liveThreat = npc.panicSource === undefined
            ? null
            : ctx.db.player_position.identity.find(npc.panicSource);
          const threat = liveThreat !== null && liveThreat.spaceId === npc.spaceId
            ? { x: liveThreat.x, y: liveThreat.y }
            : { x: npc.panicSourceX, y: npc.panicSourceY };
          const stepped = runtimeStepPanickedWildlife(wildlifeRegistry, {
            id: npc.id,
            position: { x: npc.x, y: npc.y },
            home: { x: npc.homeX, y: npc.homeY },
            facing: parseNpcFacing(npc.facing),
            moving: npc.moving,
            activity: npc.wanderDirection,
            nextDecisionTick: Number(npc.nextDecisionTick),
          }, {
            species: wildlifeProfile.species,
            seed: wildlifeSeed,
            authorityTick: Number(authorityTick),
            collision: movementMedium === 'water'
              ? waterCollision
              : collision,
            threat,
          });
          if (stepped === null) continue;
          if (stepped.position.x === npc.x && stepped.position.y === npc.y
            && stepped.facing === npc.facing && stepped.moving === npc.moving
            && stepped.activity === npc.wanderDirection) continue;
          updateWorldNpc(ctx, {
            ...npc,
            x: stepped.position.x,
            y: stepped.position.y,
            chunkX: chunkAt(stepped.position.x),
            chunkY: chunkAt(stepped.position.y),
            facing: stepped.facing,
            moving: stepped.moving,
            wanderDirection: stepped.activity,
            authorityTick,
          });
          recordTickRowTouch(updateCounters, 'npcUpdates');
          continue;
        }
        if (!wildlifeActivityNearPlayers(npc.chunkX, npc.chunkY, wildlifePlayerChunks)) continue;
        if (npc.id === starterHorseRuntimeId && starterHorseMount !== null) {
          const stepped = stepWanderingNpc({
            id: npc.id,
            position: { x: npc.x, y: npc.y },
            home: { x: npc.homeX, y: npc.homeY },
            facing: parseNpcFacing(npc.facing),
            moving: npc.moving,
            wanderDirection: npcDirection(npc.wanderDirection),
            nextDecisionTick: Number(npc.nextDecisionTick),
          }, Number(authorityTick), collision, starterHorseMount.wander);
          const nextNpc = {
            ...npc,
            x: stepped.position.x,
            y: stepped.position.y,
            chunkX: chunkAt(stepped.position.x),
            chunkY: chunkAt(stepped.position.y),
            facing: stepped.facing,
            moving: stepped.moving,
            wanderDirection: stepped.wanderDirection ?? 'idle',
            nextDecisionTick: BigInt(stepped.nextDecisionTick),
            authorityTick,
          };
          updateRowWhenChanged(npc, nextNpc, [
            'x', 'y', 'chunkX', 'chunkY', 'facing', 'moving',
            'wanderDirection', 'nextDecisionTick',
          ], updateCounters, 'npcUpdates', (next) => updateWorldNpc(ctx, next));
          continue;
        }
        const movementMedium = runtimeWildlifeMovementMedium(
          wildlifeRegistry, wildlifeProfile.species,
        );
        if (movementMedium === null) continue;
        const stepped = runtimeStepAmbientWildlife(wildlifeRegistry, {
          id: npc.id,
          position: { x: npc.x, y: npc.y },
          home: { x: npc.homeX, y: npc.homeY },
          facing: parseNpcFacing(npc.facing),
          moving: npc.moving,
          activity: npc.wanderDirection,
          nextDecisionTick: Number(npc.nextDecisionTick),
        }, {
          species: wildlifeProfile.species,
          seed: wildlifeSeed,
          authorityTick: Number(authorityTick),
          calendarTick,
          collision: movementMedium === 'water' ? waterCollision : collision,
          ...(runtimeWildlifeEatsHay(wildlifeRegistry, wildlifeProfile.species)
            ? { hayTargets: survivalLandmarkRolePoints(
                activeSurvivalLandmarks(contentRegistry(ctx), npc.spaceId).filter((landmark) => (
                  survivalLandmarksReservedAt([landmark],
                    Math.floor(npc.homeX / TILE_SIZE_FIXED), Math.floor(npc.homeY / TILE_SIZE_FIXED))
                )), 'wildlife_feed',
              ).map((point) => ({
                x: point.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
                y: point.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
              })) }
            : {}),
        });
        if (stepped === null) continue;
        const nextChunkX = chunkAt(stepped.position.x);
        const nextChunkY = chunkAt(stepped.position.y);
        if (stepped.position.x === npc.x && stepped.position.y === npc.y
          && stepped.facing === npc.facing && stepped.moving === npc.moving
          && stepped.activity === npc.wanderDirection
          && BigInt(stepped.nextDecisionTick) === npc.nextDecisionTick
          && npc.panicUntilTick === undefined) continue;
        updateWorldNpc(ctx, {
          ...npc,
          x: stepped.position.x,
          y: stepped.position.y,
          chunkX: nextChunkX,
          chunkY: nextChunkY,
          facing: stepped.facing,
          moving: stepped.moving,
          wanderDirection: stepped.activity,
          nextDecisionTick: BigInt(stepped.nextDecisionTick),
          authorityTick,
          panicUntilTick: undefined,
          panicSource: undefined,
        });
        recordTickRowTouch(updateCounters, 'npcUpdates');
        continue;
      }

      // Fin is an authored worker, not a wanderer. His persisted activity and
      // deadline keep every client on the same cast -> wait -> reel -> rest
      // rhythm without replaying either action continuously.
      const authoredNpc = authoredNpcsByRuntimeId.get(npc.id.toString());
      const fishing = authoredNpc === undefined
        ? null
        : raiseAuthoredNpcTickEvent(ctx, npcLifecycleHandlers, authoredNpc, npc);
      if (fishing !== null) {
        const homeX = authoredNpc!.home.tileX * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
        const homeY = authoredNpc!.home.tileY * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2;
        const nextNpc = {
          ...npc,
          x: homeX,
          y: homeY,
          chunkX: chunkAt(homeX),
          chunkY: chunkAt(homeY),
          facing: authoredNpc!.facing,
          moving: false,
          wanderDirection: fishing.activity,
          nextDecisionTick: fishing.nextDecisionTick,
          authorityTick,
        };
        const npcUpdated = updateRowWhenChanged(npc, nextNpc, [
          'x', 'y', 'chunkX', 'chunkY', 'facing', 'moving', 'wanderDirection', 'nextDecisionTick',
        ], updateCounters, 'npcUpdates', (next) => updateWorldNpc(ctx, next));
        if (npcUpdated) updateCounters.nonWildlifeNpcUpdates += 1;
        else updateCounters.nonWildlifeNpcNoopSkips += 1;
        const sayRange = 18 * TILE_SIZE_FIXED;
        const nearbyListener = (playersBySpace.get(npc.spaceId) ?? []).some((player) => {
          const dx = player.x - nextNpc.x;
          const dy = player.y - nextNpc.y;
          return dx * dx + dy * dy <= sayRange * sayRange;
        });
        if (fishing.speech !== undefined && nearbyListener) {
          const previousSpeech = [...ctx.db.world_speech.by_space.filter(npc.spaceId)].find(
            (speech) => speech.speakerNpcId === npc.id && speech.expiresTick > authorityTick,
          );
          if (previousSpeech === undefined) {
            ctx.db.world_speech.insert({
              id: 0n,
              speaker: ctx.sender,
              speakerNpcId: npc.id,
              speakerDisplayName: npc.displayName,
              kind: 'say',
              body: fishing.speech,
              x: nextNpc.x,
              y: nextNpc.y,
              createdTick: authorityTick,
              expiresTick: authorityTick + BigInt(AUTHORITY_HZ * 6),
              spaceId: npc.spaceId,
            });
            recordTickRowTouch(updateCounters);
          }
        }
        continue;
      }

      const automatedLandmark = automatedLandmarks.find((plan) => plan.automation !== undefined
        && plan.spaceId === npc.spaceId
        && contentRegistry(ctx).npcs.get(plan.automation.actor)?.runtimeId === npc.id.toString());
      const marlowFire = automatedLandmark === undefined
        ? null : ctx.db.world_campfire_state.id.find(automatedLandmark.runtimeId);
      const marlowCookingFire = automatedLandmark === undefined
        ? null : ctx.db.world_placeable.id.find(automatedLandmark.runtimeId);
      const marlowDesiredFireLit = automatedLandmark?.automation === undefined ? false
        : authoredCampfireShouldBeLit(calendarTick, automatedLandmark.automation);
      const marlowReturningToFire = marlowFire !== null
        && !marlowFire.manualOverride
        && (marlowFire.lit !== marlowDesiredFireLit
          || marlowCookingFire?.lit !== marlowDesiredFireLit);
      const marlowTarget = {
        x: (marlowFire?.tileX ?? 0) * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
        y: (marlowFire?.tileY ?? 0) * TILE_SIZE_FIXED + TILE_SIZE_FIXED / 2,
      };
      if (marlowReturningToFire && marlowFire !== null) {
        const dx = marlowTarget.x - npc.x;
        const dy = marlowTarget.y - npc.y;
        if (dx * dx + dy * dy <= NPC_INTERACTION_REACH_FIXED * NPC_INTERACTION_REACH_FIXED) {
          if (marlowFire.lit !== marlowDesiredFireLit) ctx.db.world_campfire_state.id.update({
            ...marlowFire,
            lit: marlowDesiredFireLit,
          });
          if (marlowCookingFire !== null && marlowCookingFire.lit !== marlowDesiredFireLit) {
            ctx.db.world_placeable.id.update({ ...marlowCookingFire, lit: marlowDesiredFireLit });
            settleProcessorPlaceable(ctx, { ...marlowCookingFire, lit: marlowDesiredFireLit });
          }
        }
      }
      const wanderingState = {
        id: npc.id,
        position: { x: npc.x, y: npc.y },
        home: { x: npc.homeX, y: npc.homeY },
        facing: parseNpcFacing(npc.facing),
        moving: npc.moving,
        wanderDirection: npcDirection(npc.wanderDirection),
        nextDecisionTick: Number(npc.nextDecisionTick),
      };
      const stepped = marlowReturningToFire
        ? stepNpcTowardPoint(wanderingState, marlowTarget, Number(authorityTick), collision)
        : stepWanderingNpc(wanderingState, Number(authorityTick), collision);
      const nextNpc = {
        ...npc,
        x: stepped.position.x,
        y: stepped.position.y,
        chunkX: chunkAt(stepped.position.x),
        chunkY: chunkAt(stepped.position.y),
        facing: stepped.facing,
        moving: stepped.moving,
        wanderDirection: stepped.wanderDirection ?? 'idle',
        nextDecisionTick: BigInt(stepped.nextDecisionTick),
        authorityTick,
      };
      const npcUpdated = updateRowWhenChanged(npc, nextNpc, [
        'x', 'y', 'chunkX', 'chunkY', 'facing', 'moving',
        'wanderDirection', 'nextDecisionTick',
      ], updateCounters, 'npcUpdates', (next) => {
        updateWorldNpc(ctx, next);
      });
      if (npcUpdated) updateCounters.nonWildlifeNpcUpdates += 1;
      else updateCounters.nonWildlifeNpcNoopSkips += 1;
    }
    stepTraversalHazards(ctx, authorityTick, onlinePlayers, occupiedNpcs, collisionBySpace);
    tickStageTiming(telemetryTimingSample, 'npc', true);
    finishTickTelemetry(authorityTick, updateCounters, obstacleCount);
  },
);

// Shadow-only ingestion. Static serving is a separate guarded publication step.
export const stageWorldChunkBlob = spacetimedb.reducer({ bytes: t.array(t.u8()) }, (ctx, { bytes }) => {
  requireWorldOwner(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const chunk = validateShadowBlob(Uint8Array.from(bytes));
  if (ctx.db.world_chunk_blob.contentHash.find(chunk.contentHash) === null) ctx.db.world_chunk_blob.insert({ contentHash: chunk.contentHash, bytes });
});
export const publishWorldChunkShadow = spacetimedb.reducer({ manifestJson: t.string(), mapId: t.string(), contentHash: t.string(), expectedRevision: t.u32() }, (ctx, input) => {
  requireWorldOwner(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const map = ctx.db.live_map_document.mapId.find(input.mapId);
  if (map === null) throw new SenderError('chunk_shadow_map_missing');
  if (input.manifestJson.length > 1024 * 1024) throw new SenderError('chunk_manifest_too_large');
  const raw = JSON.parse(input.manifestJson) as { spaceId?: number } | null;
  if (!Number.isSafeInteger(raw?.spaceId) || raw?.spaceId !== TOPSIDE_SPACE_ID || input.mapId !== LIVE_ISLAND_MAP_ID) throw new SenderError('chunk_shadow_space_not_supported');
  const spaceId = BigInt(raw.spaceId);
  const previous = ctx.db.world_chunk_shadow.spaceId.find(spaceId);
  const manifest = validateShadowPublication(input, { mapRevision: map.revision, mapHash: map.contentHash,
    contentHash: contentRegistry(ctx).contentHash, shadowRevision: previous?.revision ?? 0 }, hash => {
      const row = ctx.db.world_chunk_blob.contentHash.find(hash); return row === null ? undefined : Uint8Array.from(row.bytes);
    });
  if (input.expectedRevision === 0xffffffff) throw new SenderError('chunk_shadow_revision_exhausted');
  const revision = input.expectedRevision + 1;
  for (const row of ctx.db.world_chunk_head.by_space.filter(spaceId)) ctx.db.world_chunk_head.id.delete(row.id);
  for (const head of manifest.chunks) ctx.db.world_chunk_head.insert({ id: `${spaceId}:${head.cx}:${head.cy}`, spaceId, cx: head.cx, cy: head.cy, contentHash: head.contentHash, revision, byteLength: head.byteLength });
  const row = { spaceId, revision, mapId: input.mapId, contentHash: input.contentHash, manifestJson: input.manifestJson };
  if (previous === null) ctx.db.world_chunk_shadow.insert(row); else ctx.db.world_chunk_shadow.spaceId.update(row);
});

/** Static-world S2a: owner-only chunkAuthority switch (off | shadow | on),
 * stored in the public space 0 space_admin_flag row. Idempotent: setting the
 * current mode writes nothing. Nothing reads the mode for behaviour yet. */
export const setChunkAuthority = spacetimedb.reducer({ mode: t.string() }, (ctx, { mode }) => {
  requireStrictWorldOwner(ctx.senderAuth.jwt, ctx.db.membership.identity.find(ctx.sender));
  const next = parseChunkAuthorityMode(mode);
  if (next === null) throw new SenderError('chunk_authority_mode_invalid');
  const existing = ctx.db.space_admin_flag.spaceId.find(CHUNK_AUTHORITY_SPACE_ID);
  const plan = planChunkAuthorityFlags(existing?.flagsJson, next);
  if (plan === null) return;
  const row = { spaceId: CHUNK_AUTHORITY_SPACE_ID, flagsJson: plan.flagsJson, updatedBy: ctx.sender, updatedAt: ctx.timestamp };
  if (existing === null) ctx.db.space_admin_flag.insert(row); else ctx.db.space_admin_flag.spaceId.update(row);
  ctx.db.world_admin_audit.insert({
    id: 0n, actor: ctx.sender, action: 'set_chunk_authority', value: `${plan.previous}->${plan.mode}`,
    occurredAt: ctx.timestamp, occurredAtMicros: ctx.timestamp.microsSinceUnixEpoch,
    targetKey: CHUNK_AUTHORITY_AUDIT_TARGET_KEY, payload: chunkAuthorityAuditPayload(plan, ctx.timestamp.microsSinceUnixEpoch),
  });
});
const shadowChunkCollision = new ShadowChunkCollisionCache();
/** Shadow diagnostics only. No movement/pathfinding authority calls this yet. */
function chunkShadowCollisionAt(ctx: WorldReducerContext, spaceId: bigint, x: number, y: number) {
  const head = ctx.db.world_chunk_head.id.find(`${spaceId}:${Math.floor(x / 64)}:${Math.floor(y / 64)}`);
  return shadowChunkCollision.sample(head?.contentHash, x, y, hash => {
    const row = ctx.db.world_chunk_blob.contentHash.find(hash); return row === null ? undefined : Uint8Array.from(row.bytes);
  });
}

export const inspectWorldChunkShadow = spacetimedb.procedure(
  { spaceId: t.u64(), x: t.i32(), y: t.i32() }, t.string(),
  (ctx, { spaceId, x, y }) => ctx.withTx(tx => {
    requireWorldOwner(tx.senderAuth.jwt, tx.db.membership.identity.find(tx.sender));
    return JSON.stringify(chunkShadowCollisionAt(tx, spaceId, x, y));
  }),
);
